/**
 * Fallback menu function for preview before activation (preserves design)
 * EC-NAV-014: Supports dynamic current page highlighting via baseLinkClasses/activeLinkClasses
 */
function wpconvert_fallback_menu() {
    $json_path = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($json_path)) {
        return;
    }
    
    $data = json_decode(file_get_contents($json_path), true);
    if (!$data || !isset($data['primary']['items'])) {
        return;
    }
    
    // Get UL classes from source to preserve design
    $ul_classes = !empty($data['primary']['ulClasses']) ? $data['primary']['ulClasses'] : 'menu';
    
    // Set global submenu class for recursive function to use (extra Tailwind classes only; base sub-menu/submenu merged at render)
    global $wpconvert_submenu_class;
    $wpconvert_submenu_class = !empty($data['primary']['submenuClass']) ? $data['primary']['submenuClass'] : '';
    
    // EC-NAV-014: Set globals for current page highlighting
    global $wpconvert_base_classes, $wpconvert_active_classes, $wpconvert_inactive_classes;
    $wpconvert_base_classes = !empty($data['primary']['baseLinkClasses']) ? $data['primary']['baseLinkClasses'] : '';
    $wpconvert_active_classes = !empty($data['primary']['activeLinkClasses']) ? $data['primary']['activeLinkClasses'] : '';
    $wpconvert_inactive_classes = !empty($data['primary']['inactiveLinkClasses']) ? $data['primary']['inactiveLinkClasses'] : '';

    // EC-NAV-382: the class the SOURCE used to mark the current page (e.g.
    // "active"). Sites style their own token, not WordPress's current-menu-item.
    global $wpconvert_active_state_class, $wpconvert_active_state_target;
    $wpconvert_active_state_class = !empty($data['primary']['activeStateClass']) ? $data['primary']['activeStateClass'] : '';
    // EC-NAV-383: 'link', 'item' or 'both'; absent means 'link'.
    $wpconvert_active_state_target = !empty($data['primary']['activeStateTarget']) ? $data['primary']['activeStateTarget'] : '';
    
    // EC-NAV-MOBILE-ID-001: preserve the ORIGINAL nav <ul> id (captured as
    // ulId) so inline mobile toggles like
    // <button onclick="getElementById('navlinks').classList.toggle('open')">
    // and any #id CSS keep targeting the rendered menu. This fallback renders on
    // a freshly-activated theme (before a menu is assigned), which is exactly
    // when the customer sees the mobile nav, so the id must match here too.
    $ul_id = !empty($data['primary']['ulId']) ? $data['primary']['ulId'] : 'wpconvert-primary-ul';
    echo '<ul id="' . esc_attr($ul_id) . '" class="' . esc_attr($ul_classes) . '">';
    wpconvert_render_fallback_menu_items($data['primary']['items']);
    echo '</ul>';
}

/**
 * EC-NAV-CTA-001: PHP-side fallback CTA detection.
 * If isButton was not set during conversion, detect CTA styling from classes.
 * Checks for a permanent bg-* class (not hover/focus) plus 2+ button signals.
 */
function wpconvert_is_cta_by_classes($classes) {
    if (!is_array($classes) || empty($classes)) return false;
    $class_str = implode(' ', $classes);
    // EC-NAV-136: bg-foreground + text-background is a semantic dark button (inverted colors).
    // Detect this paired pattern before the generic bg- exclusion list rejects bg-foreground.
    $has_bg = false;
    if (preg_match('/\bbg-foreground\b/', $class_str) && preg_match('/\btext-background\b/', $class_str)) {
        $has_bg = true;
    }
    if (!$has_bg) {
        foreach ($classes as $cls) {
            if (strpos($cls, 'bg-') === 0 &&
                !preg_match('/^bg-(transparent|inherit|clip|no-repeat|cover|center|none|opacity|blend|origin|scroll|fixed|local|repeat|size|white|black|background|foreground|card|popover|muted|secondary|input|ring|border|destructive|gray|slate|zinc|neutral|stone)/', $cls) &&
                // EC-NAV-378: mirror EC-NAV-039 (which only ever lived on the JS side).
                // A trailing opacity modifier makes the background a translucent TINT —
                // bg-primary/10, and in arbitrary-value form bg-[#0B74E5]/[0.08] — which is
                // how a nav link marks itself as the current page, not a CTA fill. Without
                // this the walker's CTA branch re-emitted the snapshot page's link with its
                // captured classes verbatim, so it stayed highlighted on every other page.
                !preg_match('/^bg-(?:\[[^\]]*\]|[\w.-]+)\/(?:\d|\[)/', $cls)) {
                $has_bg = true;
                break;
            }
        }
    }
    if (!$has_bg) return false;
    $signals = 0;
    if (preg_match('/\btext-(white|black|primary-foreground|background)\b/', $class_str)) $signals++;
    if (preg_match('/\b(px-\d|py-\d|p-\d)/', $class_str)) $signals++;
    if (preg_match('/\bfont-(bold|semibold|extrabold|medium)\b/', $class_str)) $signals++;
    if (preg_match('/\buppercase\b/', $class_str)) $signals++;
    if (preg_match('/\brounded(-\w+)?\b/', $class_str)) $signals++;
    return $signals >= 2;
}

/**
 * EC-I18N-MENU-001: Return ' data-i18n="<key>"' for a menu item if the
 * conversion extractor recorded an i18nKey on it (matched against the
 * source translation dictionary). Returns '' otherwise so the walker
 * emits byte-identical markup for non-translated items and for sites
 * without i18n.
 *
 * The walker / fallback functions append the result directly inside the
 * opening <a> tag. The wpconvert-i18n.js runtime reads data-i18n on
 * language change and swaps the element's text content.
 */
/**
 * EC-I18N-URL-MENU-001: Detect the active URL-prefix locale from the request path.
 * Locales are read dynamically from menus.json (primary.locales) — never hardcoded.
 */
function wpconvert_request_locale() {
    static $cached = null;
    if ($cached !== null) {
        return $cached;
    }
    $file = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($file)) {
        $cached = '';
        return $cached;
    }
    $data = json_decode(@file_get_contents($file), true);
    $locales = array();
    $default = '';
    if (is_array($data) && !empty($data['primary']['locales']) && is_array($data['primary']['locales'])) {
        $locales = array_map('strval', $data['primary']['locales']);
        $default = !empty($data['primary']['defaultLocale']) ? (string) $data['primary']['defaultLocale'] : (string) ($locales[0] ?? '');
    } elseif (is_array($data) && !empty($data['primary']['items']) && is_array($data['primary']['items'])) {
        // EC-I18N-URL-MENU-001b: older themes may have per-item localeTitles but
        // missed primary.locales during serialization — infer from item keys.
        $seen = array();
        foreach ($data['primary']['items'] as $it) {
            if (!is_array($it) || empty($it['localeTitles']) || !is_array($it['localeTitles'])) continue;
            foreach (array_keys($it['localeTitles']) as $lk) {
                $seen[(string) $lk] = true;
            }
        }
        if (!empty($seen)) {
            $locales = array_keys($seen);
            sort($locales);
            $firstUrl = (string) ($data['primary']['items'][0]['url'] ?? '');
            $firstSeg = strtolower((string) (explode('/', trim($firstUrl, '/'))[0] ?? ''));
            $default = in_array($firstSeg, $locales, true) ? $firstSeg : (string) $locales[0];
        }
    }
    if (empty($locales)) {
        $cached = '';
        return $cached;
    }
    $path = (string) parse_url(isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : '', PHP_URL_PATH);
    $path = trim($path, '/');
    $segments = $path !== '' ? explode('/', $path) : array();
    // EC-I18N-URL-MENU-001c: scan ALL path segments — Playground/subdir installs
    // prefix the path (e.g. /scope:uuid/en/agents) so the first segment is not the locale.
    foreach ($segments as $seg) {
        $seg = strtolower((string) $seg);
        if ($seg !== '' && in_array($seg, $locales, true)) {
            $cached = $seg;
            return $cached;
        }
    }
    // Fallback: WordPress page slug prefix (en-agent-assessment → en).
    if (function_exists('is_singular') && is_singular()) {
        $obj = get_queried_object();
        if ($obj && !empty($obj->post_name)) {
            $slug = strtolower((string) $obj->post_name);
            foreach ($locales as $loc) {
                $loc = (string) $loc;
                if ($slug === $loc || strpos($slug, $loc . '-') === 0) {
                    $cached = $loc;
                    return $cached;
                }
            }
        }
    }
    // EC-I18N-URL-MENU-001d: neither the path nor the slug identified a locale,
    // so this is a guess. Do NOT memoise it. The slug branch above needs the
    // main query, and anything running before that (an early menu filter, a
    // wp_head hook) would otherwise cache the default and hand it to the header
    // once the query IS available — shipping the Finnish menu on /en pages.
    return $default !== '' ? $default : (string) $locales[0];
}

/**
 * EC-I18N-URL-MENU-001e: The locale the captured menu was snapshotted in.
 * Localizing INTO it is a no-op by definition, so the renderers hand back the
 * captured markup untouched.
 */
function wpconvert_menu_snapshot_locale() {
    static $cached = null;
    if ($cached !== null) {
        return $cached;
    }
    $cached = '';
    $file = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($file)) {
        return $cached;
    }
    $data = json_decode(@file_get_contents($file), true);
    if (is_array($data) && !empty($data['primary']['defaultLocale'])) {
        $cached = strtolower((string) $data['primary']['defaultLocale']);
    }
    return $cached;
}

/**
 * EC-I18N-URL-MENU-001e: Did the crawl actually capture a template for this
 * path? A localized route table can name pages the crawler never reached
 * (aileadit.com's routeMap has /fi/yhteys; only /fi/kumppanuus was captured),
 * and linking one of those swaps a working page for a 404. Unknown when
 * routes.json is absent — the caller then keeps today's behaviour.
 * @return bool|null true = captured, false = definitely not, null = unknown
 */
function wpconvert_route_was_captured($path) {
    static $routes = null;
    if ($routes === null) {
        $routes = false;
        $file = get_template_directory() . '/assets/data/routes.json';
        if (file_exists($file)) {
            $data = json_decode(@file_get_contents($file), true);
            if (is_array($data) && !empty($data)) {
                $routes = array();
                foreach ($data as $key => $route) {
                    $routes[rtrim((string) $key, '/')] = true;
                    if (is_array($route) && !empty($route['url'])) {
                        $routes[rtrim((string) $route['url'], '/')] = true;
                    }
                }
            }
        }
    }
    if (!is_array($routes)) {
        return null;
    }
    $p = rtrim((string) (parse_url((string) $path, PHP_URL_PATH) ?: ''), '/');
    if ($p === '') {
        return null;
    }
    return isset($routes[$p]);
}

/**
 * EC-I18N-URL-MENU-001: Resolve localized title/url for a menus.json item.
 * @param array $item
 * @return array{title:string,url:string}
 */
function wpconvert_localize_menu_item($item) {
    $title = isset($item['title']) ? (string) $item['title'] : '';
    $url = isset($item['url']) ? (string) $item['url'] : '#';
    if (!is_array($item)) {
        return array('title' => $title, 'url' => $url);
    }
    $loc = function_exists('wpconvert_request_locale') ? wpconvert_request_locale() : '';
    if ($loc === '') {
        return array('title' => $title, 'url' => $url);
    }
    // EC-I18N-URL-MENU-001e: on the snapshot's own language the capture wins.
    // The route table is a second, independent source that can disagree with
    // where the header really linked, and only the capture was verified to
    // exist as a page.
    if (function_exists('wpconvert_menu_snapshot_locale') && $loc === wpconvert_menu_snapshot_locale()) {
        return array('title' => $title, 'url' => $url);
    }
    if (!empty($item['localeTitles']) && is_array($item['localeTitles']) && !empty($item['localeTitles'][$loc])) {
        $title = (string) $item['localeTitles'][$loc];
    }
    if (!empty($item['localeUrls']) && is_array($item['localeUrls']) && !empty($item['localeUrls'][$loc])) {
        $candidate = (string) $item['localeUrls'][$loc];
        $captured = function_exists('wpconvert_route_was_captured')
            ? wpconvert_route_was_captured($candidate)
            : null;
        // false means routes.json is present and does NOT list it — keep the
        // page we know renders rather than linking a hole.
        if ($captured !== false) {
            $url = $candidate;
        }
    }
    return array('title' => $title, 'url' => $url);
}

/**
 * EC-I18N-URL-MENU-001e: Find the menus.json row a WP menu item came from,
 * searching submenus too so dropdown children localize like their parents.
 * @return array|null
 */
function wpconvert_find_menu_json_row($items, $title, $url) {
    if (!is_array($items)) {
        return null;
    }
    $want_title = strtolower(trim((string) $title));
    $wp_p = rtrim((string) (parse_url((string) $url, PHP_URL_PATH) ?: ''), '/');
    foreach ($items as $json_item) {
        if (!is_array($json_item)) continue;
        $title_match = $want_title !== '' &&
            $want_title === strtolower(trim((string) ($json_item['title'] ?? '')));
        $js_p = rtrim((string) (parse_url((string) ($json_item['url'] ?? ''), PHP_URL_PATH) ?: ''), '/');
        $url_match = ($wp_p !== '' && $js_p !== '' && $wp_p === $js_p);
        // Also match via any locale URL variant, so a visitor already on /en/
        // still resolves the row when WordPress hands us the English permalink.
        if (!$url_match && !empty($json_item['localeUrls']) && is_array($json_item['localeUrls'])) {
            foreach ($json_item['localeUrls'] as $lu) {
                $lp = rtrim((string) (parse_url((string) $lu, PHP_URL_PATH) ?: ''), '/');
                if ($wp_p !== '' && $lp !== '' && $wp_p === $lp) { $url_match = true; break; }
            }
        }
        // Likewise for a translated label.
        if (!$title_match && $want_title !== '' && !empty($json_item['localeTitles']) && is_array($json_item['localeTitles'])) {
            foreach ($json_item['localeTitles'] as $lt) {
                if ($want_title === strtolower(trim((string) $lt))) { $title_match = true; break; }
            }
        }
        if ($title_match || $url_match) { return $json_item; }
        if (!empty($json_item['children']) && is_array($json_item['children'])) {
            $nested = wpconvert_find_menu_json_row($json_item['children'], $title, $url);
            if ($nested) { return $nested; }
        }
    }
    return null;
}

/**
 * EC-I18N-URL-MENU-001: Match a WP menu item to its menus.json row and return
 * localized title/url. Falls back to the WP item's own title/url.
 */
function wpconvert_localize_wp_nav_item($wp_item) {
    $title = is_object($wp_item) ? (string) ($wp_item->title ?? '') : '';
    $url = is_object($wp_item) ? (string) ($wp_item->url ?? '') : '';
    $file = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($file)) {
        return array('title' => $title, 'url' => $url);
    }
    $data = json_decode(@file_get_contents($file), true);
    if (!is_array($data) || empty($data['primary']['items']) || !is_array($data['primary']['items'])) {
        return array('title' => $title, 'url' => $url);
    }
    $match = wpconvert_find_menu_json_row($data['primary']['items'], $title, $url);
    if (!$match) {
        return array('title' => $title, 'url' => $url);
    }
    $loc = wpconvert_localize_menu_item($match);
    return array(
        'title' => $loc['title'] !== '' ? $loc['title'] : $title,
        'url' => $loc['url'] !== '' && $loc['url'] !== '#' ? $loc['url'] : $url,
    );
}

function wpconvert_i18n_menu_attr_from_item( $item ) {
    if ( is_array( $item ) && ! empty( $item['i18nKey'] ) ) {
        return ' data-i18n="' . esc_attr( $item['i18nKey'] ) . '"';
    }
    return '';
}

/**
 * EC-I18N-MENU-001: Lookup helper used by walker paths that don't have
 * the menus.json snapshot row in scope (e.g. the default branch of
 * WPConvert_Flat_Menu_Walker::start_el, and WPConvert_Menu_Walker). It
 * builds an in-memory index of trimmed-lowercase title => i18nKey once
 * per request and returns ' data-i18n="<key>"' for the given title (or
 * '' for unmatched titles / missing menus.json / sites without i18n).
 */
function wpconvert_i18n_menu_attr_for_title( $title ) {
    static $index = null;
    if ( $index === null ) {
        $index = array();
        $file = get_template_directory() . '/assets/data/menus.json';
        if ( file_exists( $file ) ) {
            $data = json_decode( file_get_contents( $file ), true );
            if ( is_array( $data ) ) {
                if ( ! empty( $data['primary']['items'] ) && is_array( $data['primary']['items'] ) ) {
                    wpconvert_i18n_menu_index_recursive( $data['primary']['items'], $index );
                }
                if ( ! empty( $data['footer']['items'] ) && is_array( $data['footer']['items'] ) ) {
                    wpconvert_i18n_menu_index_recursive( $data['footer']['items'], $index );
                }
            }
        }
    }
    $key = strtolower( trim( (string) $title ) );
    if ( $key === '' ) return '';
    if ( isset( $index[ $key ] ) ) {
        return ' data-i18n="' . esc_attr( $index[ $key ] ) . '"';
    }
    return '';
}

function wpconvert_i18n_menu_index_recursive( $items, &$index ) {
    if ( ! is_array( $items ) ) return;
    foreach ( $items as $it ) {
        if ( ! is_array( $it ) ) continue;
        if ( ! empty( $it['i18nKey'] ) && ! empty( $it['title'] ) ) {
            $k = strtolower( trim( (string) $it['title'] ) );
            if ( $k !== '' && ! isset( $index[ $k ] ) ) {
                $index[ $k ] = $it['i18nKey'];
            }
        }
        if ( ! empty( $it['children'] ) && is_array( $it['children'] ) ) {
            wpconvert_i18n_menu_index_recursive( $it['children'], $index );
        }
    }
}

/**
 * Fallback menu function for flat nav structure (no ul/li wrapper)
 * Used for React/Vite sites that use direct <a> links instead of <ul><li>
 * EC-NAV-014: Supports dynamic current page highlighting via baseLinkClasses/activeLinkClasses
 */
// EC-NAV-234: Return ' onclick="…" id="…"' for a menus.json item that carries an
// inline router handler (class-toggle SPA navbars: onclick="return nav('services')").
// The pre-activation fallback renderers receive the menus.json row directly as
// $item, so they can read attributes straight off it. Returns '' for normal items
// (real per-page URLs, no inline handler) so output is unchanged for typical sites.
function wpconvert_inline_handler_attr_from_item($item) {
    if (!is_array($item) || empty($item['attributes']) || !is_array($item['attributes'])) {
        return '';
    }
    $attrs = $item['attributes'];
    $out = '';
    if (!empty($attrs['onclick'])) {
        $out .= ' onclick="' . esc_attr($attrs['onclick']) . '"';
    }
    if (!empty($attrs['id'])) {
        $out .= ' id="' . esc_attr($attrs['id']) . '"';
    }
    return $out;
}

function wpconvert_fallback_menu_flat() {
    $json_path = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($json_path)) {
        return;
    }
    
    $data = json_decode(file_get_contents($json_path), true);
    if (!$data || !isset($data['primary']['items'])) {
        return;
    }
    
    // EC-NAV-010/014: Get base, active, and inactive classes from menus.json
    $base_classes = !empty($data['primary']['baseLinkClasses']) ? $data['primary']['baseLinkClasses'] : '';
    $active_classes = !empty($data['primary']['activeLinkClasses']) ? $data['primary']['activeLinkClasses'] : '';
    $inactive_classes = !empty($data['primary']['inactiveLinkClasses']) ? $data['primary']['inactiveLinkClasses'] : '';
    
    // Render flat links (no ul/li wrapper)
    foreach ($data['primary']['items'] as $item) {
        // EC-I18N-URL-MENU-001: swap title/url for the active URL-prefix locale
        $localized = function_exists('wpconvert_localize_menu_item')
            ? wpconvert_localize_menu_item($item)
            : array('title' => !empty($item['title']) ? $item['title'] : '', 'url' => !empty($item['url']) ? $item['url'] : '#');
        $url = !empty($localized['url']) ? $localized['url'] : '#';
        $url = wpconvert_convert_static_url($url);
        $title = !empty($localized['title']) ? esc_html($localized['title']) : '';
        
        // EC-NAV-022/CTA-001: CTA/button items use their own classes (preserved from source)
        // Primary check: explicit isButton flag. Fallback: detect CTA from stored classes.
        $is_cta = !empty($item['isButton']);
        if (!$is_cta && !empty($item['classes']) && is_array($item['classes'])) {
            $is_cta = wpconvert_is_cta_by_classes($item['classes']);
        }
        if ($is_cta && !empty($item['classes']) && is_array($item['classes'])) {
            $btn_classes = implode(' ', $item['classes']);
            // EC-I18N-MENU-001: stamp data-i18n when the extractor matched this
            // CTA title to a translation dict key. The i18nKey field lives on
            // the item directly in menus.json so no extra lookup is needed.
            $i18n_attr = wpconvert_i18n_menu_attr_from_item($item);
            $handler_attr = wpconvert_inline_handler_attr_from_item($item);
            echo '<a href="' . esc_url($url) . '" class="' . esc_attr(trim($btn_classes)) . '"' . $handler_attr . $i18n_attr . '>' . $title . '</a>';
            continue;
        }
        
        // Check if this is the current page for active styling
        $is_current = false;
        $current_url = home_url(add_query_arg(array(), $_SERVER['REQUEST_URI']));
        $item_url = esc_url($url);
        
        // Compare URLs (strip trailing slashes for comparison)
        // EC-NAV-379: anchor-only items ("#", "#about") yield a null path, which
        // PHP 8.1+ deprecates as an rtrim() argument — cast before trimming.
        $current_path = rtrim((string) parse_url($current_url, PHP_URL_PATH), '/');
        $item_path = rtrim((string) parse_url($item_url, PHP_URL_PATH), '/');
        
        // EC-NAV-381: fragment-only URLs address no page — see the UL/LI renderer.
        if (!wpconvert_is_fragment_only_url($item_url)
            && ($current_path === $item_path || (empty($item_path) && ($current_path === '' || $current_path === '/')))) {
            $is_current = true;
        }
        
        // EC-NAV-014: Apply dynamic current page highlighting
        if ($is_current) {
            // Current page: Start with base, remove inactive-specific, add active classes
            $link_classes = $base_classes;
            if (!empty($inactive_classes)) {
                $inactive_arr = array_filter(explode(' ', $inactive_classes));
                $base_arr = array_filter(explode(' ', $link_classes));
                $base_arr = array_diff($base_arr, $inactive_arr);
                $link_classes = implode(' ', $base_arr);
            }
            if (!empty($active_classes)) {
                $link_classes .= ' ' . $active_classes;
            }
            $link_classes .= ' wpconvert-active-link current-menu-item';
        } else {
            // Not current page: Use base classes (inactive state)
            $link_classes = $base_classes;
        }
        
        // EC-I18N-MENU-001: stamp data-i18n on the regular flat-nav <a> when
        // the source dict has a matching translation for this item.title.
        $i18n_attr = wpconvert_i18n_menu_attr_from_item($item);
        $handler_attr = wpconvert_inline_handler_attr_from_item($item);
        echo '<a href="' . esc_url($url) . '" class="' . esc_attr(trim($link_classes)) . '"' . $handler_attr . $i18n_attr . '>' . $title . '</a>';
    }
}

/**
 * Walker for flat nav structure (outputs <a> tags without ul/li wrapper)
 * Used for React/Vite sites that use direct <a> links
 * EC-NAV-014: Supports dynamic current page highlighting via baseLinkClasses/activeLinkClasses
 */
class WPConvert_Flat_Menu_Walker extends Walker_Nav_Menu {
    private $menu_data = null;
    private $base_classes = '';
    private $active_classes = '';
    private $inactive_classes = '';
    /** EC-NAV-140: Children count for current top-level item (menus.json), for mega submenu layout */
    private $flat_submenu_child_count = 0;
    
    function __construct() {
        $file = get_template_directory() . '/assets/data/menus.json';
        if (file_exists($file)) {
            $this->menu_data = json_decode(file_get_contents($file), true);
            // EC-NAV-014: Load class mappings once in constructor
            if ($this->menu_data && !empty($this->menu_data['primary'])) {
                $this->base_classes = $this->menu_data['primary']['baseLinkClasses'] ?? '';
                $this->active_classes = $this->menu_data['primary']['activeLinkClasses'] ?? '';
                $this->inactive_classes = $this->menu_data['primary']['inactiveLinkClasses'] ?? '';
            }
        }
    }
    
    private function wpconvert_flat_submenu_child_count_from_json( $title ) {
        if ( ! $this->menu_data || empty( $this->menu_data['primary']['items'] ) ) {
            return 0;
        }
        $want = strtolower( trim( (string) $title ) );
        foreach ( $this->menu_data['primary']['items'] as $ji ) {
            if ( strtolower( trim( $ji['title'] ?? '' ) ) === $want ) {
                return is_array( $ji['children'] ?? null ) ? count( $ji['children'] ) : 0;
            }
        }
        return 0;
    }
    
    // EC-NAV-233: Some navbars (base44 / Vite exports) style their nav links purely
    // via an inline style attribute with NO CSS classes — the color/typography
    // lives only in attributes.style captured into menus.json. When a link has no
    // classes, every class-based branch in start_el() falls through and the link
    // would render with the default link color. Recover the captured inline style
    // (matched by title/url) so the link keeps its original appearance.
    private function wpconvert_flat_menu_inline_style_for_item( $item ) {
        if ( ! $this->menu_data || empty( $this->menu_data['primary']['items'] ) ) {
            return '';
        }
        $wp_u     = (string) ( $item->url ?? '' );
        $wp_title = strtolower( trim( (string) ( $item->title ?? '' ) ) );
        foreach ( $this->menu_data['primary']['items'] as $json_item ) {
            if ( empty( $json_item['attributes']['style'] ) ) {
                continue;
            }
            // CTA / button rows carry their own styling path — skip them here.
            if ( ! empty( $json_item['isButton'] ) ) {
                continue;
            }
            $title_match = $wp_title !== '' &&
                $wp_title === strtolower( trim( $json_item['title'] ?? '' ) );
            $url_match = rtrim( $wp_u, '/' ) === rtrim( (string) ( $json_item['url'] ?? '' ), '/' );
            if ( $title_match || $url_match ) {
                return (string) $json_item['attributes']['style'];
            }
        }
        return '';
    }

    // EC-NAV-234: Class-toggle SPA navbars switch routes via an inline handler
    // (e.g. <a id="nl-services" onclick="return nav('services')">) captured into
    // menus.json as attributes.onclick / attributes.id. WordPress menu import drops
    // those (the URL '#' also collapses to '/#'), so the walker must re-emit them or
    // the navbar links do nothing. Mirror wpconvert_flat_menu_inline_style_for_item:
    // match the WP menu item to its menus.json row by title/url and return
    // ' onclick="…" id="…"' for injection into the <a>. Returns '' when the item has
    // no inline handler/id, so normal sites (real per-page URLs) are unaffected.
    private function wpconvert_flat_menu_inline_handler_for_item( $item ) {
        if ( ! $this->menu_data || empty( $this->menu_data['primary']['items'] ) ) {
            return '';
        }
        $wp_u     = (string) ( $item->url ?? '' );
        $wp_title = strtolower( trim( (string) ( $item->title ?? '' ) ) );
        foreach ( $this->menu_data['primary']['items'] as $json_item ) {
            $attrs = ( isset( $json_item['attributes'] ) && is_array( $json_item['attributes'] ) )
                ? $json_item['attributes'] : array();
            if ( empty( $attrs['onclick'] ) && empty( $attrs['id'] ) ) {
                continue;
            }
            $title_match = $wp_title !== '' &&
                $wp_title === strtolower( trim( $json_item['title'] ?? '' ) );
            // Class-toggle SPA nav links all share url '#' (they navigate via
            // onclick, not href), so a bare '#'/'/'/'' URL is ambiguous and must
            // NOT be used to match — otherwise every item would resolve to the
            // first handler item. Only trust the URL when it is specific.
            $json_u = (string) ( $json_item['url'] ?? '' );
            $url_is_specific = ( $json_u !== '' && $json_u !== '#' && $json_u !== '/' );
            $url_match = $url_is_specific && ( rtrim( $wp_u, '/' ) === rtrim( $json_u, '/' ) );
            if ( $title_match || $url_match ) {
                $out = '';
                if ( ! empty( $attrs['onclick'] ) ) {
                    $out .= ' onclick="' . esc_attr( $attrs['onclick'] ) . '"';
                }
                if ( ! empty( $attrs['id'] ) ) {
                    $out .= ' id="' . esc_attr( $attrs['id'] ) . '"';
                }
                return $out;
            }
        }
        return '';
    }
    
    // EC-NAV-140: WP uses $depth === 0 for the first submenu (same as Walker_Nav_Menu::start_lvl).
    function start_lvl(&$output, $depth = 0, $args = null) {
        if ( $depth === 0 ) {
            $mega = ( (int) $this->flat_submenu_child_count >= 8 );
            $classes = 'wpconvert-flat-submenu' . ( $mega ? ' wpconvert-flat-submenu--mega-cols-2' : '' );
            $output .= '<div class="' . esc_attr( $classes ) . '">';
        } else {
            $output .= '<div class="wpconvert-flat-submenu wpconvert-flat-submenu--nested">';
        }
    }
    
    function end_lvl(&$output, $depth = 0, $args = null) {
        $output .= '</div>';
    }
    
    function start_el(&$output, $item, $depth = 0, $args = null, $id = 0) {
        if ( $depth === 0 ) {
            $this->flat_submenu_child_count = $this->wpconvert_flat_submenu_child_count_from_json( $item->title );
        }
        // EC-NAV-234: inline router handler (onclick/id) for class-toggle SPA nav links.
        // Injected into every <a> this walker emits so the navbar can switch routes.
        $inline_handler_attr = $this->wpconvert_flat_menu_inline_handler_for_item( $item );
        // EC-NAV-023/CTA-001: Check if this item is a CTA/button in menus.json
        // Primary: explicit isButton flag. Fallback: detect CTA from stored classes.
        if ($this->menu_data && !empty($this->menu_data['primary']['items'])) {
            // EC-NAV-322: when several CTA rows share one URL (e.g. two linktr.ee
            // buttons "Get Idle" + "Drive with Idle"), a URL-only match is ambiguous.
            // Prefer an exact TITLE match and only fall back to a URL-only match when
            // no title match exists, so each CTA keeps its own classes (btn-primary
            // vs btn-out) instead of inheriting the first same-URL row's styling.
            $cta_title_match = null;
            $cta_url_only = null;
            foreach ($this->menu_data['primary']['items'] as $json_item) {
                $is_cta = !empty($json_item['isButton']);
                if (!$is_cta && !empty($json_item['classes']) && is_array($json_item['classes'])) {
                    $is_cta = function_exists('wpconvert_is_cta_by_classes') && wpconvert_is_cta_by_classes($json_item['classes']);
                }
                if ($is_cta && !empty($json_item['classes']) && is_array($json_item['classes'])) {
                    $title_match = strtolower(trim($item->title)) === strtolower(trim($json_item['title'] ?? ''));
                    $url_match = rtrim($item->url ?: '', '/') === rtrim($json_item['url'] ?? '', '/');
                    if ($title_match) { $cta_title_match = $json_item; break; }
                    if ($url_match && $cta_url_only === null) { $cta_url_only = $json_item; }
                }
            }
            $cta_json = $cta_title_match ?: $cta_url_only;
            if ($cta_json) {
                $btn_classes = implode(' ', $cta_json['classes']);
                $wpc_id = $cta_json['wpcId'] ?? 'wpc_navbtn_' . md5($item->title . ($item->url ?: ''));
                // EC-I18N-MENU-001: stamp data-i18n on CTA navbar
                // buttons when the conversion matched their snapshot
                // title to a translation dict key. The runtime then
                // text-swaps the CTA on language change.
                $i18n_attr = wpconvert_i18n_menu_attr_from_item($cta_json);
                $loc = function_exists('wpconvert_localize_menu_item')
                    ? wpconvert_localize_menu_item($cta_json)
                    : array('title' => $item->title, 'url' => $item->url);
                $cta_href = !empty($loc['url']) ? $loc['url'] : $item->url;
                $cta_title = !empty($loc['title']) ? $loc['title'] : $item->title;
                $output .= '<a href="' . wpconvert_nav_item_href($cta_href) . '" class="' . esc_attr(trim($btn_classes)) . '" data-wpc-id="' . esc_attr($wpc_id) . '" data-wpc-editable="button"' . $inline_handler_attr . $i18n_attr . '>';
                $output .= esc_html($cta_title);
                $output .= '</a>';
                return;
            }
        }
        
        // EC-NAV-138: Per-item classes from menus.json (outline pills, icons layout) when the WP
        // menu item matches snapshot title/URL. CTAs are handled above.
        if ($this->menu_data && !empty($this->menu_data['primary']['items'])) {
            foreach ($this->menu_data['primary']['items'] as $json_item) {
                $jc = !empty($json_item['classes']) && is_array($json_item['classes']);
                if (!$jc) {
                    continue;
                }
                $is_cta = !empty($json_item['isButton']);
                if (!$is_cta && function_exists('wpconvert_is_cta_by_classes') && wpconvert_is_cta_by_classes($json_item['classes'])) {
                    $is_cta = true;
                }
                if ($is_cta) {
                    continue;
                }
                $title_match = strtolower(trim($item->title)) === strtolower(trim($json_item['title'] ?? ''));
                $wp_u = (string)($item->url ?? '');
                $js_u = (string)($json_item['url'] ?? '');
                $wp_p = parse_url($wp_u, PHP_URL_PATH);
                $js_p = parse_url($js_u, PHP_URL_PATH);
                $wp_p = is_string($wp_p) ? rtrim($wp_p, '/') : '';
                $js_p = is_string($js_p) ? rtrim($js_p, '/') : '';
                $wp_f = parse_url($wp_u, PHP_URL_FRAGMENT);
                $js_f = parse_url($js_u, PHP_URL_FRAGMENT);
                $wp_f = is_string($wp_f) ? $wp_f : '';
                $js_f = is_string($js_f) ? $js_f : '';
                $url_match = false;
                if ($wp_p !== '' && $js_p !== '' && $wp_p === $js_p) {
                    $url_match = true;
                } elseif ($wp_f !== '' && $js_f !== '' && $wp_f === $js_f) {
                    $url_match = true;
                } elseif (rtrim($wp_u, '/') === rtrim($js_u, '/')) {
                    $url_match = true;
                }
                if (!$title_match && !$url_match) {
                    continue;
                }
                $is_current_pi = in_array('current-menu-item', $item->classes) ||
                    in_array('current_page_item', $item->classes);
                $item_arr = array_filter($json_item['classes']);
                $active_arr  = !empty($this->active_classes)   ? array_filter(explode(' ', $this->active_classes))   : array();
                $inactive_arr = !empty($this->inactive_classes) ? array_filter(explode(' ', $this->inactive_classes)) : array();
                if ($is_current_pi && (!empty($active_arr) || !empty($inactive_arr))) {
                    $item_arr = array_diff($item_arr, $inactive_arr);
                    $item_arr = array_merge(array_diff($item_arr, $active_arr), $active_arr);
                    $class_attr = implode(' ', array_unique($item_arr));
                    $class_attr .= ' wpconvert-active-link current-menu-item';
                } elseif (!$is_current_pi && (!empty($active_arr) || !empty($inactive_arr))) {
                    $item_arr = array_diff($item_arr, $active_arr);
                    if (!empty($inactive_arr)) {
                        $has_inactive = !empty(array_intersect($item_arr, $inactive_arr));
                        if (!$has_inactive) {
                            $item_arr = array_merge($item_arr, $inactive_arr);
                        }
                    } elseif (!empty($this->base_classes)) {
                        $base_arr = array_filter(explode(' ', $this->base_classes));
                        $missing = array_diff($base_arr, $item_arr);
                        if (!empty($missing)) {
                            $item_arr = array_merge($item_arr, $missing);
                        }
                    }
                    $class_attr = implode(' ', array_unique($item_arr));
                } else {
                    $class_attr = implode(' ', $item_arr);
                    if ($is_current_pi) {
                        $class_attr .= ' wpconvert-active-link current-menu-item';
                    }
                }
                // EC-I18N-MENU-001: stamp data-i18n on per-item (EC-NAV-138)
                // <a> output when this snapshot row carries an i18nKey.
                $i18n_attr = wpconvert_i18n_menu_attr_from_item($json_item);
                // EC-I18N-URL-MENU-001: prefer locale-specific title/url from menus.json
                $loc = function_exists('wpconvert_localize_menu_item')
                    ? wpconvert_localize_menu_item($json_item)
                    : array('title' => $item->title, 'url' => $item->url);
                $href_url = !empty($loc['url']) ? $loc['url'] : $item->url;
                $href_title = !empty($loc['title']) ? $loc['title'] : $item->title;
                $output .= '<a href="' . wpconvert_nav_item_href($href_url) . '" class="' . esc_attr(trim($class_attr)) . '"' . $inline_handler_attr . $i18n_attr . '>';
                $output .= esc_html($href_title);
                return;
            }
        }
        
        // Check if current page - WordPress adds current-menu-item to $item->classes
        $is_current = in_array('current-menu-item', $item->classes) || 
                      in_array('current_page_item', $item->classes);
        
        // EC-NAV-014: Apply dynamic current page highlighting
        if (!empty($this->base_classes) || !empty($this->active_classes)) {
            if ($is_current) {
                // Current page: Start with base, remove inactive-specific, add active classes
                $class_attr = $this->base_classes;
                if (!empty($this->inactive_classes)) {
                    $inactive_arr = array_filter(explode(' ', $this->inactive_classes));
                    $base_arr = array_filter(explode(' ', $class_attr));
                    $base_arr = array_diff($base_arr, $inactive_arr);
                    $class_attr = implode(' ', $base_arr);
                }
                if (!empty($this->active_classes)) {
                    $class_attr .= ' ' . $this->active_classes;
                }
                $class_attr .= ' wpconvert-active-link current-menu-item';
            } else {
                // Not current page: Use base classes (inactive state)
                $class_attr = $this->base_classes;
            }
        } else {
            // No class mappings - use original classes from menu item
            $class_attr = '';
            $custom_classes = array_filter($item->classes, function($c) {
                return !in_array($c, ['menu-item', 'menu-item-type-post_type', 'menu-item-object-page', 
                                      'current-menu-item', 'current_page_item', 'menu-item-has-children']);
            });
            if (!empty($custom_classes)) {
                $class_attr = implode(' ', $custom_classes);
            }
            if ($is_current) {
                $class_attr .= ' wpconvert-active-link';
            }
        }
        
        // EC-NAV-233: When the link ends up with NO classes (inline-style-only
        // navbars), recover the captured inline style so its color/typography
        // survives. Only applied when there's nothing class-based to style it.
        $inline_style_attr = '';
        if ( trim($class_attr) === '' ) {
            $inline_style = $this->wpconvert_flat_menu_inline_style_for_item($item);
            if ( $inline_style !== '' ) {
                $inline_style_attr = ' style="' . esc_attr($inline_style) . '"';
            }
        }
        // EC-I18N-MENU-001: default fallback path — no per-item snapshot row
        // matched above, so look the i18nKey up by title in menus.json.
        $i18n_attr = function_exists('wpconvert_i18n_menu_attr_for_title')
            ? wpconvert_i18n_menu_attr_for_title($item->title)
            : '';
        // EC-I18N-URL-MENU-001: localize via menus.json localeTitles/localeUrls
        $loc = function_exists('wpconvert_localize_wp_nav_item')
            ? wpconvert_localize_wp_nav_item($item)
            : array('title' => $item->title, 'url' => $item->url);
        $output .= '<a href="' . wpconvert_nav_item_href($loc['url']) . '" class="' . esc_attr(trim($class_attr)) . '"' . $inline_style_attr . $inline_handler_attr . $i18n_attr . '>';
        $output .= esc_html($loc['title']);
    }
    
    function end_el(&$output, $item, $depth = 0, $args = null) {
        $output .= '</a>';
    }
}

/**
 * EC-NAV-DROPDOWN-003: Strip positioning + visibility classes from the
 * ROOT element of a captured rich-popover panel so the surrounding
 * group-hover wrapper can actually bridge the trigger-to-panel gap.
 *
 * Why this exists
 * ---------------
 *
 * The EC-NAV-185 hover-snapshot pipeline captures the original site's
 * dropdown panel verbatim. For cubic-corporate (and any React app that
 * uses the Lovable / Tailwind "absolute top-full mt-1 opacity-0
 * pointer-events-none group-hover:opacity-100 group-hover:pointer-
 * events-auto" pattern) the captured root looks like:
 *
 *   <div class="absolute top-full left-0 mt-1
 *               bg-slate-950 border border-slate-800 shadow-2xl
 *               rounded-lg py-2 min-w-[200px]
 *               opacity-0 translate-y-2 pointer-events-none
 *               group-hover:opacity-100 group-hover:translate-y-0
 *               group-hover:pointer-events-auto
 *               transition-all duration-200 z-50">...</div>
 *
 * The walker (display_element below) wraps that captured panel in an
 * outer absolute-positioned div with pt-2 padding-top — intended as
 * the hoverable bridge between trigger bottom and panel top. But
 * because the captured panel is ALSO position:absolute, it leaves the
 * wrapper's normal flow. The wrapper collapses to 0 x 8px (only the
 * pt-2 padding contributes, since the only child is removed from flow),
 * so the rendered panel sits 12px below the trigger (8px wrapper pt-2
 * + 4px captured mt-1) with NOTHING under the cursor in the gap.
 *
 * As soon as the cursor enters the gap, .group:hover flips false on
 * the trigger wrapper, every group-hover: utility on both the wrapper
 * AND the captured panel inverts, pointer-events-none re-engages on
 * the captured panel, and the dropdown closes even if the cursor
 * reaches the panel area within the 200ms transition (the panel no
 * longer accepts hover events).
 *
 * Fix
 * ---
 *
 * Neutralise the captured panel root so it sits in NORMAL FLOW inside
 * the wrapper. The wrapper then auto-sizes to the panel's natural
 * width (>= min-w-[200px]), its pt-2 padding-top becomes a real
 * hoverable bridge, and the wrapper itself owns positioning + opacity
 * + group-hover transitions.
 *
 * Strip rules (root element only — nested children untouched)
 * -----------------------------------------------------------
 *
 *   - Position: absolute, fixed, sticky
 *   - Edges:    top-*, -top-*, bottom-*, -bottom-*, left-*, -left-*,
 *               right-*, -right-* (covers 0, full, 1/2, N, [N], etc.)
 *   - Margins:  mt-*, -mt-* (only top — keep author-set m-x/y/b)
 *   - Translates: translate-x-*, translate-y-*, -translate-x-*,
 *                 -translate-y-* (clears -translate-x-1/2 + translate-y-2)
 *   - Hide:     opacity-0, invisible, pointer-events-none
 *   - Reveal:   group-hover:opacity-N, group-hover:visible,
 *               group-hover:translate-[xy]-N (positive + negative),
 *               group-hover:pointer-events-*
 *
 * VISUAL classes (bg-*, border, shadow-*, rounded-*, py-*, min-w-*,
 * transition-*, duration-*, z-*) are preserved verbatim. Only the
 * ROOT element's class list is rewritten — any nested mega-menu layout
 * inside the captured panel keeps every class it had.
 *
 * @param string $html Captured panelHtml (verbatim from menus.json).
 * @return string      Sanitised panelHtml safe to embed inside the
 *                     EC-NAV-185 wpconvert-rich-panel-content wrapper.
 */
/**
 * EC-NAV-372: re-base root-relative hrefs inside a captured dropdown panel.
 *
 * Panel markup is emitted verbatim, so href="/solutions-bms/" resolves against
 * the SERVER root. That is right for a site installed at "/" and wrong for one
 * in a subdirectory, where the page actually lives at "/mysite/solutions-bms/".
 * Rewriting through home_url() makes the same captured HTML correct for both.
 *
 * Deliberately narrow: single-slash paths only. Protocol-relative ("//cdn…"),
 * absolute, mailto/tel, and in-page anchors are all left untouched.
 */
function wpconvert_resolve_panel_relative_hrefs($html) {
    if (!is_string($html) || $html === '') return $html;
    return preg_replace_callback(
        '/\shref="(\/(?!\/)[^"]*)"/i',
        function ($m) {
            return ' href="' . esc_url(home_url($m[1])) . '"';
        },
        $html
    );
}

/**
 * EC-NAV-MEGA-003: was this captured panel authored as a FULL-BLEED header
 * overlay rather than as a nav-item dropdown?
 *
 * A dropdown declares its own size (min-w-*, or left-1/2 + -translate-x-1/2 to
 * centre on its trigger). A full-bleed panel declares width only by STRETCHING:
 * absolutely positioned and pinned to both horizontal edges of its containing
 * block, which in the source is the full-width header bar. Its inner card does
 * the sizing (max-w-7xl mx-auto) and its px-* become page gutters.
 *
 * Must be called BEFORE wpconvert_neutralize_rich_panel_root_positioning(),
 * which strips the very classes this reads.
 *
 * Only the ROOT element is inspected: nested full-width decoration (a
 * "left-0 right-0" hairline divider, say) is not the panel's own contract, and
 * acting on it would stretch an ordinary popover across the viewport.
 *
 * @param string $html Captured panelHtml (verbatim from menus.json).
 * @return bool        True when the panel needs viewport-wide geometry.
 */
function wpconvert_rich_panel_is_full_bleed($html) {
    if (!is_string($html) || $html === '') return false;
    if (!preg_match('/^\s*<div\b[^>]*>/i', $html, $tag)) return false;
    if (!preg_match('/\bclass=["\']([^"\']*)["\']/i', $tag[0], $cls)) return false;
    $tokens = preg_split('/\s+/', trim($cls[1]));
    if (!is_array($tokens)) return false;
    if (!in_array('absolute', $tokens, true) && !in_array('fixed', $tokens, true)) return false;
    $stretch_sets = array(
        array('left-0', 'right-0'),
        array('inset-x-0'),
        array('inset-0'),
        array('w-screen'),
    );
    foreach ($stretch_sets as $set) {
        $all = true;
        foreach ($set as $needle) {
            if (!in_array($needle, $tokens, true)) { $all = false; break; }
        }
        if ($all) return true;
    }
    return false;
}

function wpconvert_neutralize_rich_panel_root_positioning($html) {
    if (!is_string($html) || $html === '') return $html;
    // Only the first opening <div ...> at the start of the fragment is
    // the captured panel root. Limit the regex to one substitution so
    // nested divs (inner mega-menu rows / icon grids) are never touched.
    return preg_replace_callback(
        '/^(\s*<div\b)([^>]*)(>)/i',
        function ($m) {
            $attrs = $m[2];
            // Find class="..." within attributes and rewrite it.
            $attrs = preg_replace_callback(
                '/(\bclass=")([^"]*)(")/i',
                function ($cm) {
                    $tokens = preg_split('/\s+/', trim($cm[2]));
                    if (!is_array($tokens)) return $cm[0];
                    // Patterns matched against each whole class token.
                    $strip_patterns = array(
                        '/^(absolute|fixed|sticky)$/',
                        '/^-?(top|bottom|left|right)-/',
                        '/^-?mt-/',
                        '/^-?translate-[xy]-/',
                        '/^opacity-0$/',
                        '/^invisible$/',
                        '/^pointer-events-none$/',
                        '/^group-hover:opacity-/',
                        '/^group-hover:visible$/',
                        '/^group-hover:-?translate-[xy]-/',
                        '/^group-hover:pointer-events-/',
                    );
                    $kept = array();
                    foreach ($tokens as $tok) {
                        if ($tok === '') continue;
                        $strip = false;
                        foreach ($strip_patterns as $pat) {
                            if (preg_match($pat, $tok)) { $strip = true; break; }
                        }
                        if (!$strip) $kept[] = $tok;
                    }
                    return $cm[1] . implode(' ', $kept) . $cm[3];
                },
                $attrs,
                1
            );
            return $m[1] . $attrs . $m[3];
        },
        $html,
        1
    );
}

/**
 * Walker for dropdown menu structure with CSS hover support
 * Outputs proper dropdown panels that work with group-hover CSS
 */
class WPConvert_Dropdown_Menu_Walker extends Walker_Nav_Menu {
    private $link_classes = '';
    private $menu_data = null;
    private $is_mega_menu = false;
    /** EC-NAV-141: Many children, no grandchildren — wide 2-column panel (Smile Services list) */
    private $is_flat_wide_mega = false;
    private $active_link_classes = '';
    private $inactive_link_classes = '';
    
    function __construct($link_classes = '') {
        $this->link_classes = $link_classes ?: 'px-4 py-2 text-sm font-medium transition-colors rounded-md hover:bg-primary-foreground/10';
        $file = get_template_directory() . '/assets/data/menus.json';
        if (file_exists($file)) {
            $this->menu_data = json_decode(file_get_contents($file), true);
        }
        // EC-NAV-157: Read active/inactive link classes from menus.json for current page highlighting.
        // Instead of a generic bg-primary-foreground/10, swap the inactive text color class
        // (e.g. text-foreground) with the active class (e.g. text-primary) on current-menu-item.
        if ($this->menu_data && !empty($this->menu_data['primary'])) {
            $this->active_link_classes = $this->menu_data['primary']['activeLinkClasses'] ?? '';
            $this->inactive_link_classes = $this->menu_data['primary']['inactiveLinkClasses'] ?? '';
        }
    }
    
    private function apply_active_classes($class_str) {
        if (empty($this->active_link_classes)) {
            return $class_str . ' bg-primary-foreground/10';
        }
        $inactive = array_filter(explode(' ', $this->inactive_link_classes));
        $active = array_filter(explode(' ', $this->active_link_classes));
        $classes = array_filter(explode(' ', $class_str));
        $classes = array_diff($classes, $inactive);
        $classes = array_merge($classes, $active);
        return implode(' ', array_unique($classes));
    }
    
    // Check if a top-level item has grandchildren (3-level mega menu)
    private function item_has_grandchildren($item_title) {
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) return false;
        foreach ($this->menu_data['primary']['items'] as $json_item) {
            if (strtolower(trim($json_item['title'] ?? '')) === strtolower(trim($item_title))) {
                if (!empty($json_item['children'])) {
                    foreach ($json_item['children'] as $child) {
                        if (!empty($child['children']) && count($child['children']) > 0) return true;
                    }
                }
                return false;
            }
        }
        return false;
    }

    /**
     * EC-NAV-390: the captured hover underline for a top-level item, or '' when it had none.
     * Guarded like the other optional helpers this walker reaches for, so the class stays
     * usable when it is loaded on its own.
     */
    private function hover_decoration_html($item_title) {
        if (!function_exists('wpconvert_nav_hover_decoration_html')) {
            return '';
        }
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) {
            return '';
        }
        $want = strtolower(trim((string) $item_title));
        foreach ($this->menu_data['primary']['items'] as $ji) {
            if (strtolower(trim($ji['title'] ?? '')) === $want) {
                return wpconvert_nav_hover_decoration_html($ji);
            }
        }
        return '';
    }

    /** EC-NAV-390: add the group/relative hooks the decoration needs, when there is one. */
    private function hover_decoration_class($hover_deco, $class_str) {
        if ($hover_deco === '' || !function_exists('wpconvert_nav_hover_decoration_class')) {
            return $class_str;
        }
        return wpconvert_nav_hover_decoration_class($hover_deco, $class_str);
    }

    /** EC-NAV-141: Flat child count from menus.json for dropdown mega (no hardcoded site names). */
    private function wpconvert_dropdown_flat_child_count_from_json($item_title) {
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) {
            return 0;
        }
        $want = strtolower(trim((string) $item_title));
        foreach ($this->menu_data['primary']['items'] as $ji) {
            if (strtolower(trim($ji['title'] ?? '')) === $want) {
                return is_array($ji['children'] ?? null) ? count($ji['children']) : 0;
            }
        }
        return 0;
    }
    
    private function get_column_count($item_title) {
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) return 2;
        foreach ($this->menu_data['primary']['items'] as $json_item) {
            if (strtolower(trim($json_item['title'] ?? '')) === strtolower(trim($item_title))) {
                return min(count($json_item['children'] ?? []), 4);
            }
        }
        return 2;
    }

    /**
     * EC-NAV-185: Look up captured rich-popover HTML for a top-level item.
     *
     * The Path A hover-snapshot pipeline (lib/render/hover-panels.js) hovers
     * each dropdown trigger in Puppeteer at conversion time and records the
     * just-revealed panel HTML on the menus.json item under `panelHtml`.
     * When present, the walker emits that captured panel verbatim instead of
     * reconstructing a generic <ul><li> mega-menu — preserving the original
     * Lovable / shadcn icon + title + description grid one-for-one.
     *
     * @param string $item_title  Top-level menu item title from WordPress.
     * @return string|null        Verbatim panel HTML, or null when not captured.
     */
    private function lookup_panel_html($item_title) {
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) return null;
        $want = strtolower(trim((string)$item_title));
        if ($want === '') return null;
        $loc = function_exists('wpconvert_request_locale') ? wpconvert_request_locale() : '';
        foreach ($this->menu_data['primary']['items'] as $json_item) {
            if (empty($json_item['panelHtml']) || !is_string($json_item['panelHtml'])) continue;
            if (strtolower(trim((string)($json_item['title'] ?? ''))) !== $want) continue;
            // EC-I18N-PANEL-001: the panel was captured in one language; ship the
            // request locale's translation of it when the conversion built one.
            if ($loc !== '' && !empty($json_item['panelHtmlLocales'][$loc]) && is_string($json_item['panelHtmlLocales'][$loc])) {
                return $json_item['panelHtmlLocales'][$loc];
            }
            return $json_item['panelHtml'];
        }
        return null;
    }

    /**
     * EC-I18N-PANEL-001: the trigger's label in the request locale.
     *
     * The panel branch below prints the WordPress item title, which is the
     * capture's language forever — the core-walker filters (EC-I18N-URL-MENU-002)
     * cannot reach it because this walker builds its own markup. Reuse the same
     * menus.json localization every other menu surface uses.
     *
     * @param string $item_title
     * @return string
     */
    private function localized_trigger_title($item_title) {
        $title = (string) $item_title;
        if (!function_exists('wpconvert_localize_menu_item') || !$this->menu_data || empty($this->menu_data['primary']['items'])) {
            return $title;
        }
        $want = strtolower(trim($title));
        if ($want === '') return $title;
        foreach ($this->menu_data['primary']['items'] as $json_item) {
            if (!is_array($json_item)) continue;
            if (strtolower(trim((string)($json_item['title'] ?? ''))) !== $want) continue;
            $loc = wpconvert_localize_menu_item($json_item);
            if (is_array($loc) && !empty($loc['title'])) return (string) $loc['title'];
            return $title;
        }
        return $title;
    }

    /**
     * EC-NAV-MEGA-004: the captured panel's alternate states, if any.
     *
     * A mega panel is often two widgets: this dropdown, plus a state selector
     * inside it (category rail, tab strip) whose controls swap the panel's other
     * half without navigating. The capture pass drives that selector and records
     * the rendered DOM for every state; this returns them for emission.
     *
     * @param string $item_title
     * @return array|null
     */
    private function lookup_panel_states($item_title) {
        if (!$this->menu_data || empty($this->menu_data['primary']['items'])) return null;
        $want = strtolower(trim((string)$item_title));
        if ($want === '') return null;
        foreach ($this->menu_data['primary']['items'] as $json_item) {
            if (strtolower(trim((string)($json_item['title'] ?? ''))) !== $want) continue;
            if (empty($json_item['panelStates']['states'])) return null;
            $states = $json_item['panelStates']['states'];
            if (!is_array($states) || count($states) < 2) return null;
            return $json_item['panelStates'];
        }
        return null;
    }

    /**
     * EC-NAV-185: Override Walker recursion so a top-level item carrying
     * captured panelHtml emits the trigger + verbatim panel and skips the
     * usual child traversal entirely. Falls through to parent::display_element
     * for every other item so the existing flat / mega / wide-mega code paths
     * (start_lvl / start_el / end_lvl) are completely unaffected.
     *
     * Children are deliberately suppressed because the captured panel HTML
     * already contains the visible links / icons / descriptions; running the
     * `<ul><li>` walker on top of that would duplicate every link.
     */
    function display_element($element, &$children_elements, $max_depth, $depth, $args, &$output) {
        if ($depth === 0 && $element && isset($element->title)) {
            $panel_html = $this->lookup_panel_html($element->title);
            if ($panel_html !== null) {
                // EC-NAV-MEGA-003: classify BEFORE neutralising — the full-bleed
                // contract is expressed by the very classes the next step strips.
                $is_full_bleed = function_exists('wpconvert_rich_panel_is_full_bleed')
                    ? wpconvert_rich_panel_is_full_bleed($panel_html)
                    : false;
                // EC-NAV-DROPDOWN-003: strip the captured panel root's
                // positioning + visibility classes so it sits in normal
                // flow inside the wrapper below. Without this, the
                // captured "absolute top-full left-0 mt-1
                // pointer-events-none ..." classes leave the wrapper at
                // 0 x pt-2 (8px) and the 12px gap between trigger and
                // panel is un-hoverable — the dropdown collapses the
                // moment the cursor leaves the trigger text. See helper
                // docblock above for the full strip rules.
                if (function_exists('wpconvert_neutralize_rich_panel_root_positioning')) {
                    $panel_html = wpconvert_neutralize_rich_panel_root_positioning($panel_html);
                }
                // EC-NAV-372: captured panel markup ships verbatim, so any
                // root-relative href inside it is resolved against the SERVER
                // root — correct for a site at "/", broken for one installed in
                // a subdirectory. Re-base them through home_url() at runtime.
                if (function_exists('wpconvert_resolve_panel_relative_hrefs')) {
                    $panel_html = wpconvert_resolve_panel_relative_hrefs($panel_html);
                }
                // EC-NAV-185: emit captured rich panel inside group-hover wrapper.
                $link_class = $this->link_classes . ' flex items-center gap-1';
                // EC-NAV-390: a rich-panel trigger is a <button>, but it stands in for the
                // same source link as every sibling — without this it is the one item in the
                // row with no hover underline.
                $hover_deco = $this->hover_decoration_html($element->title);
                $link_class = $this->hover_decoration_class($hover_deco, $link_class);
                $output .= '<div class="relative group wpconvert-nav-rich-panel" data-wpc-rich-panel="1">';
                $output .= '<button type="button" class="' . esc_attr($link_class) . '" aria-haspopup="true">';
                $output .= esc_html($this->localized_trigger_title($element->title));
                // EC-NAV-219: skip SVG chevron when the title already contains a trailing arrow glyph
                // (e.g. aura-lace "Boutique ▾") so the link doesn't render two stacked arrows.
                if (!wpconvert_title_has_trailing_arrow($element->title) && (!function_exists('wpconvert_emit_dropdown_chevron') || wpconvert_emit_dropdown_chevron())) {
                $output .= '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="' . (function_exists('wpconvert_nav_icon_stroke') ? esc_attr(wpconvert_nav_icon_stroke()) : 'currentColor') . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-3.5 w-3.5"><path d="m6 9 6 6 6-6"></path></svg>';
                }
                $output .= $hover_deco;
                $output .= '</button>';
                // EC-NAV-MEGA-003: a panel authored as a full-width header
                // overlay gets a modifier class; the generated header CSS/JS
                // hand it back the viewport width its containing block lost.
                $panel_wrapper_class = 'absolute top-full left-0 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-150 z-50 wpconvert-rich-panel-content';
                if ($is_full_bleed) {
                    $panel_wrapper_class .= ' wpconvert-rich-panel-content--fullbleed';
                }
                $output .= '<div class="' . esc_attr($panel_wrapper_class) . '">';
                $output .= $panel_html; // sanitised captured panel — wrapper bridges hover gap
                $output .= '</div>';
                // EC-NAV-MEGA-004: the captured panel's alternate states, as an
                // inert JSON payload AFTER the panel. It must never precede the
                // panel: wpconvert_rich_panel_is_full_bleed() and
                // wpconvert_neutralize_rich_panel_root_positioning() are both
                // anchored on the fragment STARTING with the captured root div.
                // A <script> is display:none and non-interactive, so it adds no
                // geometry and no hit target (EC-NAV-DROPDOWN-006).
                $panel_states = $this->lookup_panel_states($element->title);
                if ($panel_states) {
                    // EC-NAV-372: the swapped-in markup carries the same
                    // root-relative hrefs as the panel, so re-base it identically.
                    if (function_exists('wpconvert_resolve_panel_relative_hrefs')) {
                        foreach ($panel_states['states'] as $i => $state) {
                            if (isset($state['innerHtml']) && is_string($state['innerHtml'])) {
                                $panel_states['states'][$i]['innerHtml'] =
                                    wpconvert_resolve_panel_relative_hrefs($state['innerHtml']);
                            }
                        }
                    }
                    $json = function_exists('wp_json_encode')
                        ? wp_json_encode($panel_states)
                        : json_encode($panel_states);
                    if (is_string($json) && $json !== '') {
                        // Escape the angle bracket so captured markup cannot
                        // terminate the script element.
                        $json = str_replace('<', '\u003c', $json);
                        $output .= '<script type="application/json" class="wpconvert-panel-states">'
                                 . $json . '</script>';
                    }
                }
                $output .= '</div>';
                return; // skip parent::display_element ⇒ no start_el / start_lvl / child traversal
            }
        }
        parent::display_element($element, $children_elements, $max_depth, $depth, $args, $output);
    }

    function start_lvl(&$output, $depth = 0, $args = null) {
        // EC-NAV-DROPDOWN-002: emit a two-element structure — an OUTER
        // wpconvert-dropdown-wrapper that carries position + opacity +
        // transition + pt-2 (so the trigger to panel gap is hoverable
        // padding, not un-hoverable margin), and an INNER
        // wpconvert-dropdown-panel that carries the visible surface
        // styling (background, shadow, border, padding). The original
        // React Header.tsx uses the same shape:
        //   absolute left-0 top-full z-50 pt-2  >  bg-background shadow-card
        if ($depth === 0) {
            if ($this->is_mega_menu) {
                $output .= '<div class="wpconvert-dropdown-wrapper absolute left-1/2 -translate-x-1/2 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                $output .= '<div class="wpconvert-dropdown-panel wpconvert-mega-menu rounded-xl shadow-card bg-background border border-border p-4" style="min-width:600px;max-width:90vw"><div class="wpconvert-mega-grid" style="display:grid;grid-template-columns:repeat(' . $this->mega_cols . ',1fr);gap:1.5rem">';
            } else if ($this->is_flat_wide_mega) {
                $output .= '<div class="wpconvert-dropdown-wrapper absolute left-0 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                $output .= '<div class="wpconvert-dropdown-panel wpconvert-dropdown-panel--flat-mega rounded-xl shadow-card bg-background border border-border p-3"><div class="wpconvert-dropdown-flat-mega-inner">';
            } else {
                $output .= '<div class="wpconvert-dropdown-wrapper absolute left-0 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                $output .= '<div class="wpconvert-dropdown-panel min-w-max rounded-md shadow-card bg-background border border-border">';
            }
        } else if ($depth === 1 && $this->is_mega_menu) {
            $output .= '<div class="space-y-0" style="max-height:300px;overflow-y:auto">';
        } else {
            $output .= '<div class="pl-4">';
        }
    }
    
    function end_lvl(&$output, $depth = 0, $args = null) {
        // EC-NAV-DROPDOWN-002: close BOTH the outer wrapper and the
        // inner panel — plus the inner grid/flat-mega container for
        // those variants. Three divs for mega / flat-mega, two for
        // regular dropdowns.
        if ($depth === 0 && $this->is_mega_menu) {
            $output .= '</div></div></div>';
            $this->is_mega_menu = false;
        } else if ($depth === 0 && $this->is_flat_wide_mega) {
            $output .= '</div></div></div>';
            $this->is_flat_wide_mega = false;
        } else if ($depth === 0) {
            // Regular dropdown — wrapper + panel.
            $output .= '</div></div>';
        } else {
            $output .= '</div>';
        }
    }
    
    function start_el(&$output, $item, $depth = 0, $args = null, $id = 0) {
        $has_children = in_array('menu-item-has-children', $item->classes);
        $is_current = in_array('current-menu-item', $item->classes) ||
                      in_array('current_page_item', $item->classes);

        // EC-I18N-URL-MENU-001e: the label and href this render should SHOW.
        // $item->title stays as captured because every menus.json lookup below
        // (mega columns, flat-wide panel, hover underline, CTA match) keys off
        // it — translating the item itself would collapse the dropdown.
        $wpc_display_title = (string) ($item->title ?? '');
        $wpc_href = (string) ($item->url ?? '');
        if (function_exists('wpconvert_localize_wp_nav_item')) {
            $wpc_loc = wpconvert_localize_wp_nav_item($item);
            if (!empty($wpc_loc['title'])) $wpc_display_title = (string) $wpc_loc['title'];
            if (!empty($wpc_loc['url'])) $wpc_href = (string) $wpc_loc['url'];
        }

        // EC-NAV-187 / EC-NAV-187b: Suppress current-page state for
        // non-navigating placeholder URLs.
        //
        // WordPress core marks any custom-link menu item as current-menu-item
        // when its computed URL matches the current request. For an item with
        // source url = "#" (a dropdown-trigger placeholder), wpconvert imports
        // it via the EC-NAV-055 anchor branch as menu-item-url =
        // home_url("/") concatenated with "#" — i.e. an absolute URL like
        // https://playground.wp.net/scope:foo/ followed by a hash. WPs URL
        // comparator strips the fragment, gets the home URL back, matches
        // the front-page request, and every dropdown trigger (Products,
        // Solutions, Pricing, etc.) flips current at once on the home page.
        // apply_active_classes() then paints bg-primary-foreground/10 — a
        // translucent gray pill — around every single menu item, which the
        // user perceives as "boxes" around every nav item even with no
        // dropdown open.
        //
        // Suppression rule: an item is a non-destination if its URL contains
        // a "#" AND the part before the fragment is empty / "/" / the site
        // root URL. That covers all of:
        //   - "" (empty)
        //   - "#"
        //   - "#anchor"
        //   - "/#" or "/#anchor"
        //   - "https://site/#" (resolved by EC-NAV-055)
        //   - "https://site#"  (no trailing slash — defensive)
        //   - "https://site/#anchor"
        // Items with a real path before the "#" (e.g. "/about#team") are
        // legitimate in-page anchors on a sub-page — those must still flow
        // through the normal current-page logic so a user on /about with an
        // "About > Team" anchor menu item gets the highlight.
        $item_href = (string) ($item->url ?? '');
        if ($is_current) {
            $hash_pos = strpos($item_href, '#');
            $is_placeholder = false;
            if ($item_href === '') {
                $is_placeholder = true;
            } elseif ($hash_pos !== false) {
                $prefix = substr($item_href, 0, $hash_pos);
                $home_root = rtrim((string) home_url('/'), '/');
                $prefix_trimmed = rtrim($prefix, '/');
                if ($prefix === '' || $prefix === '/' || $prefix_trimmed === '' || $prefix_trimmed === $home_root) {
                    $is_placeholder = true;
                }
            }
            if ($is_placeholder) {
                $is_current = false;
            }
        }

        // EC-NAV-023/CTA-001: Check if this item is a CTA/button
        if ($depth === 0 && $this->menu_data && !empty($this->menu_data['primary']['items'])) {
            foreach ($this->menu_data['primary']['items'] as $json_item) {
                $has_json_children = !empty($json_item['children']) && is_array($json_item['children']) && count($json_item['children']) > 0;
                $is_cta = !empty($json_item['isButton']) && !$has_json_children;
                if (!$is_cta && !empty($json_item['classes']) && is_array($json_item['classes'])) {
                    $is_cta = function_exists('wpconvert_is_cta_by_classes') && wpconvert_is_cta_by_classes($json_item['classes']);
                }
                if ($is_cta && !empty($json_item['classes']) && is_array($json_item['classes'])) {
                    $title_match = strtolower(trim($item->title)) === strtolower(trim($json_item['title'] ?? ''));
                    $url_match = rtrim($item->url ?: '', '/') === rtrim($json_item['url'] ?? '', '/');
                    if ($title_match || $url_match) {
                        $btn_classes = implode(' ', $json_item['classes']);
                        $wpc_id = $json_item['wpcId'] ?? 'wpc_navbtn_' . md5($item->title . ($item->url ?: ''));
                        $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="' . esc_attr(trim($btn_classes)) . '" data-wpc-id="' . esc_attr($wpc_id) . '" data-wpc-editable="button">';
                        $output .= esc_html($wpc_display_title);
                        return;
                    }
                }
            }
        }
        
        if ($depth === 0) {
            if ($has_children) {
                $this->is_mega_menu = $this->item_has_grandchildren($item->title);
                if ($this->is_mega_menu) {
                    $this->is_flat_wide_mega = false;
                    $this->mega_cols = $this->get_column_count($item->title);
                } else {
                    $flat_n = $this->wpconvert_dropdown_flat_child_count_from_json($item->title);
                    $this->is_flat_wide_mega = ($flat_n >= 8);
                }
                $output .= '<div class="relative group">';
                // EC-NAV-186: whitespace-nowrap prevents multi-word labels (e.g. "How It Works")
                // from wrapping to two lines inside the flex row, which made items look like
                // tall stacked boxes. Sub-walker dropdown items already get this; top-level needs it too.
                $link_class = $this->link_classes . ' flex items-center gap-1 whitespace-nowrap';
                if ($is_current) $link_class = $this->apply_active_classes($link_class);
                // EC-NAV-390: redraw the hover underline the source link carried.
                $hover_deco = $this->hover_decoration_html($item->title);
                $link_class = $this->hover_decoration_class($hover_deco, $link_class);
                $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="' . esc_attr($link_class) . '">';
                $output .= esc_html($wpc_display_title);
                // EC-NAV-219: skip SVG chevron when title already has a trailing arrow glyph
                if (!wpconvert_title_has_trailing_arrow($wpc_display_title) && (!function_exists('wpconvert_emit_dropdown_chevron') || wpconvert_emit_dropdown_chevron())) {
                $output .= '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="' . (function_exists('wpconvert_nav_icon_stroke') ? esc_attr(wpconvert_nav_icon_stroke()) : 'currentColor') . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4"><path d="m6 9 6 6 6-6"></path></svg>';
                }
                $output .= $hover_deco;
                $output .= '</a>';
            } else {
                // EC-NAV-186: same nowrap protection for leaf top-level items.
                $link_class = $this->link_classes . ' whitespace-nowrap';
                if ($is_current) $link_class = $this->apply_active_classes($link_class);
                // EC-NAV-390: redraw the hover underline the source link carried.
                $hover_deco = $this->hover_decoration_html($item->title);
                $link_class = $this->hover_decoration_class($hover_deco, $link_class);
                $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="' . esc_attr($link_class) . '">';
                $output .= esc_html($wpc_display_title);
                $output .= $hover_deco;
            }
        } else if ($depth === 1 && $this->is_mega_menu) {
            if ($has_children) {
                $output .= '<div>';
                $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="block px-2 py-1 text-xs font-semibold uppercase tracking-wider text-muted-foreground hover:text-primary transition-colors mb-1">';
                $output .= esc_html($wpc_display_title);
                $output .= '</a>';
            } else {
                $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="block px-2 py-1.5 text-sm rounded-md hover:bg-accent/10 transition-colors">';
                $output .= esc_html($wpc_display_title);
            }
        } else if ($depth === 2 && $this->is_mega_menu) {
            $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="block px-2 py-1.5 text-sm rounded-md hover:bg-accent/10 transition-colors">';
            $output .= esc_html($wpc_display_title);
        } else {
            $dropdown_class = 'block px-4 py-2 text-sm hover:bg-accent/10 transition-colors whitespace-nowrap';
            if ($is_current) $dropdown_class .= ' bg-accent/10';
            $output .= '<a href="' . wpconvert_nav_item_href($wpc_href) . '" class="' . esc_attr($dropdown_class) . '">';
            $output .= esc_html($wpc_display_title);
        }
    }
    
    function end_el(&$output, $item, $depth = 0, $args = null) {
        $has_children = in_array('menu-item-has-children', $item->classes);
        
        if ($depth === 0 && !$has_children) {
            $output .= '</a>';
        } else if ($depth === 0 && $has_children) {
            $output .= '</div>';
        } else if ($depth === 1 && $this->is_mega_menu && $has_children) {
            $output .= '</div>';
        } else {
            $output .= '</a>';
        }
    }
}

/**
 * EC-I18N-URL-MENU-001e: the label + href a submenu row should render under the
 * request locale. Returns the captured values untouched on single-language
 * sites, so their markup is byte-identical.
 * @param array $child
 * @return array{title:string,url:string}
 */
function wpconvert_localized_submenu_pair($child) {
    $url = (is_array($child) && !empty($child['url'])) ? $child['url'] : '/';
    $title = (is_array($child) && isset($child['title'])) ? (string) $child['title'] : '';
    if (function_exists('wpconvert_localize_menu_item')) {
        $loc = wpconvert_localize_menu_item($child);
        if (!empty($loc['title'])) $title = (string) $loc['title'];
        if (!empty($loc['url']) && $loc['url'] !== '#') $url = (string) $loc['url'];
    }
    return array('title' => $title, 'url' => $url);
}

/**
 * Fallback dropdown menu from menus.json when WordPress menu isn't configured
 * Outputs same structure as WPConvert_Dropdown_Menu_Walker for consistent styling
 */
function wpconvert_dropdown_fallback_menu($link_classes = '') {
    $json_path = get_template_directory() . '/assets/data/menus.json';
    if (!file_exists($json_path)) {
        return;
    }
    
    $menu_data = json_decode(file_get_contents($json_path), true);
    if (empty($menu_data['primary']['items'])) {
        return;
    }
    
    $link_classes = $link_classes ?: 'px-4 py-2 text-sm font-medium transition-colors rounded-md hover:bg-primary-foreground/10';
    
    // EC-NAV-157: Read active/inactive link classes for current page highlighting
    $active_cls = !empty($menu_data['primary']['activeLinkClasses']) ? $menu_data['primary']['activeLinkClasses'] : '';
    $inactive_cls = !empty($menu_data['primary']['inactiveLinkClasses']) ? $menu_data['primary']['inactiveLinkClasses'] : '';
    
    foreach ($menu_data['primary']['items'] as $item) {
        $has_children = !empty($item['children']) && is_array($item['children']) && count($item['children']) > 0;
        $raw_url = $item['url'] ?? '/';
        $display_title = $item['title'] ?? '';
        // EC-I18N-URL-MENU-001e: show the request locale's label and route.
        // $item keeps its captured title so the panel/decoration lookups below
        // still recognise the row.
        if (function_exists('wpconvert_localize_menu_item')) {
            $loc = wpconvert_localize_menu_item($item);
            if (!empty($loc['title'])) $display_title = $loc['title'];
            if (!empty($loc['url']) && $loc['url'] !== '#') $raw_url = $loc['url'];
        }
        $url = (is_string($raw_url) && preg_match('#^https?://#i', $raw_url)) ? esc_url($raw_url) : esc_url(home_url($raw_url));
        $title = esc_html($display_title);
        
        // EC-NAV-157: Detect current page for active state highlighting
        $current_path = wp_parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH) ?: '/';
        $item_path = wp_parse_url($raw_url, PHP_URL_PATH) ?: $raw_url;
        $is_current = (rtrim($current_path, '/') === rtrim($item_path, '/'));
        
        // Apply active classes: swap inactive with active
        $item_link_classes = $link_classes;
        if ($is_current && $active_cls) {
            $inactive_arr = array_filter(explode(' ', $inactive_cls));
            $active_arr = array_filter(explode(' ', $active_cls));
            $cls_arr = array_filter(explode(' ', $item_link_classes));
            $cls_arr = array_diff($cls_arr, $inactive_arr);
            $cls_arr = array_merge($cls_arr, $active_arr);
            $item_link_classes = implode(' ', array_unique($cls_arr));
        } elseif ($is_current) {
            $item_link_classes .= ' bg-primary-foreground/10';
        }
        
        if ($has_children) {
            // Check if any child has grandchildren (3-level mega menu)
            $has_grandchildren = false;
            foreach ($item['children'] as $child) {
                if (!empty($child['children']) && count($child['children']) > 0) {
                    $has_grandchildren = true;
                    break;
                }
            }
            
            // EC-NAV-390: redraw the hover underline the source link carried.
            $hover_deco = wpconvert_nav_hover_decoration_html($item);
            $parent_link_classes = wpconvert_nav_hover_decoration_class($hover_deco, $item_link_classes . ' flex items-center gap-1');
            echo '<div class="relative group">';
            echo '<a href="' . $url . '" class="' . esc_attr($parent_link_classes) . '">';
            echo $title;
            // EC-NAV-219: skip SVG chevron when title already has a trailing arrow glyph
            // ($title was esc_html'd above so use $item['title'] for the raw glyph check)
            if (!wpconvert_title_has_trailing_arrow($item['title'] ?? '') && (!function_exists('wpconvert_emit_dropdown_chevron') || wpconvert_emit_dropdown_chevron())) {
            echo '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="' . (function_exists('wpconvert_nav_icon_stroke') ? esc_attr(wpconvert_nav_icon_stroke()) : 'currentColor') . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4"><path d="m6 9 6 6 6-6"></path></svg>';
            }
            echo $hover_deco;
            echo '</a>';
            
            if ($has_grandchildren) {
                // EC-NAV-DROPDOWN-002: mega-menu — outer hover-bridge wrapper
                // (pt-2 padding, hoverable) + inner visible panel
                // (bg-background, shadow-card, border).
                echo '<div class="wpconvert-dropdown-wrapper absolute left-1/2 -translate-x-1/2 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                echo '<div class="wpconvert-dropdown-panel wpconvert-mega-menu rounded-xl shadow-card bg-background border border-border p-4" style="min-width:600px;max-width:90vw">';
                echo '<div style="display:grid;grid-template-columns:repeat(' . min(count($item['children']), 4) . ',1fr);gap:1.5rem">';
                foreach ($item['children'] as $child) {
                    $child_loc = function_exists('wpconvert_localized_submenu_pair')
                        ? wpconvert_localized_submenu_pair($child)
                        : array('title' => (string) ($child['title'] ?? ''), 'url' => (string) ($child['url'] ?? '/'));
                    $raw_cm = $child_loc['url'];
                    $child_url = (is_string($raw_cm) && preg_match('#^https?://#i', $raw_cm)) ? esc_url($raw_cm) : esc_url(home_url($raw_cm));
                    $child_title = esc_html($child_loc['title']);
                    echo '<div>';
                    echo '<a href="' . $child_url . '" class="block px-2 py-1 text-xs font-semibold uppercase tracking-wider text-muted-foreground hover:text-primary transition-colors mb-1">' . $child_title . '</a>';
                    if (!empty($child['children'])) {
                        echo '<div class="space-y-0" style="max-height:300px;overflow-y:auto">';
                        foreach ($child['children'] as $gc) {
                            $gc_loc = function_exists('wpconvert_localized_submenu_pair')
                                ? wpconvert_localized_submenu_pair($gc)
                                : array('title' => (string) ($gc['title'] ?? ''), 'url' => (string) ($gc['url'] ?? '/'));
                            $raw_gcm = $gc_loc['url'];
                            $gc_url = (is_string($raw_gcm) && preg_match('#^https?://#i', $raw_gcm)) ? esc_url($raw_gcm) : esc_url(home_url($raw_gcm));
                            $gc_title = esc_html($gc_loc['title']);
                            echo '<a href="' . $gc_url . '" class="block px-2 py-1.5 text-sm rounded-md hover:bg-accent/10 transition-colors">' . $gc_title . '</a>';
                        }
                        echo '</div>';
                    }
                    echo '</div>';
                }
                echo '</div>';
                echo '</div>';
                echo '</div>';
            } else {
                $flat_n = count($item['children']);
                if ($flat_n >= 8) {
                    // EC-NAV-DROPDOWN-002: flat-mega — wrapper + panel.
                    echo '<div class="wpconvert-dropdown-wrapper absolute left-0 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                    echo '<div class="wpconvert-dropdown-panel wpconvert-dropdown-panel--flat-mega rounded-xl shadow-card bg-background border border-border p-3">';
                    echo '<div class="wpconvert-dropdown-flat-mega-inner">';
                    foreach ($item['children'] as $child) {
                        $child_loc = function_exists('wpconvert_localized_submenu_pair')
                            ? wpconvert_localized_submenu_pair($child)
                            : array('title' => (string) ($child['title'] ?? ''), 'url' => (string) ($child['url'] ?? '/'));
                        $raw_c2 = $child_loc['url'];
                        $child_url = (is_string($raw_c2) && preg_match('#^https?://#i', $raw_c2)) ? esc_url($raw_c2) : esc_url(home_url($raw_c2));
                        $child_title = esc_html($child_loc['title']);
                        echo '<a href="' . $child_url . '" class="block px-4 py-2 text-sm hover:bg-accent/10 transition-colors whitespace-nowrap">' . $child_title . '</a>';
                    }
                    echo '</div></div></div>';
                } else {
                // EC-NAV-DROPDOWN-002: regular dropdown — wrapper + panel.
                echo '<div class="wpconvert-dropdown-wrapper absolute left-0 top-full z-50 pt-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">';
                echo '<div class="wpconvert-dropdown-panel min-w-max rounded-md shadow-card bg-background border border-border">';
                foreach ($item['children'] as $child) {
                    $child_loc = function_exists('wpconvert_localized_submenu_pair')
                        ? wpconvert_localized_submenu_pair($child)
                        : array('title' => (string) ($child['title'] ?? ''), 'url' => (string) ($child['url'] ?? '/'));
                    $raw_c2 = $child_loc['url'];
                    $child_url = (is_string($raw_c2) && preg_match('#^https?://#i', $raw_c2)) ? esc_url($raw_c2) : esc_url(home_url($raw_c2));
                    $child_title = esc_html($child_loc['title']);
                    echo '<a href="' . $child_url . '" class="block px-4 py-2 text-sm hover:bg-accent/10 transition-colors whitespace-nowrap">' . $child_title . '</a>';
                }
                echo '</div></div>';
                }
            }
            echo '</div>';
        } else {
            // EC-NAV-390: redraw the hover underline the source link carried.
            $hover_deco = wpconvert_nav_hover_decoration_html($item);
            $leaf_link_classes = wpconvert_nav_hover_decoration_class($hover_deco, $item_link_classes);
            echo '<a href="' . $url . '" class="' . esc_attr($leaf_link_classes) . '">' . $title . $hover_deco . '</a>';
        }
    }
}

/**
 * Convert static site URL (.html) to WordPress permalink
 * @param string $url Original URL from static site
 * @return string WordPress-friendly URL
 */
function wpconvert_convert_static_url($url) {
    // Skip empty, simple hash anchor, or external URLs
    if (empty($url) || $url === '#' || preg_match('#^https?://#i', $url)) {
        return $url;
    }

    // EC-NAV-168: Separate hash fragment from the URL before processing.
    // Static sites use "page.html#section" — the fragment must survive URL conversion.
    $hash_fragment = '';
    $hash_pos = strpos($url, '#');
    if ($hash_pos !== false && $hash_pos > 0) {
        $hash_fragment = substr($url, $hash_pos);
        $url = substr($url, 0, $hash_pos);
    }

    // EC-NAV-122: menus.json in-page anchors (#section) → front-page URL + fragment so links work
    // from inner pages (bare #section is resolved against the current document only).
    if (strlen($url) > 0 && $url[0] === '#' && strpos($url, '#/') !== 0) {
        $frag = substr($url, 1);
        if (preg_match('/^[A-Za-z][\w-]*$/', $frag)) {
            return esc_url(trailingslashit(home_url('/')) . '#' . $frag);
        }
    }
    
    // Convert hash-based SPA routes (#/about) to regular routes (/about)
    if (strpos($url, '#/') === 0) {
        $url = substr($url, 1); // Remove #, keep /
    }
    
    // Convert index.html to home
    if ($url === 'index.html' || $url === '/index.html' || $url === './index.html') {
        return home_url('/') . $hash_fragment;
    }
    
    // Convert .html files to WordPress permalinks
    if (preg_match('#\.html?$#i', $url)) {
        $slug = preg_replace('#\.html?$#i', '', $url);     // Strip .html/.htm
        $slug = preg_replace('#^\.\.?/#', '', $slug);      // Strip leading ./ or ../
        $slug = trim($slug, '/');                            // Remove leading/trailing slashes
        
        // For paths like "pages/shop", use just "shop"
        $slug_parts = explode('/', $slug);
        $simple_slug = end($slug_parts);
        
        return home_url('/' . $simple_slug . '/') . $hash_fragment;
    }
    
    // Already a WordPress-style URL
    if (strpos($url, '/') === 0) {
        return home_url($url) . $hash_fragment;
    }

    // Bare paths without a leading slash (e.g. menus.json "blog/", "about/"). Leaving these
    // unchanged outputs href="blog/" which is browser-relative — wrong off the homepage.
    // Convert to absolute home URLs (same as leading-slash paths above).
    if (preg_match('#^[a-zA-Z0-9][a-zA-Z0-9._/-]*$#', $url)) {
        return home_url('/' . trim($url, '/') . '/') . $hash_fragment;
    }

    return $url . $hash_fragment;
}

/**
 * Escaped href for wp_nav_menu walkers. Imported menu items can still carry menus.json-style
 * bare paths (e.g. blog/) in the database — esc_url alone leaves them browser-relative.
 */
function wpconvert_nav_item_href($url) {
    if (!isset($url) || $url === '' || $url === '#') {
        return '#';
    }
    return esc_url(wpconvert_convert_static_url($url));
}

/**
 * Recursively render fallback menu items (preserves classes but filters for layout)
 * This EXACT logic is replicated in WPConvert_Menu_Walker for consistency
 */
function wpconvert_render_fallback_menu_items($items, $depth = 0) {
    // EC-NAV-014: Get current page highlighting classes
    global $wpconvert_base_classes, $wpconvert_active_classes, $wpconvert_inactive_classes;
    // EC-NAV-382: the site's own current-page class, captured from the source.
    // EC-NAV-383: and which surface it belongs on ('link', 'item' or 'both').
    global $wpconvert_active_state_class, $wpconvert_active_state_target;
    
    foreach ($items as $item) {
        // Get original classes from both <a> and <li> elements
        $original_classes = !empty($item['classes']) ? $item['classes'] : [];
        $li_original_classes = !empty($item['liClasses']) ? $item['liClasses'] : [];
        $has_children = !empty($item['children']) && is_array($item['children']) && count($item['children']) > 0;
        
        // EC-NAV-094: Filter only nested dropdown links (depth>0). Top-level parents must keep flex/gap.
        $should_filter = $depth > 0;
        $filtered_classes = $original_classes;
        
        if ($should_filter && is_array($original_classes)) {
            $filtered_classes = wpconvert_filter_layout_classes($original_classes);
        }
        
        $classes_str = is_array($filtered_classes) ? implode(' ', $filtered_classes) : $filtered_classes;
        // EC-I18N-URL-MENU-001e: the drawer is the mobile face of the same
        // menu, so it follows the request locale like the desktop nav does.
        // Guarded like the walker's other optional helpers, so this renderer
        // stays usable when it is loaded on its own.
        $item_loc = function_exists('wpconvert_localized_submenu_pair')
            ? wpconvert_localized_submenu_pair($item)
            : array('title' => (string) ($item['title'] ?? ''), 'url' => (string) ($item['url'] ?? ''));
        $url = !empty($item_loc['url']) ? $item_loc['url'] : '#';
        // CRITICAL: Convert static site URLs (.html) to WordPress permalinks
        $url = wpconvert_convert_static_url($url);
        $converted_url = esc_url($url);
        $title = $item_loc['title'] !== '' ? esc_html($item_loc['title']) : '';
        
        // EC-NAV-CTA-001: CTA items use their own preserved classes (skip base/active logic)
        $is_cta = !empty($item['isButton']);
        if (!$is_cta && is_array($original_classes) && function_exists('wpconvert_is_cta_by_classes')) {
            $is_cta = wpconvert_is_cta_by_classes($original_classes);
        }
        if ($is_cta && !empty($original_classes)) {
            $btn_classes = is_array($original_classes) ? implode(' ', $original_classes) : $original_classes;
            $wpc_id = !empty($item['wpcId']) ? $item['wpcId'] : 'wpc_navbtn_' . md5($title . $url);
            // EC-I18N-MENU-001: stamp data-i18n on CTA nav buttons in the
            // pre-activation fallback renderer when the source dict matched
            // this CTA title.
            $i18n_attr = wpconvert_i18n_menu_attr_from_item($item);
            $handler_attr = wpconvert_inline_handler_attr_from_item($item);
            echo '<li class="menu-item"><a href="' . $converted_url . '" class="' . esc_attr(trim($btn_classes)) . '" data-wpc-id="' . esc_attr($wpc_id) . '" data-wpc-editable="button"' . $handler_attr . $i18n_attr . '>' . $title . '</a></li>';
            continue;
        }
        
        // EC-NAV-014: Check if this is the current page
        $is_current = false;
        // EC-NAV-379: anchor-only menu items ("#", "#about") have no URL path, and
        // parse_url() returns null for them — which PHP 8.1+ deprecates as an
        // rtrim() argument. Cast so anchor-heavy one-page menus stay notice-free.
        $current_path = rtrim((string) parse_url(home_url(add_query_arg(array(), $_SERVER['REQUEST_URI'])), PHP_URL_PATH), '/');
        $item_path = rtrim((string) parse_url($converted_url, PHP_URL_PATH), '/');
        // EC-NAV-381: a fragment-only URL addresses no page, so it can never be the
        // current one. Without this it collapses to an empty path and matches the
        // home-link arm below, highlighting EVERY anchor item on a one-page site.
        // Which anchor is active is a scroll-position question the site's own
        // scrollspy answers at runtime.
        if (!wpconvert_is_fragment_only_url($converted_url)
            && ($current_path === $item_path || (empty($item_path) && ($current_path === '' || $current_path === '/')))) {
            $is_current = true;
        }
        
        // EC-NAV-014: Apply dynamic current page highlighting
        if (!empty($wpconvert_base_classes) || !empty($wpconvert_active_classes)) {
            if ($is_current) {
                // Current page: Start with base, remove inactive-specific, add active classes
                $final_classes = $wpconvert_base_classes;
                if (!empty($wpconvert_inactive_classes)) {
                    $inactive_arr = array_filter(explode(' ', $wpconvert_inactive_classes));
                    $final_arr = array_filter(explode(' ', $final_classes));
                    $final_arr = array_diff($final_arr, $inactive_arr);
                    $final_classes = implode(' ', $final_arr);
                }
                if (!empty($wpconvert_active_classes)) {
                    $final_classes .= ' ' . $wpconvert_active_classes;
                }
                $classes_str = trim($final_classes) . ' wpconvert-active-link current-menu-item';
            } else {
                // Not current page: Use base classes (inactive state)
                $classes_str = $wpconvert_base_classes;
            }
            // EC-NAV-369: the substitutions above dropped everything the source
            // link carried. Put the structural trigger classes back so the
            // theme's own caret rule (.dropdown-toggle::after) still matches.
            // Gated on $has_children: never draw an arrow that opens nothing.
            if ($has_children) {
                $classes_str = wpconvert_merge_structural_nav_classes($classes_str, $original_classes);
            }
        }
        
        // CRITICAL: For static sites, combine LI classes with menu-item class
        // LI classes often control dropdown behavior (e.g., "level", "level2", "level3")
        $li_classes = 'menu-item';
        if (!empty($li_original_classes) && is_array($li_original_classes)) {
            $li_classes .= ' ' . implode(' ', $li_original_classes);
        }
        if ($has_children) {
            $li_classes .= ' menu-item-has-children';
        }
        // EC-NAV-014: Add current-menu-item to li for standard WP styling
        if ($is_current) {
            $li_classes .= ' current-menu-item';
        }
        // EC-NAV-383: many navs (Bootstrap 3/4 and most hand-written ones) style
        // the <li> rather than the <a>. Applied here because the <li> is echoed
        // immediately below, before the link is assembled.
        if ($is_current && !empty($wpconvert_active_state_class)
            && ($wpconvert_active_state_target === 'item' || $wpconvert_active_state_target === 'both')) {
            $li_state_arr = array_filter(explode(' ', trim($li_classes)));
            if (!in_array($wpconvert_active_state_class, $li_state_arr, true)) {
                $li_state_arr[] = $wpconvert_active_state_class;
            }
            $li_classes = implode(' ', $li_state_arr);
        }
        
        // EC-NAV-062: Preserve original li id for PHP sites with hover scripts
        $li_id_attr = '';
        if (!empty($item['liId'])) {
            $li_id_attr = ' id="' . esc_attr($item['liId']) . '"';
        }
        echo '<li' . $li_id_attr . ' class="' . esc_attr($li_classes) . '">';
        // EC-NAV-094: Lucide-style chevron for top-level dropdown parents (matches React ChevronDown + gap-1 flex row)
        // EC-NAV-219: skip the chevron emit when the title already contains a trailing
        // arrow glyph (e.g. aura-lace "Boutique ▾"); also skip the flex layout adjust
        // since there's no SVG to align inline.
        $dropdown_icon = '';
        $link_for_icon = trim($classes_str);
        // EC-NAV-380: when the source link carried its own icon, redraw THAT and
        // suppress the injected Lucide chevron so the link never gets two carets.
        $source_icon = wpconvert_nav_icon_html($item);
        if ($source_icon === '' && $has_children && $depth === 0 && ($link_for_icon !== '' || !empty($wpconvert_base_classes)) && (!function_exists('wpconvert_emit_dropdown_chevron') || wpconvert_emit_dropdown_chevron()) && !wpconvert_title_has_trailing_arrow($item['title'] ?? '')) {
            $dropdown_icon = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="' . (function_exists('wpconvert_nav_icon_stroke') ? esc_attr(wpconvert_nav_icon_stroke()) : 'currentColor') . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-down h-3.5 w-3.5 shrink-0" aria-hidden="true"><path d="m6 9 6 6 6-6"></path></svg>';
            // EC-NAV-101: Ensure flex alignment so chevron sits inline with text
            $flex_needed = ['inline-flex', 'items-center', 'gap-1'];
            $cls_arr = array_filter(explode(' ', $classes_str));
            foreach ($flex_needed as $fc) { if (!in_array($fc, $cls_arr)) $cls_arr[] = $fc; }
            $classes_str = implode(' ', $cls_arr);
        }
        // EC-I18N-MENU-001: stamp data-i18n on regular nav links in the
        // pre-activation fallback renderer when the source dict has a
        // matching key on this item.
        // EC-NAV-382: re-apply the site's own current-page class (e.g. "active").
        // The source marks the current item with it and the site's CSS keys off
        // THAT token, not WordPress's current-menu-item — so without this no item
        // is ever highlighted. Applied after the chevron logic above so it can
        // never flip those decisions by making an empty class string non-empty.
        // EC-NAV-383: skipped when the site marks the <li> instead; an absent
        // target means 'link', which is how every pre-EC-NAV-383 theme behaves.
        if ($is_current && !empty($wpconvert_active_state_class)
            && $wpconvert_active_state_target !== 'item') {
            $state_arr = array_filter(explode(' ', trim($classes_str)));
            if (!in_array($wpconvert_active_state_class, $state_arr, true)) {
                $state_arr[] = $wpconvert_active_state_class;
            }
            $classes_str = implode(' ', $state_arr);
        }
        // EC-NAV-380: keep the source icon on the side of the label it came from.
        $label_html = $title;
        if ($source_icon !== '') {
            $label_html = wpconvert_nav_icon_before($item)
                ? $source_icon . ' ' . $title
                : $title . ' ' . $source_icon;
        }
        $i18n_attr = wpconvert_i18n_menu_attr_from_item($item);
        $handler_attr = wpconvert_inline_handler_attr_from_item($item);
        echo '<a href="' . $converted_url . '" class="' . esc_attr(trim($classes_str)) . '"' . $handler_attr . $i18n_attr . '>' . $label_html . $dropdown_icon . '</a>';
        
        if ($has_children) {
            // EC-NAV-096: Always keep WordPress hook classes (sub-menu submenu) so theme CSS (.submenu a padding, etc.) applies.
            global $wpconvert_submenu_class;
            $submenu_class = trim('sub-menu submenu ' . $wpconvert_submenu_class);
            echo '<ul class="' . esc_attr($submenu_class) . '">';
            wpconvert_render_fallback_menu_items($item['children'], $depth + 1);
            echo '</ul>';
        }
        
        echo '</li>';
    }
}

/**
 * EC-NAV-219: Detect a trailing arrow glyph baked into a menu title.
 *
 * Many source sites author the dropdown trigger label with a literal
 * Unicode arrow as the visible "menu opens here" affordance, e.g.
 *   <a href="boutique.html">Boutique ▾</a>      (U+25BE ▾)
 * The walker / fallback renderer then UNCONDITIONALLY appends a Lucide
 * chevron-down SVG to every dropdown parent, so the rendered link reads
 * "Boutique ▾ ⌄" — two arrows stacked.
 *
 * This helper returns true when the trimmed title's LAST visible glyph
 * is one of the common down-/menu-arrow code points so callers can skip
 * appending an SVG chevron and preserve the author's intent.
 *
 * NOTE: this PHP code lives inside a JavaScript template literal, so
 * every backslash that should reach the emitted PHP file must be doubled
 * (\\xE2 in JS → \xE2 in PHP → byte 0xE2 in the string at runtime).
 *
 * Recognised glyphs (UTF-8 byte sequences in the array literal):
 *   ▾ BLACK DOWN-POINTING SMALL TRIANGLE  (aura-lace "Boutique ▾")
 *   ▼ BLACK DOWN-POINTING TRIANGLE
 *   ▽ WHITE DOWN-POINTING TRIANGLE
 *   ↓ DOWNWARDS ARROW
 *   ⌄ DOWN ARROWHEAD
 *   ⌃ UP ARROWHEAD (some themes invert)
 *   ⏷ BLACK MEDIUM DOWN-POINTING TRIANGLE
 *   ⮟ BLACK DOWNWARDS EQUILATERAL ARROWHEAD
 *   ⇣ DOWNWARDS DASHED ARROW
 *   ↡ DOWNWARDS TWO HEADED ARROW
 *   ⇩ DOWNWARDS WHITE ARROW
 */
/* EC-NAV-251: When the SOURCE CSS already draws a dropdown caret on the trigger
   link (e.g. .has-dropdown > a::after { content: ' ▾' }), suppress our
   injected Lucide chevron so the navbar shows ONE arrow, not two. The boolean is
   baked at conversion time from CSS analysis. */
function wpconvert_emit_dropdown_chevron() { return true; }

function wpconvert_title_has_trailing_arrow($title) {
    if (!is_string($title) || $title === '') return false;
    $t = trim($title);
    if ($t === '') return false;
    if (function_exists('mb_substr') && function_exists('mb_strlen')) {
        $last = mb_substr($t, mb_strlen($t, 'UTF-8') - 1, 1, 'UTF-8');
    } else {
        $last = substr($t, -1);
    }
    $arrows = array(
        "\xE2\x96\xBE", // U+25BE (aura-lace "Boutique ▾")
        "\xE2\x96\xBC", // U+25BC
        "\xE2\x96\xBD", // U+25BD
        "\xE2\x86\x93", // U+2193
        "\xE2\x8C\x84", // U+2304
        "\xE2\x8C\x83", // U+2303
        "\xE2\x8F\xB7", // U+23F7
        "\xE2\xAE\x9F", // U+2B9F
        "\xE2\x87\xA3", // U+21E3
        "\xE2\x86\xA1", // U+21A1
        "\xE2\x87\xA9", // U+21E9
    );
    return in_array($last, $arrows, true);
}

/**
 * EC-NAV-369: Re-apply the STRUCTURAL classes a menu link carried in the source.
 *
 * Both <ul>/<li> renderers replace a link's class attribute wholesale with the
 * base/active mapping when one exists, so everything the source <a> carried is
 * discarded. For a Bootstrap navbar that includes "dropdown-toggle", which is
 * what the theme's own ".dropdown-toggle::after" caret rule keys off — the
 * dropdown parents then render with no arrow at all.
 *
 * This is the mirror image of EC-NAV-366: a structural class is not a state
 * class, so the current-page machinery must neither promote it to activeLink
 * classes nor strip it from a real trigger. Only classes that were literally on
 * the source link are restored, and only STRUCTURAL ones — the styling classes
 * stay under base/active control.
 *
 * @param string $classes_str      the class string the highlighter produced
 * @param array  $original_classes the source link's own classes
 */
function wpconvert_merge_structural_nav_classes($classes_str, $original_classes) {
    if (!is_array($original_classes) || empty($original_classes)) return $classes_str;
    $structural = array(
        'dropdown-toggle', 'dropdown', 'dropup', 'dropright', 'dropleft',
        'has-dropdown', 'has-submenu', 'has-children', 'menu-item-has-children',
        'nav-item-dropdown', 'megamenu', 'mega-menu', 'submenu-toggle',
        'caret', 'menu-toggle',
    );
    $current = array_values(array_filter(explode(' ', (string) $classes_str)));
    foreach ($original_classes as $cls) {
        $cls = trim((string) $cls);
        if ($cls === '' || !in_array($cls, $structural, true)) continue;
        if (!in_array($cls, $current, true)) $current[] = $cls;
    }
    return trim(implode(' ', $current));
}

/**
 * EC-NAV-380: rebuild the icon element a nav link carried in the source markup.
 *
 * Icon-font themes draw the dropdown caret with a text-less <i> (Bootstrap Icons,
 * Font Awesome). menus.json stores it as structured data — tag plus class list,
 * never raw HTML — so the element is reconstructed here and the class string goes
 * through esc_attr(). Returns '' for items with no captured icon, which keeps
 * every pre-existing menu byte-identical.
 *
 * @param array $item a menus.json row (or a resolved original item)
 * @return string the icon tag, or '' when there is nothing to draw
 */
function wpconvert_nav_icon_html($item) {
    if (!is_array($item) || empty($item['titleIcon']) || !is_array($item['titleIcon'])) {
        return '';
    }
    $icon = $item['titleIcon'];
    $tag = isset($icon['tag']) ? strtolower(preg_replace('/[^a-zA-Z]/', '', (string) $icon['tag'])) : 'i';
    if (!in_array($tag, array('i', 'span'), true)) {
        $tag = 'i';
    }
    $classes = array();
    if (!empty($icon['classes']) && is_array($icon['classes'])) {
        foreach ($icon['classes'] as $cls) {
            $cls = trim((string) $cls);
            if ($cls !== '') $classes[] = $cls;
        }
    }
    if (empty($classes)) {
        return '';
    }
    return '<' . $tag . ' class="' . esc_attr(implode(' ', $classes)) . '"></' . $tag . '>';
}

/**
 * EC-NAV-390: rebuild the hover underline a nav link drew inside itself.
 *
 * The Tailwind idiom nests a text-less, absolutely positioned rule inside the
 * anchor, collapsed at rest and expanded on hover:
 *
 *   <span class="absolute bottom-0 left-4 right-4 h-[2px] bg-[#6FB7D6]
 *                origin-left transition-transform scale-x-0 group-hover:scale-x-100">
 *
 * Swapping the captured navbar for wp_nav_menu() discards the anchor's children,
 * so converted navbars lost their hover state entirely. menus.json stores the rule
 * as structured data — tag plus class list, never raw HTML — so it is rebuilt here
 * and the class string goes through esc_attr(). Returns '' for items with no
 * captured decoration, which keeps every pre-existing menu byte-identical.
 *
 * @param array $item a menus.json row
 * @return string the decoration tag, or '' when there is nothing to draw
 */
/**
 * EC-NAV-419: what the captured navigation stroked its caret icons with.
 *
 * A site whose chevrons and arrows are painted by an SVG gradient records the
 * reference here at conversion time (header.php mounts the definition itself), so an
 * emitted chevron is drawn the same way the captured one was. Anything that is not a
 * same-document paint reference or a plain colour is refused, and a site that never
 * used one gets the text colour it always had.
 */
function wpconvert_nav_icon_stroke() {
    static $stroke = null;
    if ($stroke !== null) {
        return $stroke;
    }
    $stroke = 'currentColor';
    $raw = @file_get_contents(get_template_directory() . '/assets/data/menus.json');
    if (!$raw) {
        return $stroke;
    }
    $data = json_decode($raw, true);
    $value = isset($data['primary']['navIconStroke']) ? trim((string) $data['primary']['navIconStroke']) : '';
    if ($value === '') {
        return $stroke;
    }
    $is_paint_ref = (bool) preg_match('/^url\(#[A-Za-z_][\w:.-]*\)$/', $value);
    $is_plain_color = (bool) preg_match('/^(?:[A-Za-z]+|#[0-9A-Fa-f]{3,8}|(?:rgb|hsl)a?\([\d\s.,%\/]+\))$/', $value);
    if ($is_paint_ref || $is_plain_color) {
        $stroke = $value;
    }
    return $stroke;
}

function wpconvert_nav_hover_decoration_html($item) {
    if (!is_array($item) || empty($item['hoverDecoration']) || !is_array($item['hoverDecoration'])) {
        return '';
    }
    $deco = $item['hoverDecoration'];
    $tag = isset($deco['tag']) ? strtolower(preg_replace('/[^a-zA-Z]/', '', (string) $deco['tag'])) : 'span';
    if (!in_array($tag, array('span', 'div', 'i'), true)) {
        $tag = 'span';
    }
    $classes = array();
    if (!empty($deco['classes']) && is_array($deco['classes'])) {
        foreach ($deco['classes'] as $cls) {
            $cls = trim((string) $cls);
            if ($cls !== '') $classes[] = $cls;
        }
    }
    if (empty($classes)) {
        return '';
    }
    return '<' . $tag . ' class="' . esc_attr(implode(' ', $classes)) . '" aria-hidden="true"></' . $tag . '>';
}

/**
 * EC-NAV-390: give the link the two hooks its captured decoration needs.
 *
 * The rule is revealed by a group-hover: utility, which only fires beneath an
 * ancestor carrying .group, and it is positioned absolute, which needs a
 * positioned ancestor. In the source both came from the wrapper the component
 * rendered around each item; the walker's leaf items have no wrapper, so the
 * hooks go on the anchor itself. The decoration is a descendant of the anchor, so
 * hovering the anchor reveals it exactly as the original did.
 *
 * No-ops when there is no decoration, so untouched menus keep their exact classes.
 */
function wpconvert_nav_hover_decoration_class($decoration_html, $class_str) {
    if ($decoration_html === '') {
        return $class_str;
    }
    $arr = array_filter(explode(' ', trim((string) $class_str)));
    foreach (array('relative', 'group') as $hook) {
        if (!in_array($hook, $arr, true)) $arr[] = $hook;
    }
    return implode(' ', $arr);
}

/**
 * EC-NAV-381: is this URL nothing but an in-page fragment ("#", "#about")?
 *
 * Such a link addresses no page, so the current-page comparison must skip it:
 * parse_url('#about', PHP_URL_PATH) is null, which otherwise collapses to the
 * same empty path the home link uses and marks every anchor item as current.
 * A URL that carries a path AND a fragment ("/about/#team") is a real page and
 * is deliberately NOT matched here.
 */
function wpconvert_is_fragment_only_url($url) {
    return strpos(ltrim((string) $url), '#') === 0;
}

/**
 * EC-NAV-380: does this item's captured icon sit before the label?
 */
function wpconvert_nav_icon_before($item) {
    return is_array($item)
        && !empty($item['titleIcon']['position'])
        && $item['titleIcon']['position'] === 'before';
}

/**
 * Universal function to filter layout classes from menu items
 * Used by both fallback menu and Walker for consistency
 */
function wpconvert_filter_layout_classes($classes) {
    if (!is_array($classes)) return [];
    
    $layout_classes = [
        'inline-flex', 'flex', 'grid', 'inline-grid',
        'h-10', 'h-12', 'h-8', 'w-max', 'w-full',
        'items-center', 'items-start', 'items-end', 'items-stretch',
        'justify-center', 'justify-start', 'justify-end', 'justify-between',
        'rounded-md', 'rounded-lg', 'rounded-full',
        'group', 'hidden', 'lg:flex', 'md:flex', 'sm:flex',
        'bg-background', 'bg-accent',
        'disabled:', 'focus:bg-accent', 'hover:bg-accent',
        'data-[active]', 'data-[state'
    ];
    
    return array_filter($classes, function($class) use ($layout_classes) {
        foreach ($layout_classes as $lc) {
            if (strpos($class, $lc) !== false) return false;
        }
        return true;
    });
}

/**
 * Mobile menu walker for responsive navigation (preserves original classes)
 */
class WPConvert_Mobile_Menu_Walker extends Walker_Nav_Menu {
    function start_el(&$output, $item, $depth = 0, $args = null, $id = 0) {
        // Get original classes from post meta or item classes
        $stored_classes = get_post_meta($item->ID, '_wpconvert_original_classes', true);
        $original_classes = $stored_classes ? $stored_classes : '';
        
        // Merge with WordPress classes
        $wp_classes = !empty($item->classes) ? implode(' ', array_filter($item->classes)) : '';
        $all_classes = trim($original_classes . ' ' . $wp_classes);
        
        $url = wpconvert_nav_item_href($item->url);
        $title = !empty($item->title) ? esc_html($item->title) : '';
        
        $output .= '<a href="' . $url . '" class="block font-medium ' . esc_attr($all_classes) . '">' . $title . '</a>';
    }
}

/**
 * EC-NAV-316: Restore original (un-mangled) menu-item CSS classes for menus
 * rendered by WordPress's DEFAULT Walker_Nav_Menu (e.g. the mobile drawer).
 *
 * When a menu is saved, WordPress runs sanitize_html_class() on each menu-item
 * CSS class, which strips '/', ':' and '.' — corrupting the Tailwind classes
 * captured from the source (text-white/75 -> text-white75, hover:text-white ->
 * hovertext-white, py-2.5 -> py-25). wpconvert_import_menus_from_json() also
 * stores the pristine class string in the '_wpconvert_original_classes' post
 * meta (post meta is NOT sanitized), so these filters use it to emit correct
 * classes without touching WordPress's own menu-item/current-menu-item classes.
 *
 * Safety: both filters no-op unless the item carries the converter's
 * '_wpconvert_original_classes' meta, so third-party / hand-built menus are
 * never modified. Custom walkers (WPConvert_Menu_Walker / _Flat_ / _Dropdown_)
 * build their <a>/<li> markup by hand and read the same meta directly, so they
 * bypass these core filters entirely and are unaffected (no double classes).
 */
if (!function_exists('wpconvert_restore_menu_link_classes')) {
    function wpconvert_restore_menu_link_classes($atts, $item, $args = null, $depth = 0) {
        if (empty($item->ID)) return $atts;
        $orig = get_post_meta($item->ID, '_wpconvert_original_classes', true);
        if (!$orig) return $atts;
        // esc_attr() (applied by the core walker) preserves '/' and ':', so the
        // original Tailwind classes render intact on the <a> where the source
        // design targets them.
        $existing = isset($atts['class']) ? trim((string)$atts['class']) : '';
        $atts['class'] = trim($existing . ' ' . $orig);
        return $atts;
    }
}
add_filter('nav_menu_link_attributes', 'wpconvert_restore_menu_link_classes', 10, 4);

if (!function_exists('wpconvert_strip_mangled_menu_li_classes')) {
    function wpconvert_strip_mangled_menu_li_classes($classes, $item, $args = null, $depth = 0) {
        if (empty($item->ID) || !is_array($classes)) return $classes;
        $orig = get_post_meta($item->ID, '_wpconvert_original_classes', true);
        if (!$orig) return $classes;
        // Remove only the mangled copies of the converter's own classes from the
        // <li>; WordPress's structural classes (menu-item, current-menu-item, …)
        // are never in this set, so they survive.
        $mangled = array_map('sanitize_html_class', preg_split('/\s+/', $orig, -1, PREG_SPLIT_NO_EMPTY));
        return array_values(array_diff($classes, $mangled));
    }
}
add_filter('nav_menu_css_class', 'wpconvert_strip_mangled_menu_li_classes', 10, 4);

/**
 * EC-I18N-URL-MENU-002: Localize a menu that WordPress's DEFAULT walker renders.
 *
 * The custom walkers (WPConvert_Menu_Walker / _Dropdown_ / _Flat_) each call
 * wpconvert_localize_wp_nav_item() while building their own markup, so the
 * desktop bar follows the URL-prefix locale. The injected mobile drawer, the
 * preserved-mobile-menu block and the <nav><ul> replacement all call
 * wp_nav_menu() with no walker — the core Walker_Nav_Menu prints $item->title
 * and $item->url as imported, i.e. in the capture's language on every page. The
 * defect surfaces only once menus are imported, because wpconvert_fallback_menu()
 * (what renders before that) localizes on its own.
 *
 * These two filters are the only ones the core walker applies to a label and a
 * link, and they route both through the same helper the walkers use, so what a
 * menu row says in a given language is decided in one place.
 *
 * Safety: wpconvert_core_menu_localized_pair() returns null — and both filters
 * hand back their input untouched — unless the item matches a menus.json row
 * that resolves to a DIFFERENT label or route than the item already carries. So
 * a monolingual conversion, a request in the capture's own language, a page the
 * converter never captured and a hand-built third-party menu item are all
 * no-ops, byte for byte. The custom walkers never apply either filter (they
 * write their <a> by hand), so they cannot double-localize. The href swap runs
 * at priority 20, after EC-NAV-316's class restore at 10, and touches only the
 * 'href' key.
 */
if (!function_exists('wpconvert_core_menu_localized_pair')) {
    function wpconvert_core_menu_localized_pair($item) {
        if (!is_object($item) || !function_exists('wpconvert_localize_wp_nav_item')) {
            return null;
        }
        $title = isset($item->title) ? (string) $item->title : '';
        $url = isset($item->url) ? (string) $item->url : '';
        if ($title === '' && $url === '') {
            return null;
        }
        $loc = wpconvert_localize_wp_nav_item($item);
        if (!is_array($loc)) {
            return null;
        }
        $loc_title = isset($loc['title']) ? (string) $loc['title'] : '';
        $loc_url = isset($loc['url']) ? (string) $loc['url'] : '';
        // Nothing translated: hand the caller its own values back rather than a
        // re-rendered copy of them.
        if ($loc_title === $title && $loc_url === $url) {
            return null;
        }
        return array('title' => $loc_title, 'url' => $loc_url);
    }
}

if (!function_exists('wpconvert_localize_core_menu_title')) {
    function wpconvert_localize_core_menu_title($title, $item, $args = null, $depth = 0) {
        $loc = wpconvert_core_menu_localized_pair($item);
        if (!$loc || $loc['title'] === '') {
            return $title;
        }
        return $loc['title'];
    }
}
add_filter('nav_menu_item_title', 'wpconvert_localize_core_menu_title', 10, 4);

if (!function_exists('wpconvert_localize_core_menu_href')) {
    function wpconvert_localize_core_menu_href($atts, $item, $args = null, $depth = 0) {
        // An item the core walker gave no href (a label-only row) stays that way.
        if (!is_array($atts) || !isset($atts['href'])) {
            return $atts;
        }
        $loc = wpconvert_core_menu_localized_pair($item);
        if (!$loc || $loc['url'] === '' || $loc['url'] === '#') {
            return $atts;
        }
        $atts['href'] = esc_url(wpconvert_nav_item_href($loc['url']));
        return $atts;
    }
}
add_filter('nav_menu_link_attributes', 'wpconvert_localize_core_menu_href', 20, 4);

/**
 * EC-I18N-CTA-001: value for the request locale out of a locale => value map.
 * Returns $fallback when the locale is unknown or the map does not cover it.
 */
if (!function_exists('wpconvert_locale_choice')) {
    function wpconvert_locale_choice($map, $fallback = '') {
        if (!is_array($map) || empty($map)) {
            return $fallback;
        }
        $loc = function_exists('wpconvert_request_locale') ? wpconvert_request_locale() : '';
        if ($loc !== '' && isset($map[$loc]) && $map[$loc] !== '') {
            return (string) $map[$loc];
        }
        return $fallback;
    }
}

/**
 * EC-I18N-CTA-001: label for a static link. The captured markup is returned
 * verbatim whenever it already says the right thing, so the capture's own locale
 * keeps its exact bytes (no double-escaping of entities it already carries).
 */
if (!function_exists('wpconvert_locale_static_text')) {
    function wpconvert_locale_static_text($map, $captured_html) {
        $captured_html = (string) $captured_html;
        $value = wpconvert_locale_choice($map, '');
        if ($value === '') {
            return $captured_html;
        }
        $plain = html_entity_decode($captured_html, ENT_QUOTES, 'UTF-8');
        if ($value === $plain || $value === $captured_html) {
            return $captured_html;
        }
        return esc_html($value);
    }
}

/**
 * EC-I18N-CTA-001: target for a static link. Falls back to the captured href for
 * an unknown locale, for the capture's own locale, and — crucially — when the
 * locale's route was not part of the conversion, so a language switch can never
 * point a link at a page this theme does not ship (same guard as
 * EC-I18N-URL-MENU-001e).
 */
if (!function_exists('wpconvert_locale_static_href')) {
    function wpconvert_locale_static_href($map, $captured_href) {
        $captured_href = (string) $captured_href;
        $target = wpconvert_locale_choice($map, '');
        if ($target === '' || $target === $captured_href) {
            return $captured_href;
        }
        if (function_exists('wpconvert_route_was_captured') && !wpconvert_route_was_captured($target)) {
            return $captured_href;
        }
        if (function_exists('wpconvert_nav_item_href')) {
            return wpconvert_nav_item_href($target);
        }
        return esc_url($target);
    }
}

/**
 * Walker that preserves original CSS classes and design from menus.json
 * EC-NAV-014: Implements dynamic current page highlighting using baseLinkClasses/activeLinkClasses
 */
class WPConvert_Menu_Walker extends Walker_Nav_Menu {
  private $menu_data = null;
  private $base_link_classes = '';
  private $active_link_classes = '';
  private $inactive_link_classes = '';
  // EC-NAV-382: the class the SOURCE used to mark the current page.
  private $active_state_class = '';
  // EC-NAV-383: which surface it belongs on — 'link', 'item' or 'both'.
  private $active_state_target = '';
  
  function __construct() {
    $file = get_template_directory() . '/assets/data/menus.json';
    if (file_exists($file)) {
      $this->menu_data = json_decode(file_get_contents($file), true);
      // EC-NAV-014: Load active/inactive class mappings for dynamic highlighting
      if ($this->menu_data && !empty($this->menu_data['primary'])) {
        $this->base_link_classes = $this->menu_data['primary']['baseLinkClasses'] ?? '';
        $this->active_link_classes = $this->menu_data['primary']['activeLinkClasses'] ?? '';
        $this->inactive_link_classes = $this->menu_data['primary']['inactiveLinkClasses'] ?? '';
        $this->active_state_class = $this->menu_data['primary']['activeStateClass'] ?? '';
        $this->active_state_target = $this->menu_data['primary']['activeStateTarget'] ?? '';
      }
    }
  }
  
  function start_lvl(&$output, $depth = 0, $args = null) {
    $indent = str_repeat("\t", $depth);
    // EC-NAV-096: Merge captured submenuClass with sub-menu + submenu (replacing the whole string dropped WPConvert CSS hooks)
    $submenu_class = 'sub-menu submenu';
    if ($this->menu_data && !empty($this->menu_data['primary']['submenuClass'])) {
      $submenu_class .= ' ' . $this->menu_data['primary']['submenuClass'];
    }
    $submenu_class = trim($submenu_class);
    $output .= "\n" . $indent . "<ul class=\"" . esc_attr($submenu_class) . "\">\n";
  }

  function end_lvl(&$output, $depth = 0, $args = null) {
    $indent = str_repeat("\t", $depth);
    $output .= $indent . "</ul>\n";
  }

  function start_el(&$output, $item, $depth = 0, $args = null, $id = 0) {
    $indent = ($depth) ? str_repeat("\t", $depth) : '';
    
    // Try to get original classes from post meta first (most reliable after import)
    $stored_classes = get_post_meta($item->ID, '_wpconvert_original_classes', true);
    $stored_li_classes = get_post_meta($item->ID, '_wpconvert_li_classes', true);
    $stored_has_children = get_post_meta($item->ID, '_wpconvert_has_children', true);
    $original_classes = [];
    $li_original_classes = [];
    
    if ($stored_classes) {
      $original_classes = explode(' ', $stored_classes);
    } else {
      // Fallback to finding in menus.json
      $original_item = $this->find_original_item($item->title, $item->url);
      if ($original_item && !empty($original_item['classes'])) {
        $original_classes = is_array($original_item['classes']) ? $original_item['classes'] : [];
      }
      // CRITICAL: Also get LI classes from menus.json for static sites
      if ($original_item && !empty($original_item['liClasses'])) {
        $li_original_classes = is_array($original_item['liClasses']) ? $original_item['liClasses'] : [];
      }
    }
    
    if ($stored_li_classes) {
      $li_original_classes = explode(' ', $stored_li_classes);
    }
    
    // EC-NAV-094: Filter only nested items — top-level dropdown parents keep link layout classes
    $has_children = !empty($args->has_children) || $stored_has_children === '1';
    $should_filter = $depth > 0;
    
    $filtered_classes = $original_classes;
    
    if ($should_filter) {
      // Use the SAME filtering function as fallback menu
      $filtered_classes = wpconvert_filter_layout_classes($original_classes);
      
      // Debug: Log what was filtered
      error_log("WPConvert Walker: '{$item->title}' filtered from " . count($original_classes) . " to " . count($filtered_classes) . " classes");
    }
    
    // Build classes EXACTLY like fallback menu (menu-item FIRST)
    $classes_str = is_array($filtered_classes) ? implode(' ', $filtered_classes) : '';
    
    // EC-NAV-014: Dynamic current page highlighting
    // Check if this item is the current page - WordPress adds these classes
    $is_current = in_array('current-menu-item', $item->classes) || 
                  in_array('current_page_item', $item->classes) ||
                  in_array('current-menu-ancestor', $item->classes);
    
    // If we have base/active class mappings, use them for dynamic highlighting
    if (!empty($this->base_link_classes) || !empty($this->active_link_classes)) {
      if ($is_current) {
        // Current page: Start with base classes, remove inactive-specific, add active classes
        $final_classes = $this->base_link_classes;
        
        // Remove inactive-specific classes (e.g., text-navy-600) from base
        if (!empty($this->inactive_link_classes)) {
          $inactive_arr = array_filter(explode(' ', $this->inactive_link_classes));
          $final_arr = array_filter(explode(' ', $final_classes));
          $final_arr = array_diff($final_arr, $inactive_arr);
          $final_classes = implode(' ', $final_arr);
        }
        
        // Add active classes (e.g., text-navy-800)
        if (!empty($this->active_link_classes)) {
          $final_classes .= ' ' . $this->active_link_classes;
        }
        
        // Add marker class for CSS targeting
        $classes_str = trim($final_classes) . ' wpconvert-active-link current-menu-item';
      } else {
        // Not current page: Use base classes (inactive state)
        $classes_str = $this->base_link_classes;
      }
      // EC-NAV-369: restore the source link's structural trigger classes, which
      // the base/active substitution above discarded, so a dropdown parent keeps
      // the hook its own caret CSS targets. Gated on $has_children.
      if ($has_children) {
        $classes_str = wpconvert_merge_structural_nav_classes($classes_str, $original_classes);
      }
    }
    
    // CRITICAL: For static sites, combine LI classes with menu-item class
    // LI classes often control dropdown behavior (e.g., "level", "level2", "level3")
    $li_classes = 'menu-item';
    if (!empty($li_original_classes) && is_array($li_original_classes)) {
      $li_classes .= ' ' . implode(' ', $li_original_classes);
    }
    if ($has_children) {
      $li_classes .= ' menu-item-has-children';
    }
    // EC-NAV-014: Add WordPress current-menu-item class to <li> for standard WP styling
    if ($is_current) {
      $li_classes .= ' current-menu-item';
    }
    // EC-NAV-383: mirror the fallback renderer — the site may style the <li>.
    if ($is_current && !empty($this->active_state_class)
        && ($this->active_state_target === 'item' || $this->active_state_target === 'both')) {
      $li_state_arr = array_filter(explode(' ', trim($li_classes)));
      if (!in_array($this->active_state_class, $li_state_arr, true)) {
        $li_state_arr[] = $this->active_state_class;
      }
      $li_classes = implode(' ', $li_state_arr);
    }
    
    // Output EXACTLY like fallback menu
    // EC-NAV-094: Chevron after label for dropdown parents (aligns with Tailwind flex + gap-1 link rows)
    $dropdown_icon = '';
    $trim_cls = trim($classes_str);
    // EC-NAV-380: WordPress menu items carry no icon markup, so resolve the source
    // row from menus.json and redraw the icon it captured. Suppresses the injected
    // Lucide chevron for the same no-double-caret reason as the fallback renderer.
    if (!isset($original_item) || !is_array($original_item)) {
      $original_item = $this->find_original_item($item->title, $item->url);
    }
    $source_icon = wpconvert_nav_icon_html($original_item);
    // EC-NAV-219: skip the chevron when the title already contains a trailing
    // arrow glyph (e.g. aura-lace "Boutique ▾") so two arrows don't stack.
    if ($source_icon === '' && $has_children && $depth === 0 && ($trim_cls !== '' || !empty($this->base_link_classes)) && (!function_exists('wpconvert_emit_dropdown_chevron') || wpconvert_emit_dropdown_chevron()) && !wpconvert_title_has_trailing_arrow($item->title ?? '')) {
      $dropdown_icon = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="' . (function_exists('wpconvert_nav_icon_stroke') ? esc_attr(wpconvert_nav_icon_stroke()) : 'currentColor') . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-down h-3.5 w-3.5 shrink-0" aria-hidden="true"><path d="m6 9 6 6 6-6"></path></svg>';
      // EC-NAV-101: Ensure flex alignment so chevron sits inline with text
      $flex_needed = ['inline-flex', 'items-center', 'gap-1'];
      $c_arr = array_filter(explode(' ', $classes_str));
      foreach ($flex_needed as $fc) { if (!in_array($fc, $c_arr)) $c_arr[] = $fc; }
      $classes_str = implode(' ', $c_arr);
    }
    // EC-NAV-382: re-apply the site's own current-page class, matching the
    // pre-activation fallback renderer exactly. Applied after the chevron logic
    // so it cannot flip those decisions via a newly non-empty class string.
    // EC-NAV-383: skipped when the site marks the <li> instead.
    if ($is_current && !empty($this->active_state_class)
        && $this->active_state_target !== 'item') {
      $state_arr = array_filter(explode(' ', trim($classes_str)));
      if (!in_array($this->active_state_class, $state_arr, true)) {
        $state_arr[] = $this->active_state_class;
      }
      $classes_str = implode(' ', $state_arr);
    }
    $output .= $indent . '<li class="' . esc_attr($li_classes) . '">';
    // EC-NAV-235: class-toggle SPA nav links navigate client-side via an inline
    // handler (onclick="return nav('services')") captured into menus.json. This
    // UL/LI walker (the one the desktop navbar actually uses) must re-emit it or
    // the links go nowhere. Resolve the matching menus.json row by TITLE first —
    // SPA links all share url '#', so a URL match is ambiguous and is only trusted
    // when the JSON URL is specific. Returns '' for ordinary links (no handler).
    $handler_attr = '';
    if ($this->menu_data && !empty($this->menu_data['primary']['items'])) {
      $wp_title_l = strtolower(trim((string) $item->title));
      $wp_u = (string) ($item->url ?? '');
      foreach ($this->menu_data['primary']['items'] as $ji) {
        $j_attrs = (isset($ji['attributes']) && is_array($ji['attributes'])) ? $ji['attributes'] : array();
        if (empty($j_attrs['onclick']) && empty($j_attrs['id'])) continue;
        $jt = strtolower(trim((string) ($ji['title'] ?? '')));
        $ju = (string) ($ji['url'] ?? '');
        $url_specific = ($ju !== '' && $ju !== '#' && $ju !== '/');
        if (($wp_title_l !== '' && $wp_title_l === $jt) || ($url_specific && rtrim($wp_u, '/') === rtrim($ju, '/'))) {
          $handler_attr = wpconvert_inline_handler_attr_from_item($ji);
          break;
        }
      }
    }
    // EC-I18N-MENU-001: stamp data-i18n on the UL/LI walker's anchor when
    // the matched menus.json row carries an i18nKey. Prefer the already-
    // resolved $original_item (find_original_item ran above) and fall back
    // to the title-indexed helper for items that weren't resolved here.
    $i18n_attr = '';
    if ( isset( $original_item ) && is_array( $original_item ) ) {
      $i18n_attr = wpconvert_i18n_menu_attr_from_item($original_item);
    }
    if ( $i18n_attr === '' && function_exists('wpconvert_i18n_menu_attr_for_title') ) {
      $i18n_attr = wpconvert_i18n_menu_attr_for_title($item->title);
    }
    // EC-NAV-380: keep the source icon on the side of the label it came from.
    $label_html = esc_html($item->title);
    if ($source_icon !== '') {
      $label_html = wpconvert_nav_icon_before($original_item)
        ? $source_icon . ' ' . $label_html
        : $label_html . ' ' . $source_icon;
    }
    $output .= '<a href="' . wpconvert_nav_item_href($item->url) . '" class="' . esc_attr(trim($classes_str)) . '"' . $handler_attr . $i18n_attr . '>' . $label_html . $dropdown_icon . '</a>';
  }

  function end_el(&$output, $item, $depth = 0, $args = null) {
    $output .= "</li>\n";
  }
  
  // Helper to find original item in menus.json
  private function find_original_item($title, $url, $items = null) {
    if ($items === null && $this->menu_data) {
      $items = $this->menu_data['primary']['items'] ?? [];
    }
    if (!is_array($items)) return null;
    
    foreach ($items as $item) {
      if (isset($item['title']) && $item['title'] === $title) {
        return $item;
      }
      // Also check by URL
      if (isset($item['url']) && $item['url'] === $url) {
        return $item;
      }
      // Check children recursively
      if (!empty($item['children'])) {
        $found = $this->find_original_item($title, $url, $item['children']);
        if ($found) return $found;
      }
    }
    return null;
  }
}

// Theme setup
function wpconvert_theme_setup() {
    // Add theme support for various features
    add_theme_support('post-thumbnails');
    add_theme_support('title-tag');
    add_theme_support('custom-logo');
    add_theme_support('menus');
    add_theme_support('editor-styles');
    add_theme_support('html5', array(
        'search-form',
        'comment-form',
        'comment-list',
        'gallery',
        'caption',
    ));
    
    // Register navigation menus
    register_nav_menus(array(
        'primary' => __('Primary Menu', 'wpconvert'),
        'footer' => __('Footer Menu', 'wpconvert'),
    ));
}
add_action('after_setup_theme', 'wpconvert_theme_setup');

// Allow iframe/video embeds in post content (wp_kses_post strips them by default)
function wpconvert_allow_iframes_in_posts($tags, $context) {
    if ($context === 'post') {
        $tags['iframe'] = array(
            'src' => true, 'width' => true, 'height' => true,
            'frameborder' => true, 'allow' => true, 'allowfullscreen' => true,
            'title' => true, 'class' => true, 'style' => true,
            'loading' => true, 'referrerpolicy' => true,
        );
        $tags['video'] = array(
            'src' => true, 'controls' => true, 'autoplay' => true,
            'muted' => true, 'loop' => true, 'poster' => true,
            'preload' => true, 'class' => true, 'style' => true,
            'width' => true, 'height' => true,
        );
        $tags['source'] = array('src' => true, 'type' => true);
        // Allow details/summary for FAQ accordions
        $tags['details'] = array('class' => true, 'open' => true);
        $tags['summary'] = array('class' => true);

        // EC-BLOG-211: Allow safe, presentational inline SVG so article charts
        // (e.g. score scales / bar graphs) survive wp_kses_post. Only geometry
        // and styling attributes are permitted — no <script>, no <foreignObject>,
        // and no on* event handlers — so this cannot introduce script execution.
        $svg_common = array(
            'class' => true, 'style' => true, 'fill' => true, 'fill-opacity' => true,
            'fill-rule' => true, 'stroke' => true, 'stroke-width' => true,
            'stroke-linecap' => true, 'stroke-linejoin' => true, 'stroke-dasharray' => true,
            'stroke-opacity' => true, 'opacity' => true, 'transform' => true,
            'clip-path' => true, 'mask' => true, 'id' => true,
        );
        $svg_text = array_merge($svg_common, array(
            'x' => true, 'y' => true, 'dx' => true, 'dy' => true, 'text-anchor' => true,
            'dominant-baseline' => true, 'font-size' => true, 'font-family' => true,
            'font-weight' => true, 'letter-spacing' => true,
        ));
        $tags['svg'] = array_merge($svg_common, array(
            'xmlns' => true, 'xmlns:xlink' => true, 'viewbox' => true, 'width' => true,
            'height' => true, 'preserveaspectratio' => true, 'role' => true,
            'aria-label' => true, 'aria-hidden' => true, 'focusable' => true,
        ));
        $tags['g'] = $svg_common;
        $tags['defs'] = array('id' => true);
        $tags['title'] = array();
        $tags['desc'] = array();
        $tags['path'] = array_merge($svg_common, array('d' => true));
        $tags['rect'] = array_merge($svg_common, array('x' => true, 'y' => true, 'width' => true, 'height' => true, 'rx' => true, 'ry' => true));
        $tags['circle'] = array_merge($svg_common, array('cx' => true, 'cy' => true, 'r' => true));
        $tags['ellipse'] = array_merge($svg_common, array('cx' => true, 'cy' => true, 'rx' => true, 'ry' => true));
        $tags['line'] = array_merge($svg_common, array('x1' => true, 'y1' => true, 'x2' => true, 'y2' => true));
        $tags['polyline'] = array_merge($svg_common, array('points' => true));
        $tags['polygon'] = array_merge($svg_common, array('points' => true));
        $tags['text'] = $svg_text;
        $tags['tspan'] = $svg_text;
        $tags['lineargradient'] = array_merge($svg_common, array('x1' => true, 'y1' => true, 'x2' => true, 'y2' => true, 'gradientunits' => true, 'gradienttransform' => true));
        $tags['radialgradient'] = array_merge($svg_common, array('cx' => true, 'cy' => true, 'r' => true, 'fx' => true, 'fy' => true, 'gradientunits' => true));
        $tags['stop'] = array('offset' => true, 'stop-color' => true, 'stop-opacity' => true, 'class' => true, 'style' => true, 'id' => true);
        $tags['clippath'] = array('id' => true, 'class' => true);
        $tags['use'] = array_merge($svg_common, array('href' => true, 'xlink:href' => true, 'x' => true, 'y' => true, 'width' => true, 'height' => true));
    }
    return $tags;
}
add_filter('wp_kses_allowed_html', 'wpconvert_allow_iframes_in_posts', 10, 2);

// SEO: Load seo.json once and share across hooks
function wpconvert_get_seo_data() {
    static $seo_data = null;
    if ($seo_data === null) {
        $seo_path = get_template_directory() . '/assets/data/seo.json';
        if (file_exists($seo_path)) {
            $seo_data = json_decode(file_get_contents($seo_path), true);
        }
        if (!$seo_data || !is_array($seo_data)) {
            $seo_data = array();
        }
    }
    return $seo_data;
}

// SEO: Resolve the current page's route key in seo.json
function wpconvert_get_current_route() {
    // EC-SEO-TITLE-001: Check front page BEFORE is_page().
    // Static front pages satisfy BOTH is_front_page() and is_page().
    // Without this guard the slug-based lookup returns '/home' which
    // never matches the seo.json key '/'.
    if (is_front_page()) {
        return '/';
    }

    if (is_page()) {
        $slug = get_post_field('post_name', get_the_ID());
        $route = '/' . $slug;
        $ancestors = get_post_ancestors(get_the_ID());
        if (!empty($ancestors)) {
            $full_path = '';
            foreach (array_reverse($ancestors) as $ancestor) {
                $full_path .= '/' . get_post_field('post_name', $ancestor);
            }
            $full_path .= '/' . $slug;
            $seo_data = wpconvert_get_seo_data();
            if (isset($seo_data[$full_path])) {
                $route = $full_path;
            }
        }
        return $route;
    }

    return null;
}

// EC-BREADCRUMB-001: Breadcrumb trail for single posts (and hierarchical pages).
// Delegates to the active SEO plugin's breadcrumb so the user's RankMath / Yoast
// configuration wins; falls back to a native Home > Posts > Title trail (with
// BreadcrumbList JSON-LD) when no SEO plugin is installed. Called from single.php.
function wpconvert_breadcrumbs() {
    // 1) RankMath — respect the user's "Breadcrumbs" setting.
    if (function_exists('rank_math_the_breadcrumbs')) {
        $rm_enabled = true;
        if (class_exists('RankMath\Helper') && method_exists('RankMath\Helper', 'is_breadcrumbs_enabled')) {
            $rm_enabled = RankMath\Helper::is_breadcrumbs_enabled();
        }
        if ($rm_enabled) {
            echo '<div class="wpconvert-breadcrumbs">';
            rank_math_the_breadcrumbs();
            echo '</div>';
            return;
        }
    }
    // 2) Yoast — yoast_breadcrumb() returns false when breadcrumbs are disabled.
    if (function_exists('yoast_breadcrumb')) {
        $yoast = yoast_breadcrumb('<nav class="wpconvert-breadcrumbs" aria-label="Breadcrumb">', '</nav>', false);
        if ($yoast) {
            echo $yoast;
            return;
        }
    }
    // 3) Native fallback.
    wpconvert_render_native_breadcrumbs();
}

// EC-BREADCRUMB-001: Native breadcrumb trail used when no SEO plugin provides one.
function wpconvert_render_native_breadcrumbs() {
    $items = array();
    $items[] = array('label' => 'Home', 'url' => home_url('/'));
    if (is_singular('post')) {
        $posts_page = (int) get_option('page_for_posts');
        if ($posts_page) {
            $items[] = array('label' => get_the_title($posts_page), 'url' => get_permalink($posts_page));
        }
        $items[] = array('label' => get_the_title(), 'url' => '');
    } elseif (is_page()) {
        foreach (array_reverse(get_post_ancestors(get_the_ID())) as $anc) {
            $items[] = array('label' => get_the_title($anc), 'url' => get_permalink($anc));
        }
        $items[] = array('label' => get_the_title(), 'url' => '');
    } else {
        return;
    }

    echo '<nav class="wpconvert-breadcrumbs" aria-label="Breadcrumb"><ol class="wpconvert-breadcrumbs__list">';
    $count = count($items);
    foreach ($items as $i => $crumb) {
        echo '<li class="wpconvert-breadcrumbs__item">';
        if ($i > 0) {
            echo '<span class="wpconvert-breadcrumbs__sep" aria-hidden="true">&rsaquo;</span>';
        }
        if (!empty($crumb['url']) && $i < $count - 1) {
            echo '<a href="' . esc_url($crumb['url']) . '">' . esc_html($crumb['label']) . '</a>';
        } else {
            echo '<span aria-current="page">' . esc_html($crumb['label']) . '</span>';
        }
        echo '</li>';
    }
    echo '</ol></nav>';

    // BreadcrumbList JSON-LD (mirrors the source site's structured data).
    $ld_items = array();
    $pos = 1;
    foreach ($items as $crumb) {
        $entry = array('@type' => 'ListItem', 'position' => $pos, 'name' => $crumb['label']);
        if (!empty($crumb['url'])) {
            $entry['item'] = $crumb['url'];
        }
        $ld_items[] = $entry;
        $pos++;
    }
    $ld = array('@context' => 'https://schema.org', '@type' => 'BreadcrumbList', 'itemListElement' => $ld_items);
    echo '<script type="application/ld+json">' . wp_json_encode($ld) . '</script>';

    // Minimal styling, printed once per request.
    static $css_done = false;
    if (!$css_done) {
        $css_done = true;
        echo '<style id="wpconvert-breadcrumbs-css">.wpconvert-breadcrumbs{margin:0 0 1.5rem;font-size:.875rem}.wpconvert-breadcrumbs__list{display:flex;flex-wrap:wrap;align-items:center;gap:.375rem;list-style:none;margin:0;padding:0}.wpconvert-breadcrumbs__item{display:flex;align-items:center;gap:.375rem}.wpconvert-breadcrumbs__sep{opacity:.5}.wpconvert-breadcrumbs a{color:inherit;text-decoration:none;opacity:.75}.wpconvert-breadcrumbs a:hover{opacity:1;text-decoration:underline}.wpconvert-breadcrumbs [aria-current="page"]{font-weight:600}</style>';
    }
}

// SEO #1: Override WordPress <title> with the original page title
function wpconvert_seo_title($title_parts) {
    if (defined('WPSEO_VERSION') || defined('RANK_MATH_VERSION') || defined('AIOSEO_VERSION')) {
        return $title_parts;
    }
    
    $seo_data = wpconvert_get_seo_data();
    if (empty($seo_data)) return $title_parts;
    
    $route = wpconvert_get_current_route();
    if (!$route) return $title_parts;
    
    $page_seo = isset($seo_data[$route]) ? $seo_data[$route] : null;
    if (!$page_seo || empty($page_seo['title'])) return $title_parts;
    
    // Use the original captured title as the full title
    $original_title = $page_seo['title'];
    
    // If the original title contains a separator (| - — :), use it as-is
    if (preg_match('/[|\\-—:]/', $original_title)) {
        $title_parts['title'] = $original_title;
        unset($title_parts['site']);
        unset($title_parts['tagline']);
    } else {
        $title_parts['title'] = $original_title;
    }
    
    return $title_parts;
}
add_filter('document_title_parts', 'wpconvert_seo_title', 10, 1);

// SEO: Output meta tags, Open Graph, canonical, JSON-LD, robots, verification, and favicon
function wpconvert_seo_head() {
    if (defined('WPSEO_VERSION') || defined('RANK_MATH_VERSION') || defined('AIOSEO_VERSION')) {
        return;
    }
    
    $seo_data = wpconvert_get_seo_data();
    if (empty($seo_data)) return;
    
    // Site-wide verification meta tags (google-site-verification, etc.)
    if (isset($seo_data['_global']['verification']) && is_array($seo_data['_global']['verification'])) {
        foreach ($seo_data['_global']['verification'] as $name => $content) {
            echo '<meta name="' . esc_attr($name) . '" content="' . esc_attr($content) . '">' . "\n";
        }
    }
    
    // Favicon from original site
    if (isset($seo_data['_global']['favicon']) && !has_site_icon()) {
        $favicon_url = $seo_data['_global']['favicon'];
        // EC-SEO-001: Theme-relative paths and stale crawl loopback URLs → theme assets.
        if (!preg_match('#^https?://#i', $favicon_url)) {
            $favicon_url = get_template_directory_uri() . '/' . ltrim($favicon_url, '/');
        } elseif (preg_match('#^https?://(?:localhost|127\.0\.0\.1|\[::1\])(?::\d+)?/#i', $favicon_url)) {
            $favicon_url = get_template_directory_uri() . '/assets/images/' . basename(parse_url($favicon_url, PHP_URL_PATH));
        }
        echo '<link rel="icon" href="' . esc_url($favicon_url) . '">' . "\n";
        echo '<link rel="shortcut icon" href="' . esc_url($favicon_url) . '">' . "\n";
    }
    
    $route = wpconvert_get_current_route();
    if (!$route) return;
    
    $page_seo = isset($seo_data[$route]) ? $seo_data[$route] : null;
    if (!$page_seo) return;
    
    // Meta description
    if (!empty($page_seo['description'])) {
        echo '<meta name="description" content="' . esc_attr($page_seo['description']) . '">' . "\n";
    }
    
    // Meta keywords
    if (!empty($page_seo['keywords'])) {
        echo '<meta name="keywords" content="' . esc_attr($page_seo['keywords']) . '">' . "\n";
    }
    
    // Meta robots
    if (!empty($page_seo['robots'])) {
        echo '<meta name="robots" content="' . esc_attr($page_seo['robots']) . '">' . "\n";
    }
    
    // Canonical URL (rewrite to WordPress URL)
    if (!empty($page_seo['canonical'])) {
        $wp_canonical = is_front_page() ? home_url('/') : get_permalink();
        echo '<link rel="canonical" href="' . esc_url($wp_canonical) . '">' . "\n";
    }
    
    // Open Graph tags
    if (!empty($page_seo['og']) && is_array($page_seo['og'])) {
        foreach ($page_seo['og'] as $property => $content) {
            if ($property === 'og:url') {
                $content = is_front_page() ? home_url('/') : get_permalink();
            }
            echo '<meta property="' . esc_attr($property) . '" content="' . esc_attr($content) . '">' . "\n";
        }
        if (empty($page_seo['og']['og:title']) && !empty($page_seo['title'])) {
            echo '<meta property="og:title" content="' . esc_attr($page_seo['title']) . '">' . "\n";
        }
        if (empty($page_seo['og']['og:description']) && !empty($page_seo['description'])) {
            echo '<meta property="og:description" content="' . esc_attr($page_seo['description']) . '">' . "\n";
        }
    } elseif (!empty($page_seo['title']) || !empty($page_seo['description'])) {
        echo '<meta property="og:type" content="website">' . "\n";
        echo '<meta property="og:url" content="' . esc_url(is_front_page() ? home_url('/') : get_permalink()) . '">' . "\n";
        if (!empty($page_seo['title'])) {
            echo '<meta property="og:title" content="' . esc_attr($page_seo['title']) . '">' . "\n";
        }
        if (!empty($page_seo['description'])) {
            echo '<meta property="og:description" content="' . esc_attr($page_seo['description']) . '">' . "\n";
        }
    }
    
    // Twitter Card tags
    if (!empty($page_seo['twitter']) && is_array($page_seo['twitter'])) {
        foreach ($page_seo['twitter'] as $name => $content) {
            if ($name === 'twitter:url') {
                $content = is_front_page() ? home_url('/') : get_permalink();
            }
            echo '<meta name="' . esc_attr($name) . '" content="' . esc_attr($content) . '">' . "\n";
        }
    }
    
    // JSON-LD structured data
    if (!empty($page_seo['jsonLd']) && is_array($page_seo['jsonLd'])) {
        foreach ($page_seo['jsonLd'] as $schema) {
            $json = json_encode($schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            if ($json) {
                echo '<script type="application/ld+json">' . $json . '</script>' . "\n";
            }
        }
    }
}
add_action('wp_head', 'wpconvert_seo_head', 1);

// ───────────────────────────────────────────────────────────────────────────
// EC-SEO-101..105: Yoast SEO + RankMath integration.
// WPConvert pages have placeholder post_content (markup is rendered by the PHP
// template, not stored in the post body), so SEO-plugin content analysers rate
// every page red. These hooks hand the analysers the REAL captured content,
// word count, focus keyword, SEO title/description and cornerstone flag — using
// each plugin's official filters/postmeta. All side effects are guarded so the
// code is a no-op when no SEO plugin is installed. AIOSEO is deferred to v2
// (its analyser filter surface needs verification against current source).
// ───────────────────────────────────────────────────────────────────────────

// EC-SEO-101: Lazily load seo-content.json (called only by analyser filters,
// which fire inside wp-admin / Yoast REST analyser endpoint — not on every
// front-end page render). Static-cached per request.
function wpconvert_get_seo_content() {
    static $cache = null;
    if ($cache !== null) return $cache;
    $path = get_template_directory() . '/assets/data/seo-content.json';
    if (!file_exists($path)) return $cache = array();
    $cache = json_decode(file_get_contents($path), true) ?: array();
    return $cache;
}

// EC-SEO-101: Resolve a post_id -> route key. Differs from
// wpconvert_get_current_route (which uses is_front_page()/is_page() and only
// works in front-end query context) — this works in any context (admin, REST,
// cron) by reading get_option('page_on_front') directly. The hierarchical-path
// branch accepts the key if EITHER seo-content.json OR seo.json has it, so the
// EC-SEO-101 analyser hooks and the EC-SEO-105 title/description seed agree on
// the same route key even when a short page is absent from seo-content.json.
function wpconvert_route_for_post($post_id) {
    $post = get_post($post_id);
    if (!$post || $post->post_type !== 'page') return null;
    if ((int) get_option('page_on_front') === (int) $post_id) return '/';
    $slug = $post->post_name;
    $ancestors = get_post_ancestors($post_id);
    if (!empty($ancestors)) {
        $full_path = '';
        foreach (array_reverse($ancestors) as $a) {
            $full_path .= '/' . get_post_field('post_name', $a);
        }
        $full_path .= '/' . $slug;
        $content  = wpconvert_get_seo_content();
        $seo_data = wpconvert_get_seo_data();
        if (isset($content[$full_path]) || isset($seo_data[$full_path])) {
            return $full_path;
        }
    }
    return '/' . $slug;
}

// EC-SEO-101: Yoast + RankMath content-analyser handoff. AIOSEO deferred to v2.
add_filter('wpseo_pre_analysis_post_content', 'wpconvert_seo_inject_analyzer_content', 10, 2);
add_filter('rank_math/researcher/post_content', 'wpconvert_seo_inject_analyzer_content', 10, 2);
function wpconvert_seo_inject_analyzer_content($content, $post) {
    if (!$post) return $content;
    $route = wpconvert_route_for_post(is_object($post) ? $post->ID : $post);
    $seo_content = wpconvert_get_seo_content();
    if ($route && !empty($seo_content[$route]['html'])) {
        return $seo_content[$route]['html'];
    }
    return $content;
}

// EC-SEO-102: Yoast word-count override (used by cornerstone analysis +
// readability scores). RankMath computes its own count from the analyser
// content handed to it above, so it needs no separate hook.
add_filter('wpseo_post_content_word_count', 'wpconvert_seo_word_count', 10, 2);
function wpconvert_seo_word_count($count, $post) {
    $route = wpconvert_route_for_post(is_object($post) ? $post->ID : $post);
    $seo_content = wpconvert_get_seo_content();
    if ($route && !empty($seo_content[$route]['wordCount'])) {
        return (int) $seo_content[$route]['wordCount'];
    }
    return $count;
}

// EC-SEO-103: Seed suggested focus keyword on first edit-screen open.
// add_meta_boxes passes ($post_type, $post) — taking the args from the hook
// directly is reliable (get_the_ID() is not). Seeds once per plugin and never
// overwrites a value the user has set.
// EC-SEO-106 fix: prefer the extracted H1, but fall back to the first heading
// (h2/h3/…) when the page has no <h1> — common on hero-led designs where the
// only heading is an <h2>, or where the H1 was an image/logo. Without this the
// focus keyphrase stayed empty and Yoast's SEO analysis stayed red.
add_action('add_meta_boxes', 'wpconvert_seo_seed_focus_keyword', 10, 2);
function wpconvert_seo_seed_focus_keyword($post_type, $post) {
    if ($post_type !== 'page' || !$post) return;
    $post_id = (int) $post->ID;
    $route = wpconvert_route_for_post($post_id);
    $seo_content = wpconvert_get_seo_content();
    if (!$route || empty($seo_content[$route])) return;
    $entry = $seo_content[$route];
    $keyword = '';
    if (!empty($entry['h1'])) {
        $keyword = $entry['h1'];
    } elseif (!empty($entry['headings']) && is_array($entry['headings']) && !empty($entry['headings'][0]['text'])) {
        $keyword = $entry['headings'][0]['text'];
    }
    if (!$keyword) return;
    $keyword = sanitize_text_field($keyword);
    if (defined('WPSEO_VERSION') && !get_post_meta($post_id, '_yoast_wpseo_focuskw', true)) {
        update_post_meta($post_id, '_yoast_wpseo_focuskw', $keyword);
    }
    if (defined('RANK_MATH_VERSION') && !get_post_meta($post_id, 'rank_math_focus_keyword', true)) {
        update_post_meta($post_id, 'rank_math_focus_keyword', $keyword);
    }
}

// EC-SEO-105: Seed the SEO title + meta description from the captured seo.json
// so the user's RankMath / Yoast snippet is correct out of the box (the source's
// real <title>, e.g. "25 Best Things to Do in Sifnos, Greece (2026 Guide)", lives
// in seo.json — NOT in the WP post_title, which is the short nav label). Reuses
// the EC-SEO-103 add_meta_boxes($post_type, $post) pattern. Critically this writes
// ONLY plugin postmeta — it never touches post_title, so nav labels (from
// menus.json), breadcrumbs and slugs are unaffected. Seeds once; never overwrites
// a value the user has already set.
add_action('add_meta_boxes', 'wpconvert_seo_seed_meta', 10, 2);
function wpconvert_seo_seed_meta($post_type, $post) {
    if ($post_type !== 'page' || !$post) return;
    if (!defined('WPSEO_VERSION') && !defined('RANK_MATH_VERSION')) return;
    $post_id = (int) $post->ID;
    $route   = wpconvert_route_for_post($post_id);
    if (!$route) return;
    $seo_data = wpconvert_get_seo_data();
    $page_seo = isset($seo_data[$route]) ? $seo_data[$route] : null;

    $seo_title = ($page_seo && !empty($page_seo['title'])) ? sanitize_text_field($page_seo['title']) : '';
    $seo_desc  = ($page_seo && !empty($page_seo['description'])) ? sanitize_text_field($page_seo['description']) : '';

    // EC-SEO-106 fix: many AI-built sources ship no <meta name="description">,
    // so seo.json has none. Fall back to the description derived from the page's
    // first paragraph (captured in seo-content.json) so the Yoast/RankMath
    // snippet isn't left blank.
    if (!$seo_desc) {
        $seo_content = wpconvert_get_seo_content();
        if (!empty($seo_content[$route]['description'])) {
            $seo_desc = sanitize_text_field($seo_content[$route]['description']);
        }
    }

    // Nothing to seed (neither a captured title nor any description).
    if (!$seo_title && !$seo_desc) return;

    if (defined('WPSEO_VERSION')) {
        if ($seo_title && !get_post_meta($post_id, '_yoast_wpseo_title', true)) {
            update_post_meta($post_id, '_yoast_wpseo_title', $seo_title);
        }
        if ($seo_desc && !get_post_meta($post_id, '_yoast_wpseo_metadesc', true)) {
            update_post_meta($post_id, '_yoast_wpseo_metadesc', $seo_desc);
        }
    }
    if (defined('RANK_MATH_VERSION')) {
        if ($seo_title && !get_post_meta($post_id, 'rank_math_title', true)) {
            update_post_meta($post_id, 'rank_math_title', $seo_title);
        }
        if ($seo_desc && !get_post_meta($post_id, 'rank_math_description', true)) {
            update_post_meta($post_id, 'rank_math_description', $seo_desc);
        }
    }
}

// EC-SEO-104: Cornerstone auto-tag for the front page on theme activation.
// Runs at after_switch_theme priority 100 — AFTER wpconvert_setup_reading_settings
// (priority 99) sets page_on_front; otherwise get_option('page_on_front') returns
// 0 and this would be a silent no-op. RankMath pillar postmeta uses value '1' and
// is gated on RANK_MATH_VERSION so we never leave stray meta on Yoast-only sites.
add_action('after_switch_theme', 'wpconvert_seo_mark_cornerstone', 100);
function wpconvert_seo_mark_cornerstone() {
    if (get_option('wpconvert_seo_cornerstone_marked')) return;
    $front_id = (int) get_option('page_on_front');
    if (!$front_id) return;
    if (defined('WPSEO_VERSION')) {
        update_post_meta($front_id, '_yoast_wpseo_is_cornerstone', '1');
    }
    if (defined('RANK_MATH_VERSION')) {
        update_post_meta($front_id, 'rank_math_pillar_content', '1');
    }
    update_option('wpconvert_seo_cornerstone_marked', 1);
}

// EC-BTN-003: Inject shadcn/ui CSS variable fallbacks so Tailwind classes like
// bg-background, text-foreground, bg-card, bg-input, bg-muted resolve correctly.
// SPAs define these in their CSS; WordPress themes may not, causing transparent buttons.
function wpconvert_shadcn_css_variables() {
    echo '<style id="wpconvert-shadcn-vars">
:root {
  --background: 0 0% 100%;
  --foreground: 222.2 84% 4.9%;
  --card: 0 0% 100%;
