}
add_action('wp_head', 'wpconvert_shadcn_css_variables', 0);

// EC-PERF-003: Bulk page enumeration guard. Converted themes can be activated on
// sites with very large existing page counts (tens of thousands). Any maintenance
// that enumerates ALL pages must be skipped there — a full get_pages() scan loads
// the entire page table into PHP memory and gets the worker killed (503).
function wpconvert_bulk_page_ops_allowed() {
    static $allowed = null;
    if ($allowed !== null) return $allowed;
    $counts = wp_count_posts('page');
    $total = 0;
    foreach ((array) $counts as $status_count) { $total += (int) $status_count; }
    $allowed = ($total <= 2000);
    if (!$allowed && !get_option('wpconvert_bulk_ops_skipped')) {
        update_option('wpconvert_bulk_ops_skipped', $total);
        error_log('WPConvert: skipping bulk page maintenance - ' . $total . ' pages exceeds safe threshold (2000)');
    }
    return $allowed;
}

// EC-PERF-003: Surface the skip so site owners know why automatic setup was partial.
function wpconvert_bulk_ops_admin_notice() {
    if (!get_option('wpconvert_bulk_ops_skipped')) return;
    if (!current_user_can('manage_options')) return;
    echo '<div class="notice notice-warning"><p><strong>WPConvert:</strong> automatic bulk page/menu maintenance was skipped because this site has a very large number of pages. Your content is untouched; menus and page templates may need manual review.</p></div>';
}
add_action('admin_notices', 'wpconvert_bulk_ops_admin_notice');

// EC-PAGE-SLUG-001: Fix flat pages that steal slugs from hierarchical pages.
// WordPress enforces globally unique page slugs — a flat /dental-implants page
// causes /cypress-tx/dental-implants to be renamed dental-implants-2 → 404.
// Runs on admin_init (not just after_switch_theme) so it works when theme files
// are replaced without switching themes. Uses a version flag to run once.
function wpconvert_fix_slug_conflicts() {
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return;
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) return;

    $routes_hash = md5_file($routes_path);
    $hier_leaf_slugs = array();
    foreach ($routes as $route => $data) {
        $slug = trim($route, '/');
        $segments = explode('/', $slug);
        if (count($segments) > 1) {
            $hier_leaf_slugs[end($segments)] = true;
        }
    }
    if (empty($hier_leaf_slugs)) {
        update_option('wpconvert_slugfix_step1_hash', $routes_hash);
        return;
    }

    $changed = false;

    // EC-SAFE-001: Step 1 used to DELETE the top-level page holding a conflicting slug —
    // with wp_delete_post($id, true), so it bypassed the Trash — and it never checked
    // wpconvert_is_autogen_stub_page(), so a customer-authored /services/ page was
    // destroyed whenever the site had a /locations/services/ route and no
    // page-services.php. Reconverting re-armed it, because routes.json changing changes
    // its md5.
    //
    // That delete was never necessary. WordPress scopes page slug uniqueness to SIBLINGS,
    // not globally: wp_unique_post_slug()'s hierarchical branch filters on
    // "AND post_parent = %d". A child of locations may hold the slug "services" while an
    // unrelated top-level /services/ page keeps existing. Nothing has to be removed for
    // the hierarchical route to resolve — the child's suffixed slug simply has to be
    // repaired, which is what Step 2 already did for numeric leaves.
    //
    // Steps 1 and 2 now do the same thing and share one bounded query; they differ only
    // in which leaf slugs they own and which convergence hash gates them.
    $step1_due = get_option('wpconvert_slugfix_step1_hash') !== $routes_hash;

    // Step 2: Fix child pages with -2/-3 suffixed slugs (1-2 → 1, services-2 → services).
    // EC-PERF-001: The old implementation enumerated ALL pages via get_pages('any')
    // on every init/admin_init request — on sites with large page counts that loads
    // the whole page table into memory per request and the PHP worker gets killed.
    // Now: (a) an O(1) hash guard skips the work entirely once converged (the hash
    // is cleared by WPConvert page-creation routines so new inserts re-arm it), and
    // (b) when it does run, a single bounded indexed query targets only suffixed
    // variants of the leaf slugs from routes.json — never a full scan.
    $step2_due = get_option('wpconvert_slugfix_step2_hash') !== $routes_hash;
    $repair_leaves = array();
    foreach ($hier_leaf_slugs as $leaf_slug => $_t) {
        $leaf_slug = (string) $leaf_slug;
        if ($leaf_slug === '') continue;
        // Numeric leaves (blog/1) belong to Step 2, everything else to Step 1.
        $owned_by_step2 = ctype_digit($leaf_slug);
        if ($owned_by_step2 ? $step2_due : $step1_due) {
            $repair_leaves[] = $leaf_slug;
        }
    }
    if (!empty($repair_leaves)) {
        global $wpdb;
        $like_sql = array();
        $like_params = array();
        foreach (array_slice($repair_leaves, 0, 50) as $nl) {
            $like_sql[] = 'post_name LIKE %s';
            $like_params[] = $wpdb->esc_like($nl) . '-%';
        }
        $candidate_rows = $wpdb->get_results($wpdb->prepare(
            "SELECT ID, post_name, post_parent FROM {$wpdb->posts} WHERE post_type = 'page' AND post_parent > 0 AND (" . implode(' OR ', $like_sql) . ') LIMIT 200',
            $like_params
        ));
        foreach ((array) $candidate_rows as $pg) {
            $name = $pg->post_name;
            // Was /^(\d+)-(\d+)$/ (numeric only). Now any suffixed leaf, so the
            // EC-SAFE-001 text case (services-2) is repaired the same way.
            if (!preg_match('/^(.+)-(\d+)$/', $name, $m)) {
                continue;
            }
            $base_slug = $m[1];
            if (!isset($hier_leaf_slugs[$base_slug]) || $pg->post_parent <= 0) {
                continue;
            }
            $parent = get_post((int) $pg->post_parent);
            if (!$parent || $parent->post_type !== 'page' || !function_exists('wpconvert_page_hier_path')) {
                continue;
            }
            $pp = wpconvert_page_hier_path($parent->ID);
            if ($pp === '') {
                continue;
            }
            $canonical_path = $pp . '/' . $base_slug;
            // EC-SAFE-001: only ever rename a page into a path this site actually
            // declares. Without this a customer page that merely happens to end in
            // -<digits> could be renamed on top of a route it was never part of.
            if (!isset($routes['/' . $canonical_path])) {
                continue;
            }
            $existing = function_exists('wpconvert_get_page_any_status') ? wpconvert_get_page_any_status($canonical_path) : get_page_by_path($canonical_path);
            if ($existing && (int) $existing->ID !== (int) $pg->ID && function_exists('wpconvert_is_autogen_stub_page') && wpconvert_is_autogen_stub_page($existing)) {
                // EC-SAFE-002: trash, never force delete. wp_trash_post() renames
                // post_name to {slug}__trashed, which is what actually frees the slug.
                // Drafting would NOT: wp_unique_post_slug() returns early for drafts and
                // its hierarchical check carries no post_status condition, so a drafted
                // page keeps blocking the name it holds.
                wp_trash_post($existing->ID);
                $existing = null;
            }
            if (!$existing || (int) $existing->ID === (int) $pg->ID) {
                if (wpconvert_set_post_slug_direct($pg->ID, $base_slug)) {
                    $changed = true;
                }
            }
        }
    }
    // EC-SAFE-003: converge unconditionally. The hash used to be stored only in the
    // "nothing changed" branch, so any pass that actually repaired something failed to
    // record convergence and the bounded query ran again on the next request — and this
    // is hooked on init (EC-PAGE-SLUG-004), so that includes front-end requests.
    //
    // Measured on a real install: with the numeric rescue filter below applying, the old
    // code did converge, just one pass later than it should have. The dangerous case is
    // when that filter does NOT apply — no matching routes.json entry, an empty
    // hierarchical path, or a non-stub occupant — because then wp_update_post() cannot
    // set the slug at all (core rejects numeric hierarchical slugs outright) and nothing
    // ever converges. Storing the hash here makes convergence independent of whether the
    // repair succeeded, and wpconvert_set_post_slug_direct() removes the dependency on
    // the filter in the first place.
    if ($step1_due) {
        update_option('wpconvert_slugfix_step1_hash', $routes_hash);
    }
    if ($step2_due) {
        update_option('wpconvert_slugfix_step2_hash', $routes_hash);
    }

    if ($changed) {
        // EC-PERF-002: Was delete_option('wpconvert_routes_hash'), which forced
        // wpconvert_ensure_missing_pages into a FULL re-run (page creation +
        // flush_rewrite_rules) on the next admin request — and could keep doing
        // so request after request. The one-shot flag below grants exactly one
        // bounded reconvergence pass instead.
        update_option('wpconvert_routes_reconverge', 1);
    }
}
// EC-PAGE-SLUG-004: Must run on init (front + admin), not only admin_init — otherwise /blog/1/ is resolved
// before any wp-admin visit, the child stays post_name 1-2, and the URL /blog/1/ never matches any page.
add_action('init', 'wpconvert_fix_slug_conflicts', 1);
add_action('admin_init', 'wpconvert_fix_slug_conflicts', 1);
add_action('after_switch_theme', 'wpconvert_fix_slug_conflicts', 5);

function wpconvert_repair_page_templates_on_init() {
    static $wpconvert_repair_init_done = false;
    if ($wpconvert_repair_init_done) {
        return;
    }
    $wpconvert_repair_init_done = true;
    if (!function_exists('wpconvert_repair_page_templates')) {
        return;
    }
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) {
        return;
    }
    // EC-PERF-001: O(1) guard — repair runs once per routes.json contents (or when
    // a reconvergence pass was requested), then this front-end hook is a no-op.
    // Previously the full repair (including a get_pages all-status scan) ran on
    // EVERY request, which crashed PHP on sites with large page counts.
    $tpl_hash = md5_file($routes_path);
    if (!get_option('wpconvert_routes_reconverge') && get_option('wpconvert_tplrepair_hash') === $tpl_hash) {
        return;
    }
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) {
        return;
    }
    wpconvert_repair_page_templates($routes);
    update_option('wpconvert_tplrepair_hash', $tpl_hash);
}
// Same reason: repair was only on admin_init / after_switch_theme — front never got _wp_page_template fixed.
add_action('init', 'wpconvert_repair_page_templates_on_init', 2);

// get_page_by_path only finds published pages. Trashed/draft pages with the
// same slug are invisible, so wp_insert_post creates "slug-2" duplicates.
// This helper checks ALL statuses to prevent that.
function wpconvert_get_page_any_status( $path, $post_type = 'page' ) {
    $page = get_page_by_path( $path, OBJECT, $post_type );
    if ( $page ) return $page;
    $slug = basename( $path );
    $found = get_posts( array(
        'name'        => $slug,
        'post_type'   => $post_type,
        'post_status' => array( 'trash', 'draft', 'pending', 'private' ),
        'numberposts' => 1,
    ) );
    return ! empty( $found ) ? $found[0] : null;
}

// Disposable placeholder: boilerplate post_content only. Starter/SPA pages keep that DB text but render
// from page-*.php — never treat as stub when _wp_page_template points at an existing snapshot file.
//
// EC-EDITOR-068: authorship is now recorded as _wpconvert_generated meta rather than inferred from
// the body text. Sniffing post_content was always fragile — the owner only has to retype the paragraph
// for the page to stop being recognised — and it is checked in several places that would drift apart.
// The text check stays as a fallback because pages seeded by earlier conversions carry no meta, and
// those sites are exactly the ones already in the field.
function wpconvert_is_autogen_stub_page($post) {
    if (!$post || $post->post_type !== 'page') return false;
    $c = isset($post->post_content) ? (string) $post->post_content : '';
    $flagged = (bool) get_post_meta($post->ID, '_wpconvert_generated', true);
    if (!$flagged && strpos($c, 'automatically generated by WPConvert') === false) return false;
    $tpl = get_post_meta($post->ID, '_wp_page_template', true);
    if (is_string($tpl) && $tpl !== '' && $tpl !== 'default') {
        $fn = basename($tpl);
        if (preg_match('/^page-[a-zA-Z0-9_.-]+\.php$/', $fn) && file_exists(get_template_directory() . '/' . $fn)) {
            return false;
        }
    }
    return true;
}

// EC-EDITOR-068: Record authorship once, at creation, instead of stamping meta at each of the nine
// wp_insert_post() call sites that seed pages — a list that would inevitably drift as sites are added.
// Reading the body here is safe in a way that reading it later is not: our own code wrote that string
// microseconds ago, so it cannot yet have been edited away. From then on _wpconvert_generated is the
// durable answer, which is what the editor signpost and the "Page Settings" rename rely on.
function wpconvert_flag_generated_page($post_id, $post, $update) {
    if ($update || !$post || $post->post_type !== 'page') return;
    $body = isset($post->post_content) ? (string) $post->post_content : '';
    if (strpos($body, 'automatically generated by WPConvert') === false) return;
    update_post_meta($post_id, '_wpconvert_generated', 1);
}
add_action('wp_insert_post', 'wpconvert_flag_generated_page', 10, 3);

// Full hierarchical path (e.g. blog/1) from the post_parent chain.
// get_page_uri() can return only "1" for numeric leaf slugs, which breaks
// wpconvert_repair_page_templates() $by_uri matching and leaves _wp_page_template unset.
function wpconvert_page_hier_path($post_id) {
    $post_id = (int) $post_id;
    if (!$post_id) return '';
    $cur = get_post($post_id);
    if (!$cur || $cur->post_type !== 'page') return '';
    $parts = array();
    $guard = 0;
    while ($cur && $cur->post_type === 'page' && $guard++ < 50) {
        array_unshift($parts, $cur->post_name);
        if (empty($cur->post_parent)) break;
        $cur = get_post((int) $cur->post_parent);
        if (!$cur || $cur->post_type !== 'page') break;
    }
    return trim(implode('/', $parts), '/');
}

// EC-SAFE-003: set post_name directly, bypassing wp_update_post().
//
// wp_unique_post_slug() rejects ANY purely numeric hierarchical slug — not just
// colliding ones — because such a slug is ambiguous with a pagination segment. So
// wp_update_post(array('post_name' => '1')) was silently rewritten back to 1-2 and
// the repair never took. Writing the column directly is the only way to land the
// canonical slug; clean_post_cache() then keeps get_post()/permalinks consistent.
function wpconvert_set_post_slug_direct($post_id, $slug) {
    global $wpdb;
    $post_id = (int) $post_id;
    $slug = (string) $slug;
    if (!$post_id || $slug === '') return false;
    $updated = $wpdb->update($wpdb->posts, array('post_name' => $slug), array('ID' => $post_id));
    if ($updated === false) return false;
    clean_post_cache($post_id);
    return true;
}

// Prefer routes.json slugs (e.g. 1 not 1-2) when inserting/updating blog children if only a stub blocks the name.
function wpconvert_prefer_numeric_route_slugs_for_blog_children($slug, $post_id, $post_status, $post_type, $post_parent, $original_slug) {
    // EC-SAFE-002: this filter now calls wp_trash_post() instead of wp_delete_post().
    // wp_trash_post() goes through wp_update_post(), which re-enters
    // wp_unique_post_slug() and therefore this very filter; wp_delete_post() did not.
    // The occupant checks below would terminate the recursion on their own, but a
    // static guard makes that explicit rather than incidental.
    static $wpconvert_slug_filter_running = false;
    if ($wpconvert_slug_filter_running) return $slug;
    if ($post_type !== 'page' || !$post_parent) return $slug;
    if (!preg_match('/^(\d+)$/', (string) $original_slug)) return $slug;
    if ($slug === $original_slug) return $slug;
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path) || !function_exists('wpconvert_page_hier_path')) return $slug;
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) return $slug;
    $pp = wpconvert_page_hier_path((int) $post_parent);
    if ($pp === '') return $slug;
    $canonical = $pp . '/' . $original_slug;
    if (!isset($routes['/' . $canonical])) return $slug;
    if (!function_exists('wpconvert_get_page_any_status')) return $slug;
    $occupant = wpconvert_get_page_any_status($canonical);
    if (!$occupant || (int) $occupant->ID === (int) $post_id) return $original_slug;
    if (function_exists('wpconvert_is_autogen_stub_page') && wpconvert_is_autogen_stub_page($occupant)) {
        // EC-SAFE-002: trash frees the slug (post_name becomes {slug}__trashed) and is
        // recoverable; a force delete was not, and a draft would not free it at all.
        $wpconvert_slug_filter_running = true;
        wp_trash_post($occupant->ID);
        $wpconvert_slug_filter_running = false;
        return $original_slug;
    }
    return $slug;
}
add_filter('wp_unique_post_slug', 'wpconvert_prefer_numeric_route_slugs_for_blog_children', 10, 6);

// Resolve a published/trashed page for a routes.json path (exact, flat, or blog/N-2 style).
function wpconvert_get_page_for_route($route) {
    if ($route === '/' || $route === '#' || strpos($route, '?') !== false) return null;
    $path = trim($route, '/');
    if ($path === '') return null;
    $p = get_page_by_path($path);
    if ($p) return $p;
    $p = get_page_by_path(str_replace('/', '-', $path));
    if ($p) return $p;
    $segments = explode('/', $path);
    $leaf = end($segments);
    if (!preg_match('/^(\d+)$/', $leaf)) return null;
    if (!function_exists('wpconvert_page_hier_path')) return null;
    // EC-PAGE-SLUG-006: this recovery used to require a parent (it was written for
    // /blog/1), but WordPress rewrites a purely numeric slug at EVERY depth. A
    // top-level /404 — the source archive's 404.html — is stored as "404-2", the
    // lookup for "404" failed, and the seeder inserted a fresh duplicate on every
    // single admin request: 404-2, 404-3, 404-4, unbounded. Observed on a real
    // install, and present in themes already shipped to customers.
    $parent_prefix = count($segments) > 1
        ? implode('/', array_slice($segments, 0, -1)) . '/'
        : '';
    // EC-PERF-001: Targeted indexed lookup instead of enumerating ALL pages.
    // Only pages whose slug is a suffixed variant of the numeric leaf (1-2, 1-3...)
    // can ever match, so query exactly those (post_name LIKE 'leaf-%', bounded).
    global $wpdb;
    $candidate_ids = $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts} WHERE post_type = 'page' AND post_status IN ('publish','draft','private','trash') AND post_name LIKE %s LIMIT 50",
        $wpdb->esc_like($leaf) . '-%'
    ));
    foreach ((array) $candidate_ids as $cand_id) {
        $u = wpconvert_page_hier_path((int) $cand_id);
        if ($u === '') continue;
        if ($parent_prefix !== '' && strpos($u, $parent_prefix) !== 0) continue;
        $suf = substr($u, strlen($parent_prefix));
        // With no parent prefix the whole path must be the renamed slug, so a
        // child like "loan-options/404-2" can never satisfy a top-level "/404".
        if (preg_match('/^' . preg_quote($leaf, '/') . '-\d+$/', $suf)) return get_post((int) $cand_id);
    }
    return null;
}

function wpconvert_route_has_matching_page($route) {
    return wpconvert_get_page_for_route($route) !== null;
}

// EC-PAGE-SLUG-007: true only for the Privacy Policy draft WordPress creates for
// itself and nobody has since edited. Deliberately narrow — it is the one draft on
// a fresh site that exists purely to reserve a slug, so publishing it cannot
// surface anything the owner wrote. Every other draft is left alone.
function wpconvert_is_untouched_core_privacy_page($page) {
    if (!$page || empty($page->ID)) return false;
    $privacy_id = (int) get_option('wp_page_for_privacy_policy');
    if (!$privacy_id || $privacy_id !== (int) $page->ID) return false;
    // WordPress stamps both dates identically at creation; any edit moves modified.
    return $page->post_modified_gmt === $page->post_date_gmt;
}

// EC-BLOG-167: Remove autogen stub at blog/1 when the real article lives at blog/1-2 so rename can yield /blog/1/.
function wpconvert_cleanup_blocking_numeric_blog_pages() {
    static $wpconvert_blog_stub_cleanup_done = false;
    if ($wpconvert_blog_stub_cleanup_done) {
        return;
    }
    $wpconvert_blog_stub_cleanup_done = true;
    if (!function_exists('wpconvert_get_page_for_route') || !function_exists('wpconvert_is_autogen_stub_page')) {
        return;
    }
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) {
        return;
    }
    // EC-PERF-001: O(1) guard — once converged for this routes.json, skip the
    // route loop (and its page lookups) entirely on the front end.
    $stub_hash = md5_file($routes_path);
    if (!get_option('wpconvert_routes_reconverge') && get_option('wpconvert_blogstub_hash') === $stub_hash) {
        return;
    }
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) {
        return;
    }
    $changed = false;
    foreach ($routes as $route => $_d) {
        if ($route === '/' || $route === '#' || strpos($route, '?') !== false) {
            continue;
        }
        $slug = trim($route, '/');
        if (!preg_match('#^blog/(\d+)$#', $slug)) {
            continue;
        }
        $canonical = $slug;
        $winner = wpconvert_get_page_for_route($route);
        if (!$winner) {
            continue;
        }
        $blocker = wpconvert_get_page_any_status($canonical);
        if (!$blocker || (int) $blocker->ID === (int) $winner->ID) {
            continue;
        }
        if (wpconvert_is_autogen_stub_page($blocker)) {
            // EC-SAFE-002: trash rather than force delete — this must free the
            // canonical blog/N path, which trashing does by suffixing post_name.
            wp_trash_post($blocker->ID);
            $changed = true;
        }
    }
    if ($changed) {
        // EC-PERF-002: One-shot reconvergence instead of deleting the routes hash
        // (which re-triggered full page creation on every subsequent admin request).
        update_option('wpconvert_routes_reconverge', 1);
    } else {
        update_option('wpconvert_blogstub_hash', $stub_hash);
    }
}
add_action('init', 'wpconvert_cleanup_blocking_numeric_blog_pages', 0);

// EC-BLOG-CAT-ASSIGN-001: Assign a category to a post BY NAME, reliably.
//
// WordPress's wp_set_post_terms is the WRONG primitive for assigning a category
// by name: for a hierarchical taxonomy it runs array_map('intval', $terms) on the
// list "so children with the same names but different parents aren't confused",
// which turns a name like "Food" into intval('Food') === 0. wp_set_object_terms()
// is then handed term id 0 (non-existent) and assigns NOTHING — the post silently
// stays Uncategorized. This was masked while blog cards rendered a baked-in static
// category badge; once the cards became dynamic (get_the_category()), every post
// showed "Uncategorized".
//
// This helper resolves (creating if needed) the term to a real term_id and assigns
// it via wp_set_object_terms(), which correctly accepts a name OR an id. Idempotent
// and safe to call repeatedly.
function wpconvert_assign_post_category($post_id, $cat_name) {
    $cat_name = trim((string) $cat_name);
    if ($cat_name === '') return false;

    $term = term_exists($cat_name, 'category');
    if (!$term) {
        $term = wp_insert_term($cat_name, 'category');
    }
    if (is_wp_error($term)) return $term;

    $term_id = is_array($term) ? (int) $term['term_id'] : (int) $term;
    if (!$term_id) return false;

    return wp_set_object_terms($post_id, array($term_id), 'category', false);
}

// EC-BLOG-CAT-ASSIGN-001: Standalone, self-healing category repair.
//
// Sites imported by an earlier build assigned categories with the broken
// wp_set_post_terms call above and therefore have every imported post stuck on
// "Uncategorized". Because wpconvert_import_blog_posts() is signature-latched (and
// short-circuits entirely once any live post exists), re-uploading the fixed theme
// would NOT re-run the in-loop backfill — the posts would stay Uncategorized
// forever. This routine is DECOUPLED from the import gate (mirrors the shadow-page
// cleanup) and re-runs whenever the repair version bumps or the source data
// changes. It only ever touches WPConvert-imported posts and never overwrites a
// category the owner already set to the correct source value.
function wpconvert_repair_blog_categories() {
    static $done = false;
    if ($done) return;
    $done = true;

    if (!defined('WPCONVERT_NATIVE_BLOG') || !WPCONVERT_NATIVE_BLOG) return;

    $json_path = get_template_directory() . '/assets/data/import-posts.json';
    if (!file_exists($json_path)) return;

    // Bump WPCONVERT_CAT_REPAIR_VER to force the repair to re-run after a fix.
    $repair_ver = '1';
    $sig = @md5_file($json_path);
    $sig = ($sig ? $sig : 'nofile') . ':v' . $repair_ver;
    if (get_option('wpconvert_blog_cat_repair_sig') === $sig) return;

    $data = json_decode(file_get_contents($json_path), true);
    if (!is_array($data)) return;
    $posts = isset($data['posts']) ? $data['posts'] : $data;
    if (!is_array($posts) || empty($posts)) return;

    // Don't latch until at least one imported post is present (avoid racing ahead
    // of wpconvert_import_blog_posts() and then skipping the repair forever).
    $any_native = false;
    foreach ($posts as $post_data) {
        $slug = isset($post_data['slug']) ? $post_data['slug'] : (isset($post_data['title']) ? $post_data['title'] : '');
        if ($slug === '') continue;
        if (get_page_by_path(sanitize_title($slug), OBJECT, 'post')) {
            $any_native = true;
            break;
        }
    }
    if (!$any_native) return;

    foreach ($posts as $post_data) {
        if (empty($post_data['category'])) continue;
        $slug = isset($post_data['slug']) ? $post_data['slug'] : (isset($post_data['title']) ? $post_data['title'] : '');
        if ($slug === '') continue;

        $post = get_page_by_path(sanitize_title($slug), OBJECT, 'post');
        if (!$post) continue;

        $want = sanitize_text_field($post_data['category']);
        $terms = wp_get_post_terms($post->ID, 'category', array('fields' => 'names'));
        if (is_wp_error($terms)
            || empty($terms)
            || (count($terms) === 1 && strcasecmp($terms[0], 'Uncategorized') === 0)
            || !in_array($want, $terms, true)) {
            wpconvert_assign_post_category($post->ID, $want);
        }
    }

    update_option('wpconvert_blog_cat_repair_sig', $sig);
}
// Priority 27 — after the import (init@20) and shadow-page cleanup (init@25).
add_action('init', 'wpconvert_repair_blog_categories', 27);
add_action('admin_init', 'wpconvert_repair_blog_categories', 27);
add_action('after_switch_theme', 'wpconvert_repair_blog_categories', 27);

// EC-BLOG-SHADOW-PAGE-001: After a theme swap / reconvert onto a site that already
// had a WPConvert theme, leftover SPA Pages at /{blogRoutePrefix}/{slug}/ (created
// by the previous theme from routes.json) shadow the native Posts that the new
// PRO/Agency theme imports at the same permalink. Visitors see the empty
// "This page is automatically generated by WPConvert…" stub instead of single.php.
// Delete ONLY autogen stub Pages whose hierarchical path matches a real Post slug
// under the blog prefix. Never touch the posts-index page at the bare listing slug,
// and never delete a page the owner has edited (non-stub content).
function wpconvert_cleanup_native_blog_shadow_pages() {
    static $done = false;
    if ($done) return;
    $done = true;

    if (!defined('WPCONVERT_NATIVE_BLOG') || !WPCONVERT_NATIVE_BLOG) return;
    if (!function_exists('wpconvert_is_autogen_stub_page')) return;

    $json_path = get_template_directory() . '/assets/data/import-posts.json';
    if (!file_exists($json_path)) return;

    $sig = @md5_file($json_path);
    if ($sig && get_option('wpconvert_shadow_page_cleanup_sig') === $sig) return;

    $data = json_decode(file_get_contents($json_path), true);
    if (!is_array($data)) return;
    $posts = isset($data['posts']) ? $data['posts'] : $data;
    if (!is_array($posts) || empty($posts)) return;

    $blog_prefix = isset($data['blogRoutePrefix']) ? $data['blogRoutePrefix'] : '/blog';
    $prefix_slug = trim((string) $blog_prefix, '/');
    if ($prefix_slug === '') return;

    // Do not latch the signature until at least one native Post from the JSON
    // exists — otherwise a race before wpconvert_import_blog_posts() would
    // permanently skip cleanup and leave the shadowing stubs in place.
    $any_native = false;
    foreach ($posts as $post_data) {
        if (empty($post_data['slug'])) continue;
        if (get_page_by_path(sanitize_title($post_data['slug']), OBJECT, 'post')) {
            $any_native = true;
            break;
        }
    }
    if (!$any_native) return;

    $changed = false;
    foreach ($posts as $post_data) {
        if (empty($post_data['slug'])) continue;
        $slug = sanitize_title($post_data['slug']);
        if ($slug === '') continue;

        // Require a matching native Post — never delete a Page when the Post
        // was not imported (or was removed by the owner).
        $native_post = get_page_by_path($slug, OBJECT, 'post');
        if (!$native_post) continue;

        // Hierarchical path: article/la-bandera-dominicana (the URL that
        // collides with /article/%postname%/ permalinks).
        $path = $prefix_slug . '/' . $slug;
        $page = function_exists('wpconvert_get_page_any_status')
            ? wpconvert_get_page_any_status($path)
            : get_page_by_path($path);
        if ($page && wpconvert_is_autogen_stub_page($page)) {
            // EC-SAFE-002: trash rather than force delete — the shadow page has to stop
            // occupying this path so the native post permalink wins, and trashing
            // renames post_name to {slug}__trashed, which achieves exactly that.
            wp_trash_post($page->ID);
            $changed = true;
        }
    }

    if ($sig) {
        update_option('wpconvert_shadow_page_cleanup_sig', $sig);
    }
    if ($changed) {
        flush_rewrite_rules(false);
    }
}
// Priority 25 — after wpconvert_import_blog_posts (init@20) so native Posts exist.
add_action('init', 'wpconvert_cleanup_native_blog_shadow_pages', 25);
add_action('admin_init', 'wpconvert_cleanup_native_blog_shadow_pages', 25);
add_action('after_switch_theme', 'wpconvert_cleanup_native_blog_shadow_pages', 25);

// EC-BLOG-COMMENTS-001: keep imported posts' comment_status in sync with the
// "Enable comments" Customizer toggle. Runs only when the toggle VALUE changes
// (tracked in an option), so it's a cheap no-op on normal requests. Only touches
// WPConvert-imported posts (_wpconvert_imported) — never the owner's own posts.
function wpconvert_sync_blog_comment_status() {
    if (!defined('WPCONVERT_NATIVE_BLOG') || !WPCONVERT_NATIVE_BLOG) return;
    if (!function_exists('wpconvert_enable_comments')) return;
    $want = wpconvert_enable_comments() ? 'open' : 'closed';
    if (get_option('wpconvert_comment_status_synced') === $want) return;
    $q = new WP_Query(array(
        'post_type'      => 'post',
        'post_status'    => 'any',
        'posts_per_page' => -1,
        'fields'         => 'ids',
        'meta_key'       => '_wpconvert_imported',
        'meta_value'     => 1,
        'no_found_rows'  => true,
    ));
    if (!empty($q->posts)) {
        foreach ($q->posts as $pid) {
            wp_update_post(array('ID' => $pid, 'comment_status' => $want));
        }
    }
    update_option('wpconvert_comment_status_synced', $want);
}
// Priority 26 — after the import (init@20) and shadow-page cleanup (init@25).
add_action('init', 'wpconvert_sync_blog_comment_status', 26);
add_action('customize_save_after', 'wpconvert_sync_blog_comment_status');
add_action('after_switch_theme', 'wpconvert_sync_blog_comment_status', 26);

// Ensure every route has a page with the correct _wp_page_template meta.
// Finds existing pages (even with broken hierarchy) and assigns templates.
// Creates missing pages with correct parent/child hierarchy when needed.
function wpconvert_repair_page_templates($routes) {
    if (!is_array($routes)) return;
    $tpl_dir = get_template_directory();

    // EC-PERF-001: Build the URI lookup map ONLY for paths referenced in routes.json
    // (targeted get_page_by_path / slug lookups) instead of enumerating ALL pages.
    // The old full get_pages() scan loaded every page into memory on each run and
    // crashed PHP on sites with large existing page counts.
    $by_uri = array();
    foreach ($routes as $route => $_rx) {
        if ($route === '/' || $route === '#' || strpos($route, '?') !== false) continue;
        $rslug = trim($route, '/');
        if ($rslug === '' || isset($by_uri[$rslug])) continue;
        $rflat = str_replace('/', '-', $rslug);

        // 1. Exact hierarchical path (any status — trashed/draft included)
        $rp = wpconvert_get_page_any_status($rslug);
        if ($rp) {
            $by_uri[$rslug] = $rp;
        }
        // 2. Flat-slug variant (services/x stored as services-x)
        if ($rflat !== $rslug && !isset($by_uri[$rflat])) {
            $rpf = wpconvert_get_page_any_status($rflat);
            if ($rpf) {
                $by_uri[$rflat] = $rpf;
            }
        }
        // EC-PAGE-SLUG-003: routes.json says /blog/1 but WP created blog/1-2 — map the
        // canonical path to that page so we assign page-blog-1.php and do NOT
        // wp_insert_post duplicate "blog/1" children every admin load.
        if (!isset($by_uri[$rslug]) && function_exists('wpconvert_get_page_for_route')) {
            $rpv = wpconvert_get_page_for_route('/' . $rslug);
            if ($rpv) {
                $by_uri[$rslug] = $rpv;
            }
        }
    }

    // Sort routes by depth so parents are processed before children
    $sorted_routes = $routes;
    uksort($sorted_routes, function($a, $b) {
        return substr_count($a, '/') - substr_count($b, '/');
    });

    $repaired = 0;
    $created  = 0;
    $pages_by_path = array();

    foreach ($sorted_routes as $route => $data) {
        if ($route === '/' || $route === '#' || strpos($route, '?') !== false) continue;
        // EC-ROUTE-EXT-001: Defensive — never create pages for external/absolute URLs.
        if (strpos($route, '://') !== false || preg_match('#^[a-z][a-z0-9+.-]*://#i', $route)) continue;
        $slug = trim($route, '/');
        $segments = explode('/', $slug);
        $flat_slug = str_replace('/', '-', $slug);
        $template_name = 'page-' . $flat_slug . '.php';
        $title = is_array($data) && isset($data['title']) ? $data['title'] : ucwords(str_replace('-', ' ', end($segments)));

        // Skip routes with no template file (unless they are parent stubs needed for hierarchy)
        $has_template = file_exists($tpl_dir . '/' . $template_name);

        $page = null;

        // 1. Try exact hierarchical URI match (e.g. services/cosmetic-dentistry)
        if (isset($by_uri[$slug])) {
            $page = $by_uri[$slug];
        }

        // 2. Try flat slug match (e.g. services-cosmetic-dentistry)
        if (!$page && isset($by_uri[$flat_slug])) {
            $page = $by_uri[$flat_slug];
        }

        // No leaf/partial slug matching — if the exact path doesn't match,
        // create the page fresh to avoid grabbing wrong pages from old themes.

        if ($page) {
            if ($page->post_status === 'trash') {
                wp_untrash_post($page->ID);
            }
            // EC-PAGE-SLUG-007: WordPress ships its own "Privacy Policy" page as a
            // DRAFT, holding the /privacy-policy slug. The seeder adopted it, applied
            // the template and left it a draft — so a site that genuinely has a
            // privacy policy page served a 404 on it. Publish ONLY that stub, and
            // only while it is untouched: an edited page, or any other draft, is the
            // owner's decision and stays exactly as they left it.
            if ($page->post_status === 'draft' && $has_template && wpconvert_is_untouched_core_privacy_page($page)) {
                wp_update_post(array('ID' => $page->ID, 'post_status' => 'publish'));
                $page->post_status = 'publish';
                $repaired++;
            }
            $pages_by_path[$route] = $page->ID;
            if ($has_template) {
                $current_tpl = get_post_meta($page->ID, '_wp_page_template', true);
                if ($current_tpl !== $template_name) {
                    update_post_meta($page->ID, '_wp_page_template', $template_name);
                    $repaired++;
                }
            }
        } elseif ($has_template || count($segments) > 1) {
            // Page missing — create it with correct hierarchy
            $parent_id = 0;
            if (count($segments) > 1) {
                // Ensure all parent segments exist
                for ($i = 0; $i < count($segments) - 1; $i++) {
                    $partial_path = implode('/', array_slice($segments, 0, $i + 1));
                    $partial_route = '/' . $partial_path;
                    if (isset($pages_by_path[$partial_route])) {
                        $parent_id = $pages_by_path[$partial_route];
                    } else {
                        $parent_page = get_page_by_path($partial_path);
                        if ($parent_page) {
                            $parent_id = $parent_page->ID;
                            $pages_by_path[$partial_route] = $parent_id;
                        } else {
                            $seg_title = isset($routes[$partial_route]) && is_array($routes[$partial_route]) && isset($routes[$partial_route]['title'])
                                ? $routes[$partial_route]['title']
                                : ucwords(str_replace('-', ' ', $segments[$i]));
                            $pid = wp_insert_post(array(
                                'post_title'  => $seg_title,
                                'post_name'   => $segments[$i],
                                'post_content'=> 'This page is automatically generated by WPConvert.',
                                'post_status' => 'publish',
                                'post_type'   => 'page',
                                'post_author' => 1,
                                'post_parent' => $parent_id,
                            ));
                            if ($pid && !is_wp_error($pid)) {
                                $seg_tpl = 'page-' . str_replace('/', '-', $partial_path) . '.php';
                                if (file_exists($tpl_dir . '/' . $seg_tpl)) {
                                    update_post_meta($pid, '_wp_page_template', $seg_tpl);
                                }
                                $pages_by_path[$partial_route] = $pid;
                                $parent_id = $pid;
                                $created++;
                            }
                        }
                    }
                }
            }

            $child_slug = end($segments);
            $page_id = wp_insert_post(array(
                'post_title'   => $title,
                'post_name'    => $child_slug,
                'post_content' => 'This page is automatically generated by WPConvert. The content is displayed using the page template.',
                'post_status'  => 'publish',
                'post_type'    => 'page',
                'post_author'  => 1,
                'post_parent'  => $parent_id,
                'menu_order'   => 0,
            ));
            if ($page_id && !is_wp_error($page_id)) {
                if ($has_template) {
                    update_post_meta($page_id, '_wp_page_template', $template_name);
                }
                $pages_by_path[$route] = $page_id;
                $created++;
            }
        }
    }
    if ($repaired > 0 || $created > 0) {
        error_log('WPConvert: Template repair — ' . $repaired . ' fixed, ' . $created . ' page(s) created');
    }
    if ($created > 0) {
        // EC-PERF-001: New pages may need slug/stub reconciliation — re-arm the
        // O(1) guards so the fixers run one more bounded pass.
        delete_option('wpconvert_slugfix_step2_hash');
        delete_option('wpconvert_blogstub_hash');
        flush_rewrite_rules();
    }
}

// Create WordPress pages for all discovered routes
function wpconvert_create_spa_pages() {
    // Read routes from routes.json (created during theme generation)
    $routes_path = get_template_directory() . '/assets/data/routes.json';

    // Hash-based guard: skip if routes.json has not changed since last run.
    // Replaces the old boolean wpconvert_spa_pages_created flag so that
    // re-uploading a theme with new routes triggers page creation.
    if (file_exists($routes_path)) {
        $hash = md5_file($routes_path);
        if (get_option('wpconvert_routes_hash') === $hash) {
            // EC-REINSTALL-001: Even if hash matches, spot-check that pages
            // actually exist. On theme reinstall (same zip, fresh DB or deleted
            // pages), wp_options flags persist but pages are gone.
            $routes_check = json_decode(file_get_contents($routes_path), true);
            $pages_exist = false;
            if (is_array($routes_check)) {
                foreach ($routes_check as $r => $d) {
                    if ($r === '/' || $r === '#' || strpos($r, '?') !== false) continue;
                    if (function_exists('wpconvert_route_has_matching_page') && wpconvert_route_has_matching_page($r)) {
                        $pages_exist = true;
                        break;
                    }
                }
            }
            if ($pages_exist) {
                // Pages exist but templates may be missing (e.g. theme installed
                // over a site with pre-existing pages from a different theme).
                // Run a lightweight template-repair pass without creating pages.
                wpconvert_repair_page_templates($routes_check);
                return;
            }
            // Pages missing despite matching hash — clear flag and proceed
            delete_option('wpconvert_routes_hash');
            delete_option('wpconvert_spa_pages_created');
        }
    } elseif (get_option('wpconvert_spa_pages_created')) {
        return;
    }
    $spa_routes = array();
    
    if (file_exists($routes_path)) {
        $routes_data = json_decode(file_get_contents($routes_path), true);
        if ($routes_data && is_array($routes_data)) {
            // EC-BLOG-003 / EC-BLOG-047: Skip blog detail URLs only for native-blog themes (Pro/Agency).
            // Starter uses import-posts.json for data + static page-blog-*.php; those URLs must become Pages.
            $blog_slugs = array();
            if (defined('WPCONVERT_NATIVE_BLOG') && WPCONVERT_NATIVE_BLOG) {
                $blog_json = get_template_directory() . '/assets/data/import-posts.json';
                if (file_exists($blog_json)) {
                    $blog_data = json_decode(file_get_contents($blog_json), true);
                    $blog_prefix = isset($blog_data['blogRoutePrefix']) ? $blog_data['blogRoutePrefix'] : '/blog';
                    $blog_posts = isset($blog_data['posts']) ? $blog_data['posts'] : $blog_data;
                    if (is_array($blog_posts)) {
                        foreach ($blog_posts as $bp) {
                            if (!empty($bp['slug'])) {
                                $blog_slugs[] = rtrim($blog_prefix, '/') . '/' . $bp['slug'];
                            }
                        }
                    }
                }
            }

            foreach ($routes_data as $route => $data) {
                // Skip routes with query parameters (tab variations, filters, etc.)
                // These are not separate pages - they're just different states of a page
                if (strpos($route, '?') !== false) {
                    continue;
                }
                // EC-BLOG-003: Skip blog post routes when they are native WP posts, not static templates
                if (in_array($route, $blog_slugs)) {
                    continue;
                }
                $spa_routes[$route] = $data['title'];
            }
        }
    } else {
        // Fallback: Extract routes from menus.json
        $menu_path = get_template_directory() . '/assets/data/menus.json';
        if (file_exists($menu_path)) {
            $menu_data = json_decode(file_get_contents($menu_path), true);
            if ($menu_data && isset($menu_data['primary']['items'])) {
                $spa_routes = wpconvert_extract_routes_from_menu($menu_data['primary']['items']);
            }
        }
    }
    
    // No fallback routes - if no routes detected, this is a single-page/landing page
    // Don't create pages that don't exist in the original site
    
  // Ensure a Home page exists and set it as the front page
  $home_page = wpconvert_get_page_any_status('home');
  if (!$home_page) {
    $home_page_id = wp_insert_post(array(
      'post_title'   => 'Home',
      'post_name'    => 'home',
      'post_content' => 'This page was automatically generated by WPConvert as the homepage.',
      'post_status'  => 'publish',
      'post_type'    => 'page',
      'post_author'  => 1,
      'menu_order'   => 0
    ));

    if ($home_page_id && !is_wp_error($home_page_id)) {
      update_option('page_on_front', $home_page_id);
      update_option('show_on_front', 'page');
    }
  } else {
    update_option('page_on_front', $home_page->ID);
    update_option('show_on_front', 'page');
  }
    
    // EC-ROUTE-HIER-001: Sort routes by path depth (shallowest first) so parent
    // pages are created before their children. This lets us look up parent IDs
    // when creating child pages.
    uksort($spa_routes, function($a, $b) {
        return substr_count($a, '/') - substr_count($b, '/');
    });

    $pages_by_path = array();

    foreach ($spa_routes as $route => $title) {
        if (strpos($route, '#/') === 0) {
            $route = substr($route, 1);
        }
        if ($route === '/' || $route === '#') {
            continue;
        }
        // EC-ROUTE-EXT-001: Defensive — never create pages for external/absolute
        // URLs (their slugs sanitize to junk like "https-..."), even if a
        // malformed routes.json slips one through.
        if (strpos($route, '://') !== false || preg_match('#^[a-z][a-z0-9+.-]*://#i', $route)) {
            continue;
        }
        
        $slug = trim($route, '/');
        $segments = explode('/', $slug);
        $flat_slug = str_replace('/', '-', $slug);
        $template_name = 'page-' . $flat_slug . '.php';

        if (count($segments) === 1) {
            // EC-PAGE-SLUG-001: Skip flat routes that have no page template.
            // WordPress enforces globally unique page slugs — creating a flat
            // /dental-implants page steals the slug from the hierarchical
            // /cypress-tx/dental-implants child page (which has a template).
            if (!file_exists(get_template_directory() . '/' . $template_name)) {
                continue;
            }
            // Top-level route — flat page, no parent
            $existing_page = wpconvert_get_page_any_status($slug);
            // EC-PAGE-SLUG-006: WordPress rewrites a purely numeric slug, so the /404
            // route lives at "404-2" and the lookup above cannot see it. This seeder
            // runs after the routes seeder in the same activation, so without the
            // resolver it inserts a second copy every time.
            if (!$existing_page && function_exists('wpconvert_get_page_for_route')) {
                $existing_page = wpconvert_get_page_for_route('/' . $slug);
            }
            if (!$existing_page) {
                $page_id = wp_insert_post(array(
                    'post_title'   => $title,
                    'post_name'    => $slug,
                    'post_content' => 'This page is automatically generated by WPConvert. The content is displayed using the page template.',
                    'post_status'  => 'publish',
                    'post_type'    => 'page',
                    'post_author'  => 1,
                    'menu_order'   => 0
                ));
                if ($page_id && !is_wp_error($page_id)) {
                    update_post_meta($page_id, '_wp_page_template', $template_name);
                    $pages_by_path[$route] = $page_id;
                }
            } else {
                if ($existing_page->post_status === 'trash') {
                    wp_untrash_post($existing_page->ID);
                }
                // EC-PAGE-FALLBACK-001: Ensure existing pages have correct template assignment
                update_post_meta($existing_page->ID, '_wp_page_template', $template_name);
                $pages_by_path[$route] = $existing_page->ID;
            }
        } else {
            // EC-ROUTE-HIER-001: Nested route — create hierarchical parent/child pages.
            // Walk every intermediate segment and ensure parent pages exist so
            // WordPress can resolve /cypress-tx/cosmetic-dentistry natively.
            $parent_id = 0;
            for ($i = 0; $i < count($segments) - 1; $i++) {
                $partial_path = implode('/', array_slice($segments, 0, $i + 1));
                $partial_route = '/' . $partial_path;

                if (isset($pages_by_path[$partial_route])) {
                    $parent_id = $pages_by_path[$partial_route];
                } else {
                    $parent_page = wpconvert_get_page_any_status($partial_path);
                    if ($parent_page) {
                        if ($parent_page->post_status === 'trash') {
                            wp_untrash_post($parent_page->ID);
                        }
                        $parent_id = $parent_page->ID;
                        $pages_by_path[$partial_route] = $parent_id;
                    } else {
                        $seg_title = isset($spa_routes[$partial_route])
                            ? $spa_routes[$partial_route]
                            : ucwords(str_replace('-', ' ', $segments[$i]));
                        $pid = wp_insert_post(array(
                            'post_title'   => $seg_title,
                            'post_name'    => $segments[$i],
                            'post_content' => 'This page is automatically generated by WPConvert.',
                            'post_status'  => 'publish',
                            'post_type'    => 'page',
                            'post_author'  => 1,
                            'post_parent'  => $parent_id,
                        ));
                        if ($pid && !is_wp_error($pid)) {
                            $seg_tpl = 'page-' . str_replace('/', '-', $partial_path) . '.php';
                            if (file_exists(get_template_directory() . '/' . $seg_tpl)) {
                                update_post_meta($pid, '_wp_page_template', $seg_tpl);
                            }
                            $pages_by_path[$partial_route] = $pid;
                            $parent_id = $pid;
                        }
                    }
                }
            }

            $child_slug = end($segments);
            $existing_page = wpconvert_get_page_any_status($slug);
            // EC-PAGE-SLUG-006: WordPress rewrites a purely numeric slug, so the /404
            // route lives at "404-2" and the lookup above cannot see it. This seeder
            // runs after the routes seeder in the same activation, so without the
            // resolver it inserts a second copy every time.
            if (!$existing_page && function_exists('wpconvert_get_page_for_route')) {
                $existing_page = wpconvert_get_page_for_route('/' . $slug);
            }
            if (!$existing_page) {
                $page_id = wp_insert_post(array(
                    'post_title'   => $title,
                    'post_name'    => $child_slug,
                    'post_content' => 'This page is automatically generated by WPConvert. The content is displayed using the page template.',
                    'post_status'  => 'publish',
                    'post_type'    => 'page',
                    'post_author'  => 1,
                    'post_parent'  => $parent_id,
                    'menu_order'   => 0
                ));
                if ($page_id && !is_wp_error($page_id)) {
                    if (file_exists(get_template_directory() . '/' . $template_name)) {
                        update_post_meta($page_id, '_wp_page_template', $template_name);
                    }
                    $pages_by_path[$route] = $page_id;
                }
            } else {
                if ($existing_page->post_status === 'trash') {
                    wp_untrash_post($existing_page->ID);
                }
                // EC-PAGE-FALLBACK-001: Ensure existing pages have correct template assignment
                if (file_exists(get_template_directory() . '/' . $template_name)) {
                    update_post_meta($existing_page->ID, '_wp_page_template', $template_name);
                }
                $pages_by_path[$route] = $existing_page->ID;
            }
        }
    }

    // Mark pages as created
    update_option('wpconvert_spa_pages_created', true);
    // EC-THEME-001: Keep routes hash in sync so wpconvert_ensure_missing_pages (admin_init) does not
    // re-insert pages on next load (same content as wpconvert_ensure_missing_pages uses).
    if (file_exists($routes_path)) {
        update_option('wpconvert_routes_hash', md5_file($routes_path));
    }
    // EC-PERF-001: Newly created pages may need slug/stub reconciliation — re-arm
    // the O(1) guards so the fixers run one more bounded pass.
    delete_option('wpconvert_slugfix_step2_hash');
    delete_option('wpconvert_blogstub_hash');
    
    // EC-PERMA-001: Set pretty permalink structure for ALL sites (not just blogs).
    // Without this, WordPress defaults to "Plain" format (?page_id=123) which breaks
    // all navigation links that expect clean URLs like /services/, /about/, etc.
    $current_structure = get_option('permalink_structure');
    if (empty($current_structure)) {
        update_option('permalink_structure', '/%postname%/');
    }
    
    // Flush rewrite rules so WordPress recognizes the new page structure and permalinks
    flush_rewrite_rules();
}
add_action('after_switch_theme', 'wpconvert_create_spa_pages');

function wpconvert_ensure_missing_pages() {
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if ( ! file_exists( $routes_path ) ) return;
    $routes = json_decode( file_get_contents( $routes_path ), true );
    if ( ! is_array( $routes ) ) return;

    $hash = md5_file( $routes_path );
    // EC-PERF-002: One-shot reconvergence — slug/stub fixers set this flag instead of
    // deleting wpconvert_routes_hash (which used to force a full re-run, with
    // flush_rewrite_rules, on EVERY subsequent admin request). Consume it here so
    // exactly one extra pass happens.
    $reconverge = (bool) get_option( 'wpconvert_routes_reconverge' );
    if ( $reconverge ) {
        delete_option( 'wpconvert_routes_reconverge' );
    }
    if ( ! $reconverge && get_option( 'wpconvert_routes_hash' ) === $hash ) {
        // EC-REINSTALL-001: Spot-check that pages actually exist before trusting hash
        $pages_exist = false;
        foreach ( $routes as $r => $d ) {
            if ( $r === '/' || $r === '#' || strpos( $r, '?' ) !== false ) continue;
            if ( function_exists( 'wpconvert_route_has_matching_page' ) && wpconvert_route_has_matching_page( $r ) ) {
                $pages_exist = true;
                break;
            }
        }
        if ( $pages_exist ) {
            // EC-PAGE-REPAIR-URI-001: Hash match skips full page creation; still reconcile
            // _wp_page_template so /blog/1 picks up page-blog-1.php after theme updates.
            wpconvert_repair_page_templates( $routes );
            return;
        }
        delete_option( 'wpconvert_routes_hash' );
    }

    // EC-ROUTE-HIER-001: Sort by depth so parents are created before children
    uksort( $routes, function($a, $b) {
        return substr_count($a, '/') - substr_count($b, '/');
    });

    foreach ( $routes as $route => $data ) {
        if ( strpos( $route, '?' ) !== false || $route === '/' || $route === '#' ) continue;
        // EC-ROUTE-EXT-001: Defensive — never create pages for external/absolute URLs.
        if ( strpos( $route, '://' ) !== false || preg_match( '#^[a-z][a-z0-9+.-]*://#i', $route ) ) continue;
        $slug = trim( $route, '/' );
        $segments = explode('/', $slug);
        $flat_slug = str_replace('/', '-', $slug);

        $tpl = 'page-' . $flat_slug . '.php';
        $has_template = file_exists( get_template_directory() . '/' . $tpl );

        // Check if page already exists (any status) to prevent slug-2 duplicates
        if ( wpconvert_get_page_any_status( $slug ) || wpconvert_get_page_any_status( $flat_slug ) ) continue;
        if ( function_exists( 'wpconvert_route_has_matching_page' ) && wpconvert_route_has_matching_page( $route ) ) continue;

        // EC-PAGE-SLUG-001: Skip flat routes without templates to prevent slug conflicts
        if (count($segments) === 1 && !$has_template) continue;

        if (count($segments) > 1) {
            // Nested route — find or create parent, then create child
            $parent_id = 0;
            for ($i = 0; $i < count($segments) - 1; $i++) {
                $partial = implode('/', array_slice($segments, 0, $i + 1));
                $parent_page = wpconvert_get_page_any_status($partial);
                if ($parent_page) {
                    if ($parent_page->post_status === 'trash') {
                        wp_untrash_post($parent_page->ID);
                    }
                    $parent_id = $parent_page->ID;
                } else {
                    $pid = wp_insert_post(array(
                        'post_title'   => ucwords(str_replace('-', ' ', $segments[$i])),
                        'post_name'    => $segments[$i],
                        'post_content' => 'This page is automatically generated by WPConvert.',
                        'post_status'  => 'publish',
                        'post_type'    => 'page',
                        'post_author'  => 1,
                        'post_parent'  => $parent_id,
                    ));
                    if ($pid && !is_wp_error($pid)) {
                        $seg_tpl = 'page-' . str_replace('/', '-', $partial) . '.php';
                        if (file_exists(get_template_directory() . '/' . $seg_tpl)) {
                            update_post_meta($pid, '_wp_page_template', $seg_tpl);
                        }
                        $parent_id = $pid;
                    }
                }
            }
            $child_slug = end($segments);
            $page_id = wp_insert_post(array(
                'post_title'   => $data['title'] ?? ucwords(str_replace('-', ' ', $child_slug)),
                'post_name'    => $child_slug,
                'post_content' => 'This page is automatically generated by WPConvert.',
                'post_status'  => 'publish',
                'post_type'    => 'page',
                'post_author'  => 1,
                'post_parent'  => $parent_id,
            ));
        } else {
            $page_id = wp_insert_post(array(
                'post_title'   => $data['title'] ?? ucwords(str_replace('-', ' ', $slug)),
                'post_name'    => $slug,
                'post_content' => 'This page is automatically generated by WPConvert.',
                'post_status'  => 'publish',
                'post_type'    => 'page',
                'post_author'  => 1,
            ));
        }
        if ( $page_id && ! is_wp_error( $page_id ) && $has_template ) {
            update_post_meta( $page_id, '_wp_page_template', $tpl );
        }
    }
    update_option( 'wpconvert_routes_hash', $hash );
    // EC-PERF-001: Inserted pages may need slug/stub reconciliation — re-arm the
    // O(1) guards so the fixers run one more bounded pass.
    delete_option( 'wpconvert_slugfix_step2_hash' );
    delete_option( 'wpconvert_blogstub_hash' );
    flush_rewrite_rules( false );
}
add_action( 'admin_init', 'wpconvert_ensure_missing_pages' );

// EC-SAMPLE-001: Remove WordPress's default "Sample Page" and "Hello world!" post.
// Every fresh WP install ships these; they are never part of a converted site.
// Left in place they leak into the auto page list and — when no primary menu is
// assigned — into WordPress's wp_page_menu() nav fallback (the stray "Sample Page"
// nav item + the /sample-page/ URL reported after conversion). Runs once, guarded
// by an option, and never deletes a slug the converted site actually uses.
function wpconvert_remove_default_content() {
    if ( get_option( 'wpconvert_default_content_cleaned' ) ) return;

    // Collect slugs the converted site legitimately uses so we never trash them.
    $reserved = array();
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if ( file_exists( $routes_path ) ) {
        $routes = json_decode( file_get_contents( $routes_path ), true );
        if ( is_array( $routes ) ) {
            foreach ( $routes as $key => $r ) {
                if ( is_array( $r ) && ! empty( $r['slug'] ) ) {
                    $reserved[] = $r['slug'];
                } elseif ( is_string( $key ) ) {
                    $reserved[] = trim( $key, '/' );
                }
            }
        }
    }

    // EC-SAFE-002: draft, never force delete. On a fresh install these really are
    // WordPress's throwaway defaults, but on a long-lived site the owner may have
    // written real content under the default title and slug, and the previous force
    // delete bypassed the Trash entirely, so there was nothing to restore. Drafting
    // fully serves the intent — getting placeholder content off the front end — with
    // none of the risk, and unlike the Trash it never auto-purges after
    // EMPTY_TRASH_DAYS.
    // Freeing the slug is not required here: the $reserved check above already skips
    // any slug the converted site actually uses.

    // Default "Sample Page" (slug: sample-page). Guard on the default title so a
    // real converted page that happens to reuse the slug is never removed.
    if ( ! in_array( 'sample-page', $reserved, true ) ) {
        $sample = get_page_by_path( 'sample-page' );
        if ( $sample && strtolower( trim( $sample->post_title ) ) === 'sample page' && $sample->post_status !== 'draft' ) {
            wp_update_post( array( 'ID' => $sample->ID, 'post_status' => 'draft' ) );
        }
    }

    // Default "Hello world!" post (slug: hello-world).
    if ( ! in_array( 'hello-world', $reserved, true ) ) {
        $hello = get_page_by_path( 'hello-world', OBJECT, 'post' );
        if ( $hello && strtolower( trim( $hello->post_title ) ) === 'hello world!' && $hello->post_status !== 'draft' ) {
            wp_update_post( array( 'ID' => $hello->ID, 'post_status' => 'draft' ) );
        }
    }

    update_option( 'wpconvert_default_content_cleaned', 1 );
}
add_action( 'admin_init', 'wpconvert_remove_default_content' );

// EC-NAV-370: cross-process mutex for the menu importers.
//
// WordPress fires after_switch_theme from check_theme_switched() on wp_loaded and
// only clears the theme_switched option at the END of that function, so EVERY
// request that starts before the clear runs the importer. Browsers routinely open
// several connections at once, so the first page load after activation would run
// two or three importers in parallel, each clearing the menu and inserting its own
// full copy — leaving the navbar with every item two or three times over.
//
// INSERT IGNORE is the same atomic primitive WP core uses for
// WP_Upgrader::create_lock(): exactly one concurrent request can create the row.
function wpconvert_acquire_menu_import_lock( $release_timeout = 120 ) {
    global $wpdb;
    $lock_option = 'wpconvert_menu_import_lock';

    $insert_sql = "INSERT IGNORE INTO $wpdb->options (option_name, option_value, autoload) VALUES (%s, %s, 'no') /* LOCK */";
    $inserted = $wpdb->query( $wpdb->prepare( $insert_sql, $lock_option, time() ) );

    // The storage engine rejected the statement (unsupported SQL dialect). Degrade
    // to the historical unlocked behaviour: a rare duplicate import that the dedupe
    // pass repairs is far better than a site that never imports its menu at all.
    if ( false === $inserted ) return true;

    if ( $inserted ) {
        wp_cache_delete( $lock_option, 'options' );
        return true;
    }

    // Somebody else holds it. Only reclaim it once it is provably stale, so a
    // crashed request cannot wedge the importer forever.
    $held_since = (int) get_option( $lock_option );
    if ( $held_since && $held_since > ( time() - $release_timeout ) ) return false;

    wpconvert_release_menu_import_lock();
    $retaken = $wpdb->query( $wpdb->prepare( $insert_sql, $lock_option, time() ) );
    if ( $retaken ) wp_cache_delete( $lock_option, 'options' );
    return (bool) $retaken;
}

function wpconvert_release_menu_import_lock() {
    delete_option( 'wpconvert_menu_import_lock' );
}

// EC-NAV-370: remove menu items that are exact duplicates of one another —
// same parent, title, url and type. Only a repeated import can produce those, so
// items the site owner added by hand are never at risk. Deletion keeps the lowest
// ID in each group, which makes the repair convergent: two workers running it at
// the same time reach the same result. Duplicated parents take their whole subtree
// with them, otherwise the orphaned children surface as top-level items.
function wpconvert_dedupe_menu_items( $menu_id ) {
    $menu_id = (int) $menu_id;
    if ( ! $menu_id ) return 0;

    $items = wp_get_nav_menu_items( $menu_id, array( 'post_status' => 'any' ) );
    if ( empty( $items ) ) return 0;

    $rows = array();
    $children_of = array();
    foreach ( $items as $item ) {
        $rows[] = $item;
        $children_of[ (int) $item->menu_item_parent ][] = (int) $item->ID;
    }
    usort( $rows, function ( $a, $b ) { return (int) $a->ID - (int) $b->ID; } );

    $seen = array();
    $doomed = array();
    foreach ( $rows as $item ) {
        $key = (int) $item->menu_item_parent . '|' . $item->title . '|' . $item->url . '|' . $item->type;
        if ( isset( $seen[ $key ] ) ) {
            $doomed[] = (int) $item->ID;
        } else {
            $seen[ $key ] = true;
        }
    }
    if ( empty( $doomed ) ) return 0;

    $queue = $doomed;
    $delete = array();
    while ( $queue ) {
        $id = (int) array_shift( $queue );
        if ( isset( $delete[ $id ] ) ) continue;
        $delete[ $id ] = true;
        if ( ! empty( $children_of[ $id ] ) ) {
            foreach ( $children_of[ $id ] as $child_id ) $queue[] = $child_id;
        }
    }

    foreach ( array_keys( $delete ) as $id ) {
        wp_delete_post( $id, true );
    }
    error_log( 'WPConvert: removed ' . count( $delete ) . ' duplicate menu item(s) from menu ' . $menu_id );
    return count( $delete );
}

// Drop every duplicate out of the menus this theme owns.
function wpconvert_dedupe_theme_menus() {
    $removed = 0;
    foreach ( array( 'Primary Menu', 'Footer Menu' ) as $name ) {
        $menu = wp_get_nav_menu_object( $name );
        if ( $menu ) $removed += wpconvert_dedupe_menu_items( (int) $menu->term_id );
    }
    $locations = get_theme_mod( 'nav_menu_locations', array() );
    foreach ( array( 'primary', 'footer' ) as $slot ) {
        if ( empty( $locations[ $slot ] ) ) continue;
        $menu = wp_get_nav_menu_object( (int) $locations[ $slot ] );
        if ( $menu && ! in_array( $menu->name, array( 'Primary Menu', 'Footer Menu' ), true ) ) {
            $removed += wpconvert_dedupe_menu_items( (int) $menu->term_id );
        }
    }
    return $removed;
}

// Re-import menus when menus.json changes (theme files replaced without activation),
// or when nav_menu_locations for the current theme are missing (different folder name).
function wpconvert_ensure_menus_current() {
    $json_path = get_template_directory() . '/assets/data/menus.json';
    if ( ! file_exists( $json_path ) ) return;

    // EC-NAV-370: repair installs already broken by the activation race. Their
    // menus.json hash still matches and their primary location is still valid, so
    // they take the early return below and would otherwise stay duplicated forever.
    // One-shot, and admin-side only, so visitors never pay for it.
    if ( ! get_option( 'wpconvert_menu_dedupe_done' ) ) {
        update_option( 'wpconvert_menu_dedupe_done', 1 );
        wpconvert_dedupe_theme_menus();
    }

    $hash = md5_file( $json_path );
    $locs = get_theme_mod( 'nav_menu_locations', array() );
    $has_primary = ! empty( $locs['primary'] ) && wp_get_nav_menu_object( $locs['primary'] );
    if ( get_option( 'wpconvert_menus_hash' ) === $hash && $has_primary ) return;

    $data = json_decode( file_get_contents( $json_path ), true );
    if ( ! $data || ! is_array( $data ) ) return;

    if ( ! wpconvert_acquire_menu_import_lock() ) return;

    $menu_name = 'Primary Menu';
    $menu_obj  = wp_get_nav_menu_object( $menu_name );
    $menu_id   = $menu_obj ? (int) $menu_obj->term_id : (int) wp_create_nav_menu( $menu_name );

    $existing_items = wp_get_nav_menu_items( $menu_id );
    if ( $existing_items ) {
        foreach ( $existing_items as $item ) {
            wp_delete_post( $item->ID, true );
        }
    }

    $locations = get_theme_mod( 'nav_menu_locations', array() );

    // EC-PERF-001: Targeted maps from menu items only — never enumerate all pages
    // (the old get_pages('any') scan crashed PHP on sites with huge page counts).
    $pages_by_path  = array();
    $pages_by_title = array();
    $pages_by_slug  = array();
    if ( ! empty( $data['primary']['items'] ) ) {
        wpconvert_build_menu_page_maps( $data['primary']['items'], $pages_by_path, $pages_by_title, $pages_by_slug );
    }
    if ( ! empty( $data['footer']['items'] ) ) {
        wpconvert_build_menu_page_maps( $data['footer']['items'], $pages_by_path, $pages_by_title, $pages_by_slug );
    }

    if ( ! empty( $data['primary']['items'] ) ) {
        wpconvert_insert_menu_items( $data['primary']['items'], $menu_id, 0, $pages_by_path, $pages_by_title, $pages_by_slug );
    }
    $locations['primary'] = $menu_id;

    if ( ! empty( $data['footer']['items'] ) ) {
        $footer_menu_name = 'Footer Menu';
        $footer_menu_obj  = wp_get_nav_menu_object( $footer_menu_name );
        $footer_menu_id   = $footer_menu_obj ? (int) $footer_menu_obj->term_id : (int) wp_create_nav_menu( $footer_menu_name );

        $existing_footer = wp_get_nav_menu_items( $footer_menu_id );
        if ( $existing_footer ) {
            foreach ( $existing_footer as $item ) {
                wp_delete_post( $item->ID, true );
            }
        }
        wpconvert_insert_menu_items( $data['footer']['items'], $footer_menu_id, 0, $pages_by_path, $pages_by_title, $pages_by_slug );
        $locations['footer'] = $footer_menu_id;
    }

    set_theme_mod( 'nav_menu_locations', $locations );
    update_option( 'wpconvert_menu_created', 1 );
    update_option( 'wpconvert_menus_hash', $hash );

    // EC-NAV-370: net for anything that slipped past the lock.
    wpconvert_dedupe_menu_items( $menu_id );
    if ( ! empty( $footer_menu_id ) ) wpconvert_dedupe_menu_items( $footer_menu_id );
    wpconvert_release_menu_import_lock();
    error_log( 'WPConvert: Menus re-imported (menus.json changed)' );
}
add_action( 'admin_init', 'wpconvert_ensure_menus_current' );

// Path under home_url (strip subdirectory prefix) for matching routes.json keys like /blog/1.
function wpconvert_route_path_rel_home($url) {
    $path = wp_parse_url($url, PHP_URL_PATH);
    $path = is_string($path) ? trim($path, '/') : '';
    $home_path = wp_parse_url(home_url('/'), PHP_URL_PATH);
    $home_path = is_string($home_path) ? trim($home_path, '/') : '';
    if ($home_path !== '' && ($path === $home_path || strpos($path, $home_path . '/') === 0)) {
        return ($path === $home_path) ? '' : substr($path, strlen($home_path) + 1);
    }
    return $path;
}

// EC-ROUTE-HIER-001: Prevent WordPress from redirecting hierarchical page URLs
// to the flat-slug canonical URL. When a page is matched by its hierarchical
// path (e.g. /cypress-tx/cosmetic-dentistry) but was originally created with a
// flat slug (legacy), WordPress's redirect_canonical detects a mismatch and
// 301-redirects — often to the wrong page via fuzzy matching.
//
// EC-BLOG-165: The old guard required is_page() before reading routes.json, so when
// WordPress did not resolve the request as a Page (common: Starter /blog/1 with a
// numeric child slug), redirect_canonical still ran and sent users to /blog/. We now
// match routes.json using a home-relative path (subdirectory-safe) whenever the
// canonical target path would differ from the requested path.
function wpconvert_prevent_nested_redirect($redirect_url, $requested_url) {
    if (!$redirect_url || !$requested_url) return $redirect_url;
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return $redirect_url;
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!$routes || !is_array($routes)) return $redirect_url;

    $req_rel = wpconvert_route_path_rel_home($requested_url);
    if ($req_rel !== '' && isset($routes['/' . $req_rel])) {
        $redir_rel = wpconvert_route_path_rel_home($redirect_url);
        if ($redir_rel !== $req_rel) {
            $parts_r = wp_parse_url($redirect_url);
            $parts_q = wp_parse_url($requested_url);
            if (!empty($parts_r['host'])) {
                $scheme = isset($parts_r['scheme']) ? $parts_r['scheme'] : 'https';
                $port = isset($parts_r['port']) ? ':' . (int) $parts_r['port'] : '';
                $new_path = isset($parts_q['path']) ? $parts_q['path'] : '/';
                $query = isset($parts_q['query']) ? '?' . $parts_q['query'] : '';
                return $scheme . '://' . (string) $parts_r['host'] . $port . $new_path . $query;
            }
            return $requested_url;
        }
        return $redirect_url;
    }

    return $redirect_url;
}
add_filter('redirect_canonical', 'wpconvert_prevent_nested_redirect', 10, 2);

// EC-BLOG-166: routes.json and links use /blog/1 but WordPress stored the child as 1-2 (unique slug),
// so the real permalink is /blog/1-2/. /blog/1/ has no matching page — 404 or empty. Redirect to the resolved page.
function wpconvert_redirect_numeric_route_to_resolved_page() {
    if (is_admin() || wp_doing_ajax() || is_feed() || is_preview()) return;
    if (!function_exists('wpconvert_get_page_for_route') || !function_exists('wpconvert_route_path_rel_home')) return;
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return;
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) return;
    if (empty($_SERVER['REQUEST_URI'])) return;
    $scheme = is_ssl() ? 'https://' : 'http://';
    $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '';
    $req_full = $scheme . $host . $_SERVER['REQUEST_URI'];
    $rel = wpconvert_route_path_rel_home($req_full);
    if ($rel === '') return;
    $route_key = '/' . $rel;
    if (!isset($routes[$route_key])) return;

    $exact = get_page_by_path($rel);
    if ($exact && $exact->post_status === 'publish') return;

    $page = wpconvert_get_page_for_route($route_key);
    if (!$page || $page->post_status !== 'publish') return;
    $target = get_permalink($page->ID);
    if (!$target) return;

    $req_path = wp_parse_url($req_full, PHP_URL_PATH);
    $tgt_path = wp_parse_url($target, PHP_URL_PATH);
    $req_norm = is_string($req_path) ? untrailingslashit($req_path) : '';
    $tgt_norm = is_string($tgt_path) ? untrailingslashit($tgt_path) : '';
    if ($req_norm === $tgt_norm) return;

    wp_safe_redirect($target, 301);
    exit;
}
add_action('template_redirect', 'wpconvert_redirect_numeric_route_to_resolved_page', 0);

// EC-PAGE-NUMERIC-CHILD-001: Numeric child page slugs (e.g. /blog/1/) collide with WordPress's
// built-in paginated-single-page rewrite ((.+?)(?:/([0-9]+))?/?$ → pagename=$1&page=$2).
// WP parses /blog/1/ as pagename=blog + page=1, then 404s because the blog page has no
// <!--nextpage--> sub-pages. Fix: when WP sets pagename + numeric "page" query var AND a real
// hierarchical child page exists at "<pagename>/<page>", rewrite the query to that path and
// drop "page"/"name". Fires only when the child page truly exists, so it cannot intercept
// genuine <!--nextpage--> multipage content (those URLs have no real child page underneath).
function wpconvert_request_remap_numeric_child_page($qv) {
    if (!is_array($qv)) return $qv;
    if (empty($qv['pagename']) || !isset($qv['page'])) return $qv;
    $page_qv = $qv['page'];
    if (is_array($page_qv)) return $qv;
    $page_qv = (string) $page_qv;
    if ($page_qv === '' || !preg_match('/^\/?\d+\/?$/', $page_qv)) return $qv;
    $num = trim($page_qv, '/');
    if ($num === '' || !ctype_digit($num) || $num === '0') return $qv;
    $candidate = trim($qv['pagename'], '/') . '/' . $num;
    $child = get_page_by_path($candidate);
    if (!$child) return $qv;
    if ($child->post_status !== 'publish' && $child->post_status !== 'private') return $qv;
    $qv['pagename'] = $candidate;
    unset($qv['page']);
    unset($qv['name']);
    return $qv;
}
add_filter('request', 'wpconvert_request_remap_numeric_child_page', 1);

// EC-PAGE-TEMPLATE-001: Core hierarchy is page-{leaf}.php (page-1.php) then page.php.
// WPConvert snapshots use the flat merged name (page-blog-1.php). When _wp_page_template
// is missing or default, users only see the generic page.php stub (the_content only).
// resolved template here is host-agnostic — no reliance on $wp->request or REQUEST_URI
// inside page.php (Playground and some proxies still break those).
function wpconvert_resolve_flat_hierarchical_page_template($template) {
    if (!function_exists('wpconvert_page_hier_path')) return $template;
    if (!is_singular('page')) return $template;
    $id = get_queried_object_id();
    if (!$id) return $template;
    $hp = wpconvert_page_hier_path($id);
    $flat = '';
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if ($hp !== '' && strpos($hp, '/') !== false) {
        $flat = str_replace('/', '-', $hp);
    } else {
        // Broken post_parent (leaf-only path) — still map URL to routes.json flat template.
        if (!empty($_SERVER['REQUEST_URI']) && file_exists($routes_path)) {
            $scheme = is_ssl() ? 'https://' : 'http://';
            $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '';
            $req_full = $scheme . $host . $_SERVER['REQUEST_URI'];
            $rel = wpconvert_route_path_rel_home($req_full);
            $routes = json_decode(file_get_contents($routes_path), true);
            if (is_array($routes) && $rel !== '' && isset($routes['/' . $rel])) {
                $flat = str_replace('/', '-', $rel);
            }
        }
    }
    if ($flat === '') return $template;
    $specific = get_template_directory() . '/page-' . $flat . '.php';
    // EC-PAGE-SLUG-002: Leaf slug 1-2 (WP unique slug) — use routes + page-blog-1.php when /blog/1 exists.
    if (!file_exists($specific) && $hp !== '' && strpos($hp, '/') !== false && file_exists($routes_path)) {
        $routes_retry = json_decode(file_get_contents($routes_path), true);
        $parts_retry = explode('/', $hp);
        $last_retry = array_pop($parts_retry);
        if (is_array($routes_retry) && $last_retry !== null && $last_retry !== '' && preg_match('/^(\d+)-\d+$/', $last_retry, $m_retry)) {
            $try_rel = (count($parts_retry) ? implode('/', $parts_retry) . '/' : '') . $m_retry[1];
            $try_route = '/' . $try_rel;
            if (isset($routes_retry[$try_route])) {
                $try_flat = str_replace('/', '-', $try_rel);
                $try_spec = get_template_directory() . '/page-' . $try_flat . '.php';
                if (file_exists($try_spec)) {
                    $specific = $try_spec;
                }
            }
        }
    }
    if (!file_exists($specific)) return $template;
    if (basename($template) === basename($specific)) return $template;
    if (basename($template) !== 'page.php') return $template;
    return $specific;
}
add_filter('template_include', 'wpconvert_resolve_flat_hierarchical_page_template', 99);

// EC-REWRITE-HIER-001: Do NOT register custom rewrite rules for nested routes.
// Previous versions mapped /cypress-tx/dental-cleaning/ to pagename=cypress-tx-dental-cleaning,
// which looks for a *root* page with that slug. EC-ROUTE-HIER-001 creates real parent/child
// pages (parent slug cypress-tx, child slug dental-cleaning). WordPress core rewrite rules
// resolve /parent/child/ correctly; our flat pagename rule matched first (priority top) and
// produced an empty main query → index.php "Nothing found" even though the page exists.

// EC-ROUTE-RESERVED-001: Rescue routes placed under a WP-reserved permalink base.
//
// Client-rendered SPAs frequently use /category/:key (or /tag/:key, /author/:key, …) as
// ORDINARY content routes. The converter captures each page and creates a real hierarchical
// Page at path "category/<key>" — but "/category/" is WordPress's reserved category-archive
// base, whose core rewrite rule (category/(.+?)/?$ → category_name=<key>) is evaluated BEFORE
// the generic page rule. With no matching category term the request resolves to an empty
// archive → the theme's "Nothing found" page (reported on the "All Things Dominican" site:
// every navbar item + homepage "Browse by topic" card led to an empty page).
//
// Fix: for each converted route whose FIRST segment is a reserved base, register a
// TOP-priority rewrite mapping the exact path to its hierarchical Page via pagename=<path>
// (the same query var core's page rule uses — unlike the flat-slug mistake of EC-REWRITE-HIER-001,
// the full hierarchical path resolves the child page correctly). 'top' places the rule ahead
// of the taxonomy rule so it wins. This is scoped STRICTLY to reserved-base routes present in
// this site's routes.json: a conversion with no such routes registers nothing and never
// flushes, so no other site / navbar is affected.
function wpconvert_reserved_permalink_bases() {
    return array('category', 'tag', 'author', 'type', 'page', 'comments', 'feed', 'embed', 'search');
}

// Collect the converted nested routes whose top segment is a reserved base (cached per request).
function wpconvert_reserved_base_route_paths() {
    static $cached = null;
    if ($cached !== null) return $cached;
    $cached = array();
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return $cached;
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) return $cached;
    $reserved = wpconvert_reserved_permalink_bases();
    foreach ($routes as $route => $data) {
        if (!is_string($route)) continue;
        $path = trim(preg_replace('/[?#].*$/', '', $route), '/');
        if ($path === '' || strpos($path, '://') !== false) continue;
        $segments = explode('/', $path);
        if (count($segments) < 2) continue; // only nested /<base>/<x> is shadowed
        if (in_array(strtolower($segments[0]), $reserved, true)) {
            $cached[] = $path;
        }
    }
    return $cached;
}

// Register the top-priority rescue rules on init so they are present whenever WP builds
// (or flushes) the rewrite array.
function wpconvert_register_reserved_base_route_rules() {
    foreach (wpconvert_reserved_base_route_paths() as $path) {
        add_rewrite_rule('^' . $path . '/?$', 'index.php?pagename=' . $path, 'top');
    }
}
add_action('init', 'wpconvert_register_reserved_base_route_rules', 5);

// One-time, hash-guarded flush so the rules above take effect — covers the in-place reconvert
// case where after_switch_theme never fires. No-op (never touches rewrites) when this site has
// no reserved-base routes, so unrelated conversions are unaffected.
function wpconvert_flush_reserved_base_route_rules() {
    $reserved_paths = wpconvert_reserved_base_route_paths();
    if (empty($reserved_paths)) return;
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return;
    $hash = md5_file($routes_path);
    if (get_option('wpconvert_reserved_base_rules_hash') === $hash) return;
    flush_rewrite_rules(false);
    update_option('wpconvert_reserved_base_rules_hash', $hash);
}
add_action('init', 'wpconvert_flush_reserved_base_route_rules', 6);
add_action('after_switch_theme', 'wpconvert_flush_reserved_base_route_rules', 6);

// Helper to extract all routes from menu structure
function wpconvert_extract_routes_from_menu($items, &$routes = array()) {
    foreach ($items as $item) {
        if (!empty($item['url']) && !empty($item['title'])) {
            $url = $item['url'];
            // Convert hash-based SPA routes (#/about) to regular routes (/about)
            if (strpos($url, '#/') === 0) {
                $url = substr($url, 1); // Remove #, keep /
            }
            // Only add internal paths (skip simple hash anchors like # and
            // EC-ROUTE-EXT-001: protocol-relative //host or scheme URLs)
            if (strpos($url, '/') === 0 && $url !== '#' && strpos($url, '//') !== 0 && strpos($url, '://') === false) {
                $routes[$url] = $item['title'];
            }
        }
        // Recursively extract from children
        if (!empty($item['children']) && is_array($item['children'])) {
            wpconvert_extract_routes_from_menu($item['children'], $routes);
        }
    }
    return $routes;
}

// Helper to normalize anchor urls -> slug
function wpconvert_slug_from_anchor($url) {
  // "#team" or "/#team" -> "team"
  if (strpos($url, '#') === 0) return sanitize_title(substr($url, 1));
  if (strpos($url, '/#') === 0) return sanitize_title(substr($url, 2));
  return '';
}

// EC-PERF-001: Resolve only the pages that menus.json items actually reference,
// instead of enumerating every page on the site. The old full get_pages() scan
// ran during theme activation and crashed PHP on sites with large existing page
// counts (the activation request itself got killed). Menus reference at most a
// few dozen URLs, so targeted lookups are bounded regardless of site size.
function wpconvert_build_menu_page_maps($items, &$pages_by_path, &$pages_by_title, &$pages_by_slug) {
    if (!is_array($items)) return;
    foreach ($items as $item) {
        $url = isset($item['url']) ? (string) $item['url'] : '';
        $title = isset($item['title']) ? (string) $item['title'] : '';

        // Hash-router routes (#/about) -> /about, same as the importer does
        if (strpos($url, '#/') === 0) {
            $url = substr($url, 1);
        }
        $candidates = array();
        if ($url !== '' && $url !== '#' && $url !== '/' && strpos($url, '://') === false && strpos($url, '#') !== 0 && !preg_match('#^(mailto|tel|javascript):#i', $url)) {
            $upath = $url;
            $hash_pos = strpos($upath, '#');
            if ($hash_pos !== false) {
                $upath = substr($upath, 0, $hash_pos);
            }
            $upath = preg_replace('#\.html?$#i', '', $upath);
            $upath = preg_replace('#^\.\.?/#', '', $upath);
            $upath = trim($upath, '/');
            if ($upath !== '') {
                $candidates[] = $upath;
                $useg = explode('/', $upath);
                if (count($useg) > 1) {
                    $candidates[] = end($useg);                    // leaf slug (child pages)
                    $candidates[] = str_replace('/', '-', $upath); // flat-slug variant
                }
            }
        }
        if ($title !== '') {
            $candidates[] = sanitize_title($title);
        }
        foreach (array_unique(array_filter($candidates)) as $cand) {
            $mp = get_page_by_path($cand);
            if (!$mp && strpos($cand, '/') === false) {
                $found = get_posts(array('name' => $cand, 'post_type' => 'page', 'post_status' => 'publish', 'numberposts' => 1));
                if (!empty($found)) {
                    $mp = $found[0];
                }
            }
            if ($mp) {
                $full_path = trim(get_page_uri($mp->ID), '/');
                if ($full_path !== '') {
                    $pages_by_path[$full_path] = $mp->ID;
                }
                $pages_by_slug[$mp->post_name] = $mp->ID;
                $pages_by_title[sanitize_title($mp->post_title)] = $mp->ID;
            }
        }
        if (!empty($item['children']) && is_array($item['children'])) {
            wpconvert_build_menu_page_maps($item['children'], $pages_by_path, $pages_by_title, $pages_by_slug);
        }
    }
}

// Import and assign menus on theme activation
function wpconvert_import_menus_from_json() {
  // Guard with option to prevent duplicates, BUT also verify the current
  // theme actually has its nav_menu_locations set. When a theme is uploaded
  // with a different folder name, the global wpconvert_menu_created flag
  // persists but nav_menu_locations (a per-theme theme_mod) is empty.
  if (get_option('wpconvert_menu_created')) {
    $locs = get_theme_mod('nav_menu_locations', array());
    $has_primary = !empty($locs['primary']) && wp_get_nav_menu_object($locs['primary']);
    if ($has_primary) {
      return;
    }
  }
  
  $json_path = get_template_directory() . '/assets/data/menus.json';
  if (!file_exists($json_path)) {
    update_option('wpconvert_menu_created', 1);
    return;
  }

  $data = json_decode(file_get_contents($json_path), true);
  if (!$data || !is_array($data)) {
    update_option('wpconvert_menu_created', 1);
    return;
  }

  // EC-NAV-370: after_switch_theme fires on every request that starts before
  // check_theme_switched() clears the theme_switched option, so the first page
  // load after activation can run several importers in parallel. Only one may
  // proceed; the others simply skip, and the visitor sees the menus.json
  // fallback menu in the meantime.
  if (!wpconvert_acquire_menu_import_lock()) return;

  // EC-NAV-370: snapshot the menus that exist right now. The leftover-theme sweep
  // at the end deletes from THIS list only — resolving it against
  // wp_get_nav_menus() after the import would delete a menu that a concurrent
  // worker created a moment ago, leaving the site with no primary menu at all.
  $pre_existing_menu_ids = array();
  foreach ((array) wp_get_nav_menus() as $m) {
    $pre_existing_menu_ids[] = (int) $m->term_id;
  }

  // Create or get menu
  $menu_name = 'Primary Menu';
  $menu_obj = wp_get_nav_menu_object($menu_name);
  $menu_id = $menu_obj ? (int)$menu_obj->term_id : (int)wp_create_nav_menu($menu_name);
  
  // Remove any existing items to avoid duplicates
  $existing_items = wp_get_nav_menu_items($menu_id);
  if ($existing_items) {
    foreach ($existing_items as $item) {
      wp_delete_post($item->ID, true);
    }
  }
  
  $locations = get_theme_mod('nav_menu_locations', array());

  // If a different menu was previously assigned to the primary location,
  // clear its items too so the old menu doesn't create duplicates in wp-admin.
  if (!empty($locations['primary']) && (int)$locations['primary'] !== $menu_id) {
    $old_items = wp_get_nav_menu_items((int)$locations['primary']);
    if ($old_items) {
      foreach ($old_items as $item) {
        wp_delete_post($item->ID, true);
      }
    }
  }
  
  // EC-PERF-001: Build page lookup maps ONLY for pages referenced by menu items
  // (targeted lookups, bounded by menu size) — never enumerate all pages.
  $pages_by_path = array();
  $pages_by_title = array();
  $pages_by_slug = array();
  if (!empty($data['primary']['items'])) {
    wpconvert_build_menu_page_maps($data['primary']['items'], $pages_by_path, $pages_by_title, $pages_by_slug);
  }
  if (!empty($data['footer']['items'])) {
    wpconvert_build_menu_page_maps($data['footer']['items'], $pages_by_path, $pages_by_title, $pages_by_slug);
  }

  // Debug logging (count only — never dump all paths, the list can be huge)
  error_log('WPConvert: Page lookup maps built - ' . count($pages_by_path) . ' pages by path');
  
  // Import menu items from JSON
  if (!empty($data['primary']['items'])) {
    wpconvert_insert_menu_items($data['primary']['items'], $menu_id, 0, $pages_by_path, $pages_by_title, $pages_by_slug);
  } else {
    // Fallback: add existing pages once.
    // EC-PERF-001: Capped to a few top-level pages — the old unbounded get_pages()
    // would insert EVERY page as a menu item (tens of thousands on large sites).
    // EC-PERF-003: Skipped entirely on very large sites (scale guard) — auto-filling
    // a menu from arbitrary existing pages is wrong there anyway.
    $fallback_pages = wpconvert_bulk_page_ops_allowed() ? (get_pages(array(
      'number'      => 10,
      'parent'      => 0,
      'sort_column' => 'menu_order,post_title',
      'post_status' => 'publish',
    )) ?: array()) : array();
    foreach ($fallback_pages as $p) {
      wp_update_nav_menu_item($menu_id, 0, [
        'menu-item-object-id' => $p->ID,
        'menu-item-object'    => 'page',
        'menu-item-type'      => 'post_type',
        'menu-item-status'    => 'publish'
      ]);
    }
  }

  $locations['primary'] = $menu_id;
  
  // Import footer menu if it exists
  if (!empty($data['footer']['items'])) {
    $footer_menu_name = 'Footer Menu';
    $footer_menu_obj = wp_get_nav_menu_object($footer_menu_name);
    $footer_menu_id = $footer_menu_obj ? (int)$footer_menu_obj->term_id : (int)wp_create_nav_menu($footer_menu_name);
    
    // Remove any existing items to avoid duplicates
    $existing_footer_items = wp_get_nav_menu_items($footer_menu_id);
    if ($existing_footer_items) {
      foreach ($existing_footer_items as $item) {
        wp_delete_post($item->ID, true);
      }
    }
    
    // Insert footer menu items
    wpconvert_insert_menu_items($data['footer']['items'], $footer_menu_id, 0, $pages_by_path, $pages_by_title, $pages_by_slug);
    $locations['footer'] = $footer_menu_id;
    
    error_log('WPConvert: Footer menu created with ' . count($data['footer']['items']) . ' items');
  }
  
  set_theme_mod('nav_menu_locations', $locations);
  update_option('wpconvert_menu_created', 1);
  if (file_exists($json_path)) {
    update_option('wpconvert_menus_hash', md5_file($json_path));
  }

  // Remove any leftover menus from previous themes to prevent duplicates
  // showing up in Appearance > Menus. Bounded to the pre-import snapshot: a menu
  // that appeared while we were importing belongs to a concurrent worker, not to
  // a previous theme.
  $keep_ids = array($menu_id);
  if (!empty($footer_menu_id)) $keep_ids[] = $footer_menu_id;
  foreach ($pre_existing_menu_ids as $old_menu_id) {
    if (!in_array((int)$old_menu_id, $keep_ids, true)) {
      $old_items = wp_get_nav_menu_items((int)$old_menu_id);
      if ($old_items) {
        foreach ($old_items as $item) {
          wp_delete_post($item->ID, true);
        }
      }
      wp_delete_nav_menu((int)$old_menu_id);
    }
  }

  // EC-NAV-370: net for anything that slipped past the lock (a stale-lock
  // takeover, or a database that cannot run the locking statement).
  wpconvert_dedupe_menu_items($menu_id);
  if (!empty($footer_menu_id)) wpconvert_dedupe_menu_items($footer_menu_id);
  update_option('wpconvert_menu_dedupe_done', 1);
  wpconvert_release_menu_import_lock();
}

// Helper function to recursively insert menu items
function wpconvert_insert_menu_items($items, $menu_id, $parent_id, $pages_by_path, $pages_by_title, $pages_by_slug = array()) {
  foreach ($items as $item) {
    $title = isset($item['title']) ? wp_strip_all_tags($item['title']) : '';
    $url = isset($item['url']) ? $item['url'] : '#';
    
    // EC-NAV-168: Separate hash fragment BEFORE any URL processing.
    // Static sites use "page.html#section" — the # prevents .html detection
    // (regex requires .html at end of string) and breaks normalization
    // (# is not in the bare-path character class). Without this, the raw URL
    // reaches wp_update_nav_menu_item which calls esc_url_raw, prepending
    // http:// → "http://page.html#section" stored in the database, which
    // wpconvert_convert_static_url skips as "external".
    $import_hash_fragment = '';
    $import_hash_pos = strpos($url, '#');
    if ($import_hash_pos !== false && $import_hash_pos > 0) {
      $import_hash_fragment = substr($url, $import_hash_pos);
      $url = substr($url, 0, $import_hash_pos);
    }
    
    $args = [
      'menu-item-title'  => $title,
      'menu-item-status' => 'publish',
      'menu-item-parent-id' => (int)$parent_id,
    ];
    
    // Store original classes as meta
    if (!empty($item['classes']) && is_array($item['classes'])) {
      $args['menu-item-classes'] = implode(' ', $item['classes']);
    }
    
    // UNIVERSAL: Handle home page and internal links correctly
    // Convert hash-based SPA routes (#/about) to regular routes (/about)
    if (strpos($url, '#/') === 0) {
      $url = substr($url, 1); // Remove #, keep /
    }
    
    // EC-NAV-120: menus.json may use bare paths (blog/) while siblings use /collection. Without a
    // leading slash, items fall through to "External" and WP stores literal "blog/" as menu-item-url
    // (browser-relative). Normalize to /blog before internal-path matching.
    if ($url !== '#' && $url !== '/' && !preg_match('#^https?://#i', $url) && strpos($url, '#') !== 0 && strpos($url, '/') !== 0 && preg_match('#^[a-zA-Z0-9][a-zA-Z0-9._/-]*$#', $url)) {
      $url = '/' . trim($url, '/');
    }
    
    if ($url === '/' || $url === '' || $url === 'index.html') {
      // Home page - link to site root
      $args['menu-item-type'] = 'custom';
      $args['menu-item-url'] = home_url('/');
      error_log("WPConvert: Home menu item created");
    } elseif (preg_match('/^\/#[^\/]/', $url) || (strpos($url, '#') === 0 && strpos($url, '#/') !== 0)) {
      // EC-NAV-055: Homepage anchor link (e.g., /#news, #about) — scroll to section on homepage
      // Must NOT enter the internal-path branch which appends a trailing slash after the fragment
      $args['menu-item-type'] = 'custom';
      $args['menu-item-url'] = home_url('/') . ltrim($url, '/');
      error_log("WPConvert: Anchor menu item created for '$url'");
    } elseif (preg_match('#\.html?$#i', $url) && !preg_match('#^https?://#i', $url)) {
      // CRITICAL: Static site HTML file (e.g., shop.html, about.html, ./pages/shop.html)
      // Convert to WordPress page link
      $slug = preg_replace('#\.html?$#i', '', $url); // Strip .html/.htm
      $slug = preg_replace('#^\.\.?/#', '', $slug);  // Strip leading ./ or ../
      $slug = trim($slug, '/');                        // Remove leading/trailing slashes
      
      // For paths like "pages/shop", try just "shop" first
      $slug_parts = explode('/', $slug);
      $simple_slug = end($slug_parts);
      
      $target_id = null;
      
      // Strategy 1: Try simple slug first (e.g., "shop" from "pages/shop")
      if (isset($pages_by_slug[$simple_slug])) {
        $target_id = $pages_by_slug[$simple_slug];
        error_log("WPConvert: Matched '$url' to page ID $target_id via simple slug '$simple_slug' from .html");
      }
      
      // Strategy 2: Try full slug (e.g., "pages-shop" or original slug)
      if (!$target_id && isset($pages_by_slug[$slug])) {
        $target_id = $pages_by_slug[$slug];
        error_log("WPConvert: Matched '$url' to page ID $target_id via full slug '$slug' from .html");
      }
      
      // Strategy 3: Direct path match
      if (!$target_id && isset($pages_by_path[$slug])) {
        $target_id = $pages_by_path[$slug];
        error_log("WPConvert: Matched '$url' to page ID $target_id via path from .html");
      }
      
      // Strategy 4: Title-based match
      if (!$target_id && isset($pages_by_title[sanitize_title($title)])) {
        $target_id = $pages_by_title[sanitize_title($title)];
        error_log("WPConvert: Matched '$url' to page ID $target_id via title from .html");
      }
      
      if ($target_id) {
        $args['menu-item-type'] = 'post_type';
        $args['menu-item-object'] = 'page';
        $args['menu-item-object-id'] = (int)$target_id;
      } else {
        // Create as custom link with WordPress-friendly URL
        error_log("WPConvert: No page found for '$url' (title: '$title'), creating as custom link to /$slug/");
        $args['menu-item-type'] = 'custom';
        $args['menu-item-url'] = home_url('/' . $slug . '/');
      }
    } elseif (0 === strpos($url, '/') && $url !== '/') {
      // Internal path link - try multiple matching strategies
      $slug = trim($url, '/');
      $target_id = null;
      
      // Strategy 1: Direct full path match (e.g., services/process-serving)
      if (isset($pages_by_path[$slug])) {
        $target_id = $pages_by_path[$slug];
        error_log("WPConvert: Matched '$url' to page ID $target_id via direct path");
      }
      
      // Strategy 2: Title-based match
      if (!$target_id && isset($pages_by_title[sanitize_title($title)])) {
        $target_id = $pages_by_title[sanitize_title($title)];
        error_log("WPConvert: Matched '$url' to page ID $target_id via title");
      }
      
      // Strategy 3: Slug-only match (for child pages)
      if (!$target_id) {
        $parts = explode('/', $slug);
        $last_part = end($parts);
        if (isset($pages_by_slug[$last_part])) {
          $target_id = $pages_by_slug[$last_part];
          error_log("WPConvert: Matched '$url' to page ID $target_id via slug");
        }
      }
      
      if ($target_id) {
        $args['menu-item-type'] = 'post_type';
        $args['menu-item-object'] = 'page';
        $args['menu-item-object-id'] = (int)$target_id;
      } else {
        // Log warning and create as custom link
        error_log("WPConvert: No page found for URL '$url' (title: '$title'), creating as custom link");
        $args['menu-item-type'] = 'custom';
        $args['menu-item-url'] = home_url('/' . $slug . '/');
      }
    } else {
      // External or hash link
      $args['menu-item-type'] = 'custom';
      $args['menu-item-url'] = $url;
    }
    
    // EC-NAV-168: Reattach hash fragment to the resolved URL.
    // For post_type items, WordPress derives the URL from the page object,
    // but we still need to store the fragment so the walker can append it.
    if ($import_hash_fragment !== '') {
      if (!empty($args['menu-item-url'])) {
        $args['menu-item-url'] .= $import_hash_fragment;
      }
      if (!empty($args['menu-item-object-id'])) {
        // For page links, override to custom link with the correct URL + fragment
        // because post_type links don't support hash fragments natively
        $page_url = get_permalink((int)$args['menu-item-object-id']);
        if ($page_url) {
          $args['menu-item-type'] = 'custom';
          $args['menu-item-url'] = $page_url . $import_hash_fragment;
          unset($args['menu-item-object-id']);
          unset($args['menu-item-object']);
        }
      }
    }
    
    $item_id = wp_update_nav_menu_item($menu_id, 0, $args);
    
    // Store original classes as post meta for walker to retrieve
    if ($item_id) {
      if (!empty($item['classes']) && is_array($item['classes'])) {
        update_post_meta($item_id, '_wpconvert_original_classes', implode(' ', $item['classes']));
      }
      
      // CRITICAL: Also store LI classes for static sites (e.g., "level", "level2", "level3")
      if (!empty($item['liClasses']) && is_array($item['liClasses'])) {
        update_post_meta($item_id, '_wpconvert_li_classes', implode(' ', $item['liClasses']));
      }
      
      // EC-NAV-065b: Store original li id for PHP sites with hover/interaction scripts.
      // WordPress generates its own li IDs (menu-item-42) but original scripts like
      // hoverTextMap expect the original IDs (menuitem-1, menuitem-2, etc.).
      if (!empty($item['liId'])) {
        update_post_meta($item_id, '_wpconvert_li_id', $item['liId']);
      }
      
      // CRITICAL: Also store whether this item has children for filtering logic
      $has_children = !empty($item['children']) && is_array($item['children']) && count($item['children']) > 0;
      update_post_meta($item_id, '_wpconvert_has_children', $has_children ? '1' : '0');
    }
    
    // Recursively add children
    if (!empty($item['children']) && is_array($item['children'])) {
      wpconvert_insert_menu_items($item['children'], $menu_id, $item_id, $pages_by_path, $pages_by_title, $pages_by_slug);
    }
  }
}

add_action('after_switch_theme', 'wpconvert_import_menus_from_json');

// EC-NAV-065b: Restore original li IDs on WordPress nav menu items.
// The auto-import creates WP menu items with WordPress-generated IDs (menu-item-42).
// Original PHP sites have scripts (e.g. hoverTextMap) that depend on specific li IDs
// like "menuitem-1". This filter reads the stored _wpconvert_li_id meta and uses it.
function wpconvert_restore_li_id($id, $item, $args, $depth) {
    $custom_id = get_post_meta($item->ID, '_wpconvert_li_id', true);
    if ($custom_id) {
        return $custom_id;
    }
    return $id;
}
add_filter('nav_menu_item_id', 'wpconvert_restore_li_id', 10, 4);


/**
 * EC-BLOG-172: Resolve a single root-relative /assets or /images URL to the
 * theme's stored asset (assets/images/...). Returns the input unchanged for any
 * URL we should not touch (absolute, protocol-relative, data:, non-asset paths).
 */
if (!function_exists('wpconvert_resolve_local_asset_url')) {
    function wpconvert_resolve_local_asset_url($raw) {
        if (!is_string($raw) || $raw === '') return $raw;
        $raw = trim($raw);
        // Leave absolute, protocol-relative and data: URLs alone.
        if (preg_match('#^(https?:)?//#i', $raw) || stripos($raw, 'data:') === 0) return $raw;
        // Only handle root-relative local asset/image paths.
        if ($raw[0] !== '/') return $raw;
        $rel = ltrim($raw, '/');
        // Only /assets/... and /images/... are theme assets — bail otherwise
        // (e.g. /blog/<slug> permalinks must never be rewritten).
        if (!preg_match('#^(assets|images)/#', $rel)) return $raw;
        // Vite flat assets: /assets/x.jpg → assets/images/x.jpg
        if (preg_match('#^assets/(?!images/)#', $rel)) {
            $rel = preg_replace('#^assets/#', 'assets/images/', $rel, 1);
        }
        // Public-dir images: /images/x.jpg → assets/images/x.jpg
        if (preg_match('#^images/#', $rel)) {
            $rel = 'assets/' . $rel;
        }
        $rel_basename = basename($rel);
        $candidates = array($rel, 'assets/images/' . $rel_basename);
        foreach ($candidates as $cand) {
            if (file_exists(get_template_directory() . '/' . $cand)) {
                return get_template_directory_uri() . '/' . $cand;
            }
        }
        // Fall back to a theme-relative URL (better than a site-root 404).
        return get_template_directory_uri() . '/' . $rel;
    }
}

/**
 * EC-BLOG-172: Rewrite inline image URLs (src + srcset) inside imported blog
 * post content so /assets and /images paths point at the theme's stored copies.
 */
if (!function_exists('wpconvert_rewrite_content_asset_urls')) {
    function wpconvert_rewrite_content_asset_urls($content) {
        if (!is_string($content) || $content === '') return $content;
        // src="/assets/..." or src='/images/...'
        $content = preg_replace_callback(
            '#\bsrc=("|\')(/(?:assets|images)/[^"\']+)\1#i',
            function ($m) {
                return 'src=' . $m[1] . esc_url(wpconvert_resolve_local_asset_url($m[2])) . $m[1];
            },
            $content
        );
        // srcset="/assets/a.jpg 1x, /assets/b.jpg 2x"
        $content = preg_replace_callback(
            '#\bsrcset=("|\')([^"\']+)\1#i',
            function ($m) {
                $parts = array_map('trim', explode(',', $m[2]));
                $out = array();
                foreach ($parts as $p) {
                    if ($p === '') continue;
                    $bits = preg_split('#\s+#', $p, 2);
                    $url = wpconvert_resolve_local_asset_url($bits[0]);
                    $out[] = isset($bits[1]) ? $url . ' ' . $bits[1] : $url;
                }
                return 'srcset=' . $m[1] . implode(', ', $out) . $m[1];
            },
            $content
        );
        return $content;
    }
}


// Import blog posts from import-posts.json on theme activation
function wpconvert_import_blog_posts() {
    if (!defined('WPCONVERT_NATIVE_BLOG') || !WPCONVERT_NATIVE_BLOG) {
        return;
    }

    $json_path = get_template_directory() . '/assets/data/import-posts.json';
    if (!file_exists($json_path)) return;

    // EC-BLOG-182: Gate on a SIGNATURE of the import data, not a permanent
    // boolean latch. A "reconvert" ships a fresh import-posts.json into the same
    // active theme; the old one-time wpconvert_blog_imported flag (which an
    // earlier — possibly empty — import may have set) would otherwise block
    // re-seeding FOREVER, so corrected posts could never appear. The per-post
    // dedupe-by-slug below makes re-runs fully idempotent (no duplicates, and
    // any user edits to already-imported posts are preserved). We only re-run
    // when the source data actually changes.
    $import_sig = @md5_file($json_path);
    if ($import_sig && get_option('wpconvert_blog_import_sig') === $import_sig) {
        // EC-BLOG-219: Self-heal. The signature can get latched even when a prior
        // run produced ZERO live posts — e.g. an earlier (broken) conversion, a
        // reconvert layered over stale wp_options, or a DB that lost the posts.
        // If the sig matches but NO published post exists, fall through and
        // re-import instead of skipping forever (which left the native blog index
        // permanently empty). When at least one post is present we honor it and
        // skip, so this never fights a site with real content.
        $existing_live = get_posts(array(
            'post_type'   => 'post',
            'post_status' => 'publish',
            'numberposts' => 1,
            'fields'      => 'ids',
            'no_found_rows' => true,
            'suppress_filters' => true,
        ));
        if (!empty($existing_live)) return;
    }

    $data = json_decode(file_get_contents($json_path), true);
    if (!is_array($data) || empty($data)) return;

    // Support both old format (flat array) and new format (object with posts + metadata)
    $posts = isset($data['posts']) ? $data['posts'] : $data;
    $blog_prefix = isset($data['blogRoutePrefix']) ? $data['blogRoutePrefix'] : '/blog';

    if (!is_array($posts) || empty($posts)) return;

    require_once(ABSPATH . 'wp-admin/includes/media.php');
    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/image.php');

    // EC-BLOG-002 / EC-BLOG-215 / EC-BLOG-216: Match the source blog URLs
    // (/{prefix}/<slug>/). The actual structure change + rewrite-rule flush lives
    // in the standalone, self-healing wpconvert_ensure_blog_permalink() (hooked on
    // after_switch_theme + admin_init + init) so it ALSO runs on a reconvert, whose
    // in-place theme swap never fires after_switch_theme. Calling it here keeps the
    // fresh-activation ordering (structure set before the import loop).
    $prefix_slug = ltrim($blog_prefix, '/');
    wpconvert_ensure_blog_permalink();

    // EC-BLOG-209: The posts index (home.php) must mount at the blog LISTING
    // route slug, which can differ from the post permalink prefix. E.g. Horizons
    // lists reviews at "/reviews" but each post lives under "/article/<slug>";
    // mounting the posts page at "article" left the "Reviews" nav item pointing
    // at an unrouted "/reviews" ("Nothing found"). Prefer blogListingSlug when the
    // generator recorded one; fall back to the permalink prefix otherwise.
    $listing_slug = (isset($data['blogListingSlug']) && $data['blogListingSlug'])
        ? ltrim($data['blogListingSlug'], '/')
        : $prefix_slug;

    // Set up static front page + posts page so home.php serves blog index
    $front_page = get_page_by_path('front-page');
    if (!$front_page) {
        $front_page = get_page_by_path('home');
    }
    if ($front_page) {
        update_option('show_on_front', 'page');
        update_option('page_on_front', $front_page->ID);
    }

    // Create a Blog page for the posts index if it doesn't exist
    $blog_page = get_page_by_path($listing_slug);
    if (!$blog_page) {
        $blog_page_id = wp_insert_post(array(
            'post_title'  => ucwords(str_replace('-', ' ', $listing_slug)),
            'post_name'   => $listing_slug,
            'post_status' => 'publish',
            'post_type'   => 'page',
        ));
        if (!is_wp_error($blog_page_id)) {
            update_option('page_for_posts', $blog_page_id);
        }
    } else {
        update_option('page_for_posts', $blog_page->ID);
    }

    $imported = 0;
    foreach ($posts as $post_data) {
        // EC-BLOG-183: Compute the publish date and NEVER schedule into the
        // future. A year-less / ambiguous source date makes strtotime() assume
        // the current year, often yielding a FUTURE timestamp → wp_insert_post
        // silently flips post_status to 'future' (Scheduled) and the article
        // never appears on the front-end. Imported posts are existing published
        // content, so clamp any future date back to "now" and keep them live.
        $date = '';
        if (!empty($post_data['date'])) {
            $ts = strtotime($post_data['date']);
            if ($ts) {
                if ($ts > current_time('timestamp')) $ts = current_time('timestamp');
                $date = date('Y-m-d H:i:s', $ts);
            }
        }
        $post_date = $date ?: current_time('mysql');

        $existing = get_page_by_path(sanitize_title($post_data['slug'] ?? $post_data['title']), OBJECT, 'post');
        if ($existing) {
            // EC-BLOG-183: Recover posts that a PRIOR (stale) import scheduled
            // into the future. Only flips the stuck status/date — never touches
            // the post body, so user edits are preserved. Re-runs reach here
            // because the corrected dates change the import-posts.json signature.
            if (get_post_status($existing) === 'future') {
                wp_update_post(array(
                    'ID'            => $existing->ID,
                    'post_status'   => 'publish',
                    'post_date'     => $post_date,
                    'post_date_gmt' => get_gmt_from_date($post_date),
                ));
            }

            // EC-BLOG-203: Backfill taxonomy + meta onto already-imported posts.
            // A post created by an EARLIER conversion (before category support, or
            // where wp_set_post_terms failed) would otherwise be skipped forever on
            // every reconvert, so get_the_category() stayed empty and the category
            // badge never rendered on the blog cards. These calls are idempotent and
            // never touch the post body/title, so user edits remain preserved.
            if (!empty($post_data['category'])) {
                $existing_cat = sanitize_text_field($post_data['category']);
                $existing_terms = wp_get_post_terms($existing->ID, 'category', array('fields' => 'names'));
                if (is_wp_error($existing_terms)
                    || empty($existing_terms)
                    || (count($existing_terms) === 1 && strcasecmp($existing_terms[0], 'Uncategorized') === 0)
                    || !in_array($existing_cat, $existing_terms, true)) {
                    wpconvert_assign_post_category($existing->ID, $existing_cat);
                }
            }
            if (!empty($post_data['author']) && !get_post_meta($existing->ID, '_wpconvert_author_name', true)) {
                update_post_meta($existing->ID, '_wpconvert_author_name', sanitize_text_field($post_data['author']));
            }
            // EC-BLOG-224: backfill author role/bio (from a resolved shared author object).
            if (!empty($post_data['authorRole']) && !get_post_meta($existing->ID, '_wpconvert_author_role', true)) {
                update_post_meta($existing->ID, '_wpconvert_author_role', sanitize_text_field($post_data['authorRole']));
            }
            if (!empty($post_data['authorBio']) && !get_post_meta($existing->ID, '_wpconvert_author_bio', true)) {
                update_post_meta($existing->ID, '_wpconvert_author_bio', sanitize_textarea_field($post_data['authorBio']));
            }
            if (!empty($post_data['readTime']) && !get_post_meta($existing->ID, '_wpconvert_read_time', true)) {
                update_post_meta($existing->ID, '_wpconvert_read_time', sanitize_text_field($post_data['readTime']));
            }
            continue;
        }

        // EC-BLOG-172: Resolve inline /assets|/images image URLs (e.g. the
        // "More in {category}" related-posts sidebar) to the theme dir BEFORE
        // sanitising, so baked snapshot thumbnails don't 404 at the site root.
        $post_body = wpconvert_rewrite_content_asset_urls($post_data['content'] ?? '');

        $post_id = wp_insert_post(array(
            'post_title'    => sanitize_text_field($post_data['title'] ?? 'Untitled'),
            'post_content'  => wp_kses_post($post_body),
            'post_excerpt'  => sanitize_text_field($post_data['excerpt'] ?? ''),
            'post_status'   => 'publish',
            'post_type'     => 'post',
            'post_date'     => $post_date,
            'post_name'     => sanitize_title($post_data['slug'] ?? $post_data['title']),
            // EC-BLOG-COMMENTS-001: honor the "Enable comments" toggle at import
            // (default OFF). wpconvert_sync_blog_comment_status() keeps existing
            // imported posts in sync when the owner flips the toggle later.
            'comment_status' => (function_exists('wpconvert_enable_comments') && wpconvert_enable_comments()) ? 'open' : 'closed',
            'ping_status'    => 'closed',
        ));

        if (is_wp_error($post_id)) continue;

        // EC-BLOG-183: Tag imported posts so future maintenance passes can
        // identify WPConvert-seeded content unambiguously.
        update_post_meta($post_id, '_wpconvert_imported', 1);

        // EC-BLOG-228: Stamp the importing user so the theme can distinguish a
        // freshly-imported (still source-owned) post from one the owner later
        // reassigns to a real WP author. Bylines/bio follow the source
        // placeholder only while post_author still equals this id. Stamped on
        // NEW inserts ONLY — never backfilled (see the $existing branch above),
        // because backfilling would re-lock a post the owner already reassigned.
        update_post_meta($post_id, '_wpconvert_import_author_id', (int) get_post_field('post_author', $post_id));

        // EC-BLOG-CAT-ASSIGN-001: Assign the source category by NAME. Do NOT use
        // wp_set_post_terms here: for a HIERARCHICAL taxonomy (category) core runs
        // array_map('intval', $terms) on the list, so a name like "Food" becomes
        // intval('Food') === 0 and NOTHING is assigned — the post silently stays
        // Uncategorized. wpconvert_assign_post_category() resolves/creates the term and
        // assigns it via wp_set_object_terms (which accepts names). Pass false for
        // $append so the imported category REPLACES the default Uncategorized term WP
        // auto-assigns during wp_insert_post.
        if (!empty($post_data['category'])) {
            $cat_name = sanitize_text_field($post_data['category']);
            $set_result = wpconvert_assign_post_category($post_id, $cat_name);
            if (is_wp_error($set_result)) {
                error_log('WPConvert: Failed to set category "' . $cat_name . '" on post ' . $post_id . ': ' . $set_result->get_error_message());
            }
        }

        // Set featured image from URL
        if (!empty($post_data['image'])) {
            $image_url = $post_data['image'];
            // Handle relative paths (Vite /assets/x.jpg → theme stores under assets/images/)
            if (strpos($image_url, 'http') !== 0) {
                $rel = ltrim($image_url, '/');
                if (preg_match('#^assets/(?!images/)#', $rel)) {
                    $rel = preg_replace('#^assets/#', 'assets/images/', $rel, 1);
                }
                // EC-BLOG-050: React/Vite sites use /images/foo.jpg (public dir)
                // but the theme stores everything under assets/images/.
                if (preg_match('#^images/#', $rel)) {
                    $rel = 'assets/' . $rel;
                }
                // EC-BLOG-152: Generic public-folder paths like /blog/foo.jpg — the
                // markdown blog importer rewrites these to assets/images/<basename>,
                // but if the snapshot pipeline saved them as <dir>-<basename> (collision
                // safety), the un-prefixed path would 404.  Try both, prefixed last.
                $rel_basename = basename($rel);
                $rel_dir = dirname($rel);
                $candidates = array($rel);
                if ($rel_dir && $rel_dir !== '.' && $rel_dir !== 'assets/images') {
                    $rel_dir_first = explode('/', $rel_dir)[0];
                    $candidates[] = 'assets/images/' . $rel_basename;
                    $candidates[] = 'assets/images/' . $rel_dir_first . '-' . $rel_basename;
                }
                $resolved = $rel;
                foreach ($candidates as $cand) {
                    $abs = get_template_directory() . '/' . $cand;
                    if (file_exists($abs)) { $resolved = $cand; break; }
                }
                $image_url = get_template_directory_uri() . '/' . $resolved;
            }
            // Always store external URL as fallback meta (media_sideload_image often fails)
            update_post_meta($post_id, '_wpconvert_featured_image_url', esc_url_raw($image_url));
            $attach_id = media_sideload_image($image_url, $post_id, $post_data['title'], 'id');
            if (!is_wp_error($attach_id)) {
                set_post_thumbnail($post_id, $attach_id);
            }
        }

        // Store readTime as custom field
        if (!empty($post_data['readTime'])) {
            update_post_meta($post_id, '_wpconvert_read_time', sanitize_text_field($post_data['readTime']));
        }

        // Set author if provided
        if (!empty($post_data['author'])) {
            update_post_meta($post_id, '_wpconvert_author_name', sanitize_text_field($post_data['author']));
        }
        // EC-BLOG-224: store author role/bio when the source resolved a shared author
        // object (author reference to a name/role/bio record). single.php renders an
        // author box from these; falls back gracefully when absent.
        if (!empty($post_data['authorRole'])) {
            update_post_meta($post_id, '_wpconvert_author_role', sanitize_text_field($post_data['authorRole']));
        }
        if (!empty($post_data['authorBio'])) {
            update_post_meta($post_id, '_wpconvert_author_bio', sanitize_textarea_field($post_data['authorBio']));
        }

        // EC-BLOG-221: per-post accent color for imageless color-band blogs. The
        // listing card + single hero render a gradient from this when the post has
        // no featured image (mirrors the source post.color design).
        if (!empty($post_data['color'])) {
            update_post_meta($post_id, '_wpconvert_accent_color', sanitize_text_field($post_data['color']));
        }

        $imported++;
    }

    // EC-BLOG-182: Record the data signature so we skip on unchanged re-runs but
    // re-import when a future reconvert ships new posts. Keep the legacy boolean
    // for any external tooling that may still read it.
    if ($import_sig) update_option('wpconvert_blog_import_sig', $import_sig);
    update_option('wpconvert_blog_imported', true);
    error_log("WPConvert: Imported $imported blog posts from source site");
}
// EC-BLOG-181: Run the import on init/admin_init in addition to after_switch_theme.
// "Reconverting" a site re-uploads the SAME theme over the active one, which does
// NOT fire after_switch_theme — so posts would never import and the blog stays
// empty even though assets/data/import-posts.json is present. The EC-BLOG-182
// data-signature gate (inside the function) keeps these extra hooks idempotent
// and cheap (one get_option + md5_file) on every subsequent request. Mirrors the
// init/admin_init pattern already used by wpconvert_fix_slug_conflicts.
add_action('after_switch_theme', 'wpconvert_import_blog_posts');
add_action('admin_init', 'wpconvert_import_blog_posts');
add_action('init', 'wpconvert_import_blog_posts', 20);

// EC-BLOG-216: Native-blog posts redirected to the home page after a RECONVERT.
//
// Root cause: the permalink switch to /{prefix}/%postname%/ lived INSIDE
// wpconvert_import_blog_posts(), behind the EC-BLOG-182 import-signature gate, and
// used a one-shot boolean latch option. On a reconvert the theme
// is re-uploaded in place, so after_switch_theme (WordPress's reliable rewrite-flush
// point) never fires. When the permalink OPTION flipped to /blog/%postname%/, every
// the_permalink() blog-card link repointed to /blog/<slug>/ — but the rewrite RULES
// were not reliably regenerated (a mid-init flush does not persist on hosts with a
// persistent object cache / opcache, and the one-shot latch blocked any later
// self-heal). Result: /blog/<slug>/ matched no post rule → 404 → WordPress's
// redirect_canonical() bounced the visitor to the front page.
//
// Fix: a standalone, self-healing routine, DECOUPLED from the import-signature gate,
// hooked on after_switch_theme + admin_init + init. It (1) sets the structure only
// when the current one is a built-in WP preset (a user's CUSTOM structure is always
// preserved — the long-stable EC-BLOG-002 guard), and (2) flushes the rewrite rules
// exactly once per structure change via a signature sentinel (never every request),
// so a reconvert whose rules went stale converges within one extra request.
function wpconvert_ensure_blog_permalink() {
    if (!defined('WPCONVERT_NATIVE_BLOG') || !WPCONVERT_NATIVE_BLOG) return;

    $json_path = get_template_directory() . '/assets/data/import-posts.json';
    if (!file_exists($json_path)) return;
    $data = json_decode(file_get_contents($json_path), true);
    if (!is_array($data)) return;

    $blog_prefix = isset($data['blogRoutePrefix']) ? $data['blogRoutePrefix'] : '/blog';
    $prefix_slug = ltrim((string) $blog_prefix, '/');
    if ($prefix_slug === '') return;
    $target = '/' . $prefix_slug . '/%postname%/';

    global $wp_rewrite;

    $current = get_option('permalink_structure');
    // Only ever override WordPress's own built-in presets — a hand-picked CUSTOM
    // structure is never touched.
    $presets = array(
        '',                                       // "Plain" (?p=123)
        '/%postname%/',                           // "Post name" (also EC-PERMA-001's seed)
        '/%year%/%monthnum%/%day%/%postname%/',   // "Day and name" (fresh-install default)
        '/%year%/%monthnum%/%postname%/',         // "Month and name"
        '/archives/%post_id%',                    // "Numeric"
    );
    if ($current !== $target && in_array($current, $presets, true)) {
        // CRITICAL: update_option() alone leaves the already-instantiated
        // $wp_rewrite object holding the OLD structure, so a subsequent
        // flush_rewrite_rules() would regenerate rules for the WRONG (old)
        // structure — posts kept 404ing at /{prefix}/<slug>/ (→ redirect home)
        // while the stale dated rules still resolved. set_permalink_structure()
        // updates BOTH the option and the in-memory object.
        if (is_object($wp_rewrite)) {
            $wp_rewrite->set_permalink_structure($target);
        } else {
            update_option('permalink_structure', $target);
        }
        $current = $target;
    }

    if ($current !== $target) return;

    // Regenerate rewrite rules when they don't yet carry a rule for this prefix, or
    // when the signature sentinel hasn't recorded this structure. The prefix check
    // makes the heal robust even if a prior run recorded the sentinel while the rules
    // were still stale. Once healed both are satisfied → no flush on later requests.
    $sig_ok = (get_option('wpconvert_blog_rewrite_sig') === $target);
    $rules = get_option('rewrite_rules');
    $has_prefix_rule = false;
    if (is_array($rules)) {
        foreach ($rules as $regex => $q) {
            if (strpos($regex, $prefix_slug . '/(') === 0) { $has_prefix_rule = true; break; }
        }
    }
    if (!$sig_ok || !$has_prefix_rule) {
        // Make sure the in-memory object matches the option before regenerating.
        if (is_object($wp_rewrite) && $wp_rewrite->permalink_structure !== $target) {
            $wp_rewrite->set_permalink_structure($target);
        }
        if (is_object($wp_rewrite)) {
            $wp_rewrite->flush_rules(false);
        } else {
            flush_rewrite_rules(false);
        }
        update_option('wpconvert_blog_rewrite_sig', $target);
    }
}
add_action('after_switch_theme', 'wpconvert_ensure_blog_permalink');
add_action('admin_init', 'wpconvert_ensure_blog_permalink');
add_action('init', 'wpconvert_ensure_blog_permalink', 20);

// EC-BLOG-031: Auto-configure WordPress reading settings for the blog page.
// EC-BLOG-037: page_for_posts must ONLY be set for native-blog themes (single.php exists).
// Starter themes use static page-blog*.php for the listing; if we assign page_for_posts,
// WordPress treats /blog/ as the posts index (home.php → index.php) and never renders
// the snapshot — users only see default posts like "Hello world".
function wpconvert_setup_reading_settings() {
    if (get_option('wpconvert_reading_setup')) return;
    
    $routes_file = get_template_directory() . '/assets/data/routes.json';
    $menus_file = get_template_directory() . '/assets/data/menus.json';
    
    $blog_slug = '';
    
    // Strategy 1: Find blog page from menus.json (most reliable — matches nav link)
    if (file_exists($menus_file)) {
        $menus = json_decode(file_get_contents($menus_file), true);
        if ($menus) {
            foreach (['primary', 'footer'] as $location) {
                if (!isset($menus[$location]['items'])) continue;
                foreach ($menus[$location]['items'] as $item) {
                    if (isset($item['title']) && preg_match('/^blog$/i', trim($item['title']))) {
                        $url = isset($item['url']) ? $item['url'] : '';
                        $slug = trim($url, '/');
                        if ($slug) { $blog_slug = $slug; break 2; }
                    }
                }
            }
        }
    }
    
    // Strategy 2: Find page with blog-related slug
    if (!$blog_slug) {
        $candidates = ['BlogPage', 'blog', 'Blog', 'blog-page'];
        foreach ($candidates as $slug) {
            $page = get_page_by_path($slug);
            if ($page) { $blog_slug = $slug; break; }
        }
    }
    
    if ($blog_slug) {
        $blog_page = get_page_by_path($blog_slug);
        if ($blog_page) {
            update_option('show_on_front', 'page');
            // Native PRO/Agency themes ship single.php + home.php loop; Starter does not.
            $native_blog_theme = file_exists(get_template_directory() . '/single.php');
            if ($native_blog_theme) {
                update_option('page_for_posts', $blog_page->ID);
            } else {
                error_log("WPConvert: Static blog theme — skipping page_for_posts so /{$blog_slug}/ uses page template snapshot");
            }
            
            // Also set front page if not already set
            $front = get_page_by_path('LandingPage');
            if (!$front) $front = get_page_by_path('home');
            if (!$front) {
                // Use the page with front-page.php template (bounded — only one needed)
                $pages = get_pages(array('meta_key' => '_wp_page_template', 'meta_value' => 'front-page.php', 'number' => 1));
                if (!empty($pages)) $front = $pages[0];
            }
            if ($front) {
                update_option('page_on_front', $front->ID);
            }
            
            error_log("WPConvert: Set blog page to '{$blog_slug}' (ID: {$blog_page->ID})");
        }
    }
    
    update_option('wpconvert_reading_setup', true);
}
add_action('after_switch_theme', 'wpconvert_setup_reading_settings', 99);

// Import and set custom logo on theme activation
function wpconvert_setup_custom_logo() {
    // Guard with option to prevent duplicates
    if (get_option('wpconvert_logo_setup')) {
        return;
    }
    
    $logo_json = get_template_directory() . '/assets/data/logo-setup.json';
    if (!file_exists($logo_json)) {
        update_option('wpconvert_logo_setup', 1);
        return;
    }
    
    $logo_info = json_decode(file_get_contents($logo_json), true);
    if (!$logo_info || empty($logo_info['src'])) {
        update_option('wpconvert_logo_setup', 1);
        return;
    }
    
    // Find the logo file in theme assets
    $logo_filename = basename($logo_info['src']);
    $logo_path = get_template_directory() . '/assets/images/' . $logo_filename;
    
    if (!file_exists($logo_path)) {
        // Try alternative paths for the logo
        $alt_paths = [
            get_template_directory() . '/assets/images/' . pathinfo($logo_filename, PATHINFO_FILENAME) . '.png',
            get_template_directory() . '/assets/images/' . pathinfo($logo_filename, PATHINFO_FILENAME) . '.jpg',
            get_template_directory() . '/assets/images/' . pathinfo($logo_filename, PATHINFO_FILENAME) . '.svg'
        ];
        
        $found = false;
        foreach ($alt_paths as $alt_path) {
            if (file_exists($alt_path)) {
                $logo_path = $alt_path;
                $logo_filename = basename($alt_path);
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            error_log('WPConvert: Logo file not found at ' . $logo_path);
            update_option('wpconvert_logo_setup', 1);
            return;
        }
    }
    
    // Import to Media Library
    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/media.php');
    require_once(ABSPATH . 'wp-admin/includes/image.php');
    
    $upload_dir = wp_upload_dir();
    $destination = $upload_dir['path'] . '/' . $logo_filename;
    
    // Check if logo already exists in media library
    $existing_attachment = get_posts([
        'post_type' => 'attachment',
        'meta_query' => [
            [
                'key' => '_wp_attached_file',
                'value' => $logo_filename,
                'compare' => 'LIKE'
            ]
        ]
    ]);
    
    if (!empty($existing_attachment)) {
        // Use existing attachment
        $attach_id = $existing_attachment[0]->ID;
        error_log('WPConvert: Using existing logo attachment ID ' . $attach_id);
    } else {
        // Copy and create new attachment
        if (copy($logo_path, $destination)) {
            $filetype = wp_check_filetype($logo_filename);
            $attachment = array(
                'guid'           => $upload_dir['url'] . '/' . $logo_filename,
                'post_mime_type' => $filetype['type'],
                'post_title'     => $logo_info['alt'] ?: 'Site Logo',
                'post_content'   => '',
                'post_status'    => 'inherit'
            );
            
            $attach_id = wp_insert_attachment($attachment, $destination);
            $attach_data = wp_generate_attachment_metadata($attach_id, $destination);
            wp_update_attachment_metadata($attach_id, $attach_data);
            
            error_log('WPConvert: Created new logo attachment ID ' . $attach_id);
        } else {
            error_log('WPConvert: Failed to copy logo file to uploads directory');
            update_option('wpconvert_logo_setup', 1);
            return;
        }
    }
    
    // Set as custom logo
    if ($attach_id) {
        set_theme_mod('custom_logo', $attach_id);
        error_log('WPConvert: Custom logo set successfully (ID: ' . $attach_id . ')');
    }
    
    update_option('wpconvert_logo_setup', 1);
}
add_action('after_switch_theme', 'wpconvert_setup_custom_logo');

// Import all media files (images and videos) to WordPress Media Library.
//
// TIME-BOUNDED AND RESUMABLE. Thumbnail generation is the expensive part:
// wp_generate_attachment_metadata() resizes each file into every registered
// image size, so a 152-image conversion is roughly 760 resizes in one request
// (measured at 36s inside WordPress Playground). Running that to completion
// inline breaks two things:
//
//   1. It blocks theme activation. A Playground preview is waiting on that
//      request, and Playground's service worker times it out — the customer
//      sees a browser error page instead of their site.
//   2. On a host with the default 30s max_execution_time the request is killed
//      BEFORE the completion flag at the tail is written. Nothing records that
//      the import got most of the way, so the next request starts over from
//      file zero, dies again, and the site never finishes activating.
//
// So: spend a small budget, remember how far we got, continue on the next
// admin request. Front-end visitors never pay for this.
function wpconvert_media_import_budget_seconds() {
    $limit = (int) ini_get('max_execution_time');
    // 0 means "no limit" (CLI, and WordPress Playground). That is not a licence
    // to block activation for a minute — bound it anyway.
    if ($limit <= 0) {
        return 5;
    }
    // Leave most of the request's allowance for everything else on the hook.
    return max(2, min(10, (int) floor($limit / 3)));
}

// The ordered work queue: images first, then videos.
//
// Order must be STABLE across requests, or a resume cursor recorded by one
// request would point at a different file in the next one and silently skip
// media. glob() order is not guaranteed, hence the explicit sort.
function wpconvert_media_import_queue() {
    $queue = [];

    $images_dir = get_template_directory() . '/assets/images/';
    if (is_dir($images_dir)) {
        // Multiple glob calls instead of GLOB_BRACE for cross-platform
        // compatibility (GLOB_BRACE is unavailable on Windows and on some PHP
        // builds, including WordPress Playground).
        foreach (['jpg', 'jpeg', 'png', 'gif', 'svg', 'webp', 'ico'] as $ext) {
            $found = glob($images_dir . '*.' . $ext) ?: [];
            sort($found);
            $queue = array_merge($queue, $found);
        }
    }

    $videos_dir = get_template_directory() . '/assets/videos/';
    if (is_dir($videos_dir)) {
        foreach (['mp4', 'webm', 'mov', 'ogg', 'avi'] as $ext) {
            $found = glob($videos_dir . '*.' . $ext) ?: [];
            sort($found);
            $queue = array_merge($queue, $found);
        }
    }

    return $queue;
}

// Import a single file. Returns true when a new attachment was created.
function wpconvert_import_one_media_file($source_path, $upload_dir) {
    $filename = basename($source_path);

    // Already in the media library — guards repeat activations.
    $existing = get_posts([
        'post_type' => 'attachment',
        'meta_query' => [
            [
                'key' => '_wp_attached_file',
                'value' => $filename,
                'compare' => 'LIKE'
            ]
        ]
    ]);
    if (!empty($existing)) {
        return false;
    }

    $destination = $upload_dir['path'] . '/' . $filename;
    if (!copy($source_path, $destination)) {
        return false;
    }

    $filetype = wp_check_filetype($filename);
    $attachment = [
        'guid'           => $upload_dir['url'] . '/' . $filename,
        'post_mime_type' => $filetype['type'],
        'post_title'     => sanitize_file_name(pathinfo($filename, PATHINFO_FILENAME)),
        'post_content'   => '',
        'post_status'    => 'inherit'
    ];

    $attach_id = wp_insert_attachment($attachment, $destination);
    if (!$attach_id || is_wp_error($attach_id)) {
        return false;
    }

    $attach_data = wp_generate_attachment_metadata($attach_id, $destination);
    wp_update_attachment_metadata($attach_id, $attach_data);
    return true;
}

function wpconvert_import_media_files() {
    // Guard with option to prevent duplicates
    if (get_option('wpconvert_media_imported')) {
        return;
    }

    // Require WordPress media functions
    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/media.php');
    require_once(ABSPATH . 'wp-admin/includes/image.php');

    $queue = wpconvert_media_import_queue();
    $total = count($queue);
    if ($total === 0) {
        update_option('wpconvert_media_imported', 1);
        return;
    }

    $cursor = (int) get_option('wpconvert_media_import_cursor', 0);
    // A cursor past the end means the asset folder shrank since the last pass;
    // starting over is correct and the per-file check makes it cheap.
    if ($cursor < 0 || $cursor >= $total) {
        $cursor = 0;
    }

    if ($cursor === 0) {
        error_log('WPConvert: Starting media import...');
    }

    $started    = microtime(true);
    $budget     = wpconvert_media_import_budget_seconds();
    $upload_dir = wp_upload_dir();
    $imported   = 0;

    for ($i = $cursor; $i < $total; $i++) {
        // Checked BEFORE the work so the budget is never overshot by a whole
        // thumbnail generation. Always process at least one file per pass, or
        // a budget smaller than a single file would never make progress.
        if ($i > $cursor && (microtime(true) - $started) >= $budget) {
            update_option('wpconvert_media_import_cursor', $i);
            error_log("WPConvert: Media import paused at $i of $total (time budget) - resumes on the next admin request");
            return;
        }

        if (wpconvert_import_one_media_file($queue[$i], $upload_dir)) {
            $imported++;
        }
    }

    update_option('wpconvert_media_imported', 1);
    delete_option('wpconvert_media_import_cursor');
    error_log("WPConvert: Media import completed - $imported new of $total file(s)");
}
add_action('after_switch_theme', 'wpconvert_import_media_files');
// Resume an import that ran out of its time budget during activation. On
// admin_init only: a front-end visitor must never pay for thumbnail generation,
// and the admin is the only person who can see the Media Library anyway.
add_action('admin_init', 'wpconvert_import_media_files');

// Clear cached setup flags on theme activation so re-imports can run
// when theme files change. Hash-based guards on admin_init detect actual
// file changes; these boolean flags are secondary protection only.
function wpconvert_clear_menu_cache() {
    // EC-THEME-001: Do NOT delete wpconvert_spa_pages_created or
    // wpconvert_menu_created — they must persist so the after_switch_theme
    // handlers do not unconditionally rebuild on every activation cycle.
    // Actual file changes are detected by hash-based admin_init hooks
    // (wpconvert_ensure_missing_pages / wpconvert_ensure_menus_current).
    delete_option('wpconvert_logo_setup');
    delete_option('wpconvert_media_imported');
    // Must go with the flag above. A stale cursor left behind would make the
    // re-import resume from the middle and silently skip everything before it.
    delete_option('wpconvert_media_import_cursor');
    wp_cache_flush();
}
add_action('after_switch_theme', 'wpconvert_clear_menu_cache');

// Enqueue scripts and styles
function wpconvert_enqueue_assets() {
    // EC-PHP-014: Basenames of local JS/CSS that are statically enqueued below
    // via the scripts.external / styles.external loops. The EC-PHP-006 runtime
    // auto-discovery loops consult these arrays so the same file is not
    // registered twice under different handles. WordPress de-duplicates by
    // handle (not by URL), so two different handles for the same file produce
    // two identical script/link tags. For main.js this caused a SyntaxError on
    // the second copy due to top-level "const" redeclaration; for style.css the
    // second copy won the cascade and silenced the EC-NAV-188/EC-NAV-086/
    // EC-HERO-DECOR-001 compensation rules.
    $skip_already_enqueued_js = array('main.js', 'components.js');
    $skip_already_enqueued_css = array();

    // Enqueue jQuery (required for accordion and interactive functionality)
    wp_enqueue_script('jquery');
    
    // EC-JQ-001: WordPress jQuery runs in noConflict() mode; legacy HTML-template
    // scripts (Visanet lang.js, etc.) call `$` at top level. Expose the alias once.
    wp_add_inline_script('jquery', 'window.$ = window.jQuery;', 'after');
    
    
    // Enqueue sticky navigation JS if detected during conversion
    $sticky_nav_js = get_template_directory() . '/assets/js/sticky-nav.js';
    if (file_exists($sticky_nav_js)) {
        wp_enqueue_script(
            'wpconvert-sticky-nav',
            get_template_directory_uri() . '/assets/js/sticky-nav.js',
            array('jquery'),
            '2.0.0',
            true
        );
    }
    
    // EC-FILTER-001: Enqueue content filter/search JS if detected during conversion
    $content_filter_js = get_template_directory() . '/assets/js/wpconvert-content-filter.js';
    if (file_exists($content_filter_js)) {
        wp_enqueue_script(
            'wpconvert-content-filter',
            get_template_directory_uri() . '/assets/js/wpconvert-content-filter.js',
            array(),
            '2.0.0',
            true
        );
    }
    
    // EC-BLOG-026: Enqueue blog filter JS for client-side category filtering
    $blog_filter_js = get_template_directory() . '/assets/js/blog-filter.js';
    if (file_exists($blog_filter_js)) {
        wp_enqueue_script(
            'wpconvert-blog-filter',
            get_template_directory_uri() . '/assets/js/blog-filter.js',
            array(),
            '2.0.0',
            true
        );
    }
    
    // EC-HERO-CAROUSEL-008: Stacked-opacity hero carousel (data-wpc-carousel) — inline scripts are stripped from templates
    $hero_carousel_js = get_template_directory() . '/assets/js/wpconvert-hero-carousel.js';
    if (file_exists($hero_carousel_js)) {
        wp_enqueue_script(
            'wpconvert-hero-carousel',
            get_template_directory_uri() . '/assets/js/wpconvert-hero-carousel.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-CAROUSEL-022: Static-grid carousel runtime (data-wpconvert-static-carousel)
    // — wires prev/next arrows whose React source left them without onClick handlers.
    $static_grid_carousel_js = get_template_directory() . '/assets/js/wpconvert-static-grid-carousel.js';
    if (file_exists($static_grid_carousel_js)) {
        wp_enqueue_script(
            'wpconvert-static-grid-carousel',
            get_template_directory_uri() . '/assets/js/wpconvert-static-grid-carousel.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-CAROUSEL-030: Data-driven testimonial slider runtime (data-wpc-testimonial-slider)
    // — cycles the materialized testimonial slides and wires arrows/dots for
    // dc-runtime exports that rendered a single card + inline data array.
    $testimonial_slider_js = get_template_directory() . '/assets/js/wpconvert-testimonial-slider.js';
    if (file_exists($testimonial_slider_js)) {
        wp_enqueue_script(
            'wpconvert-testimonial-slider',
            get_template_directory_uri() . '/assets/js/wpconvert-testimonial-slider.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-GALLERY-001: Product-image gallery runtime (data-wpconvert-gallery)
    // — re-wires thumbnail buttons whose React setActive onClick was lost in
    // the static snapshot so clicking a thumbnail swaps the main product image.
    $product_gallery_js = get_template_directory() . '/assets/js/wpconvert-product-gallery.js';
    if (file_exists($product_gallery_js)) {
        wp_enqueue_script(
            'wpconvert-product-gallery',
            get_template_directory_uri() . '/assets/js/wpconvert-product-gallery.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-SWIPER-002: Themento (Elementor) data-swiper slider FALLBACK runtime.
    // Elementor's frontend webpack bundle loses its dependency order during
    // conversion so the site's own inc.js slider handler (fired from
    // elementor/frontend/init) never runs — the hero/post carousels are dead.
    // This standalone runtime re-inits any [data-swiper] container the site left
    // dead (inert if none exist / Swiper is absent / already initialized).
    $swiper_init_js = get_template_directory() . '/assets/js/wpconvert-swiper-init.js';
    if (file_exists($swiper_init_js)) {
        wp_enqueue_script(
            'wpconvert-swiper-init',
            get_template_directory_uri() . '/assets/js/wpconvert-swiper-init.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-SCRUB-001: Apple-style scroll-scrub frame-sequence hero runtime. The
    // source <canvas> was frozen to a single PNG at capture; this re-drives the
    // exported frame sequence on scroll (inert unless a page carries a
    // [data-wpconvert-scroll-scrub] stage; the frozen <img> stays as fallback).
    $scroll_scrub_js = get_template_directory() . '/assets/js/wpconvert-scroll-scrub.js';
    if (file_exists($scroll_scrub_js)) {
        wp_enqueue_script(
            'wpconvert-scroll-scrub',
            get_template_directory_uri() . '/assets/js/wpconvert-scroll-scrub.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-SCRUB-006: sticky scrollytelling replay. The capture pass baked each state of
    // the stage into the markup; this picks one by scroll progress (inert unless a page
    // carries a [data-wpc-scroll-story] spacer).
    $scroll_story_js = get_template_directory() . '/assets/js/wpconvert-scroll-story.js';
    if (file_exists($scroll_story_js)) {
        wp_enqueue_script(
            'wpconvert-scroll-story',
            get_template_directory_uri() . '/assets/js/wpconvert-scroll-story.js',
            array(),
            '1.0.0',
            true
        );
    }

    // EC-PARALLAX-001: generic parallax runtime — re-drives translateY-on-scroll
    // layers and background-attachment:fixed layers frozen at capture (inert
    // unless a page carries a stamped [data-wpconvert-parallax-y|-bg] element;
    // provides a background-position fallback on touch/small screens).
    $parallax_js = get_template_directory() . '/assets/js/wpconvert-parallax.js';
    if (file_exists($parallax_js)) {
        wp_enqueue_script(
            'wpconvert-parallax',
            get_template_directory_uri() . '/assets/js/wpconvert-parallax.js',
            array(),
            '2.0.0',
            true
        );
    }

    // EC-WEBGL-001: live-WebGL capsule runtime — lazy-loads a sandboxed iframe
    // running the original Three.js/WebGL scene and swaps out the poster when it
    // signals ready (inert unless a page carries a .wpconvert-webgl element;
    // honors prefers-reduced-motion / Save-Data / no-WebGL by keeping the poster).
    $webgl_js = get_template_directory() . '/assets/js/wpconvert-webgl.js';
    if (file_exists($webgl_js)) {
        wp_enqueue_script(
            'wpconvert-webgl',
            get_template_directory_uri() . '/assets/js/wpconvert-webgl.js',
            array(),
            '2.0.0',
            true
        );
    }
    
    // Enqueue main stylesheet with high priority to override WordPress defaults
    // Use priority 999 to ensure it loads after WordPress default styles
    // filemtime() cache-busts so edits to style.css are picked up without a hard refresh
    wp_enqueue_style('wpconvert-style', get_stylesheet_uri(), array(), filemtime(get_stylesheet_directory() . '/style.css'));
    
    // NOTE: Do NOT add inline font-family override - it breaks custom fonts (Google Fonts, etc.)
    // Custom fonts are loaded via @import in style.css and/or wp_enqueue_style for external fonts
    
    // Enqueue additional CSS files from assets/css (for static sites and Vite projects)
    $css_dir = get_template_directory() . '/assets/css';
    if (is_dir($css_dir)) {
        $css_files = glob($css_dir . '/*.css');
        foreach ($css_files as $css_file) {
            $file_name = basename($css_file);

            // EC-PHP-014: Skip files already statically enqueued via the
            // styles.external loop emitted below. Without this guard, both
            // loops register the same file under different handles and the
            // browser receives two identical <link> tags — the second wins
            // the cascade and silently overrides earlier compensation rules.
            if (in_array($file_name, $skip_already_enqueued_css, true)) continue;

            // EC-RTL-001: Direction-variant (RTL) stylesheets (e.g. *-rtl.css)
            // define body{direction:rtl} and must only load under an RTL
            // locale. WordPress runs LTR by default (is_rtl() === false), so on
            // LTR sites these are skipped — matching the original which links
            // them only on its separate *-rtl.html page. RTL locales still load
            // them, preserving right-to-left support.
            if (preg_match('/(?:^|[-_.])rtl(?:[-_.]|$)/i', $file_name) && !is_rtl()) {
                continue;
            }

            // CRITICAL: For URL conversions, assets/css/style.css contains the main site CSS
            // We MUST enqueue it separately from the theme's root style.css
            if ($file_name === 'style.css') {
                wp_enqueue_style(
                    'wpconvert-site-styles',
                    get_template_directory_uri() . '/assets/css/style.css',
                    array('wpconvert-style'), // Load after theme stylesheet
                    filemtime($css_file)
                );
                continue;
            }

            wp_enqueue_style(
                'wpconvert-asset-' . sanitize_title($file_name),
                get_template_directory_uri() . '/assets/css/' . $file_name,
                array('wpconvert-style'), // Load after main stylesheet
                filemtime($css_file)
            );
        }
    }
    
    // EC-PHP-006: Auto-enqueue JS files from assets/js/ (for PHP sites and static sites
    // whose external scripts were copied to assets/js/ but may not be in scripts.external)
    $js_dir = get_template_directory() . '/assets/js';
    if (is_dir($js_dir)) {
        $js_files = glob($js_dir . '/*.js');
        $skip_js = array('sticky-nav.js', 'wpconvert-content-filter.js', 'wpconvert-hero-carousel.js', 'wpconvert-static-grid-carousel.js', 'wpconvert-testimonial-slider.js', 'wpconvert-product-gallery.js', 'wpconvert-swiper-init.js', 'wpconvert-scroll-scrub.js', 'wpconvert-parallax.js', 'wpconvert-webgl.js');
        // EC-PHP-014: Merge in the basenames already statically enqueued so we
        // do not register them twice under different handles.
        $skip_js = array_unique(array_merge($skip_js, $skip_already_enqueued_js));
        foreach ($js_files as $js_file) {
            $file_name = basename($js_file);
            if (in_array($file_name, $skip_js, true)) continue;
            if (preg_match('/^jquery[\.\_\-]min\.js$/i', $file_name)) continue;
            
            // EC-JS-001: Skip SPA framework JS that would hydrate/wipe the DOM
            if (preg_match('/^(webpack|framework|main-app|main|polyfills|layout|_app|_error|_document|vendor|runtime)-[a-z0-9]+\.js$/i', $file_name)) continue;
            if (preg_match('/^(page|chunk|index)-[a-z0-9_-]+\.js$/i', $file_name)) continue;
            if (preg_match('/^[a-f0-9]{6,}-[a-f0-9]+\.js$/i', $file_name)) continue;
            if (preg_match('/^\d+-[a-z0-9]+\.js$/i', $file_name)) continue;
            if (preg_match('/^\d+\.js$/', $file_name)) continue;
            if (preg_match('/manifest\.js$/i', $file_name)) continue;
            if (in_array($file_name, array('_app.js','_error.js','_document.js','page.js','webpack-runtime.js','route.js'))) continue;
            
            // EC-PHP-006b: Load auto-discovered site scripts in the FOOTER. Static
            // sites place interaction scripts at the end of body and many are
            // IIFEs with no DOMContentLoaded guard (e.g. rooms.js calls
            // getElementById(...).addEventListener(...) at top level). Enqueuing
            // them in the head ran them before the markup existed, so the null
            // refs threw and the interactive map / tab toggles silently died.
            wp_enqueue_script(
                'wpconvert-asset-' . sanitize_title($file_name),
                get_template_directory_uri() . '/assets/js/' . $file_name,
                array('jquery'),
                '2.0.0',
                true
            );
        }
    }
    
    // Enqueue external stylesheets (CDN and local - includes head styles merged earlier)
    
    
    // Enqueue external scripts (filter out analytics - includes head scripts merged earlier)
    // NOTE: Commerce scripts are preserved and will be enqueued here
    // EC-JS-001: Also filter out SPA framework scripts (Next.js chunks, webpack, React)
    // EC-PHP-020: local script main.js
    $wpconvert_local_0_js = get_template_directory() . '/assets/js/main.js';
    if (file_exists($wpconvert_local_0_js)) {
        wp_enqueue_script('wpconvert-local-0', get_template_directory_uri() . '/assets/js/main.js', array('jquery'), '2.0.0', true);
    }
    // EC-PHP-020: local script components.js
    $wpconvert_local_1_js = get_template_directory() . '/assets/js/components.js';
    if (file_exists($wpconvert_local_1_js)) {
        wp_enqueue_script('wpconvert-local-1', get_template_directory_uri() . '/assets/js/components.js', array('jquery'), '2.0.0', true);
    }
    
    // CRITICAL: Attach Tailwind config to Tailwind CDN script (extracted during theme generation)
    // No Tailwind CDN detected
    
    // CRITICAL: Prevent React from trying to hydrate in WordPress (causes error #299)
    // Run this BEFORE any React scripts load
    wp_add_inline_script('jquery', <<<'REACT_PREVENT_JS'
        // Prevent React createRoot/hydrateRoot from executing if root element doesn't exist
        (function() {
            if (typeof window !== "undefined") {
                // Intercept createRoot calls before React loads
                var originalCreateRoot = null;
                var originalHydrateRoot = null;
                
                // Override when React loads
                Object.defineProperty(window, 'React', {
                    set: function(value) {
                        if (value && value.createRoot) {
                            originalCreateRoot = value.createRoot;
                            value.createRoot = function(container) {
                                if (!container || !document.contains(container)) {
                                    console.warn("[WPConvert] React createRoot prevented - container not found");
                                    return { render: function() {}, unmount: function() {} };
                                }
                                return originalCreateRoot.call(this, container);
                            };
                        }
                        this._react = value;
                    },
                    get: function() {
                        return this._react;
                    }
                });
                
                Object.defineProperty(window, 'ReactDOM', {
                    set: function(value) {
                        if (value) {
                            if (value.createRoot) {
                                originalCreateRoot = value.createRoot;
                                value.createRoot = function(container) {
                                    if (!container || !document.contains(container)) {
                                        console.warn("[WPConvert] ReactDOM createRoot prevented");
                                        return { render: function() {}, unmount: function() {} };
                                    }
                                    return originalCreateRoot.call(this, container);
                                };
                            }
                            if (value.hydrateRoot) {
                                originalHydrateRoot = value.hydrateRoot;
                                value.hydrateRoot = function(container) {
                                    if (!container || !document.contains(container)) {
                                        console.warn("[WPConvert] ReactDOM hydrateRoot prevented");
                                        return { render: function() {}, unmount: function() {} };
                                    }
                                    return originalHydrateRoot.call(this, container);
                                };
                            }
                        }
                        this._reactDOM = value;
                    },
                    get: function() {
                        return this._reactDOM;
                    }
                });
            }
        })();
REACT_PREVENT_JS
    , 'before');
    
    // No safe inline scripts to enqueue
    
    // EC-JS-URI-001: The inline jQuery block below is emitted via a single-quoted
    // heredoc (nowdoc), so PHP never runs inside it. Expose runtime URLs through
    // wp_localize_script instead of embedding PHP echo tags (which would leak
    // verbatim into the page and break nav-injection / routes / search fetches).
    wp_localize_script('jquery', 'wpConvertThemeData', array(
        'templateUri' => get_template_directory_uri(),
        'homeUrl'     => home_url(),
    ));

    // Add smooth scrolling and accordion functionality
    wp_add_inline_script('jquery', <<<'WPCONVERT_JS'
        jQuery(document).ready(function($) {
            try { // EC-LINK-002: external links open in a new tab
            function addTargetBlank(link) {
                var href = (link && link.getAttribute ? link.getAttribute('href') : '') || '';
                href = String(href).trim();
                if (!href || href === '#' || /^javascript:/i.test(href) || /^mailto:/i.test(href) || /^tel:/i.test(href)) return;
                try {
                    var url = new URL(href, window.location.href);
                    if (url.protocol !== 'http:' && url.protocol !== 'https:') return;
                    if (!url.hostname) return;
                    if (url.origin !== window.location.origin) {
                        link.setAttribute('target', '_blank');
                        if (!link.getAttribute('rel')) link.setAttribute('rel', 'noopener noreferrer');
                    }
                } catch (e) { /* skip invalid href */ }
            }
            function addTargetBlankToExternalLinks() {
                document.querySelectorAll('a[href]').forEach(addTargetBlank);
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', addTargetBlankToExternalLinks);
            } else {
                addTargetBlankToExternalLinks();
            }
            } catch(e) { console.warn("[WPConvert] External link target error:", e.message); }
            // EC-TESTIMONIAL-004b: Shared by universal carousel + EC-CAROUSEL-002 — skip only inner JSON testimonial card
            function wpcInsideJsonTestimonialCard($el) {
                var $tsec = $el.closest("[data-wpconvert-testimonials]");
                if (!$tsec.length) return false;
                var $ariaPrev = $tsec.find('button[aria-label*="Prev"], button[aria-label*="Previous"], button[aria-label*="previous"]').first();
                if (!$ariaPrev.length) return true;
                var $innerCard = $ariaPrev.closest('[class*="rounded-3xl"],[class*="rounded-2xl"],[class*="rounded-xl"]').first();
                if (!$innerCard.length) return true;
                return $el.closest($innerCard).length > 0;
            }
            try { // [WPConvert: Smooth Scrolling]
            // Smooth scrolling for anchor links
            // EC-EDITOR-005: Skip when WPConvert editor is active to avoid scroll conflict
            $('a[href^="#"]').on("click", function(e) {
                if (window.location.search.indexOf("wpc_edit=1") !== -1) return;
                // EC-NAV-286: Never hijack Bootstrap/Mobirise interactive control anchors.
                // This jQuery handler is the twin of the vanilla handleAnchorClick guarded by
                // EC-NAV-285 — both run on every a[href^="#"] click. Carousel/lightbox prev-next
                // controls (<a class="carousel-control-next" data-bs-slide="next" href="#lb-xxxx">),
                // gallery thumbnails, and collapse/modal/tab/dropdown togglers point at hidden
                // targets that sit at offset top 0. Letting this handler preventDefault + animate
                // to $target.offset().top - 80 yanks the page to the top — and a gallery that
                // auto-advances via a synthetic click every few seconds makes it "keep scrolling
                // to the top". Skip these so Bootstrap/Mobirise own them; only real in-page nav
                // links smooth-scroll.
                if (this.matches && this.matches(
                    '.carousel-control, .carousel-control-next, .carousel-control-prev, ' +
                    '[data-bs-slide], [data-slide], [data-bs-slide-to], [data-slide-to], ' +
                    '[data-bs-toggle], [data-toggle], [data-bs-dismiss], [data-dismiss], ' +
                    '.dropdown-toggle, .navbar-toggler'
                )) {
                    return;
                }
                e.preventDefault();
                var target = $(this).attr("href");
                if (target === "#") return;
                
                var $target = $(target);
                if ($target.length) {
                    $("html, body").animate({
                        scrollTop: $target.offset().top - 80
                    }, 800);
                }
            });
            } catch(e) { console.warn("[WPConvert] Smooth scrolling error:", e); }
            
            try { // [WPConvert: Accordion/Collapsible]
            // Universal accordion/collapsible functionality
            // Works for Radix UI, Material UI, Bootstrap, Ant Design, custom accordions
            // CRITICAL: Only target actual trigger elements (buttons, summary) - NOT wrapper divs with data-state
            // Using [data-state] in selector caused double-firing because parent wrappers also have data-state
            // EC-ACCORDION-011: Also target h3[data-state] > a — Radix accordion triggers
            // that were converted from <button> to <a> during snapshot processing.
            $(document).on("click", "button[aria-controls], button[aria-expanded], h3[data-state] > button, h3[data-state] > a, .accordion-trigger, summary", function(e) {
                e.stopPropagation(); // Prevent event bubbling to parent wrappers
                
                var $trigger = $(this);
                
                // EC-ACCORDION-012: image-card CTA buttons (e.g. MenuCard "+ Tilføj")
                // are explicitly guarded — never treat them as accordion triggers.
                if ($trigger.attr("data-wpc-no-accordion-trigger") === "1") {
                    return;
                }
                
                // CRITICAL: Only handle actual trigger elements (button, summary, a inside accordion h3, or explicit accordion-trigger)
                if (!$trigger.is("button, summary, a") && !$trigger.hasClass("accordion-trigger")) {
                    console.log("Skipping non-trigger element:", $trigger.prop("tagName"));
                    return;
                }

                // EC-ACCORDION-016: Native <details>/<summary> rows are toggled by the
                // browser (the [open] attribute shows/hides the panel) and the icon is
                // owned by EC-ACCORDION-007 + the source CSS. If this universal handler
                // also ran it would grab the <summary>'s sibling answer panel, see it as
                // "visible" right after the native open, and take the HIDE branch below —
                // forcing max-height:0/opacity:0 so the answer disappears while the marker
                // still rotates to "×" (KaliHub: "only 1 FAQ has answers"). Let the
                // browser own native details entirely.
                if ($trigger.is("summary") && $trigger.closest("details").length) {
                    return;
                }
                
                // EC-ACCORDION-011: Track <a> accordion triggers — defer preventDefault
                // until we confirm a content panel exists. If no panel, let the link navigate.
                var isAccordionLink = $trigger.is("a") && $trigger.closest("h3[data-state]").length;
                
                // CRITICAL: Skip menu/hamburger buttons - these are handled separately
                var ariaLabel = ($trigger.attr("aria-label") || "").toLowerCase();
                if (ariaLabel.indexOf("menu") !== -1 || $trigger.hasClass("menu-toggle") || $trigger.hasClass("hamburger-menu")) {
                    console.log("Skipping accordion handler for menu button");
                    return; // Let the hamburger menu handler deal with this
                }

                // EC-NAV-411: the guard above is label-based, so a localized
                // hamburger label ("Meni", "Menü", "メニュー") slips through and this
                // handler grabs the EC-NAV-408 fullscreen overlay as its panel,
                // collapsing it to height:0 immediately after the inline onclick
                // opened it. The overlay owns its own open/close state.
                if ($trigger.attr("data-wpc-fs-toggle")) {
                    return;
                }

                // EC-NAV-284: Skip the native Bootstrap/Mobirise navbar toggler. It is a
                // <button class="navbar-toggler" data-bs-toggle="collapse" aria-expanded
                // ="false" aria-label="Toggle navigation"> — matched by the
                // button[aria-expanded] selector above — but its aria-label is "Toggle
                // navigation" (no "menu"), so the guard above misses it. Without this
                // skip, the universal accordion handler grabs the .navbar-collapse panel
                // and fights Bootstrap: the first tap flips the hamburger to an X but the
                // menu stays closed, the next tap opens it while showing the wrong icon
                // (the "needs two clicks / inverted icon" mobile bug). The native toggler
                // and .navbar-collapse are owned by Bootstrap + navbar-dropdown.js.
                if ($trigger.is('.navbar-toggler, [data-toggle="collapse"], [data-bs-toggle="collapse"]') ||
                    $trigger.closest('.navbar-toggler, .navbar-collapse').length) {
                    return;
                }

                var targetId = $trigger.attr("aria-controls");
                var triggerId = $trigger.attr("id");
                var $content = null;
                
                console.log("Accordion clicked, targetId:", targetId, "triggerId:", triggerId);
                
                // Method 1: aria-controls attribute points to content ID
                if (targetId) {
                    $content = $(document.getElementById(targetId));
                    if ($content.length) {
                        console.log("Found content via aria-controls");
                    }
                }
                
                // Method 2: Radix UI pattern - look for [role="region"] sibling with aria-labelledby matching trigger
                if ((!$content || !$content.length) && triggerId) {
                    var $radixContent = $trigger.siblings('[role="region"][aria-labelledby="' + triggerId + '"]');
                    if ($radixContent.length) {
                        $content = $radixContent;
                        console.log("Found content via Radix aria-labelledby");
                    }
                }
                
                // Method 3: Look for next sibling with [role="region"] or [data-state] (Radix pattern)
                if (!$content || !$content.length) {
                    var $radixSibling = $trigger.next('[role="region"], [data-state]');
                    if ($radixSibling.length) {
                        $content = $radixSibling;
                        console.log("Found content via Radix sibling role/data-state");
                    }
                }
                
                // Method 4: Look for next sibling element (FAQ-style accordions)
                // Common pattern: <button aria-expanded="false">Question</button><div style="max-height:0">Answer</div>
                if (!$content || !$content.length) {
                    var $nextSibling = $trigger.next('div, [class*="content"], [class*="panel"], [class*="answer"]');
                    if ($nextSibling.length) {
                        $content = $nextSibling;
                        console.log("Using sibling element as accordion content");
                    }
                }
                
                // Method 5: Content is inside a parent container, sibling of the trigger wrapper
                if (!$content || !$content.length) {
                    var $parent = $trigger.parent();
                    var $siblingContent = $parent.next('div, [role="region"], [class*="content"], [class*="panel"]');
                    if ($siblingContent.length) {
                        $content = $siblingContent;
                        console.log("Using parent sibling as accordion content");
                    }
                }
                
                // Method 6: Look within the accordion item container for content
                if (!$content || !$content.length) {
                    var $accordionItem = $trigger.closest('[data-state], [class*="accordion-item"], [class*="AccordionItem"]');
                    if ($accordionItem.length) {
                        var $itemContent = $accordionItem.find('[role="region"], [data-state="open"], [data-state="closed"], [class*="content"], [class*="panel"]').not($trigger);
                        if ($itemContent.length) {
                            $content = $itemContent.first();
                            console.log("Found content within accordion item container");
                        }
                    }
                }
                
                // Method 7: Global search for aria-labelledby matching trigger ID (Radix UI)
                if ((!$content || !$content.length) && triggerId) {
                    var $globalContent = $('[aria-labelledby="' + triggerId + '"]');
                    if ($globalContent.length) {
                        $content = $globalContent.first();
                        console.log("Found content via global aria-labelledby search");
                    }
                }
                
                // Method 8: Last resort - find any sibling div that has content
                if (!$content || !$content.length) {
                    var $anySibling = $trigger.siblings('div').filter(function() {
                        return $(this).text().trim().length > 20;
                    });
                    if ($anySibling.length) {
                        $content = $anySibling.first();
                        console.log("Found content via any sibling div with content");
                    }
                }
                
                if ($content && $content.length) {
                    // EC-ACCORDION-014: Grid-rows accordions are managed by the
                    // dedicated vanilla handler (wpconvert_accordion_enqueue),
                    // which owns single-open + opacity. Skip them here so the two
                    // handlers don't double-toggle (open then immediately close).
                    if ($content.is('[data-wpconvert-grid-accordion]')) {
                        return;
                    }

                    // EC-NAV-411: never treat the fullscreen menu overlay as a
                    // collapsible panel, whichever trigger resolved to it.
                    if ($content.is('[data-wpc-fs-menu], #wpconvert-fullscreen-menu')) {
                        return;
                    }

                    // EC-ACCORDION-011: Now that we confirmed a panel exists,
                    // prevent <a> link navigation so the accordion can toggle
                    if (isAccordionLink) e.preventDefault();
                    
                    // Also update data-state on the parent h3 trigger wrapper
                    var $h3 = $trigger.closest("h3[data-state]");
                    
                    // Detect if this accordion uses CSS max-height/opacity transitions
                    var usesMaxHeight = $content.css("max-height") !== undefined && $content.css("max-height") !== "none";
                    var currentMaxHeight = $content.css("max-height");
                    var currentHeight = $content.css("height");
                    var isHidden = $content.attr("hidden") !== undefined || 
                                   $content.css("display") === "none" ||
                                   (usesMaxHeight && (currentMaxHeight === "0px" || currentMaxHeight === "0")) ||
                                   (currentHeight === "0px" || currentHeight === "0");
                    
                    // EC-ACCORDION-022: aria-expanded on the trigger is the sole source of
                    // truth when present. Radix snapshots can leave role="region" panels
                    // at data-state="open" (with display:block) while the trigger still
                    // shows aria-expanded="false". Honouring panel data-state makes the
                    // handler think the panel is already visible → first click closes
                    // instead of opens (the "double-click to open" symptom).
                    var expandedAttr = $trigger.attr("aria-expanded");
                    if (expandedAttr === "false") {
                        isHidden = true;
                    } else if (expandedAttr === "true") {
                        isHidden = false;
                    } else {
                        // Legacy accordions without aria-expanded — fall back to panel state.
                        if ($content.attr("data-state") === "closed") {
                            isHidden = true;
                        } else if ($content.attr("data-state") === "open") {
                            isHidden = false;
                        }
                    }
                    
                    if (isHidden) {
                        // Show - handle both hidden attribute and CSS transitions
                        // CRITICAL: Remove ALL hiding first, then measure, then apply final styles
                        $content.removeAttr("hidden");
                        $content.removeAttr("aria-hidden");
                        
                        // CRITICAL: Must make element visible BEFORE measuring scrollHeight
                        // Otherwise scrollHeight will be 0 for display:none elements
                        $content.css({
                            "display": "block",
                            "visibility": "visible",
                            "opacity": "1",
                            "height": "auto",
                            "max-height": "none",
                            "overflow": "visible",
                            "animation": "none"
                        });
                        
                        // Now get scroll height (element is visible so this will work)
                        var scrollHeight = $content.prop("scrollHeight");
                        console.log("Accordion scrollHeight:", scrollHeight);
                        
                        // If scrollHeight is still 0, the content might be truly empty
                        // In that case, just leave it visible with auto height
                        if (scrollHeight === 0) {
                            console.log("Warning: scrollHeight is 0, content may be empty");
                        }
                        
                        $content.attr("data-state", "open");
                        $content.removeAttr("aria-hidden");
                        $trigger.attr("aria-expanded", "true");
                        $trigger.attr("data-state", "open");
                        if ($h3 && $h3.length) $h3.attr("data-state", "open");
                        
                        // Rotate chevron icon if present
                        $trigger.find('svg, .chevron, [class*="chevron"]').css("transform", "rotate(180deg)");
                        if ($h3 && $h3.length) $h3.find('svg').last().css("transform", "rotate(180deg)");
                        
                        console.log("Accordion expanded");
                    } else {
                        // Hide - handle both hidden attribute and CSS transitions
                        $content.css({
                            "max-height": "0px",
                            "height": "0px",
                            "opacity": "0",
                            "overflow": "hidden",
                            "display": "block",
                            "animation": "none"
                        });
                        
                        $content.attr("data-state", "closed");
                        $trigger.attr("aria-expanded", "false");
                        $trigger.attr("data-state", "closed");
                        if ($h3 && $h3.length) $h3.attr("data-state", "closed");
                        
                        // Reset chevron icon rotation
                        $trigger.find('svg, .chevron, [class*="chevron"]').css("transform", "rotate(0deg)");
                        if ($h3 && $h3.length) $h3.find('svg').last().css("transform", "rotate(0deg)");
                        
                        console.log("Accordion collapsed");
                    }
                } else {
                    console.warn("Content div not found for accordion trigger");
                }
            });
            
            // On page load, check for empty accordion content
            $("[aria-controls]").each(function() {
                var targetId = $(this).attr("aria-controls");
                if (targetId) {
                    var $content = $(document.getElementById(targetId));
                    if ($content.length && $content.html().trim() === "") {
                        console.warn("Empty accordion content detected for:", targetId);
                    }
                }
            });
            } catch(e) { console.warn("[WPConvert] Accordion error:", e); }
            
            try { // [WPConvert: CSS Max-Height Accordion] EC-FAQ-002b
            // Handles FAQ/accordion buttons that use CSS max-h-0/max-h-96 toggling
            // instead of aria attributes. These buttons have a sibling div with
            // Tailwind max-height + opacity transition classes.
            (function() {
                function isCssAccordionBtn(btn) {
                    var $btn = $(btn);
                    var $sib = $btn.next("div");
                    if (!$sib.length) return false;
                    var cls = " " + ($sib.attr("class") || "") + " ";
                    return (cls.indexOf("max-h-0") !== -1 || cls.indexOf("max-h-96") !== -1) && cls.indexOf("transition") !== -1;
                }
                
                $(document).on("click", "button", function(e) {
                    var btn = this;
                    // EC-ACCORDION-012: image-card CTA buttons are guarded.
                    if ($(btn).attr("data-wpc-no-accordion-trigger") === "1") return;
                    if (!isCssAccordionBtn(btn)) return;
                    
                    // Already handled by aria accordion handler
                    if ($(btn).attr("aria-controls") || $(btn).attr("aria-expanded")) return;
                    
                    e.preventDefault();
                    e.stopPropagation();
                    
                    var $btn = $(btn);
                    var $content = $btn.next("div");
                    var cls = $content.attr("class") || "";
                    var isOpen = cls.indexOf("max-h-96") !== -1 && cls.indexOf("max-h-0") === -1;
                    
                    // Close all siblings in the same container first (accordion behavior)
                    var $container = $btn.parent().parent();
                    $container.find("> div > button").each(function() {
                        if (this === btn) return;
                        var $otherContent = $(this).next("div");
                        var otherCls = $otherContent.attr("class") || "";
                        if (otherCls.indexOf("max-h-96") !== -1) {
                            $otherContent.attr("class", otherCls.replace(/max-h-96/g, "max-h-0").replace(/opacity-100/g, "opacity-0"));
                            // Reset icon rotation
                            $(this).find(".rotate-45").removeClass("rotate-45");
                            $(this).find(".bg-primary.text-white").removeClass("bg-primary text-white");
                            // Reset parent border
                            var $item = $(this).closest("div[class*='border']");
                            if ($item.length) {
                                var ic = $item.attr("class") || "";
                                $item.attr("class", ic.replace(/border-primary(?!\/)(?! shadow)/g, "border-primary/5").replace(/ shadow-md/g, ""));
                            }
                            // Reset question text style
                            var $qspan = $(this).find("span").first();
                            var qc = $qspan.attr("class") || "";
                            $qspan.attr("class", qc.replace(/text-primary font-bold/, "text-primary/70"));
                        }
                    });
                    
                    if (isOpen) {
                        // Close this item
                        $content.attr("class", cls.replace(/max-h-96/g, "max-h-0").replace(/opacity-100/g, "opacity-0"));
                        $btn.find(".rotate-45").removeClass("rotate-45");
                        $btn.find(".bg-primary.text-white").removeClass("bg-primary text-white");
                        var $parentItem = $btn.closest("div[class*='border']");
                        if ($parentItem.length) {
                            var pc = $parentItem.attr("class") || "";
                            $parentItem.attr("class", pc.replace(/border-primary(?!\/)(?! shadow)/g, "border-primary/5").replace(/ shadow-md/g, ""));
                        }
                        var $qs = $btn.find("span").first();
                        var qsc = $qs.attr("class") || "";
                        $qs.attr("class", qsc.replace(/text-primary font-bold/, "text-primary/70"));
                    } else {
                        // Open this item
                        $content.attr("class", cls.replace(/max-h-0/g, "max-h-96").replace(/opacity-0/g, "opacity-100"));
                        // Rotate plus icon to X
                        var $iconSpan = $btn.find("span").last();
                        if ($iconSpan.find("svg").length) {
                            $iconSpan.addClass("rotate-45 bg-primary text-white");
                        }
                        var $parentItem = $btn.closest("div[class*='border']");
                        if ($parentItem.length) {
                            var pc = $parentItem.attr("class") || "";
                            $parentItem.attr("class", pc.replace(/border-primary\/5/g, "border-primary") + " shadow-md");
                        }
                        var $qs = $btn.find("span").first();
                        var qsc = $qs.attr("class") || "";
                        $qs.attr("class", qsc.replace(/text-primary\/70/, "text-primary font-bold"));
                    }
                });
            })();
            } catch(e) { console.warn("[WPConvert] CSS accordion error:", e); }
            
            try { // [WPConvert: Pill Tab Group Toggle] EC-FAQ-002b
            // Handles pill-style tab button groups (rounded-full buttons in a flex container)
            // where one button is "active" (bg-primary text-white) and others are inactive.
            // Toggles active styling on click. Content filtering is separate (EC-FILTER-001).
            (function() {
                $("button.rounded-full, button[class*='rounded-full']").each(function() {
                    var $btn = $(this);
                    var $container = $btn.parent();
                    if ($container.data("wpc-pill-init")) return;
                    if ($container.closest("[data-wpc-bill-scope]").length) return; // EC-PRICING-TOGGLE-001: yield to injector
                    var $pills = $container.find("> button[class*='rounded-full']");
                    if ($pills.length < 3) return;
                    // Verify it's a pill group: check for flex container + buttons with similar sizing
                    var containerCls = $container.attr("class") || "";
                    if (containerCls.indexOf("flex") === -1) return;
                    $container.data("wpc-pill-init", true);
                    
                    // Find active and inactive class patterns
                    var activeBtn = null, inactiveBtn = null;
                    $pills.each(function() {
                        var cls = $(this).attr("class") || "";
                        if (cls.indexOf("bg-primary") !== -1 && cls.indexOf("text-white") !== -1 && cls.indexOf("text-white/") === -1) activeBtn = this;
                        else if (!inactiveBtn) inactiveBtn = this;
                    });
                    if (!activeBtn || !inactiveBtn) return;
                    
                    var activeCls = $(activeBtn).attr("class");
                    var inactiveCls = $(inactiveBtn).attr("class");
                    
                    $pills.on("click", function(e) {
                        e.preventDefault();
                        $pills.each(function() { $(this).attr("class", inactiveCls); });
                        $(this).attr("class", activeCls);
                        var cat = $(this).attr("data-wpconvert-faq-cat");
                        if (cat) {
                            var $faq = $("#faq");
                            if ($faq.length) {
                                $faq.find("[data-wpconvert-faq-panel]").each(function() {
                                    var on = ($(this).attr("data-wpconvert-faq-panel") || "") === cat;
                                    $(this).toggle(on);
                                });
                            }
                        }
                    });
                });
            })();
            } catch(e) { console.warn("[WPConvert] Pill tab error:", e); }
            
            try { // [WPConvert: Category/Filter Buttons]
            // EC-FILTER-001: Universal category/filter button functionality
            // Detects filter button groups near grids/lists and enables click-to-filter
            // Searches section, main, container, and generic wrapper elements
            (function() {
                var filterInitialized = {};

                function initFilter($btnGroup, $gridContainer, allowNoAll) {
                    var groupId = $btnGroup.get(0);
                    if (filterInitialized[groupId]) return;
                    if ($btnGroup.attr("data-wpc-filter-group")) return;
                    // EC-PRICING-TOGGLE-001: never treat the source-driven pricing
                    // toggle as a category filter (would hide pricing cards on click).
                    if ($btnGroup.find("[data-wpc-bill-set]").length || $btnGroup.closest("[data-wpc-bill-scope]").length) return;

                    var $filterButtons = $btnGroup.find("> button, > [role='button'], > a").filter(function() {
                        var t = $(this).text().trim();
                        return t.length > 0 && t.length < 30 && !/submit|send|cancel|close|search|login|sign/i.test(t);
                    });
                    // EC-FILTER-006: Allow 2+ buttons when explicitly permitted (tab-style groups)
                    if ($filterButtons.length < 2) return;
                    if ($filterButtons.length < 3 && !allowNoAll) return;

                    var hasAllBtn = false;
                    $filterButtons.each(function() {
                        var t = $(this).text().trim().toLowerCase();
                        // EC-FILTER-010: also match "all products", "all items", etc.
                        if (t === "all" || t === "view all" || t === "show all" || /^all\b/.test(t)) hasAllBtn = true;
                    });
                    // EC-FILTER-006: Skip "All" requirement when caller explicitly allows it
                    if (!hasAllBtn && !allowNoAll) return;

                    var $filterableItems = $gridContainer.find("[class*='card'], [class*='product'], [class*='item'], article");
                    if ($filterableItems.length === 0) {
                        $filterableItems = $gridContainer.children("a, div, article, li");
                    }
                    if ($filterableItems.length < 2) return;

                    filterInitialized[groupId] = true;
                    console.log("[WPConvert] Category filter detected:", $filterButtons.length, "buttons,", $filterableItems.length, "items");

