                        if ($item.find(".wpconvert-category-badge").length) return;
                        var $imgBox = $item.find("[class*='aspect-video']").first();
                        if (!$imgBox.length) $imgBox = $item.find("div.relative").filter(function() { return $(this).find("img").length > 0; }).first();
                        if (!$imgBox.length) $imgBox = $item.find("div").filter(function() { return $(this).find("img").length > 0; }).first();
                        if ($imgBox.length) {
                            if ($imgBox.css("position") !== "absolute" && $imgBox.css("position") !== "relative") $imgBox.css("position", "relative");
                            $imgBox.append('<div class="wpconvert-category-badge" style="position:absolute;top:1rem;right:1rem;padding:0.25rem 0.75rem;border-radius:9999px;font-size:0.75rem;font-weight:500;z-index:10;pointer-events:none;background:var(--primary,hsl(186 100% 50%));color:var(--primary-foreground,#000);opacity:0.9">' + $("<span>").text(cat).html() + "</div>");
                        }
                    });

                    function matchesCategory($item, filterText) {
                        var dataCat = ($item.attr("data-category") || $item.attr("data-filter") || $item.attr("data-type") || "").toLowerCase();
                        if (dataCat && dataCat === filterText) return true;
                        if (dataCat && dataCat.indexOf(filterText) !== -1) return true;

                        var fullText = $item.text().toLowerCase();
                        var imgAlts = [];
                        $item.find("img").each(function() { imgAlts.push(($(this).attr("alt") || "").toLowerCase()); });
                        var searchText = fullText + " " + imgAlts.join(" ") + " " + ($item.attr("href") || "").toLowerCase() + " " + ($item.attr("class") || "").toLowerCase();

                        if (searchText.indexOf(filterText) !== -1) return true;

                        var words = filterText.split(/\s+/).filter(function(w) { return w.length > 1; });
                        if (words.length > 1) {
