                            });
                            return;
                        }
                        // EC-FILTER-006: For tab-style groups without "All", if no grid items
                        // match ANY button text, treat buttons as content panel toggles instead
                        // of category filters (handled by pricing toggle / tab toggle below)

                        var visibleCount = 0;
                        $gridContainer.children().each(function() {
                            var $cell = $(this);
                            var $primary = $cell.is("[data-category]") ? $cell : $cell.find("[data-category]").first();
                            if (!$primary.length) $primary = $cell;
                            if (matchesCategory($primary, filterText)) {
                                $cell.css("display", "");
                                visibleCount++;
                            } else {
                                $cell.css("display", "none");
                            }
                        });
                        console.log("[WPConvert] Filtered to", filterText + ":", visibleCount, "items visible");
                    });
                }

                // Search broad set of containers (not just section)
                $("section, main, [role='main'], [class*='container'], [class*='wrapper'], [class*='content'], [class*='page']").each(function() {
                    var $root = $(this);

                    // Strategy 1: Find div with 3+ child buttons (one being "All") followed by a grid
                    $root.find("div, [class*='flex'], [class*='tabs'], [class*='button-group'], [class*='filter']").each(function() {
                        var $candidate = $(this);
                        var directBtns = $candidate.find("> button, > [role='button'], > a[class*='button']");
                        if (directBtns.length < 3) return;
                        var hasAll = false;
                        directBtns.each(function() {
                            var t = $(this).text().trim().toLowerCase();
                            // EC-FILTER-010: also match "all products", "all items", etc.
