                        });
                        if (!hasAll) return;

                        // Find the grid: next sibling, parent siblings, ancestors, or section-wide
                        var $grid = $candidate.nextAll("[class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.nextAll("div").find("[class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.parent().find("[class*='grid'], [class*='list']").not($candidate).first();
                        if (!$grid.length) $grid = $candidate.parent().nextAll("[class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.parent().parent().find("> [class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.closest("section, [class*='container'], [class*='wrapper']").find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
                        // EC-FILTER-010: cross-section — grid may be in the next sibling section
                        if (!$grid.length) {
                            var $sect = $candidate.closest("section");
                            if ($sect.length) $grid = $sect.next("section").find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
                        }
                        if (!$grid.length) $grid = $candidate.nextAll("div, ul").first();
                        if ($grid.length) initFilter($candidate, $grid);
                    });

                    // Strategy 2: Heading-based detection (original approach, broadened)
                    var $heading = $root.find("h1, h2, h3").first();
                    if (!$heading.length) return;
                    var $headingParent = $heading.parent();
                    var $btnGroup = $headingParent.next("div, [class*='flex']").filter(function() {
                        return $(this).find("> button, > [role='button']").length >= 3;
                    }).first();
                    if (!$btnGroup.length) {
                        $btnGroup = $headingParent.nextAll("div, [class*='flex']").filter(function() {
                            return $(this).find("> button, > [role='button']").length >= 3;
                        }).first();
                    }
                    if ($btnGroup.length) {
                        var $grid = $btnGroup.nextAll("[class*='grid'], [class*='list'], div").first();
                        if (!$grid.length) $grid = $btnGroup.parent().nextAll("[class*='grid']").first();
                        if (!$grid.length) $grid = $btnGroup.closest("section, [class*='container']").find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
                        if ($grid.length) initFilter($btnGroup, $grid);
