                        });
                        if (hasAll) return;
                        // Look for a nearby grid
                        var $grid = $candidate.nextAll("[class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.parent().find("[class*='grid']").not($candidate).first();
                        if (!$grid.length) $grid = $candidate.parent().nextAll("[class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.parent().parent().find("> [class*='grid']").first();
                        if (!$grid.length) $grid = $candidate.closest("section, [class*='container']").find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
