            } catch(e) { console.warn("[WPConvert] Category filter error:", e); }
            
            try { // [WPConvert: EC-PRICING-001 Pricing Toggle]
            // EC-PRICING-001: Universal pricing toggle (Monthly/Annual, Monthly/Yearly, etc.)
            // Handles Radix Switch (button[role="switch"]) and 2-button/label toggle patterns
            (function() {
                var periodRx = /monthly|annual|yearly|quarterly|weekly/i;
                function findPricingGrid($from) {
                    var $g = $from.nextAll("[class*='grid']").first();
                    if (!$g.length) $g = $from.parent().nextAll("[class*='grid']").first();
                    if (!$g.length) $g = $from.parent().parent().find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
                    if (!$g.length) $g = $from.closest("section").find("[class*='grid']").filter(function() { return $(this).children().length >= 2; }).first();
                    // EC-PRICING-002: Also search the NEXT sibling section.
                    // Common pattern: hero section has the toggle, separate pricing section has the grid.
                    if (!$g.length) {
                        var $sec = $from.closest("section");
                        if ($sec.length) {
                            $g = $sec.nextAll("section").first().find("[class*='grid']").filter(function() {
                                return $(this).children().length >= 2;
                            }).first();
                        }
                    }
                    return $g;
                }
                // Pattern A: Radix Switch — span(Monthly) + button[role=switch] + span(Annual)
                $('button[role="switch"]').each(function() {
                    var $sw = $(this);
                    if ($sw.data("pricing-wired")) return;
                    // EC-PRICING-TOGGLE-001: skip toggles already owned by the
                    // source-driven pricing injector (it handles prices + active
                    // styling). Double-handling here inverts the active button.
                    if ($sw.closest("[data-wpc-bill-scope]").length || $sw.find("[data-wpc-bill-set]").length) return;
                    var $parent = $sw.parent();
                    var kids = $parent.children();
                    var labels = [];
                    kids.each(function() {
                        var tag = (this.tagName || "").toLowerCase();
                        var txt = $(this).text().trim();
                        if ((tag === "span" || tag === "label" || tag === "p") && periodRx.test(txt)) {
                            labels.push({ el: $(this), text: txt.toLowerCase() });
                        }
                    });
                    if (labels.length < 2) return;
                    var $grid = findPricingGrid($parent);
                    if (!$grid.length) return;
                    $sw.data("pricing-wired", true);
                    var isAnnual = $sw.attr("data-state") === "checked" || $sw.attr("aria-checked") === "true";
                    // Read pricing data from section attribute if available
                    var pricingData = null;
                    var rawPD = $sw.closest("section, [class*='pricing']").attr("data-wpconvert-pricing");
                    // EC-PRICING-002: Also check the grid's parent section (toggle may be in hero,
                    // pricing data attribute on the pricing section)
                    if (!rawPD && $grid.length) rawPD = $grid.closest("section, [class*='pricing']").attr("data-wpconvert-pricing");
                    if (rawPD) try { pricingData = JSON.parse(rawPD); } catch(e) {}
                    // Find price elements in each card
                    var cardPrices = [];
                    $grid.children().each(function(ci) {
                        var $card = $(this);
                        var $priceEl = $card.find("span, div").filter(function() {
                            return /^\$[\d,]+/.test($(this).text().trim()) && $(this).children().length === 0;
                        }).first();
                        if (!$priceEl.length) $priceEl = $card.find("[class*='font-black'], [class*='font-extrabold']").filter(function() {
                            return /\$/.test($(this).text().trim());
                        }).first();
                        var monthly = null, annual = null;
                        if (pricingData && pricingData[ci]) {
                            monthly = pricingData[ci].monthly;
                            annual = pricingData[ci].annual;
                        }
                        cardPrices.push({ el: $priceEl, monthly: monthly, annual: annual });
                    });
                    // Toggle label styling
                    function updateLabels(ann) {
                        labels.forEach(function(l) {
                            var isMonthly = /month/i.test(l.text);
                            if ((isMonthly && !ann) || (!isMonthly && ann)) {
                                l.el.removeClass("text-slate-500 text-gray-500 text-muted").addClass("text-white");
                            } else {
                                l.el.removeClass("text-white").addClass("text-slate-500");
                            }
                        });
                    }
                    function updatePrices(ann) {
                        cardPrices.forEach(function(cp) {
                            if (!cp.el.length) return;
                            var price = ann ? cp.annual : cp.monthly;
                            if (price !== null) cp.el.text("$" + Number(price).toLocaleString());
                        });
                    }
                    $sw.on("click", function() {
                        isAnnual = !isAnnual;
                        var newState = isAnnual ? "checked" : "unchecked";
                        $sw.attr("data-state", newState).attr("aria-checked", String(isAnnual));
                        $sw.find("[data-state]").attr("data-state", newState);
                        updateLabels(isAnnual);
                        updatePrices(isAnnual);
                        console.log("[EC-PRICING-001] Switch toggled:", isAnnual ? "annual" : "monthly");
                    });
                    console.log("[EC-PRICING-001] Radix Switch pricing toggle initialized, cards:", cardPrices.length);
                });
                // Pattern B: Two buttons/labels with pricing period text (non-switch)
                $("section, [class*='pricing']").each(function() {
                    var $sec = $(this);
                    if ($sec.data("pricing-toggle-init")) return;
                    $sec.find("div").each(function() {
                        var $group = $(this);
                        // EC-PRICING-TOGGLE-001: yield to the source-driven pricing
                        // injector. It already wires these buttons (prices + active
                        // styling); the generic handler below mis-derives the active
                        // class set (treats btn[0] as active) and inverts the
                        // highlight, so skip any group it owns.
                        if ($group.find("[data-wpc-bill-set]").length || $group.closest("[data-wpc-bill-scope]").length) return;
                        var $btns = $group.find("> button, > [role='button'], > label, > a").filter(function() {
                            return periodRx.test($(this).text().trim());
                        });
                        if ($btns.length !== 2) return;
                        if ($btns.filter('[role="switch"]').length > 0) return;
                        var $grid = findPricingGrid($group);
                        if (!$grid.length) return;
                        $sec.data("pricing-toggle-init", true);
                        var pricingData = null;
                        var rawPD = $sec.attr("data-wpconvert-pricing");
                        if (rawPD) try { pricingData = JSON.parse(rawPD); } catch(e) {}
                        var cardPrices = [];
                        $grid.children().each(function(ci) {
                            var $card = $(this);
                            var $priceEl = $card.find("span, div").filter(function() {
                                return /^\$[\d,]+/.test($(this).text().trim()) && $(this).children().length === 0;
                            }).first();
                            var monthly = null, annual = null;
                            if (pricingData && pricingData[ci]) {
                                monthly = pricingData[ci].monthly;
                                annual = pricingData[ci].annual;
                            }
                            cardPrices.push({ el: $priceEl, monthly: monthly, annual: annual });
                        });
                        var fc = ($btns.eq(0).attr("class")||"").split(/\s+/);
                        var sc = ($btns.eq(1).attr("class")||"").split(/\s+/);
                        var ao = fc.filter(function(c){return sc.indexOf(c)===-1&&c;});
                        var io = sc.filter(function(c){return fc.indexOf(c)===-1&&c;});
                        $btns.on("click", function(e) {
                            e.preventDefault();
                            var idx = $btns.index($(this));
                            var ann = idx === 1;
                            $btns.each(function(bi) {
                                var $b = $(this);
                                if (bi === idx) { io.forEach(function(c){$b.removeClass(c);}); ao.forEach(function(c){$b.addClass(c);}); }
                                else { ao.forEach(function(c){$b.removeClass(c);}); io.forEach(function(c){$b.addClass(c);}); }
                            });
                            cardPrices.forEach(function(cp) {
                                if (!cp.el.length) return;
                                var price = ann ? cp.annual : cp.monthly;
                                if (price !== null) cp.el.text("$" + Number(price).toLocaleString());
                            });
                        });
                        console.log("[EC-PRICING-001] Button pricing toggle initialized");
                    });
                });
            })();
            } catch(e) { console.warn("[WPConvert] Pricing toggle error:", e); }
            
            try { // [WPConvert: EC-BLOG-030 Inline Blog Search]
            // EC-BLOG-030: Wire inline search inputs near post/card grids for client-side filtering
            // Covers static blog pages where search input exists but isn't connected to anything
            // EC-BLOG-030b: Skip inputs inside [data-wpconvert-form], skip <form> grids,
            // and use word boundaries for "post" so "Postcode" does not false-positive.
            (function() {
                var allInputs = $('input[type="text"], input[type="search"], input:not([type])').not('#wpconvert-search-input');
                allInputs.each(function() {
                    var $inp = $(this);
                    if ($inp.data("wpc-search-init")) return;
                    if ($inp.closest("[data-wpconvert-form]").length) return;
                    var ph = ($inp.attr("placeholder") || "").toLowerCase();
                    if (!/search|filter|find|blog|\bposts?\b|article/i.test(ph)) return;
                    // Find nearby card grid (skip <form> elements — they are real forms, not card grids)
                    var $section = $inp.closest("section, main, [class*='container']");
                    if (!$section.length) $section = $inp.parent().parent().parent();
                    var $grid = $section.find("[class*='grid']").filter(function() {
                        return $(this).children().length >= 2 && !$(this).is("form");
                    }).first();
                    if (!$grid.length) return;
                    var $cards = $grid.children();
                    if ($cards.length < 2) return;
