                    var hamburgerSvg = '<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-8 h-8"><line x1="4" x2="20" y1="12" y2="12"></line><line x1="4" x2="20" y1="6" y2="6"></line><line x1="4" x2="20" y1="18" y2="18"></line></svg>';
                    $btn.html(hamburgerSvg);
                }
                
                // Detect which side of the screen the hamburger button is on
                var $mobileNav = $("#wpconvert-mobile-nav");
                var btnRect = $btn[0].getBoundingClientRect();
                var windowWidth = $(window).width();
                var btnCenterX = btnRect.left + (btnRect.width / 2);
                
                // If button is in left half of screen, slide menu from left; otherwise from right
                if (btnCenterX < windowWidth / 2) {
                    $mobileNav.removeClass("slide-right").addClass("slide-left");
                    console.log("Hamburger on LEFT side - menu will slide from left");
                } else {
                    $mobileNav.removeClass("slide-left").addClass("slide-right");
                    console.log("Hamburger on RIGHT side - menu will slide from right");
                }
                
                // Make the button toggle a mobile navigation menu
                $btn.off("click.wpconvert").on("click.wpconvert", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    var isOpen = $btn.attr("aria-expanded") === "true";
                    
                    if (isOpen) {
                        // Close menu
                        $mobileNav.removeClass("open").addClass("closed");
                        $btn.attr("aria-expanded", "false");
                        $("body").removeClass("mobile-nav-open");
                    } else {
                        // Open menu
                        $mobileNav.removeClass("closed").addClass("open");
                        $btn.attr("aria-expanded", "true");
                        $("body").addClass("mobile-nav-open");
