            try { // [WPConvert: Search Modal]
            // UNIVERSAL SEARCH MODAL - works for any site with search icons
            // Handles search button clicks, Ctrl+K shortcut, and provides live search
            (function() {
                var $searchModal = $("#wpconvert-search-modal");
                var $searchInput = $("#wpconvert-search-input");
                var $searchResults = $("#wpconvert-search-results");
                var searchData = null;
                
                if (!$searchModal.length) return;
                
                // Load searchable pages from routes.json and menus.json
                function loadSearchData() {
                    if (searchData && searchData.length > 0) return Promise.resolve(searchData);
                    
                    searchData = [];
                    var promises = [];
                    
                    // Load routes.json (can be object or array)
                    promises.push(
                        $.getJSON(((window.wpConvertThemeData && wpConvertThemeData.templateUri) || "") + "/assets/data/routes.json")
                            .then(function(routes) {
                                if (routes) {
                                    // Handle both object format {"/path": {...}} and array format [{...}]
                                    if (Array.isArray(routes)) {
                                        routes.forEach(function(route) {
                                            if (route.path && route.title) {
                                                searchData.push({
                                                    title: route.title,
                                                    path: route.path || route.url,
                                                    keywords: (route.title + " " + (route.path || route.url || "")).toLowerCase()
                                                });
                                            }
                                        });
                                    } else if (typeof routes === "object") {
                                        // Object format: {"/path": {title, url, slug}}
                                        Object.keys(routes).forEach(function(path) {
                                            var route = routes[path];
                                            if (route && route.title && !path.includes(":")) { // Skip dynamic routes
                                                searchData.push({
                                                    title: route.title,
                                                    path: path,
                                                    keywords: (route.title + " " + path).toLowerCase()
                                                });
                                            }
                                        });
                                    }
                                }
                            })
                            .catch(function() { /* routes.json may not exist */ })
                    );
                    
                    // Also load menus.json
                    promises.push(
                        $.getJSON(((window.wpConvertThemeData && wpConvertThemeData.templateUri) || "") + "/assets/data/menus.json")
                            .then(function(menus) {
                                if (menus && menus.primary && menus.primary.items) {
                                    menus.primary.items.forEach(function(item) {
                                        if (item.url && !searchData.some(function(s) { return s.path === item.url; })) {
                                            searchData.push({
                                                title: item.title,
                                                path: item.url,
                                                keywords: item.title.toLowerCase()
                                            });
                                        }
                                        // Add children
                                        if (item.children && Array.isArray(item.children)) {
                                            item.children.forEach(function(child) {
                                                if (child.url && !searchData.some(function(s) { return s.path === child.url; })) {
                                                    searchData.push({
                                                        title: child.title,
                                                        path: child.url,
                                                        keywords: (child.title + " " + item.title).toLowerCase()
                                                    });
                                                }
                                            });
                                        }
                                    });
                                }
                                // Also check footer menu
                                if (menus && menus.footer && menus.footer.items) {
                                    menus.footer.items.forEach(function(item) {
                                        if (item.url && !searchData.some(function(s) { return s.path === item.url; })) {
                                            searchData.push({
                                                title: item.title,
                                                path: item.url,
                                                keywords: item.title.toLowerCase()
                                            });
                                        }
                                    });
                                }
                            })
                            .catch(function() { /* menus.json may not exist */ })
                    );
                    
                    return Promise.all(promises).then(function() {
                        console.log("WPConvert Search: Loaded " + searchData.length + " searchable pages");
                        return searchData;
                    });
                }
                
                function openSearch() {
                    $searchModal.addClass("open");
                    $searchInput.val("").focus();
                    $searchResults.empty();
                    $("body").css("overflow", "hidden");
                    loadSearchData();
                }
                
                function closeSearch() {
                    $searchModal.removeClass("open");
                    $("body").css("overflow", "");
                }
                
                function performSearch(query) {
                    if (!query || query.length < 1) {
                        $searchResults.empty();
                        return;
                    }
                    
                    loadSearchData().then(function(data) {
                        var q = query.toLowerCase();
                        var results = data.filter(function(item) {
                            return item.keywords.indexOf(q) !== -1 || 
                                   item.title.toLowerCase().indexOf(q) !== -1;
                        }).slice(0, 8);
                        
                        $searchResults.empty();
                        
                        if (results.length === 0) {
                            $searchResults.html('<div style="padding: 1rem; text-align: center; color: hsl(var(--muted-foreground));">No results found for "' + query + '"</div>');
                        } else {
                            results.forEach(function(item) {
                                var $result = $('<a class="wpconvert-search-result" href="' + (((window.wpConvertThemeData && wpConvertThemeData.homeUrl) || "")) + item.path + '"></a>');
                                $result.html('<div class="wpconvert-search-result-title">' + item.title + '</div><div class="wpconvert-search-result-url">' + item.path + '</div>');
                                $result.on("click", function() {
                                    closeSearch();
                                });
                                $searchResults.append($result);
                            });
                        }
                    });
                }
                
                // Expose global functions
                window.wpconvertOpenSearch = openSearch;
                window.wpconvertCloseSearch = closeSearch;
                
                // Bind close button and backdrop AFTER functions are defined
                $("#wpconvert-search-close").off("click.wpconvert").on("click.wpconvert", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    closeSearch();
                });
                
                $("#wpconvert-search-backdrop").off("click.wpconvert").on("click.wpconvert", function(e) {
                    e.preventDefault();
                    closeSearch();
                });
                
                // Handle search button clicks - find search buttons in HEADER/NAV only
                // EC-SEARCH-002: Restrict .lucide-search matching to header/nav context
                // to avoid false positives on content buttons (e.g. "SEO Optimization" tab
                // with a search icon triggers modal instead of filtering)
                var searchSelector = [
                    'header button[aria-label*="Search" i]',
                    'nav button[aria-label*="Search" i]',
                    'header button[aria-label*="search" i]',
                    'nav button[aria-label*="search" i]',
                    '[data-wpconvert-trigger][aria-label*="search" i]',
                    'header button:has(.lucide-search)',
                    'nav button:has(.lucide-search)',
                    '[class*="navbar"] button:has(.lucide-search)',
                    'header a[aria-label*="Search" i]',
                    'nav a[aria-label*="Search" i]'
                ].join(", ");
                
                $(searchSelector).off("click.wpconvert-search").on("click.wpconvert-search", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    openSearch();
                });
                
                // Keyboard shortcuts
                $(document).on("keydown.wpconvert-search", function(e) {
                    // Ctrl+K or Cmd+K to open
                    if ((e.ctrlKey || e.metaKey) && e.key === "k") {
                        e.preventDefault();
                        openSearch();
                    }
                    // Escape to close
                    if (e.key === "Escape" && $searchModal.hasClass("open")) {
                        closeSearch();
                    }
                });
                
                // Search input handler
                var searchTimeout;
                $searchInput.on("input", function() {
                    clearTimeout(searchTimeout);
                    var query = $(this).val();
                    searchTimeout = setTimeout(function() {
                        performSearch(query);
                    }, 150);
                });
                
                // Enter key on input navigates to first result
                $searchInput.on("keydown", function(e) {
                    if (e.key === "Enter") {
                        var $firstResult = $searchResults.find("a").first();
                        if ($firstResult.length) {
                            window.location.href = $firstResult.attr("href");
                        }
                    }
                });
                
                console.log("WPConvert Search Modal initialized");
            })();
            } catch(e) { console.warn("[WPConvert] Search modal error:", e); }
            
            try { // [WPConvert: Mobile Menu Toggle]
            // UNIVERSAL MOBILE MENU TOGGLE (for preserved mobile menus with data-wpc-* attributes)
            // This handles mobile menus that were preserved from the original site with wp_nav_menu() integration
            (function() {
                var toggles = document.querySelectorAll("[data-wpc-menu-toggle]");
                var panel = document.querySelector("[data-wpc-menu-panel]");
                var overlay = document.querySelector("[data-wpc-menu-overlay]");
                
                if (!toggles.length || !panel) return;
                
                console.log("WPC Mobile Menu: Found preserved mobile menu with data attributes");
                
                function openMenu() {
                    panel.classList.add("is-open");
                    if (overlay) overlay.classList.add("is-open");
                    document.body.classList.add("wpc-menu-open");
                    toggles.forEach(function(t) { t.setAttribute("aria-expanded", "true"); });
                }
                
                function closeMenu() {
                    panel.classList.remove("is-open");
                    if (overlay) overlay.classList.remove("is-open");
                    document.body.classList.remove("wpc-menu-open");
                    toggles.forEach(function(t) { t.setAttribute("aria-expanded", "false"); });
                }
                
                function toggleMenu() {
                    if (panel.classList.contains("is-open")) {
                        closeMenu();
                    } else {
                        openMenu();
                    }
                }
                
                // Toggle button click
                toggles.forEach(function(toggle) {
                    toggle.addEventListener("click", function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                        toggleMenu();
                    });
                });
                
                // Close on overlay click
                if (overlay) {
                    overlay.addEventListener("click", closeMenu);
                }
                
                // Close on ESC key
                document.addEventListener("keydown", function(e) {
                    if (e.key === "Escape" && panel.classList.contains("is-open")) {
                        closeMenu();
                    }
                });
                
                // Close on link click (important for mobile UX - menu closes after navigation)
                panel.querySelectorAll("a").forEach(function(link) {
                    link.addEventListener("click", function() {
                        // Small delay to allow navigation to start
                        setTimeout(closeMenu, 100);
                    });
                });
            })();
            } catch(e) { console.warn("[WPConvert] Mobile menu toggle error:", e); }
            
            try { // [WPConvert: URL Tab Switching]
            // URL-based tab switching (for services, contact pages with ?tab= parameter)
            // GENERIC: Works with any color scheme by detecting active/inactive classes dynamically
            var urlParams = new URLSearchParams(window.location.search);
            var activeTab = urlParams.get("tab");
            if (activeTab) {
                console.log("URL has tab parameter:", activeTab);
                
                // Find tab container (group of sibling buttons)
                var $tabGroups = $("button").parent().filter(function() {
                    return $(this).find("button").length >= 2;
                });
                
                $tabGroups.each(function() {
                    var $container = $(this);
                    var $buttons = $container.find("button");
                    
                    // Detect active/inactive classes from existing buttons
                    // First button is typically "active" by default, others are "inactive"
                    var $firstBtn = $buttons.first();
                    var $otherBtn = $buttons.eq(1);
                    
                    if ($firstBtn.length && $otherBtn.length) {
                        var activeClasses = $firstBtn.attr("class") || "";
                        var inactiveClasses = $otherBtn.attr("class") || "";
                        
                        // Find and activate the matching tab
                        $buttons.each(function() {
                            var $tabBtn = $(this);
                            var btnText = $tabBtn.text().toLowerCase().trim().replace(/\s+/g, "-");
                            var tabMatch = btnText.includes(activeTab.toLowerCase()) || 
                                           btnText.replace(/[^a-z0-9]/g, "").includes(activeTab.toLowerCase().replace(/[^a-z0-9]/g, "")) ||
                                           $tabBtn.attr("data-tab") === activeTab ||
                                           $tabBtn.attr("id") === "tab-" + activeTab;
                            
                            if (tabMatch) {
                                console.log("Found matching tab button:", btnText);
                                
                                // Swap classes: make all buttons inactive, then make matched one active
                                $buttons.attr("class", inactiveClasses);
                                $tabBtn.attr("class", activeClasses);
                                
                                // Trigger click for any JavaScript handlers
                                $tabBtn.trigger("click");
                            }
                        });
                    }
                });
            }
            } catch(e) { console.warn("[WPConvert] URL tab switching error:", e); }
            
            try { // [WPConvert: Universal Carousel]
            // Universal Carousel/Slider Functionality
            // Detects and enables carousels/sliders (testimonials, product sliders, etc.)
            
            // Helper function to initialize carousel behavior
            function initializeCarousel($carousel, $prevBtn, $nextBtn) {
                // EC-GALLERY-FLASH-001: Never carousel-ify a stacked gallery section.
                if ($carousel.closest("[data-wpconvert-stacked-gallery-section]").length ||
                    $carousel.find("[data-wpconvert-stacked-gallery]").length) {
                    return;
                }
                // EC-HERO-CAROUSEL-014: Never re-process the stacked-opacity hero
                // carousel already wired by wpconvert-hero-carousel.js. The universal
                // EC-CAROUSEL-002/003 handler matches the hero's prev/next arrows,
                // then showCurrentItems() .hide()s the slides' inner blocks — which
                // display:none's the title overlay (image shows, title vanishes) and
                // flashes the bg-zinc-950 container black. .closest() includes self,
                // so this covers both the hero container and any slide passed in.
                if ($carousel.closest("[data-wpc-carousel]").length ||
                    $carousel.find("[data-wpc-slide]").length) {
                    return;
                }
                // EC-CAROUSEL-029: Never touch Owl Carousel instances. Owl uses .item as
                // its slide class and an .owl-nav with prev/next buttons (or navText icons
                // like .icon-arrow-left/right), so both the prev/next discovery (Method 1)
                // and the [class*=carousel] scan (Method 2) match an owl carousel — then
                // showCurrentItems() runs $items.hide(), inline display:none on every
                // .item and collapsing the cards to 0px (section shows 1-2 cards, flashes,
                // or nothing). Owl fully owns slide visibility. [data-owl-options] is in the
                // source HTML regardless of init timing; the owl-* classes appear post-init.
                // .closest() includes self, so a passed-in container, slide, or wrapper is all
                // covered.
                if ($carousel.is("[data-owl-options], .owl-carousel, .owl-loaded") ||
                    $carousel.closest("[data-owl-options], .owl-carousel, .owl-loaded").length ||
                    $carousel.find("[data-owl-options], .owl-carousel, .owl-stage, .owl-stage-outer, .owl-loaded").length) {
                    return;
                }
                // EC-CAROUSEL-031: Never touch a Bootstrap carousel either. bootstrap.js
                // ships and is enqueued with these themes, so Bootstrap already drives the
                // slides by toggling .active on the .carousel-item elements. Meanwhile BOTH
                // discovery methods claim the container: its .carousel-control-prev/next
                // anchors look like our prev/next buttons (Method 1) and "carousel" is in
                // its class list (Method 2). We then pick our own "slides" — including the
                // control anchors — and showCurrentItems() display:none's them, so the whole
                // hero blanks out the moment the image advances (Butterfly Cancer Care
                // Foundation). .carousel-inner / .carousel-item are structural markers that
                // exist in the source HTML before any JS runs; data-ride / data-bs-ride
                // cover the Bootstrap 4 and 5 spellings. .closest() includes self, so a
                // container, a slide, or a wrapping section are all covered.
                if ($carousel.is('.carousel, [data-ride="carousel"], [data-bs-ride="carousel"]') ||
                    $carousel.closest('.carousel, [data-ride="carousel"], [data-bs-ride="carousel"]').length ||
                    $carousel.find(".carousel-inner, .carousel-item, .carousel-control-prev, .carousel-control-next").length) {
                    return;
                }
                // EC-GALLERY-002d: the injected gallery lightbox owns its own prev/next.
                // Adopting them makes this carousel disable the arrows once it decides
                // there is nothing to cycle, and a disabled <button> fires no click at all,
                // so the modal's arrows died silently while the keyboard still worked.
                if ($carousel.closest("[data-wpc-gallery-modal-root]").length ||
                    $prevBtn.closest("[data-wpc-gallery-modal-root]").length ||
                    $nextBtn.closest("[data-wpc-gallery-modal-root]").length) {
                    return;
                }
                var $track = null;
                var $items = null;
                
                $track = $carousel.find('[class*="grid"]').first();
                if ($track.length) {
                    $items = $track.children().filter(function() {
                        var $el = $(this);
                        // Include items that have testimonial/review content (quotes, names, ratings)
                        var hasContent = $el.find('p, h1, h2, h3, h4, h5, h6, [class*="quote"], [class*="testimonial"], [class*="review"]').length > 0;
                        var isNotButton = !$el.is("button") && !$el.find("button[aria-label]").length;
                        return isNotButton && hasContent;
                    });
                    console.log("Found " + $items.length + " carousel items in grid");
                }
                
                if (!$items || $items.length <= 1) {
                    $track = $carousel.find('[class*="track"], [class*="slider-inner"], [class*="items"]').first();
                    if ($track.length) {
                        $items = $track.children().not("button");
                    }
                }
                
                if (!$items || $items.length <= 1) {
                    $items = $carousel.children().not("button").filter(function() {
                        var $el = $(this);
                        return !$el.find("button[aria-label]").length;
                    });
                }
                
                if (!$items || $items.length === 0) {
                    return;
                }
                
                var totalItems = $items.length;
                
                function parseColumns($el) {
                    var configs = { base: null, sm: null, md: null, lg: null, xl: null };
                    var classString = ($el.attr("class") || "") + " " + ($el.parent().attr("class") || "");
                    classString.split(/\s+/).forEach(function(cls) {
                        var match = cls.match(/^(sm:|md:|lg:|xl:)?grid-cols-(\d+)/);
                        if (match) {
                            var bp = match[1] ? match[1].replace(":", "") : "base";
                            configs[bp] = parseInt(match[2], 10);
                        }
                    });
                    return configs;
                }
                
                function columnsForWidth(configs, width) {
                    if (width >= 1280 && configs.xl) return configs.xl;
                    if (width >= 1024 && configs.lg) return configs.lg;
                    if (width >= 768 && configs.md) return configs.md;
                    if (width >= 640 && configs.sm) return configs.sm;
                    return configs.base || configs.lg || configs.md || 1;
                }
                
                var columnConfig = parseColumns($track.length ? $track : $carousel);
                var itemsPerView = Math.max(1, Math.min(totalItems, columnsForWidth(columnConfig, window.innerWidth)));
                var currentIndex = 0;
                
                function updateDots(activeIndex) {
                    var $dots = $carousel.find('[class*="dot"], [class*="pagination"] button, button[role="tab"]');
                    if ($dots.length === 0) return;
                    $dots.removeClass("active bg-arta-red w-6");
                    $dots.eq(activeIndex % $dots.length).addClass("active bg-arta-red w-6");
                }
                
                function showCurrentItems() {
                    $items.hide();
