                    }
                    updateDots(currentIndex);
                }
                
                function recalcItemsPerView() {
                    var newView = Math.max(1, Math.min(totalItems, columnsForWidth(columnConfig, window.innerWidth)));
                    if (newView !== itemsPerView) {
                        itemsPerView = newView;
                        currentIndex = 0;
