                    $prevBtn.prop("disabled", true).css("opacity", 0.3);
                    $nextBtn.prop("disabled", true).css("opacity", 0.3);
                    console.log("All carousel items fit on screen, buttons disabled");
                }
                
                $items.each(function(index) {
                    $(this).attr('data-original-index', index);
                });

                $prevBtn.off("click.wpconvertCarousel").on("click.wpconvertCarousel", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (totalItems <= itemsPerView) return;
                    if (autoAdvanceInterval) clearInterval(autoAdvanceInterval);
                    
                    var $last = $items.last();
                    $items = $items.not($last);
                    
                    $last.hide().prependTo($track).fadeIn(300);
                    $items = $last.add($items);
                    
                    var currentOriginalIndex = parseInt($items.first().attr('data-original-index') || 0);
                    updateDots(currentOriginalIndex);
                    
                    if (totalItems > itemsPerView) {
                        startAutoAdvance();
                    }
                });
                
                $nextBtn.off("click.wpconvertCarousel").on("click.wpconvertCarousel", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (totalItems <= itemsPerView) return;
                    if (autoAdvanceInterval) clearInterval(autoAdvanceInterval);
                    
                    var $first = $items.first();
                    $items = $items.not($first);
                    
                    $first.hide().appendTo($track).fadeIn(300);
                    $items = $items.add($first);
                    
                    var currentOriginalIndex = parseInt($items.first().attr('data-original-index') || 0);
                    updateDots(currentOriginalIndex);
                    
                    if (totalItems > itemsPerView) {
                        startAutoAdvance();
                    }
                });
                
                function startAutoAdvance() {
                    autoAdvanceInterval = setInterval(function() {
                        $nextBtn.trigger('click');
                    }, 6000);
                }
                
                if (totalItems > itemsPerView) {
                    startAutoAdvance();
                }
                
                var $dots = $carousel.find('[class*="dot"], [class*="pagination"] button, button[role="tab"]');
                if ($dots.length > 0) {
                    $dots.on("click", function(e) {
                        e.preventDefault();
                        clearInterval(autoAdvanceInterval);
                        currentIndex = $(this).index();
                        showCurrentItems();
                    });
                }
                
                var resizeTimer = null;
                $(window).on("resize.wpconvertCarousel", function() {
                    clearTimeout(resizeTimer);
                    resizeTimer = setTimeout(function() {
                        recalcItemsPerView();
                    }, 200);
                });
                
                // CRITICAL: Add drag/swipe support for touch and mouse
                var isDragging = false;
                var startX = 0;
                var startY = 0;
                var scrollLeft = 0;
                var scrollTop = 0;
                
                // Mouse drag support
                $track.on("mousedown.wpconvertCarousel", function(e) {
                    isDragging = true;
                    startX = e.pageX - $(this).offset().left;
                    startY = e.pageY - $(this).offset().top;
                    scrollLeft = $(this).scrollLeft();
                    scrollTop = $(this).scrollTop();
