                });
                
                $(document).on("mousemove.wpconvertCarousel", function(e) {
                    if (!isDragging) return;
                    e.preventDefault();
                    var x = e.pageX - $track.offset().left;
                    var y = e.pageY - $track.offset().top;
                    var walkX = (x - startX) * 2;
