            try { // EC-DIAG-001: multi-step estimate wizard
            (function() {
  'use strict';
  var roots = document.querySelectorAll('[data-wpc-diag-wizard]');
  if (!roots.length) return;

  Array.prototype.forEach.call(roots, function(root) {
    if (root.getAttribute('data-wpc-diag-bound') === '1') return;
    root.setAttribute('data-wpc-diag-bound', '1');

    var holder = root.querySelector('script[data-wpc-diag-data]');
    if (!holder) return;
    var data;
    try { data = JSON.parse(holder.textContent || 'null'); } catch (e) { return; }
    if (!data || !data.issues || !data.issues.length || !data.model) return;

    var issueBtns = root.querySelectorAll('[data-wpc-diag-issue]');
    var body = root.querySelector('[data-wpc-diag-body]');
    var questionView = root.querySelector('[data-wpc-diag-question-view]');
    var questionEl = root.querySelector('[data-wpc-diag-question]');
    var optionRow = root.querySelector('[data-wpc-diag-options]');
    var titleEl = root.querySelector('[data-wpc-diag-title]');
    var progressEl = root.querySelector('[data-wpc-diag-progress]');
    var controlsEl = root.querySelector('[data-wpc-diag-controls]');
    if (!issueBtns.length || !body || !questionView || !questionEl || !optionRow) return;

    var labels = data.labels || {};
    var templates = data.templates || {};
    var state = { issueId: data.activeIssueId, step: 0, answers: [], showResult: false };
    var resultPanel = null;

    function issueById(id) {
      for (var i = 0; i < data.issues.length; i++) {
        if (data.issues[i].id === id) return data.issues[i];
      }
      return data.issues[0];
    }

    function fromHtml(html) {
      var wrap = document.createElement('div');
      wrap.innerHTML = String(html || '').trim();
      return wrap.firstElementChild;
    }

    function round(mode, value) {
      if (mode === 'floor') return Math.floor(value);
      if (mode === 'ceil') return Math.ceil(value);
      return Math.round(value);
    }

    function estimate() {
      var issue = issueById(state.issueId);
      var product = 1;
      var recommendations = [];
      for (var q = 0; q < state.answers.length; q++) {
        var question = issue.questions[q];
        var option = question && question.options[state.answers[q]];
        if (option) {
          product *= option.multiplier;
          if (option.recommendation) recommendations.push(option.recommendation);
        }
      }
      var price = issue.basePrice * product;
      var m = data.model;
      var lower = round(m.lower.mode, price * m.lower.factor);
      var upper = round(m.upper.mode, price * m.upper.factor);
      return {
        text: (m.prefix || '') + lower + (m.separator || '') + (m.prefix || '') + upper + (m.suffix || ''),
        recommendations: recommendations
      };
    }

    function applyStateClasses(el, selected) {
      var mode = el.getAttribute('data-wpc-cls-mode');
      var active = el.getAttribute('data-wpc-active-cls') || '';
      var inactive = el.getAttribute('data-wpc-inactive-cls') || '';
      if (!mode) return;
      if (mode === 'full') {
        el.className = selected ? active : inactive;
        return;
      }
      var add = (selected ? active : inactive).split(' ').filter(Boolean);
      var remove = (selected ? inactive : active).split(' ').filter(Boolean);
      remove.forEach(function(c) { el.classList.remove(c); });
      add.forEach(function(c) { el.classList.add(c); });
    }

    function renderIssues() {
      Array.prototype.forEach.call(issueBtns, function(btn) {
        var selected = btn.getAttribute('data-wpc-diag-issue') === state.issueId;
        btn.setAttribute('aria-pressed', selected ? 'true' : 'false');
        applyStateClasses(btn, selected);
        var icon = btn.querySelector('[data-wpc-diag-icon]');
        if (icon) applyStateClasses(icon, selected);
      });
    }

    function renderLabels() {
      var issue = issueById(state.issueId);
      if (titleEl && labels.titleTemplate) {
        titleEl.textContent = labels.titleTemplate.replace('{{title}}', issue.title);
      }
      if (progressEl) {
        if (state.showResult && labels.resultLabel) {
          progressEl.textContent = labels.resultLabel;
        } else if (labels.progressTemplate) {
          progressEl.textContent = labels.progressTemplate
            .replace('{{step}}', String(state.step + 1))
            .replace('{{total}}', String(issue.questions.length));
        }
      }
    }

    function renderQuestion() {
      var issue = issueById(state.issueId);
      var question = issue.questions[state.step];
      if (!question) return;
      questionEl.textContent = question.text;

      optionRow.innerHTML = '';
      question.options.forEach(function(option, index) {
        var btn = fromHtml(templates.option);
        if (!btn) return;
        btn.removeAttribute('id');
        btn.setAttribute('data-wpc-diag-option', String(index));
        var label = btn.querySelector('span') || btn;
        label.textContent = option.text;
        btn.addEventListener('click', function(event) {
          event.preventDefault();
          state.answers[state.step] = index;
          state.answers.length = state.step + 1;
          if (state.step < issue.questions.length - 1) state.step += 1;
          else state.showResult = true;
          render();
        });
        optionRow.appendChild(btn);
      });
    }

    function renderResult() {
      if (resultPanel && resultPanel.parentNode) resultPanel.parentNode.removeChild(resultPanel);
      resultPanel = null;
      if (!state.showResult) {
        questionView.style.display = '';
        return;
      }

      questionView.style.display = 'none';
      var priced = estimate();
      var html = String(templates.result || '');

      var items = '';
      if (templates.recommendation) {
        items = priced.recommendations.map(function(rec) {
          return templates.recommendation.replace('{{text}}', rec);
        }).join('');
      }
      html = html.split('{{recommendations}}').join(items);
      html = html.split('{{price}}').join(priced.text);

      resultPanel = document.createElement('div');
      resultPanel.setAttribute('data-wpc-diag-result', 'true');
      resultPanel.innerHTML = html;
      body.appendChild(resultPanel);
    }

    function renderControls() {
      if (!controlsEl) return;
      controlsEl.innerHTML = '';

      if (state.step > 0 && !state.showResult && templates.back) {
        var back = fromHtml(templates.back);
        if (back) {
          back.removeAttribute('id');
          back.addEventListener('click', function(event) {
            event.preventDefault();
            state.step -= 1;
            state.answers.pop();
            render();
          });
          controlsEl.appendChild(back);
        }
      }

      if (state.showResult && templates.reset) {
        var reset = fromHtml(templates.reset);
        if (reset) {
          reset.removeAttribute('id');
          reset.addEventListener('click', function(event) {
            event.preventDefault();
            state.step = 0;
            state.answers = [];
            state.showResult = false;
            render();
          });
          controlsEl.appendChild(reset);
        }
      }
    }

    function render() {
      renderIssues();
      renderLabels();
      if (!state.showResult) renderQuestion();
      renderResult();
      renderControls();
    }

    Array.prototype.forEach.call(issueBtns, function(btn) {
      btn.addEventListener('click', function(event) {
        event.preventDefault();
        var id = btn.getAttribute('data-wpc-diag-issue');
        if (!id) return;
        state.issueId = id;
        state.step = 0;
        state.answers = [];
        state.showResult = false;
        render();
      });
    });

    render();
  });
})();
            } catch(e) { console.warn("[WPConvert] Estimate wizard error:", e); }

