            try { // EC-NAV-MEGA-004: state selector inside a captured mega panel
            (function () {
  var SWITCH = 'data-wpc-panel-switch';

  function payloadFor(el) {
    var host = el.closest('.wpconvert-nav-rich-panel, [data-wpc-rich-panel]');
    if (!host) return null;
    var tag = host.querySelector('script.wpconvert-panel-states');
    if (!tag) return null;
    if (!host.__wpcPanelStates) {
      try { host.__wpcPanelStates = JSON.parse(tag.textContent); }
      catch (e) { host.__wpcPanelStates = { states: [] }; }
    }
    var data = host.__wpcPanelStates;
    if (!data || !data.states || data.states.length < 2) return null;
    return { host: host, data: data };
  }

  // The captured panel root is the element the controls live inside; swapping
  // its innerHTML leaves the root element — and therefore its classes, which
  // EC-NAV-MEGA-003's full-bleed CSS keys off — completely untouched.
  function rootFor(host, control) {
    var wrap = host.querySelector('.wpconvert-rich-panel-content') || host;
    var node = control;
    while (node && node.parentElement && node.parentElement !== wrap) {
      node = node.parentElement;
    }
    return node && node.parentElement === wrap ? node : wrap.firstElementChild;
  }

  function apply(control) {
    var found = payloadFor(control);
    if (!found) return false;
    var idx = parseInt(control.getAttribute(SWITCH), 10);
    if (isNaN(idx) || idx < 0 || idx >= found.data.states.length) return false;
    var root = rootFor(found.host, control);
    if (!root) return false;
    var html = found.data.states[idx].innerHtml;
    if (typeof html !== 'string' || root.innerHTML === html) return true;
    root.innerHTML = html;
    return true;
  }

  function controlFrom(target) {
    return target && target.closest ? target.closest('[' + SWITCH + ']') : null;
  }

  document.addEventListener('click', function (e) {
    var control = controlFrom(e.target);
    if (!control) return;
    // Mirror the source: the href is decorative, the click only swaps state.
    e.preventDefault();
    apply(control);
  }, false);

  document.addEventListener('mouseover', function (e) {
    var control = controlFrom(e.target);
    if (!control) return;
    apply(control);
  }, false);
})();
            } catch(e) { console.warn("[WPConvert] Mega panel state selector error:", e); }

            try { // EC-GALLERY-002: GalleryModal photo lightbox
            (function() {
  'use strict';
  var root = document.querySelector('[data-wpc-gallery-modal-root]');
  var dataEl = document.querySelector('[data-wpc-gallery-modal-data]');
  if (!root || !dataEl) return;
  if (root.getAttribute('data-wpc-gallery-bound') === '1') return;
  root.setAttribute('data-wpc-gallery-bound', '1');

  // EC-GALLERY-002d: portal to <body>, the way the source component's React portal did.
  // The theme wraps page templates in <main class="site-main">, which is positioned with
  // a z-index and therefore opens a stacking context: a z-index set on anything inside it
  // is resolved *within* main, so the modal could never paint over the sibling
  // <nav class="fixed z-50">. Moving the node keeps its listeners; we bind afterwards.
  if (document.body && root.parentNode !== document.body) {
    document.body.appendChild(root);
  }

  var galleries;
  try { galleries = JSON.parse(dataEl.textContent || '[]'); } catch (e) { return; }
  if (!galleries || !galleries.length) return;
  var byId = {};
  for (var gi = 0; gi < galleries.length; gi++) byId[galleries[gi].id] = galleries[gi];

  var titleEl = root.querySelector('[data-wpc-gallery-modal-title]');
  var imgEl = root.querySelector('[data-wpc-gallery-modal-image]');
  var counterEl = root.querySelector('[data-wpc-gallery-modal-counter]');
  var panel = root.querySelector('[data-wpc-gallery-modal-panel]');
  var current = null;
  var index = 0;

  function render() {
    if (!current || !current.images || !current.images.length) return;
    if (titleEl) titleEl.textContent = current.title || '';
    if (imgEl) {
      imgEl.src = current.images[index];
      imgEl.alt = (current.title || 'Gallery') + ' ' + (index + 1);
    }
    if (counterEl) counterEl.textContent = (index + 1) + ' / ' + current.images.length;
  }

  // EC-GALLERY-002d: other injectors (the universal carousel especially) adopt any
  // prev/next arrow pair they find and disable it when they decide there is nothing to
  // cycle. A disabled <button> dispatches no click event at all, so reclaim ours.
  function enableControls() {
    var controls = root.querySelectorAll(
      '[data-wpc-gallery-modal-prev],[data-wpc-gallery-modal-next],[data-wpc-gallery-modal-close]'
    );
    for (var ci = 0; ci < controls.length; ci++) {
      controls[ci].disabled = false;
      controls[ci].removeAttribute('disabled');
      controls[ci].style.opacity = '';
    }
  }

  function open(id) {
    current = byId[id];
    if (!current) return;
    index = 0;
    enableControls();
    render();
    // EC-GALLERY-002d: inline display — .hidden/.flex may be absent or may lose the
    // cascade in the converted site's compiled CSS.
    root.style.display = 'flex';
    root.classList.remove('hidden');
    root.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function close() {
    root.style.display = 'none';
    root.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    current = null;
  }

  function next() {
    if (!current || !current.images.length) return;
    index = (index + 1) % current.images.length;
    render();
  }

  function prev() {
    if (!current || !current.images.length) return;
    index = (index - 1 + current.images.length) % current.images.length;
    render();
  }

  document.querySelectorAll('[data-wpc-gallery-trigger]').forEach(function(btn) {
    btn.style.cursor = 'pointer';
    btn.addEventListener('click', function(e) {
      if (e && e.preventDefault) e.preventDefault();
      open(btn.getAttribute('data-wpc-gallery-trigger'));
    });
  });

  var closeBtn = root.querySelector('[data-wpc-gallery-modal-close]');
  if (closeBtn) closeBtn.addEventListener('click', close);
  var prevBtn = root.querySelector('[data-wpc-gallery-modal-prev]');
  if (prevBtn) prevBtn.addEventListener('click', prev);
  var nextBtn = root.querySelector('[data-wpc-gallery-modal-next]');
  if (nextBtn) nextBtn.addEventListener('click', next);

  root.addEventListener('click', function(e) {
    if (e.target === root) close();
  });
  if (panel) {
    panel.addEventListener('click', function(e) { e.stopPropagation(); });
  }
  document.addEventListener('keydown', function(e) {
    if (root.style.display === 'none') return;
    if (e.key === 'Escape') close();
    else if (e.key === 'ArrowRight') next();
    else if (e.key === 'ArrowLeft') prev();
  });
})();
            } catch(e) { console.warn("[WPConvert] Gallery modal error:", e); }

            try { // EC-GALLERY-003 / EC-CAROUSEL-016i: GalleryCarousel photo stacks
            (function(){
  /* EC-GALLERY-003 / EC-CAROUSEL-016i: GalleryCarousel photo stacks */
  function setup(box){
    if (!box || box.getAttribute('data-wpc-gallery-carousel-bound')) return;
    var imgs = Array.prototype.slice.call(box.children).filter(function(n){
      return n.tagName === 'IMG';
    });
    if (imgs.length < 2) {
      imgs = Array.prototype.slice.call(box.querySelectorAll('img')).filter(function(img){
        var c = img.getAttribute('class') || '';
        return /\babsolute\b/.test(c);
      });
    }
    if (imgs.length < 2) return;
    box.setAttribute('data-wpc-gallery-carousel-bound', 'true');

    var card = box.closest('.bg-card, [class*="rounded-2xl"]') || box.parentElement;
    var allBtns = Array.prototype.slice.call(box.querySelectorAll('button'));
    var dots = allBtns.filter(function(b){
      return /^go to (photo|image|picture)\s+\d+/i.test(b.getAttribute('aria-label') || '');
    });
    var prevOverlay = allBtns.find(function(b){
      var a = (b.getAttribute('aria-label') || '').toLowerCase();
      return /\b(previous|prev)\b/.test(a) && /\b(photo|image|picture|gallery)\b/.test(a);
    }) || null;
    var nextOverlay = allBtns.find(function(b){
      var a = (b.getAttribute('aria-label') || '').toLowerCase();
      return /\bnext\b/.test(a) && /\b(photo|image|picture|gallery)\b/.test(a);
    }) || null;
    var counter = null;
    var prevFooter = null;
    var nextFooter = null;
    if (card) {
      var spans = card.querySelectorAll('span');
      for (var s = 0; s < spans.length; s++) {
        if (/^\s*\d+\s*\/\s*\d+\s*$/.test(spans[s].textContent || '')) { counter = spans[s]; break; }
      }
      var cardBtns = card.querySelectorAll('button');
      for (var bi = 0; bi < cardBtns.length; bi++) {
        if (cardBtns[bi] === prevOverlay || cardBtns[bi] === nextOverlay) continue;
        if (dots.indexOf(cardBtns[bi]) >= 0) continue;
        var t = (cardBtns[bi].textContent || '').replace(/\s+/g, ' ').trim();
        if (/^(prev|previous)$/i.test(t)) prevFooter = cardBtns[bi];
        if (/^next$/i.test(t)) nextFooter = cardBtns[bi];
      }
    }

    var idx = 0;
    var timer = null;
    function show(n){
      idx = ((n % imgs.length) + imgs.length) % imgs.length;
      imgs.forEach(function(img, i){
        img.style.transition = 'opacity 0.5s ease';
        img.style.opacity = i === idx ? '1' : '0';
      });
      dots.forEach(function(d, i){
        d.style.cursor = 'pointer';
        if (i === idx) { d.style.width = '1.5rem'; }
        else { d.style.width = '0.375rem'; }
      });
      if (counter) counter.textContent = (idx + 1) + ' / ' + imgs.length;
    }
    function start(){ stop(); timer = setInterval(function(){ show(idx + 1); }, 5000); }
    function stop(){ if (timer) { clearInterval(timer); timer = null; } }
    function bind(el, delta){
      if (!el) return;
      el.addEventListener('click', function(e){
        if (e && e.preventDefault) e.preventDefault();
        if (e && e.stopPropagation) e.stopPropagation();
        stop(); show(idx + delta); start();
      });
    }
    bind(prevOverlay, -1);
    bind(nextOverlay, 1);
    bind(prevFooter, -1);
    bind(nextFooter, 1);
    dots.forEach(function(d, i){
      d.addEventListener('click', function(e){
        if (e && e.preventDefault) e.preventDefault();
        if (e && e.stopPropagation) e.stopPropagation();
        stop(); show(i); start();
      });
    });
    box.addEventListener('mouseenter', stop);
    box.addEventListener('mouseleave', start);
    show(0);
    start();
    box.__wpcGalleryStop = stop;
  }
  function boot(){
    document.querySelectorAll('[data-wpc-gallery-carousel="true"]').forEach(setup);
  }
  function stopAll(){
    document.querySelectorAll('[data-wpc-gallery-carousel="true"]').forEach(function(box){
      if (typeof box.__wpcGalleryStop === 'function') box.__wpcGalleryStop();
    });
  }
  window.__wpcStopGalleryCarousels = stopAll;
  // Always boot immediately. JSDOM (and some WP inline-script timings) can leave
  // readyState at "loading" without ever firing DOMContentLoaded for outside-only evals.
  boot();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ boot(); });
