                    // triple signal (opacity:0 + pointer-events:none + positioned) is a
                    // strict overlay marker, so no genuine scroll-reveal block matches.
                    if ((style.opacity === '0' || style.opacity === '0.0') &&
                        style.pointerEvents === 'none') {
                        var __pos = computedStyle.position;
                        if (__pos === 'fixed' || __pos === 'absolute' || __pos === 'sticky') {
                            return;
                        }
                    }

                    // Check for hiding inline styles (Framer Motion patterns)
                    if (style.opacity === '0' || style.opacity === '0.0') {
                        // Only reveal if element has content/dimensions
                        if (el.offsetHeight > 0 || el.offsetWidth > 0 || el.textContent.trim().length > 0) {
                            style.opacity = '1';
                            hasHidingStyle = true;
                        }
                    }
                    
                    // Check for visibility hidden
                    if (style.visibility === 'hidden' && computedStyle.display !== 'none') {
                        style.visibility = 'visible';
                        hasHidingStyle = true;
                    }
                    
                    // Check for transform that moves element off-screen
                    if (style.transform && (
                        style.transform.includes('translateY') || 
                        style.transform.includes('translateX') ||
                        style.transform.includes('scale(0)')
                    )) {
                        // EC-CAROUSEL-009: Embla/shadcn carousels set translateX on the flex track via WPConvert JS.
                        // Stripping it (especially on the delayed run) breaks the culture image slider.
                        if (el.closest('[aria-roledescription="carousel"]')) {
                            /* skip */
                        } else {
                        // Reset problematic transforms (preserve intentional ones like rotate)
                        // EC-SCRUB-004: PRESERVE the centering idiom translateX/Y(±50%)
                        // (paired with left/top:50%). Only zero pixel/length entrance
                        // offsets — blindly zeroing translateX(-50%) shifts centered
                        // overlays right/down by half their size (e.g. the scroll-scrub
                        // "SCROLL — WATCH THE TRANSFORMATION" hint on Manchester Roofing Pro).
                        var transform = style.transform;
                        var isCentering50 = function(v) { return /^\s*-?50(?:\.0+)?%\s*$/.test(v); };
                        transform = transform.replace(/translateY\(([^)]*)\)/g, function(m, v) { return isCentering50(v) ? m : 'translateY(0)'; });
                        transform = transform.replace(/translateX\(([^)]*)\)/g, function(m, v) { return isCentering50(v) ? m : 'translateX(0)'; });
                        transform = transform.replace(/scale\(0(?:\.\d+)?\)/g, 'scale(1)');
                        
                        if (transform !== style.transform) {
                            style.transform = transform;
                            hasHidingStyle = true;
                        }
                        }
                    }
                    
                    if (hasHidingStyle) {
                        revealed++;
                    }
                });
                
                if (revealed > 0) {
                    console.log('[WPConvert] ✅ Revealed ' + revealed + ' hidden elements (Framer Motion fallback)');
                }
            }
            
            // Run immediately (for inline styles in initial HTML)
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', revealHiddenElements);
            } else {
                revealHiddenElements();
            }
            
            // Also run after a short delay to catch late-loading elements
            setTimeout(revealHiddenElements, 100);
        })();
ANIMATION_FALLBACK_JS
    , 'before');

    // EC-ANIM-009: IntersectionObserver scroll-reveal — adds .visible to scroll-fade-up etc.
    // CSS transitions handle the animation; this script only triggers the class toggle.
    wp_add_inline_script('jquery', <<<'SCROLL_REVEAL_JS'
        (function() {
            var selectors = '.scroll-fade-up, .scroll-fade-left, .scroll-fade-right, .scroll-scale-in';
            function initScrollReveal() {
                var els = document.querySelectorAll(selectors);
                if (!els.length || typeof IntersectionObserver === 'undefined') return;
                var io = new IntersectionObserver(function(entries) {
                    entries.forEach(function(entry) {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            io.unobserve(entry.target);
                        }
                    });
                }, { threshold: 0.15 });
                els.forEach(function(el) {
                    if (el.closest('[aria-roledescription="carousel"]')) {
                        el.classList.add('visible');
                    } else {
                        io.observe(el);
                    }
                });
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', initScrollReveal);
            } else {
                initScrollReveal();
            }
        })();
SCROLL_REVEAL_JS
    , 'after');
    
    // Phase 3: Animation Libraries (Pro/Agency Only)
    // CRITICAL: Only include animation library code for Pro/Agency plans at generation time
    // Starter plan users should NOT get any animation library code in their theme
    

    // EC-NAV-088: Navbar / hero gap — wp_add_inline_style on a handle that depends on
    // wpconvert-site-styles so these rules load AFTER the Vite bundle (body padding-top, etc.).
    $wpconvert_ecnav088_deps = array('wpconvert-style');
    if (wp_style_is('wpconvert-site-styles', 'enqueued')) {
        $wpconvert_ecnav088_deps[] = 'wpconvert-site-styles';
    }
    wp_register_style('wpconvert-ecnav088', false, $wpconvert_ecnav088_deps, '2.0.3');
    wp_enqueue_style('wpconvert-ecnav088');
    // EC-ANIM-008c / EC-ANIM-009: Carousel-only override (loads after all wpconvert-asset-* chunks).
    // Scroll-reveal elements are animated via IntersectionObserver (below); only carousels need
    // forced visibility so Embla can measure track width on load.
    wp_add_inline_style(
        'wpconvert-ecnav088',
        '/* EC-ANIM-008c/009: carousel-only scroll-reveal override */' .
        '.scroll-fade-up:has([aria-roledescription="carousel"]),' .
        '.scroll-fade-up:has([data-wpconvert-blog-filter-bar]),' .
        '.scroll-fade-left:has([aria-roledescription="carousel"]),' .
        '.scroll-fade-right:has([aria-roledescription="carousel"]),' .
        '.scroll-scale-in:has([aria-roledescription="carousel"]){' .
        'opacity:1!important;transform:none!important}' .
        '/* EC-ACCORDION-STATE: Sync panel visibility with trigger state — Puppeteer snapshots */' .
        '/* can capture panels as data-state=open while their trigger is data-state=closed */' .
        'h3[data-state="closed"]+[role="region"],' .
        'h3[data-state="closed"]+[data-state][role="region"]{' .
        'display:none!important;max-height:0!important;overflow:hidden!important;animation:none!important}'
    );
    if (is_front_page()) {
        wp_add_inline_style(
            'wpconvert-ecnav088',
            '/* EC-NAV-088/089: front-page nav+hero + admin-bar offset (last in cascade) */' .
            'body.front-page{padding-top:0!important}' .
            'body.front-page .site-main,body.front-page .site-main #primary{margin-top:0!important;padding-top:0!important}' .
            'body.front-page .site-main #primary>section.min-h-screen:first-of-type:not([class*="pt-"]):not([class*="mt-"]),' .
            'body.front-page .site-main #primary>div:first-of-type>section.min-h-screen:first-of-type:not([class*="pt-"]):not([class*="mt-"]),' .
            'body.front-page .site-main>div:first-of-type>section.min-h-screen:first-of-type:not([class*="pt-"]):not([class*="mt-"]){margin-top:calc(-1*var(--wpconvert-header-bar-height,4rem) - var(--wp-admin--admin-bar--height,0px))!important}' .
            'body.admin-bar nav.fixed.top-0:not(#wpconvert-mobile-nav),' .
            'body.admin-bar nav.fixed[class*="top-0"]:not(#wpconvert-mobile-nav){top:var(--wp-admin--admin-bar--height,32px)!important}' .
            '/* EC-HERO-014: Full-viewport hero fidelity — SPA wrapper path + min-height guard */body.front-page #primary section#top.min-h-screen,body.front-page #primary > div:first-of-type > section.min-h-screen:first-of-type {  min-height: 100vh !important;  min-height: 100dvh !important;}body.front-page #primary section#top.min-h-screen > .absolute.bottom-10 {  z-index: 10;}'
        );
    }
}
