// ---------------------------------------------------------------------------
// EC-PERMA-002: verify the rewrite rules this theme depends on actually work.
//
// EC-PERMA-001 forces /%postname%/ on activation and flushes, and the generated
// templates hardcode pretty URLs (home_url('/contact/')), so pretty permalinks are
// a hard requirement rather than a preference. But they only resolve if the SERVER
// honours WordPress's rewrite rules: Apache needs a writable .htaccess with
// AllowOverride, and Nginx never reads .htaccess at all. Where that is not true the
// request 404s in the web server BEFORE WordPress loads, so nothing inside PHP ever
// saw it. That is why the failure was silent, and why Playground — which routes
// requests internally — never reproduced it. Symptom as reported: "the homepage is
// fine but all the other pages, the header and the footer are missing".
//
// The probe deliberately runs in the BROWSER, not as a server-side loopback:
// wp_remote_get() back to the same site during admin_init deadlocks on hosts with a
// single PHP worker, and a loopback would not see what a real visitor sees (HTTPS,
// redirects, a CDN in front). This mirrors how core's own Site Health works.
// ---------------------------------------------------------------------------
function wpconvert_rewrite_probe_signature() {
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    $routes_hash = file_exists($routes_path) ? md5_file($routes_path) : 'noroutes';
    return md5($routes_hash . '|' . site_url() . '|' . (string) get_option('permalink_structure'));
}

function wpconvert_rewrite_probe_state() {
    $state = get_option('wpconvert_rewrite_check');
    if (!is_array($state)) {
        $state = array();
    }
    return wp_parse_args($state, array('verdict' => '', 'sig' => '', 'time' => 0, 'healed' => 0));
}

// Resolve one real, published converted page to probe. Bounded to the first few
// routes (EC-PERF-001): never scan a large route map on an admin request.
function wpconvert_rewrite_probe_page() {
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path) || !function_exists('wpconvert_get_page_for_route')) {
        return null;
    }
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes)) {
        return null;
    }
    $checked = 0;
    foreach ($routes as $route => $_d) {
        $slug = trim((string) $route, '/');
        if ($slug === '' || strpos($slug, '://') !== false) {
            continue;
        }
        if ($checked >= 5) {
            break;
        }
        $checked++;
        $page = wpconvert_get_page_for_route($route);
        if ($page && isset($page->post_status) && $page->post_status === 'publish') {
            return $page;
        }
    }
    return null;
}

function wpconvert_rewrite_probe_enqueue($hook) {
    if (!current_user_can('manage_options') || !function_exists('rest_url')) {
        return;
    }
    $state = wpconvert_rewrite_probe_state();
    $sig = wpconvert_rewrite_probe_signature();
    // A clean bill of health latches: nothing to re-check until the routes, the site
    // URL or the permalink structure changes. A 'broken' verdict deliberately does
    // NOT latch, so the notice clears itself once the owner fixes their server
    // instead of requiring them to find the re-check button.
    if ($state['verdict'] === 'ok' && $state['sig'] === $sig) {
        return;
    }
    if (get_transient('wpconvert_rewrite_probe_lock')) {
        return;
    }
    // Never probe before activation has actually created pages.
    $page = wpconvert_rewrite_probe_page();
    if (!$page) {
        return;
    }
    $permalink = get_permalink($page->ID);
    if (!$permalink) {
        return;
    }
    set_transient('wpconvert_rewrite_probe_lock', 1, 10 * MINUTE_IN_SECONDS);
    // The reporting endpoint MUST NOT itself depend on rewrite rules. rest_url()
    // returns the pretty /wp-json/ form whenever a permalink structure is set, but
    // on a broken host /wp-json/ 404s for exactly the same reason the pages do, so
    // the verdict could never be reported by the sites that need it most. The
    // ?rest_route= form is core's own rewrite-free fallback and always resolves.
    $endpoint = add_query_arg('rest_route', '/wpconvert/v1/rewrite-check', home_url('/'));
    wp_register_script('wpconvert-rewrite-probe', false, array(), null, true);
    wp_enqueue_script('wpconvert-rewrite-probe');
    wp_add_inline_script('wpconvert-rewrite-probe', 'window.wpconvertRewriteProbe = ' . wp_json_encode(array(
        'homeUrl'  => home_url('/'),
        'pageUrl'  => $permalink,
        'endpoint' => $endpoint,
        'nonce'    => wp_create_nonce('wp_rest'),
    )) . ';', 'before');
    wp_add_inline_script('wpconvert-rewrite-probe', <<<'WPC_REWRITE_PROBE_JS'
(function () {
  var cfg = window.wpconvertRewriteProbe;
  if (!cfg || !cfg.pageUrl || !cfg.homeUrl || typeof window.fetch !== 'function') { return; }
  var bust = Date.now().toString(36);
  // credentials:'omit' so we measure what a logged-out visitor gets, which is the
  // audience actually affected. cache:'no-store' so a cached 200 cannot mask a 404.
  function probe(url) {
    var sep = url.indexOf('?') === -1 ? '?' : '&';
    return fetch(url + sep + 'wpc_rwcheck=' + bust, {
      method: 'GET',
      credentials: 'omit',
      redirect: 'follow',
      cache: 'no-store'
    }).then(function (r) { return r.status; }).catch(function () { return 0; });
  }
  Promise.all([probe(cfg.homeUrl), probe(cfg.pageUrl)]).then(function (codes) {
    return fetch(cfg.endpoint, {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': cfg.nonce },
      body: JSON.stringify({ home_status: codes[0], page_status: codes[1] })
    });
  }).catch(function () {});
})();
WPC_REWRITE_PROBE_JS
    );
}
add_action('admin_enqueue_scripts', 'wpconvert_rewrite_probe_enqueue');

function wpconvert_register_rewrite_check_route() {
    register_rest_route('wpconvert/v1', '/rewrite-check', array(
        'methods'             => 'POST',
        'callback'            => 'wpconvert_rest_rewrite_check',
        'permission_callback' => function () {
            return current_user_can('manage_options');
        },
    ));
}
add_action('rest_api_init', 'wpconvert_register_rewrite_check_route');

function wpconvert_rest_rewrite_check($request) {
    $home = (int) $request->get_param('home_status');
    $page = (int) $request->get_param('page_status');

    // Conservative by construction: 'inconclusive' is the DEFAULT and only one
    // unambiguous signature moves off it. Auth walls (401/403), 5xx, network errors
    // and anything unforeseen therefore stay silent and change nothing, because a
    // false positive would put an alarming banner on a perfectly healthy site.
    $verdict = 'inconclusive';
    if ($home === 200 && $page === 200) {
        $verdict = 'ok';
    } elseif ($home === 200 && $page === 404) {
        $verdict = 'broken';
    }

    $prev = wpconvert_rewrite_probe_state();
    $healed_before = ($verdict === 'ok') ? 0 : (int) $prev['healed'];
    $healed_now = false;

    if ($verdict === 'broken' && !$healed_before) {
        $healed_now = wpconvert_maybe_write_rewrite_rules();
        if ($healed_now) {
            // Re-arm exactly once so the next admin screen confirms the repair
            // rather than leaving a stale 'broken' verdict on a now-working site.
            delete_transient('wpconvert_rewrite_probe_lock');
        }
    }

    if ($verdict === 'broken' && apply_filters('wpconvert_permalink_auto_fallback', false)) {
        // Off by default and intentionally so: this only half-fixes the site (the
        // templates still emit pretty URLs) and it silently changes the URLs of any
        // pre-existing posts, which is unacceptable on a false positive.
        update_option('permalink_structure', '');
        flush_rewrite_rules();
        $verdict = 'fallback';
    }

    update_option('wpconvert_rewrite_check', array(
        'verdict' => $verdict,
        'sig'     => wpconvert_rewrite_probe_signature(),
        'time'    => time(),
        'healed'  => $healed_now ? 1 : $healed_before,
    ));

    return rest_ensure_response(array('verdict' => $verdict, 'healed' => (bool) $healed_now));
}

// Repair the common case only: Apache with a writable .htaccess. Nginx and
// AllowOverride-None cannot be fixed from PHP, and the notice says so plainly.
function wpconvert_maybe_write_rewrite_rules() {
    // Multisite manages rewrite rules differently and core does not write .htaccess
    // for it the way it does for single site.
    if (is_multisite()) {
        return false;
    }
    // The REST handler is NOT wp-admin, so these admin-only helpers are not loaded
    // here. Calling them without this would be a fatal error.
    if (!function_exists('got_mod_rewrite') || !function_exists('save_mod_rewrite_rules') || !function_exists('get_home_path')) {
        $misc = ABSPATH . 'wp-admin/includes/misc.php';
        $file = ABSPATH . 'wp-admin/includes/file.php';
        if (!file_exists($misc) || !file_exists($file)) {
            return false;
        }
        require_once $file;
        require_once $misc;
    }
    if (!function_exists('got_mod_rewrite') || !got_mod_rewrite()) {
        return false;
    }
    $home_path = function_exists('get_home_path') ? get_home_path() : ABSPATH;
    $htaccess = $home_path . '.htaccess';
    if (file_exists($htaccess)) {
        if (!wp_is_writable($htaccess)) {
            return false;
        }
    } elseif (!wp_is_writable($home_path)) {
        return false;
    }
    // Core rewrites only its own "# BEGIN WordPress" block and preserves every other
    // rule in the file. We never hand-write rewrite directives ourselves.
    return (bool) save_mod_rewrite_rules();
}

function wpconvert_rewrite_admin_notice() {
    if (!current_user_can('manage_options')) {
        return;
    }
    $state = wpconvert_rewrite_probe_state();
    if ($state['verdict'] !== 'broken') {
        return;
    }
    $recheck = wp_nonce_url(
        add_query_arg('wpconvert_rewrite_recheck', '1', admin_url()),
        'wpconvert_rewrite_recheck'
    );
    echo '<div class="notice notice-error">';
    echo '<p><strong>WPConvert:</strong> your homepage loads, but the rest of the site is returning &#8220;Not Found&#8221;. Your content is fine &#8212; this is a web-server setting. WordPress needs permalink (rewrite) rules to be honoured, and right now they are not.</p>';
    echo '<p><strong>Apache:</strong> open <a href="' . esc_url(admin_url('options-permalink.php')) . '">Settings &rarr; Permalinks</a> and press Save Changes. If the pages still 404, the .htaccess file is not writable or AllowOverride is switched off &#8212; ask your host to allow .htaccess overrides for this site.</p>';
    echo '<p><strong>Nginx:</strong> .htaccess is never read, so this must be set in the server config. Add the following inside your server block and reload Nginx:</p>';
    echo '<p><code>location / { try_files $uri $uri/ /index.php?$args; }</code></p>';
    echo '<p><a class="button button-primary" href="' . esc_url($recheck) . '">Re-check now</a></p>';
    echo '</div>';
}
add_action('admin_notices', 'wpconvert_rewrite_admin_notice');

function wpconvert_handle_rewrite_recheck() {
    if (!isset($_GET['wpconvert_rewrite_recheck'])) {
        return;
    }
    if (!current_user_can('manage_options')) {
        return;
    }
    check_admin_referer('wpconvert_rewrite_recheck');
    delete_option('wpconvert_rewrite_check');
    delete_transient('wpconvert_rewrite_probe_lock');
    wp_safe_redirect(remove_query_arg(array('wpconvert_rewrite_recheck', '_wpnonce')));
    exit;
}
add_action('admin_init', 'wpconvert_handle_rewrite_recheck');

// ---------------------------------------------------------------------------
// EC-ROUTE-MAP-007: opt-in cleanup for junk pages left by an EARLIER conversion.
//
// EC-ROUTE-MAP-004/005/006 stop the junk being generated, but a customer who
// already converted has those pages in their database: /src/pages/about,
// /src/partials/header, /wordpress-export/... — 31 of 53 pages on the site that
// prompted this work. Reconverting ships a clean theme and a smaller routes.json,
// but it cannot remove pages WordPress has already created, and nothing in the
// theme deletes them (correctly — see EC-SAFE-001/002). They stay published and
// indexable, which is the visible half of the original complaint.
//
// So: offer, never act. This lists candidates and does nothing at all until the
// owner clicks. The action sets them to Draft — never Trash, which auto-purges
// after EMPTY_TRASH_DAYS and is therefore only temporarily reversible, and never
// a delete. Draft still removes the page from the front end, which is the whole
// of what was asked for.
// ---------------------------------------------------------------------------
function wpconvert_orphan_cleanup_candidates($limit = 200) {
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    if (!file_exists($routes_path)) return array();
    $routes = json_decode(file_get_contents($routes_path), true);
    if (!is_array($routes) || empty($routes)) return array();

    // Slugs the CURRENT conversion still declares. Compared on the leaf segment
    // because that is what becomes the page's post_name.
    $valid_slugs = array();
    foreach ($routes as $route => $_data) {
        $clean = trim((string) $route, '/');
        if ($clean === '') continue;
        $parts = explode('/', $clean);
        $leaf = sanitize_title(end($parts));
        if ($leaf !== '') $valid_slugs[$leaf] = true;
    }
    // A route file that produced no usable slugs means something is wrong with
    // the theme rather than with the customer's pages. Offer nothing.
    if (empty($valid_slugs)) return array();

    $front_id = (int) get_option('page_on_front');
    $posts_id = (int) get_option('page_for_posts');

    // EC-PERF-001: bounded. Never walk an unbounded page table on an admin request.
    $pages = get_posts(array(
        'post_type'        => 'page',
        'post_status'      => 'publish',
        'numberposts'      => $limit,
        'orderby'          => 'ID',
        'order'            => 'ASC',
        'suppress_filters' => false,
    ));
    if (!is_array($pages)) return array();

    $orphans = array();
    foreach ($pages as $pg) {
        if ((int) $pg->ID === $front_id || (int) $pg->ID === $posts_id) continue;
        if (isset($valid_slugs[$pg->post_name])) continue;
        // Only pages we generated. Deliberately the helper and not the
        // _wpconvert_generated meta: that meta is stamped by a wp_insert_post hook
        // at creation time, so pages from an OLDER conversion never carry it and
        // requiring it would make this a no-op for the very customers who need it.
        // The helper also returns false while the page still points at a
        // page-*.php that exists in the theme, so live converted pages are
        // structurally protected.
        if (!wpconvert_is_autogen_stub_page($pg)) continue;
        // Anything the owner has touched is theirs, not ours.
        if ($pg->post_modified_gmt !== $pg->post_date_gmt) continue;
        $orphans[] = $pg;
    }
    return $orphans;
}

function wpconvert_orphan_cleanup_notice() {
    if (!current_user_can('manage_options')) return;
    if (get_option('wpconvert_orphan_cleanup_dismissed')) return;

    $done = get_transient('wpconvert_orphan_cleanup_done');
    if ($done !== false) {
        delete_transient('wpconvert_orphan_cleanup_done');
        echo '<div class="notice notice-success is-dismissible"><p><strong>WPConvert:</strong> ';
        echo esc_html(sprintf('%d leftover page(s) moved to Drafts. Nothing was deleted — you can restore any of them from Pages → Drafts.', (int) $done));
        echo '</p></div>';
    }

    // The scan touches the database, and admin_notices fires on every admin
    // screen, so cache it. Keyed on the route set: a reconversion changes
    // routes.json, and the cached list must not outlive the answer it was
    // computed from. (The ACTION always recomputes from scratch, so a stale cache
    // could only ever mislead the display, never draft the wrong page.)
    $routes_path = get_template_directory() . '/assets/data/routes.json';
    $routes_sig = file_exists($routes_path) ? md5_file($routes_path) : 'noroutes';
    $cache = get_transient('wpconvert_orphan_cleanup_cache');
    if (!is_array($cache) || !isset($cache['sig']) || $cache['sig'] !== $routes_sig) {
        $rows = array();
        foreach (wpconvert_orphan_cleanup_candidates() as $pg) {
            $rows[] = array('id' => (int) $pg->ID, 'title' => $pg->post_title, 'slug' => $pg->post_name);
        }
        $cache = array('sig' => $routes_sig, 'rows' => $rows);
        set_transient('wpconvert_orphan_cleanup_cache', $cache, 12 * HOUR_IN_SECONDS);
    }
    $cached = isset($cache['rows']) && is_array($cache['rows']) ? $cache['rows'] : array();
    if (empty($cached)) return;

    $count = count($cached);
    $clean_url = wp_nonce_url(
        add_query_arg('wpconvert_orphan_cleanup', 'draft', admin_url('edit.php?post_type=page')),
        'wpconvert_orphan_cleanup'
    );
    $dismiss_url = wp_nonce_url(
        add_query_arg('wpconvert_orphan_cleanup', 'dismiss', admin_url('edit.php?post_type=page')),
        'wpconvert_orphan_cleanup'
    );

    echo '<div class="notice notice-warning">';
    echo '<p><strong>WPConvert:</strong> ' . esc_html(sprintf(
        '%d page(s) were created by an earlier conversion and are no longer part of this site. They are still published and can show up in search results.',
        $count
    )) . '</p>';
    echo '<p style="max-height:9em;overflow:auto;margin:0 0 .8em"><code>';
    $names = array();
    foreach ($cached as $row) {
        $names[] = esc_html($row['title'] !== '' ? $row['title'] : $row['slug']) . ' <span style="opacity:.6">(/' . esc_html($row['slug']) . ')</span>';
    }
    echo implode(' &middot; ', $names);
    echo '</code></p>';
    echo '<p>Only pages WPConvert created and that you have never edited are listed. They will be moved to <strong>Drafts</strong>, not deleted, so you can restore any of them at any time.</p>';
    echo '<p><a class="button button-primary" href="' . esc_url($clean_url) . '">Move ' . (int) $count . ' page(s) to Drafts</a> ';
    echo '<a class="button" href="' . esc_url($dismiss_url) . '">Keep them &mdash; don&rsquo;t ask again</a></p>';
    echo '</div>';
}
add_action('admin_notices', 'wpconvert_orphan_cleanup_notice');

function wpconvert_handle_orphan_cleanup() {
    if (!isset($_GET['wpconvert_orphan_cleanup'])) return;
    if (!current_user_can('manage_options')) return;
    check_admin_referer('wpconvert_orphan_cleanup');

    $action = sanitize_text_field(wp_unslash($_GET['wpconvert_orphan_cleanup']));
    if ($action === 'dismiss') {
        update_option('wpconvert_orphan_cleanup_dismissed', 1);
    } elseif ($action === 'draft') {
        $drafted = 0;
        foreach (wpconvert_orphan_cleanup_candidates() as $pg) {
            // Draft, never Trash: Trash auto-purges after EMPTY_TRASH_DAYS, a
            // draft survives until the owner decides.
            $ok = wp_update_post(array('ID' => $pg->ID, 'post_status' => 'draft'), true);
            if (!is_wp_error($ok)) $drafted++;
        }
        set_transient('wpconvert_orphan_cleanup_done', $drafted, 5 * MINUTE_IN_SECONDS);
    }

    delete_transient('wpconvert_orphan_cleanup_cache');
    wp_safe_redirect(remove_query_arg(array('wpconvert_orphan_cleanup', '_wpnonce')));
    exit;
}
add_action('admin_init', 'wpconvert_handle_orphan_cleanup');

/**
 * Universal Smooth Scroll for Anchor Links
 * Handles #anchor links throughout the site with smooth scrolling behavior
 * Auto-generated by WPConvert for ALL converted sites
 */
function wpconvert_smooth_scroll_enqueue() {
    ?>
    <script id="wpconvert-smooth-scroll">
    (function() {
        'use strict';
        
        // Configuration
        const CONFIG = {
            offset: 80,              // Offset from top (accounts for sticky headers)
            duration: 800,           // Scroll duration in ms
            easing: 'easeInOutCubic' // Easing function
        };
        
        // Easing functions
        const easings = {
            linear: function(t) { return t; },
            easeInOutCubic: function(t) { 
                return t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1; 
            },
            easeInOutQuad: function(t) {
                return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
            }
        };
        
        /**
         * Smooth scroll to target element
         */
        function smoothScrollTo(target, duration, offset, easing) {
            const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - offset;
            const startPosition = window.pageYOffset;
            const distance = targetPosition - startPosition;
            const easingFunction = easings[easing] || easings.easeInOutCubic;
            let startTime = null;
            
            function animation(currentTime) {
                if (startTime === null) startTime = currentTime;
                const timeElapsed = currentTime - startTime;
                const progress = Math.min(timeElapsed / duration, 1);
                const ease = easingFunction(progress);
                
                window.scrollTo(0, startPosition + distance * ease);
                
                if (timeElapsed < duration) {
                    requestAnimationFrame(animation);
                } else {
                    // Update URL hash without jumping
                    if (target.id && window.history && window.history.pushState) {
                        window.history.pushState(null, null, '#' + target.id);
                    }
                }
            }
            
            requestAnimationFrame(animation);
        }
        
        /**
         * Calculate header offset dynamically
         * Accounts for sticky/fixed headers
         */
        function getHeaderOffset() {
            const fixedElements = document.querySelectorAll('header, nav, [class*="sticky"], [class*="fixed"]');
            let maxHeight = CONFIG.offset;
            
            fixedElements.forEach(function(el) {
                const styles = window.getComputedStyle(el);
                const position = styles.position;
                
                if (position === 'fixed' || position === 'sticky') {
                    const rect = el.getBoundingClientRect();
                    // Only consider elements at top of page
                    if (rect.top < 100) {
                        maxHeight = Math.max(maxHeight, rect.height + 20);
                    }
                }
            });
            
            return maxHeight;
        }
        
        /**
         * Find target element by ID or data attribute
         * Handles cases where IDs were modified during conversion
         */
        function findTarget(hash) {
            // Remove # from hash
            const id = hash.replace('#', '');
            if (!id) return null;
            
            // Try direct ID match
            let target = document.getElementById(id);
            if (target) return target;
            
            // Try case-insensitive match (IDs might have been lowercased)
            const elements = document.querySelectorAll('[id]');
            for (let i = 0; i < elements.length; i++) {
                if (elements[i].id.toLowerCase() === id.toLowerCase()) {
                    return elements[i];
                }
            }
            
            // Try data-section attribute (common in converted SPAs)
            target = document.querySelector('[data-section="' + id + '"]');
            if (target) return target;
            
            // Try finding by heading text content (last resort)
            const headings = document.querySelectorAll('h1, h2, h3');
            const searchText = id.replace(/-/g, ' ').toLowerCase();
            for (let i = 0; i < headings.length; i++) {
                const headingText = headings[i].textContent.toLowerCase();
                if (headingText.includes(searchText)) {
                    return headings[i];
                }
            }
            
            return null;
        }
        
        /**
         * Handle anchor link clicks
         */
        function handleAnchorClick(e) {
            // EC-EDITOR-005: Skip when WPConvert editor is active to avoid scroll conflict
            if (window.location.search.indexOf('wpc_edit=1') !== -1) return;

            const href = this.getAttribute('href');
            
            // Only handle anchor links (starting with #)
            if (!href || !href.startsWith('#')) return;
            
            // Skip empty hashes
            if (href === '#' || href === '#!') return;

            // EC-NAV-285: Never hijack Bootstrap/Mobirise interactive controls that
            // happen to use an in-page href. Carousel/lightbox prev-next controls are
            // <a class="carousel-control-next" data-bs-slide="next" href="#lb-xxxx">, and
            // collapse/modal/tab/dropdown togglers are <a data-bs-toggle="..." href="#id">.
            // The universal handler would preventDefault + smooth-scroll the page to that
            // target, so any control click — including a gallery that auto-advances every
            // few seconds via a synthetic click — yanks the page away ("auto-scrolls to
            // the top"). Let Bootstrap own these; only real in-page nav links scroll.
            if (this.matches && this.matches(
                '.carousel-control, .carousel-control-next, .carousel-control-prev, ' +
                '[data-bs-slide], [data-slide], [data-bs-slide-to], [data-slide-to], ' +
                '[data-bs-toggle], [data-toggle], [data-bs-dismiss], [data-dismiss], ' +
                '.dropdown-toggle, .navbar-toggler'
            )) {
                return;
            }

            const target = findTarget(href);
            
            if (target) {
                e.preventDefault();
                
                // Get dynamic header offset
                const offset = getHeaderOffset();
                
                // Smooth scroll to target
                smoothScrollTo(target, CONFIG.duration, offset, CONFIG.easing);
                
                // Update focus for accessibility
                target.setAttribute('tabindex', '-1');
                target.focus();
            } else {
                // Target not found - log warning but don't break
                console.warn('WPConvert Smooth Scroll: Target not found for', href);
            }
        }
        
        /**
         * Initialize smooth scroll on page load
         */
        function init() {
            // Handle all anchor links
            const anchorLinks = document.querySelectorAll('a[href^="#"]');
            anchorLinks.forEach(function(link) {
                link.addEventListener('click', handleAnchorClick);
            });
            
            // CONSERVATIVE FALLBACK: Handle buttons with explicit data attributes
            // Only activates if button has data-scroll-to or similar attributes
            const scrollButtons = document.querySelectorAll('button[data-scroll-to], button[data-anchor]');
            scrollButtons.forEach(function(btn) {
                const scrollTarget = btn.getAttribute('data-scroll-to') || btn.getAttribute('data-anchor');
                if (scrollTarget) {
                    btn.addEventListener('click', function(e) {
                        const targetId = scrollTarget.replace('#', '');
                        const target = document.getElementById(targetId);
                        if (target) {
                            e.preventDefault();
                            const offset = getHeaderOffset();
                            smoothScrollTo(target, CONFIG.duration, offset, CONFIG.easing);
                            console.log('WPConvert Smooth Scroll: Button scrolled to #' + targetId);
                        }
                    });
                }
            });
            
            // Handle hash in URL on page load
            if (window.location.hash) {
                // Small delay to ensure page is fully loaded
                setTimeout(function() {
                    const target = findTarget(window.location.hash);
                    if (target) {
                        const offset = getHeaderOffset();
                        smoothScrollTo(target, CONFIG.duration, offset, CONFIG.easing);
                    }
                }, 100);
            }
        }
        
        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
        
    })();
    </script>
    <?php
}
add_action('wp_footer', 'wpconvert_smooth_scroll_enqueue', 999);

/**
 * EC-SCROLL-003: Back-to-top FloatingConsole — restore React scroll listener + click.
 * Auto-generated by WPConvert for converted sites with aria-label="Back to top" FABs.
 */
function wpconvert_back_to_top_enqueue() {
    ?>
    <script id="wpconvert-back-to-top">
    (function(){
  'use strict';
  var THRESHOLD = 300;
  function findButtons(){
    return Array.prototype.slice.call(
      document.querySelectorAll('[data-wpconvert-back-to-top]')
    );
  }
  function setVisible(btn, visible){
    if(!btn) return;
    btn.classList.toggle('opacity-0', !visible);
    btn.classList.toggle('pointer-events-none', !visible);
    if(visible) btn.removeAttribute('aria-hidden');
    else btn.setAttribute('aria-hidden','true');
  }
  function wire(){
    var buttons = findButtons();
    if(!buttons.length) return;
    buttons.forEach(function(btn){
      if(btn.getAttribute('data-wpconvert-btt-wired') === '1') return;
      btn.setAttribute('data-wpconvert-btt-wired','1');
      btn.setAttribute('type','button');
      if(!btn.getAttribute('onclick')){
        btn.addEventListener('click', function(e){
          e.preventDefault();
          window.scrollTo({ top: 0, behavior: 'smooth' });
        });
      }
    });
    function sync(){
      var show = window.scrollY > THRESHOLD;
      buttons.forEach(function(btn){ setVisible(btn, show); });
    }
    sync();
    window.addEventListener('scroll', sync, { passive: true });
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', wire);
  } else {
    wire();
  }
})();
    </script>
    <?php
}
add_action('wp_footer', 'wpconvert_back_to_top_enqueue', 998);

