/**
 * Universal Accordion/FAQ Toggle Functionality
 * Dynamically detects and enables accordion patterns from any converted website
 */
function wpconvert_accordion_enqueue() {
    ?>
    <script>
    (function() {
        'use strict';
        
        // EC-ACCORDION-003: Find the content panel for an accordion button.
        // Handles two DOM patterns:
        // 1. Direct sibling: <button/> <div class="overflow-hidden">  (custom accordions)
        // 2. Header-wrapped: <h3><button/></h3> <div role="region">   (Radix UI / shadcn)
        //
        // EC-ACCORDION-012: An accordion content panel always comes AFTER its
        // trigger and is real content (not an img/picture/video-only wrapper).
        // Otherwise we mis-detect image-card layouts where the CTA button is
        // the LAST child of the card (MenuCard "+ Tilfoj"): the old
        // third-branch loop returned the image wrapper at the TOP of the
        // card and the init collapsed it to height:0.
        function isImageOnlyPanel(el) {
            if (!el || !el.children) return false;
            var hasText = (el.textContent || '').replace(/\s+/g, '').length > 0;
            if (hasText) return false;
            var kids = el.children;
            if (!kids.length) return false;
            for (var i = 0; i < kids.length; i++) {
                var tag = kids[i].tagName;
                if (tag !== 'IMG' && tag !== 'PICTURE' && tag !== 'VIDEO' && tag !== 'SOURCE') {
                    return false;
                }
            }
            return true;
        }
        function findContentPanel(btn) {
            // EC-ACCORDION-024: the author's explicit aria-controls link wins over
            // sibling heuristics — but only for NON-Radix targets (Radix content
            // has role="region"/data-state and is owned by the jQuery handler).
            var ac = btn.getAttribute && btn.getAttribute('aria-controls');
            if (ac) {
                var acTarget = document.getElementById(ac);
                if (acTarget && acTarget.tagName === 'DIV' &&
                    acTarget.getAttribute('role') !== 'region' &&
                    !acTarget.hasAttribute('data-state') &&
                    !isImageOnlyPanel(acTarget)) {
                    return acTarget;
                }
            }

            var sibling = btn.nextElementSibling;
            if (sibling && sibling.tagName === 'DIV') {
                if (isImageOnlyPanel(sibling)) return null;
                return sibling;
            }
            
            var parent = btn.parentElement;
            if (parent && /^H[1-6]$/.test(parent.tagName)) {
                var parentSibling = parent.nextElementSibling;
                if (parentSibling && parentSibling.tagName === 'DIV') {
                    if (isImageOnlyPanel(parentSibling)) return null;
                    return parentSibling;
                }
            }
            // EC-ACCORDION-012: third branch -- button has no nextElementSibling.
            // The original intent (button is first child of wrapper, wrapper
            // contains a hidden div) is enforced by ONLY returning DIVs that
            // come AFTER the button in DOM order. Image-only DIVs are skipped.
            if (parent && !sibling) {
                var kids = parent.children;
                var btnIdx = -1;
                for (var k = 0; k < kids.length; k++) {
                    if (kids[k] === btn) { btnIdx = k; break; }
                }
                if (btnIdx >= 0) {
                    for (var j = btnIdx + 1; j < kids.length; j++) {
                        if (kids[j].tagName === 'DIV' && !isImageOnlyPanel(kids[j])) {
                            return kids[j];
                        }
                    }
                }
            }
            return null;
        }

        // EC-ACCORDION-013: Morph a single lucide plus/minus icon to match the
        // accordion's expanded state. Custom React useState FAQs (Galaxy
        // Construction) render ONE icon at a time via isOpen ? <Minus/> : <Plus/>,
        // so the display-swap path (which needs both icons) never fires. We rewrite
        // the icon's class token and its inner <path>s in place. No-op when both
        // icons are present (handled by display-swap) or when no lucide plus/minus
        // icon exists (e.g. chevron-only accordions), keeping other patterns intact.
        function setLucidePlusMinusState(btn, expanded) {
            if (btn.querySelector('.lucide-plus') && btn.querySelector('.lucide-minus')) return false;
            var icon = btn.querySelector('.lucide-plus, .lucide-minus');
            if (!icon) return false;
            var cls = icon.getAttribute('class') || '';
            if (expanded) {
                icon.setAttribute('class', cls.replace(/lucide-plus/g, 'lucide-minus'));
                icon.innerHTML = '<path d="M5 12h14"></path>';
            } else {
                icon.setAttribute('class', cls.replace(/lucide-minus/g, 'lucide-plus'));
                icon.innerHTML = '<path d="M5 12h14"></path><path d="M12 5v14"></path>';
            }
            return true;
        }

        // EC-ACCORDION-015: CSS-drawn plus icons (two perpendicular bars inside a span
        // that rotates 45deg to form an X — Adco FAQ pattern). No lucide SVG involved.
        function setCssPlusRotateState(btn, expanded) {
            var icon = btn.querySelector('span[aria-hidden="true"]');
            if (!icon || !icon.querySelector('span')) {
                var spans = btn.querySelectorAll('span');
                icon = spans.length ? spans[spans.length - 1] : null;
            }
            if (!icon || !icon.querySelector('span')) return false;
            if (expanded) {
                icon.classList.remove('rotate-0');
                icon.classList.add('rotate-45');
            } else {
                icon.classList.remove('rotate-45');
                icon.classList.add('rotate-0');
            }
            return true;
        }

        // EC-ACCORDION-019: Text "+/−" toggle indicator. A React useState FAQ that renders
        // {isOpen ? "—" : "+"} inside a <span> (The Hollywood Effect) has NO lucide SVG, NO
        // chevron, and NO CSS-rotate span — so none of the icon handlers above can see it,
        // and the glyph never changed on toggle. Swap the glyph's text directly. The exact
        // plus/minus characters the site uses (e.g. "+" and an em dash "—") are resolved once
        // from the live DOM so we reuse them verbatim instead of guessing.
        var __wpcFaqPlusGlyph = '+';
        var __wpcFaqMinusGlyph = '−';
        var __wpcFaqGlyphsResolved = false;
        function isFaqPlusGlyph(t) { return t === '+'; }
        function isFaqMinusGlyph(t) {
            return t === '−' || t === '—' || t === '–' || t === '-';
        }
        function findTextToggleIndicator(btn) {
            if (!btn || !btn.querySelectorAll) return null;
            var els = btn.querySelectorAll('span, i, em, b, strong, div');
            for (var k = els.length - 1; k >= 0; k--) {
                var e = els[k];
                if (e.children && e.children.length) continue; // leaf only
                var t = (e.textContent || '').trim();
                if (t.length === 1 && (isFaqPlusGlyph(t) || isFaqMinusGlyph(t))) return e;
            }
            return null;
        }
        function resolveFaqToggleGlyphs() {
            if (__wpcFaqGlyphsResolved) return;
            __wpcFaqGlyphsResolved = true;
            try {
                var btns = document.querySelectorAll(
                    'section[id="faq"] button, [id="faq"] button, button[data-wpconvert-accordion]'
                );
                for (var i = 0; i < btns.length; i++) {
                    var ind = findTextToggleIndicator(btns[i]);
                    if (!ind) continue;
                    var t = (ind.textContent || '').trim();
                    if (isFaqPlusGlyph(t)) __wpcFaqPlusGlyph = t;
                    else if (isFaqMinusGlyph(t)) __wpcFaqMinusGlyph = t;
                }
            } catch (e) {}
        }
        function setTextPlusMinusState(btn, expanded) {
            var ind = findTextToggleIndicator(btn);
            if (!ind) return false;
            resolveFaqToggleGlyphs();
            ind.textContent = expanded ? __wpcFaqMinusGlyph : __wpcFaqPlusGlyph;
            return true;
        }

        // EC-ACCORDION-014: The sibling group container for an accordion item.
        // React single-open FAQs (useState<number|null>) render items as siblings
        // inside one <ul>/<ol>/<dl> or a shared wrapper. Grouping by the nearest
        // such container keeps "open one closes the others" scoped to ONE
        // accordion — never unrelated accordions elsewhere on the page.
        function findAccordionGroup(el) {
            if (!el) return null;
            var group = el.closest('ul, ol, dl, [role="list"]');
            if (group) return group;
            if (el.parentElement && el.parentElement.parentElement) return el.parentElement.parentElement;
            return el.parentElement || null;
        }

        // EC-ACCORDION-014: Collapse a grid-rows accordion item — used to close
        // sibling items in single-open groups. Mirrors the manual "close" path.
        function collapseGridAccordionItem(otherBtn) {
            var oc = findContentPanel(otherBtn);
            if (oc && oc.hasAttribute('data-wpconvert-grid-accordion')) {
                oc.style.gridTemplateRows = '0fr';
                oc.style.opacity = '0';
                oc.classList.remove('opacity-100');
                oc.classList.add('opacity-0');
            }
            otherBtn.setAttribute('data-expanded', 'false');
            otherBtn.setAttribute('aria-expanded', 'false');
            setLucidePlusMinusState(otherBtn, false);
            setCssPlusRotateState(otherBtn, false);
            setTextPlusMinusState(otherBtn, false); // EC-ACCORDION-019: text +/− indicator
            var chev = otherBtn.querySelector('.lucide-chevron-down, .lucide-chevron-up, [class*="chevron"]');
            if (chev) chev.style.transform = 'rotate(0deg)';
        }

        function init() {
            var buttons = document.querySelectorAll('button');
            var accordionsInitialized = 0;
            
            buttons.forEach(function(btn) {
                // EC-ACCORDION-012: Image-card CTA buttons (e.g. MenuCard
                // + Tilfoj) are explicitly stamped at build time as
                // non-accordion triggers. Honour the marker here so the
                // accordion init can never wire them up regardless of
                // what findContentPanel would otherwise return.
                if (btn.getAttribute('data-wpc-no-accordion-trigger') === '1') return;

                // EC-ACCORDION-007: Skip buttons with aria-controls pointing to existing
                // Radix content. The jQuery accordion handler already manages these via
                // aria-controls → role="region". Attaching a second handler on the
                // injected data-wpc-faq-answer div would show duplicate answers.
                // EC-ACCORDION-024: only skip when the target is genuinely Radix-managed
                // (role="region" or its own data-state). Non-Radix grid-rows panels
                // (Nexora audit trail) also carry aria-controls but NEED the vanilla
                // wiring — the blanket skip left them frozen open with no handler.
                var ariaCtrl = btn.getAttribute('aria-controls');
                var ctrlTarget = ariaCtrl ? document.getElementById(ariaCtrl) : null;
                if (ctrlTarget && (ctrlTarget.getAttribute('role') === 'region' || ctrlTarget.hasAttribute('data-state'))) return;

                var sibling = findContentPanel(btn);
                if (!sibling) return;

                // EC-NAV-283: Never treat a Bootstrap/Mobirise responsive navbar as an
                // accordion. The .navbar-collapse menu carries the collapse class
                // (matched by the /overflow-hidden|collapse/i sniff below) and its
                // .navbar-toggler (data-toggle/data-bs-toggle="collapse") is its own
                // collapse trigger, handled by Bootstrap + navbar-dropdown.js. Wiring the
                // accordion handler onto it force-collapses the DESKTOP menu to
                // height:0/opacity:0 (items "appear then disappear" on load) AND adds a
                // SECOND click handler that fights the native toggle (hamburger needs two
                // taps and shows the wrong open/closed icon). Leave the native navbar to
                // its own JS.
                if ((btn.matches && btn.matches('.navbar-toggler, [data-toggle="collapse"], [data-bs-toggle="collapse"]')) ||
                    (sibling.classList && sibling.classList.contains('navbar-collapse'))) {
                    return;
                }

                var siblingClasses = sibling.className || '';
                var siblingStyle = sibling.getAttribute('style') || '';
                var hasHidden = sibling.hasAttribute('hidden');
                var hasRoleRegion = sibling.getAttribute('role') === 'region';
                
                // EC-ACCORDION-005: Also check first child for overflow-hidden (grid-rows pattern)
                var firstChild = sibling.firstElementChild;
                var childClasses = firstChild ? (firstChild.className || '') : '';
                
                // Detect accordion pattern:
                // 1. Sibling has overflow-hidden class (common accordion pattern)
                // 2. Sibling has height: 0 or height: auto in inline style
                // 3. Sibling has opacity: 0 or opacity: 1 in inline style
                // EC-ACCORDION-003: Also detect Radix UI pattern (role="region" + hidden + data-state)
                // EC-ACCORDION-005: Tailwind grid-rows-[0fr] pattern (sibling is grid, child has overflow-hidden)
                var isGridRowsAccordion = /grid-rows-\[0fr\]|grid-rows-\[1fr\]/.test(siblingClasses) || /grid-template-rows:\s*[01]fr/i.test(siblingStyle); // EC-ACCORDION-020: also inline grid-template-rows
                var hasChildOverflowHidden = /overflow-hidden/.test(childClasses);
                
                var isFaqAnswer = sibling.hasAttribute('data-wpc-faq-answer');
                var isAccordion = /overflow-hidden|collapse/i.test(siblingClasses) ||
                                  /height:[ ]*(0|auto)|opacity:[ ]*(0|1)/i.test(siblingStyle) ||
                                  (hasRoleRegion && (hasHidden || sibling.hasAttribute('data-state'))) ||
                                  (isGridRowsAccordion && hasChildOverflowHidden) ||
                                  isFaqAnswer;
                
                if (!isAccordion) return;
                
                // Check current state
                var isExpanded = false;
                if (isGridRowsAccordion) {
                    isExpanded = /grid-rows-\[1fr\]/.test(siblingClasses) || /grid-template-rows:\s*1fr/i.test(siblingStyle); // EC-ACCORDION-020
                    // EC-ACCORDION-024: the snapshot close pass stamps the BUTTON
                    // aria-expanded="false" but could not always re-collapse a
                    // grid-rows panel captured open. The button attribute is the
                    // source of truth (mirrors EC-ACCORDION-022) — honouring it
                    // here collapses frozen-open panels at init.
                    var btnExpandedAttr = btn.getAttribute('aria-expanded');
                    if (btnExpandedAttr === 'false') isExpanded = false;
