                } else if (hasHidden || /display:[ ]*none/i.test(siblingStyle)) {
                    isExpanded = false;
                } else if (/height:[ ]*auto|opacity:[ ]*1/i.test(siblingStyle) && 
                           !/height:[ ]*0|opacity:[ ]*0/i.test(siblingStyle)) {
                    isExpanded = true;
                }
                
                btn.setAttribute('data-wpconvert-accordion', 'true');
                btn.setAttribute('data-expanded', isExpanded ? 'true' : 'false');
                sibling.setAttribute('data-wpconvert-accordion-content', 'true');
                
                // EC-ACCORDION-005: Grid-rows accordion uses grid-template-rows for animation
                if (isGridRowsAccordion) {
                    sibling.setAttribute('data-wpconvert-grid-accordion', 'true');
                    sibling.style.transition = 'grid-template-rows 0.3s ease, opacity 0.3s ease';
                    // EC-ACCORDION-014: drive opacity inline so the captured
                    // opacity-0 / opacity-100 classes can't leave an opened panel
                    // invisible, and keep aria-expanded in sync (source of truth
                    // for the jQuery handler, which we also guard against below).
                    if (!isExpanded) {
                        sibling.style.gridTemplateRows = '0fr';
                        sibling.style.opacity = '0';
                    } else {
                        sibling.style.gridTemplateRows = '1fr';
                        sibling.style.opacity = '1';
                    }
                    btn.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
                    setCssPlusRotateState(btn, isExpanded);
                } else {
                    // EC-ACCORDION-003: Remove hidden attribute and display:none so CSS can control visibility.
                    // The accordion starts collapsed via height:0 + opacity:0 instead.
                    sibling.removeAttribute('hidden');
                    sibling.style.display = '';
                    
                    sibling.style.overflow = 'hidden';
                    sibling.style.transition = 'height 0.3s ease, opacity 0.3s ease';
                    
                    // EC-ACCORDION-004: Tailwind max-h-0 class sets max-height:0px which
                    // blocks expansion regardless of inline height. Override with a
                    // large value instead of 'none' — some browsers treat 'none' (the
                    // initial value) as removing the inline declaration, letting the
                    // class rule win.
                    if (/max-h-/.test(siblingClasses)) {
                        sibling.style.maxHeight = '9999px';
                    }
                    
                    if (!isExpanded) {
                        sibling.style.height = '0px';
                        sibling.style.opacity = '0';
                    } else {
                        sibling.style.height = 'auto';
                        sibling.style.opacity = '1';
                    }
                }
                
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    
                    var currentlyExpanded = btn.getAttribute('data-expanded') === 'true';
                    var content = findContentPanel(btn);
                    if (!content) return;
                    
                    // EC-ACCORDION-005: Grid-rows toggle
                    if (content.hasAttribute('data-wpconvert-grid-accordion')) {
                        if (currentlyExpanded) {
                            content.style.gridTemplateRows = '0fr';
                            content.style.opacity = '0';
                            content.classList.remove('opacity-100');
                            content.classList.add('opacity-0');
