                            // open items first (matches React useState FAQs).
                            var grp = findAccordionGroup(btn);
                            if (grp && grp.getAttribute('data-wpc-accordion-single') === '1') {
                                grp.querySelectorAll('button[data-wpconvert-accordion]').forEach(function(ob) {
                                    if (ob !== btn && ob.getAttribute('data-expanded') === 'true') {
                                        var ocp = findContentPanel(ob);
                                        if (ocp && ocp.hasAttribute('data-wpconvert-grid-accordion')) collapseGridAccordionItem(ob);
                                    }
                                });
                            }
                            content.style.gridTemplateRows = '1fr';
                            content.style.opacity = '1';
                            content.classList.remove('opacity-0');
                            content.classList.add('opacity-100');
