                        var targetHeight = content.scrollHeight;
                        if (!targetHeight) {
                            content.style.transition = 'none';
                            content.style.height = 'auto';
                            content.style.maxHeight = '9999px';
                            content.style.opacity = '0';
                            targetHeight = content.scrollHeight || content.offsetHeight;
                            content.style.height = '0px';
                            content.offsetHeight; // force reflow
                            content.style.transition = 'height 0.3s ease, opacity 0.3s ease';
                        }
                        if (targetHeight > 0) {
                            content.style.height = targetHeight + 'px';
                        } else {
                            content.style.height = 'auto';
                        }
                        content.style.opacity = '1';
                        btn.setAttribute('data-expanded', 'true');
                        
                        setTimeout(function() {
                            if (btn.getAttribute('data-expanded') === 'true') {
                                content.style.height = 'auto';
                            }
                        }, 300);
                    }
                    
                    var plusIcon = btn.querySelector('.lucide-plus, [class*="plus"]');
                    var minusIcon = btn.querySelector('.lucide-minus, [class*="minus"]');
                    
                    if (plusIcon && minusIcon) {
                        if (currentlyExpanded) {
                            plusIcon.style.display = '';
                            minusIcon.style.display = 'none';
                        } else {
                            plusIcon.style.display = 'none';
                            minusIcon.style.display = '';
                        }
                    } else {
                        // EC-ACCORDION-013: single-icon useState pattern
                        // (isOpen ? <Minus/> : <Plus/>) — only ONE lucide icon
                        // exists, so morph it between plus and minus.
                        setLucidePlusMinusState(btn, !currentlyExpanded);
                    }
                    
                    var chevron = btn.querySelector('.lucide-chevron-down, .lucide-chevron-up, [class*="chevron"]');
                    if (chevron) {
                        chevron.style.transition = 'transform 0.3s ease';
                        chevron.style.transform = currentlyExpanded ? 'rotate(0deg)' : 'rotate(180deg)';
                    }

                    // EC-ACCORDION-019: swap a text "+/−" indicator (no-op if none present).
                    setTextPlusMinusState(btn, !currentlyExpanded);
                });
                
                var plusIcon = btn.querySelector('.lucide-plus, [class*="plus"]');
                var minusIcon = btn.querySelector('.lucide-minus, [class*="minus"]');
                if (plusIcon && minusIcon) {
                    if (isExpanded) {
                        plusIcon.style.display = 'none';
                        minusIcon.style.display = '';
                    } else {
                        plusIcon.style.display = '';
                        minusIcon.style.display = 'none';
                    }
                } else {
                    // EC-ACCORDION-013: single-icon pattern — sync the lone
                    // lucide plus/minus icon to the initial expanded state.
                    setLucidePlusMinusState(btn, isExpanded);
                }

                // EC-ACCORDION-019: sync a text "+/−" indicator to the initial state
                // (no-op if the button has no such glyph).
                setTextPlusMinusState(btn, isExpanded);
                
                accordionsInitialized++;
            });

            // EC-ACCORDION-014: Detect single-open accordion groups. React FAQs
            // built with useState<number|null> keep exactly ONE panel open at a
            // time. We only mirror that when the captured DOM proves the intent:
            // a group whose grid-rows items (>=2) have EXACTLY ONE initially
            // expanded. Groups with zero or multiple open keep the default
            // multi-open behaviour, so existing multi-open accordions/FAQs are
            // never changed.
            try {
                var gridPanels = document.querySelectorAll('[data-wpconvert-grid-accordion]');
                var seenGroups = [];
                gridPanels.forEach(function(panel) {
                    var btnForPanel = panel.parentElement ? panel.parentElement.querySelector('button[data-wpconvert-accordion]') : null;
                    var grp = findAccordionGroup(btnForPanel || panel);
                    if (!grp || seenGroups.indexOf(grp) !== -1) return;
                    seenGroups.push(grp);
                    var items = grp.querySelectorAll('[data-wpconvert-grid-accordion]');
                    if (items.length < 2) return;
                    var openCount = 0;
                    grp.querySelectorAll('button[data-wpconvert-accordion]').forEach(function(b) {
                        var cp = findContentPanel(b);
                        if (cp && cp.hasAttribute('data-wpconvert-grid-accordion') && b.getAttribute('data-expanded') === 'true') openCount++;
                    });
                    if (openCount === 1) grp.setAttribute('data-wpc-accordion-single', '1');
                });
            } catch (e) {}

            if (accordionsInitialized > 0) {
                console.log('WPConvert Accordion: Initialized ' + accordionsInitialized + ' accordion(s)');
            }
            
            // EC-ACCORDION-007: Enhance <details>/<summary> elements for consistent FAQ styling
            // Sub-pages may have FAQ sections converted to native <details>/<summary>.
            // Add animated +/- icon toggle and smooth open/close transitions.
            var detailsEnhanced = 0;
            document.querySelectorAll('details').forEach(function(det) {
                if (det.hasAttribute('data-wpc-enhanced')) return;
                det.setAttribute('data-wpc-enhanced', 'true');
                var summary = det.querySelector('summary');
                if (!summary) return;
                // EC-ACCORDION-017: If the source CSS already renders a toggle
                // marker via a ::before/::after pseudo-element (e.g. a
                // summary::after content of "+" plus a details[open] rotate),
                // injecting our own span icon would DOUBLE the marker — the user
                // sees two "+" (and a "+" beside a rotated half-"x") on every FAQ
                // row (KaliHub user report). Detect the CSS-generated marker and
                // leave the toggle entirely to the source CSS, which already
                // animates the open/closed state.
                //
                // EC-ACCORDION-017b: the marker is NOT always on the <summary>
                // itself. Editorial/serif templates (e.g. the Idle "Fresh New"
                // site) draw the +/- on a dedicated decorative CHILD span
                //   <summary>Question<span class="pm"></span></summary>
                // whose ::before/::after paint two positioned background bars
                // (a "+") with an EMPTY-STRING content value, not a "+" glyph.
                // The original guard only looked at summary::before/::after AND
                // only matched a text glyph, so it missed this shape and appended
                // a second toggle → two "+" per FAQ row again. Detect a marker on
                // the summary OR on any decorative (text-empty) child, and treat
                // an empty-string pseudo content value as a geometric marker too.
                function wpcSummaryPseudoIsMarker(el, pe) {
                    try {
                        var c = window.getComputedStyle(el, pe).getPropertyValue('content');
                        if (!c || c === 'none' || c === 'normal') return false;
                        // Text-glyph marker: +, −, ×, ✕, ✖, x, -
                        if (/[+−×✕✖x-]/i.test(c)) return true;
                        // Geometric marker: an empty-string content ("") that a
                        // decorative element paints as bars/shape via background
                        // or border (the "+"/"−" is drawn, not typed).
                        var stripped = c.replace(/^s*["']|["']s*$/g, '');
                        return stripped === '';
                    } catch (e) { return false; }
                }
                var hasCssToggleMarker =
                    wpcSummaryPseudoIsMarker(summary, '::before') ||
                    wpcSummaryPseudoIsMarker(summary, '::after');
                if (!hasCssToggleMarker) {
                    // A dedicated marker lives on a text-empty child (e.g. .pm).
                    var wpcMarkerKids = summary.querySelectorAll('*');
                    for (var wpcMk = 0; wpcMk < wpcMarkerKids.length; wpcMk++) {
                        var wpcKid = wpcMarkerKids[wpcMk];
                        if (wpcKid.textContent && wpcKid.textContent.trim() !== '') continue;
                        if (wpcSummaryPseudoIsMarker(wpcKid, '::before') ||
                            wpcSummaryPseudoIsMarker(wpcKid, '::after')) {
                            hasCssToggleMarker = true;
                            break;
                        }
                    }
                }
                // EC-ACCORDION-026: the marker is not always drawn in CSS. Tailwind/
                // lucide FAQs ship it as a real <svg> chevron after the question text,
                // rotated by the source's own group-open:rotate-180 class:
                //   <summary>Question<svg class="lucide-chevron-down"></svg></summary>
                // Both CSS guards above miss it (an <svg> is text-empty, so 017b
                // inspects it, but its ::before/::after report "none"), so every row got
                // a chevron AND an injected "+" (aileadit.com user report). A graphic
                // that TRAILS the question text is the row's toggle affordance; one that
                // precedes it is a category icon, and the row still needs a marker.
                if (!hasCssToggleMarker) {
                    try {
                        var wpcGraphics = summary.querySelectorAll('svg, img');
                        if (wpcGraphics.length) {
                            var wpcWalk = document.createTreeWalker(summary, NodeFilter.SHOW_TEXT, null);
                            var wpcLastText = null, wpcNode;
                            while ((wpcNode = wpcWalk.nextNode())) {
                                if (wpcNode.nodeValue && wpcNode.nodeValue.trim() !== '') wpcLastText = wpcNode;
                            }
                            if (wpcLastText) {
                                for (var wpcGi = 0; wpcGi < wpcGraphics.length; wpcGi++) {
                                    var wpcPos = wpcLastText.compareDocumentPosition(wpcGraphics[wpcGi]);
                                    if (wpcPos & Node.DOCUMENT_POSITION_FOLLOWING) {
                                        hasCssToggleMarker = true;
                                        break;
                                    }
                                }
                            }
                        }
                    } catch (e) { /* fall through and inject as before */ }
                }
                if (hasCssToggleMarker) {
                    detailsEnhanced++;
                    return;
                }
                // Add toggle icon if not already present
                var toggleSpan = summary.querySelector('.wpc-toggle-icon');
                if (!toggleSpan) {
                    var existingIcon = summary.querySelector('span:last-child');
                    if (existingIcon && /^[+-×]$/.test(existingIcon.textContent.trim())) {
                        toggleSpan = existingIcon;
                        toggleSpan.classList.add('wpc-toggle-icon');
                    } else {
                        toggleSpan = document.createElement('span');
                        toggleSpan.className = 'wpc-toggle-icon';
                        toggleSpan.textContent = '+';
                        toggleSpan.style.cssText = 'margin-left:auto;transition:transform 0.3s ease;font-size:1.25em;';
                        summary.appendChild(toggleSpan);
                    }
                }
                function updateIcon() {
                    if (det.open) {
                        toggleSpan.textContent = toggleSpan.textContent === '+' ? '−' : toggleSpan.textContent;
                        toggleSpan.style.transform = 'rotate(45deg)';
                    } else {
                        toggleSpan.textContent = toggleSpan.textContent === '−' ? '+' : toggleSpan.textContent;
                        toggleSpan.style.transform = 'rotate(0deg)';
                    }
                }
                det.addEventListener('toggle', updateIcon);
                updateIcon();
                detailsEnhanced++;
            });
            if (detailsEnhanced > 0) {
                console.log('WPConvert Accordion: Enhanced ' + detailsEnhanced + ' <details> element(s)');
            }
        }
        
        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
        
    })();
    </script>
    <?php
}
