/**
 * Universal Before/After Image Comparison Slider
 * Dynamically detects and enables before/after slider patterns from any converted website
 */
function wpconvert_comparison_slider_enqueue() {
    ?>
    <script>
    (function() {
        'use strict';
        
        function init() {
            // Find all range inputs that might be comparison sliders
            var rangeInputs = document.querySelectorAll('input[type="range"]');
            var slidersInitialized = 0;
            
            rangeInputs.forEach(function(input) {
                // Look for comparison slider pattern:
                // - Range input inside a container with overlapping elements
                // - Sibling or nearby element with clip-path styling
                var container = input.closest('div[class*="relative"], div[class*="overflow"]');
                if (!container) return;
                
                // Find elements that use clip-path (the "after" reveal layer)
                var clipPathElements = container.querySelectorAll('[style*="clip-path"], [style*="clipPath"]');
                if (clipPathElements.length === 0) return;
                
                // Find the divider line (vertical bar that moves with slider)
                var dividerLine = container.querySelector('[class*="bg-gold"], [class*="bg-primary"], div[style*="left:"]');
                
                // Mark as initialized
                input.setAttribute('data-wpconvert-comparison', 'true');
                
                // Make input visible and interactive
                input.style.opacity = '0';
                input.style.cursor = 'ew-resize';
                input.style.zIndex = '20';
                
                // Add input handler
                input.addEventListener('input', function(e) {
                    var value = e.target.value;
                    
                    // Update clip-path on reveal elements
                    clipPathElements.forEach(function(el) {
                        // clip-path: inset(0 RIGHT% 0 0) - RIGHT is 100 - value
                        el.style.clipPath = 'inset(0 ' + (100 - value) + '% 0 0)';
                    });
                    
                    // Update divider line position
                    if (dividerLine) {
                        dividerLine.style.left = value + '%';
                    }
                });
                
                // Trigger initial positioning based on current value
                input.dispatchEvent(new Event('input'));
                
                slidersInitialized++;
            });

            // ============================================================
            // EC-SLIDER-002: Pointer-drag comparison sliders (NO range input).
            // React before/after components (e.g. Vertex Services) render a
            // container marked cursor-ew-resize with a clip-path reveal layer and
            // a draggable divider handle, wiring mouse/touch handlers in JS that do
            // NOT survive static conversion — so the handle sits frozen at 50% and
            // "does not drag". Re-attach pointer + touch dragging here.
            // ============================================================
            var clipEls = document.querySelectorAll('[style*="clip-path"], [style*="clipPath"]');
            clipEls.forEach(function(clip) {
                var container = clip.closest('[class*="cursor-ew-resize"]');
                if (!container) {
                    // Fallback: nearest positioned ancestor that also holds a handle
                    // (an element positioned via an inline left:% style).
                    var anc = clip.parentElement;
                    while (anc && anc !== document.body) {
                        if (anc.querySelector('[style*="left:"]') &&
                            /relative|overflow/.test(anc.className || '')) { container = anc; break; }
                        anc = anc.parentElement;
                    }
                }
                if (!container) return;
                if (container.querySelector('input[type="range"]')) return; // Strategy 1 owns it
                if (container.hasAttribute('data-wpconvert-comparison-drag')) return;
                container.setAttribute('data-wpconvert-comparison-drag', 'true');
                container.style.cursor = 'ew-resize';
                container.style.userSelect = 'none';

                var revealEls = container.querySelectorAll('[style*="clip-path"], [style*="clipPath"]');
                var handle = container.querySelector('[style*="left:"]');
                var dragging = false;

                function setPos(clientX) {
                    var rect = container.getBoundingClientRect();
                    if (!rect.width) return;
                    var pct = ((clientX - rect.left) / rect.width) * 100;
                    pct = Math.max(2, Math.min(98, pct));
                    revealEls.forEach(function(el) {
                        el.style.clipPath = 'inset(0 ' + (100 - pct) + '% 0 0)';
                        el.style.webkitClipPath = 'inset(0 ' + (100 - pct) + '% 0 0)';
                    });
                    if (handle) handle.style.left = pct + '%';
                }

                container.addEventListener('mousedown', function(e) { dragging = true; setPos(e.clientX); e.preventDefault(); });
                window.addEventListener('mousemove', function(e) { if (dragging) setPos(e.clientX); });
                window.addEventListener('mouseup', function() { dragging = false; });
                container.addEventListener('touchstart', function(e) { if (e.touches && e.touches[0]) setPos(e.touches[0].clientX); }, { passive: true });
                container.addEventListener('touchmove', function(e) { if (e.touches && e.touches[0]) setPos(e.touches[0].clientX); }, { passive: true });

                slidersInitialized++;
            });

            if (slidersInitialized > 0) {
                console.log('WPConvert Comparison Slider: Initialized ' + slidersInitialized + ' slider(s)');
            }
        }
        
        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
        
    })();
    </script>
    <?php
}
