/**
 * EC-VIDEO-001: Universal Video Lightbox for Portfolio/Gallery Cards
 * Detects video cards (play button overlay + thumbnail) and enables click-to-play
 * in a modal lightbox. Supports YouTube, Vimeo, and direct video URLs.
 */
function wpconvert_video_lightbox_enqueue() {
    ?>
    <script id="wpconvert-video-lightbox">
    (function() {
        'use strict';
        
        function getEmbedUrl(rawUrl) {
            var url = (rawUrl || '').trim();
            if (!url || /\bexample\d*\b/i.test(url)) return '';
            
            if (url.indexOf('vimeo.com') !== -1) {
                var vm = url.match(/vimeo\.com\/(?:video\/)?(\d+)/);
                return vm ? 'https://player.vimeo.com/video/' + vm[1] + '?autoplay=1&title=0&byline=0&portrait=0&dnt=1' : '';
            }
            if (url.indexOf('youtube.com') !== -1 || url.indexOf('youtu.be') !== -1) {
                var yt = url.match(/youtu\.be\/([^?&\/]+)/) ||
                         url.match(/[?&]v=([^?&\/]+)/) ||
                         url.match(/youtube\.com\/embed\/([^?&\/]+)/);
                return yt ? 'https://www.youtube-nocookie.com/embed/' + yt[1] + '?autoplay=1&rel=0&modestbranding=1' : '';
            }
            return url;
        }
        
        function createModal() {
            if (document.getElementById('wpconvert-video-modal')) return;
            var overlay = document.createElement('div');
            overlay.id = 'wpconvert-video-modal';
            overlay.style.cssText = 'display:none;position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.85);backdrop-filter:blur(4px);align-items:center;justify-content:center;padding:2rem;';
            overlay.innerHTML = '<div style="position:relative;width:100%;max-width:960px;"><button id="wpconvert-video-close" style="position:absolute;top:-40px;right:0;background:none;border:none;color:#fff;font-size:28px;cursor:pointer;padding:4px 8px;z-index:1;" aria-label="Close video">&times;</button><div style="position:relative;width:100%;padding-top:56.25%;background:#000;border-radius:8px;overflow:hidden;"><iframe id="wpconvert-video-frame" style="position:absolute;top:0;left:0;width:100%;height:100%;border:none;" allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture;fullscreen" allowfullscreen></iframe></div></div>';
            document.body.appendChild(overlay);
            
            var closeBtn = document.getElementById('wpconvert-video-close');
            closeBtn.addEventListener('click', closeModal);
            overlay.addEventListener('click', function(e) {
                if (e.target === overlay) closeModal();
            });
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape') closeModal();
            });
        }
        
        function openModal(videoUrl) {
            var modal = document.getElementById('wpconvert-video-modal');
            var iframe = document.getElementById('wpconvert-video-frame');
            if (!modal || !iframe) return;
            var embedUrl = getEmbedUrl(videoUrl);
            if (!embedUrl) return;
            iframe.src = embedUrl;
            modal.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
        
        function closeModal() {
            var modal = document.getElementById('wpconvert-video-modal');
            var iframe = document.getElementById('wpconvert-video-frame');
            if (!modal) return;
            modal.style.display = 'none';
            if (iframe) iframe.src = '';
            document.body.style.overflow = '';
        }
        
        function init() {
            if (window.location.search.indexOf('wpc_edit=1') !== -1) return;
            var cardsFound = 0;
            
            // Strategy 1: Cards with data-video-url (set during snapshot extraction)
            document.querySelectorAll('[data-video-url]').forEach(function(card) {
                var videoUrl = card.getAttribute('data-video-url');
                if (!videoUrl) return;
                card.style.cursor = 'pointer';
                card.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    openModal(videoUrl);
                });
                cardsFound++;
            });
            
            // Strategy 2: Cards with play button SVGs but no data-video-url
            // Auto-detect video URLs from thumbnail image sources
            var playIcons = document.querySelectorAll('.lucide-play, [class*="lucide-play"]');
            playIcons.forEach(function(icon) {
                var card = icon.closest('[class*="cursor-pointer"]') ||
                           icon.closest('[class*="card"]') ||
                           icon.closest('[class*="group"]');
                if (!card || card.hasAttribute('data-video-url') || card.hasAttribute('data-wpconvert-video-bound')) return;
                
                var img = card.querySelector('img');
                if (!img) return;
                var src = img.getAttribute('src') || '';
                
                var videoUrl = '';
                // YouTube thumbnail -> YouTube embed
                var ytMatch = src.match(/img\.youtube\.com\/vi\/([a-zA-Z0-9_-]+)\//);
                if (ytMatch) {
                    videoUrl = 'https://www.youtube.com/watch?v=' + ytMatch[1];
                }
                // Vimeo CDN thumbnail — can't derive URL, skip
                
                if (videoUrl) {
                    card.setAttribute('data-wpconvert-video-bound', 'true');
                    card.addEventListener('click', function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                        openModal(videoUrl);
                    });
                    cardsFound++;
                }
            });
            
            if (cardsFound > 0) {
                createModal();
                console.log('[WPConvert] Video lightbox initialized for ' + cardsFound + ' card(s)');
            }
        }
        
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    })();
    </script>
    <?php
}
add_action('wp_footer', 'wpconvert_video_lightbox_enqueue', 996);

/**
 * Universal Tab/Carousel Selector Functionality
 * Dynamically detects and enables tab selector patterns from any converted website
 * Handles patient selectors, image galleries, content tabs, etc.
 */
function wpconvert_tab_selector_enqueue() {
    ?>
    <script>
    (function() {
        'use strict';
        
        function init() {
            // Find button groups that look like tab selectors
            // Pattern: multiple sibling buttons in a flex container with gap
            var containers = document.querySelectorAll('div[class*="flex"][class*="gap"]');
            var tabGroupsInitialized = 0;
            
            containers.forEach(function(container, containerIndex) {
                var buttons = container.querySelectorAll(':scope > button');
                
                // Need at least 2 buttons to be a tab selector
                if (buttons.length < 2) return;
                
                // Check if buttons have similar structure (tab selector pattern)
                // Only compare SIZE classes (w-, h-), ignore color/styling differences
                var hasSimilarButtons = true;
                var firstButtonSizeClasses = buttons[0].className.split(' ').filter(function(c) {
                    // Only check size classes - ignore border colors, bg colors, hover states
                    return /^(w-[0-9]+|h-[0-9]+)$/.test(c);
                }).sort().join(' ');
                
                buttons.forEach(function(btn) {
                    var btnSizeClasses = btn.className.split(' ').filter(function(c) {
                        return /^(w-[0-9]+|h-[0-9]+)$/.test(c);
                    }).sort().join(' ');
                    if (btnSizeClasses !== firstButtonSizeClasses) {
                        hasSimilarButtons = false;
                    }
                });
                
                // Also require that buttons have size classes (not just any flex container)
                if (!firstButtonSizeClasses || !hasSimilarButtons) return;
                
                // Skip if already handled (navigation buttons with < > arrows)
                var hasNavArrows = container.querySelector('svg[class*="chevron-left"], svg[class*="chevron-right"]');
                var isNavContainer = container.querySelectorAll(':scope > button').length === 2 && hasNavArrows;
                if (isNavContainer) return;
                
                // Find the active button (has gold/primary styling)
                var activeButton = null;
                var activeIndex = 0;
                buttons.forEach(function(btn, index) {
                    if (/border-gold|bg-gold|border-primary|bg-primary/.test(btn.className)) {
                        activeButton = btn;
                        activeIndex = index;
                    }
                });
                
                // Find associated content area
                // Look for text that shows selected item info
                // It could be: sibling of container, sibling of parent, or in ancestor section
                var infoText = null;
                var searchContext = container.parentElement;
                
                // Try parent's siblings first (common pattern)
                if (searchContext && searchContext.parentElement) {
                    var grandparent = searchContext.parentElement;
                    infoText = grandparent.querySelector('div[class*="text-center"] p[class*="text-gold"], div[class*="text-center"] p[class*="font-serif"]');
                }
                
                // If not found, try the whole section
                if (!infoText) {
                    var section = container.closest('section');
                    if (section) {
                        infoText = section.querySelector('div[class*="text-center"][class*="mt-"] p[class*="text-gold"], div[class*="text-center"][class*="mt-"] p[class*="font-serif"]');
                    }
                }
                
                // Mark as initialized
                container.setAttribute('data-wpconvert-tabs', 'true');
                
                // Store button labels for updating info text
                var buttonLabels = [];
                buttons.forEach(function(btn) {
                    buttonLabels.push(btn.textContent.trim());
                });
                
                // Add click handlers to each button
                buttons.forEach(function(btn, index) {
                    btn.addEventListener('click', function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                        
                        // Update active styling on all buttons
                        buttons.forEach(function(b, i) {
                            if (i === index) {
                                // Make this button active - use RegExp constructor to avoid escape issues
                                b.className = b.className
                                    .replace(new RegExp('border-white/[0-9]+', 'g'), 'border-gold')
                                    .replace(new RegExp('hover:border-white/[0-9]+', 'g'), '');
                                if (b.className.indexOf('bg-gold') === -1) {
                                    b.className = b.className.replace('border-gold', 'border-gold bg-gold/20');
                                }
                            } else {
                                // Make this button inactive
                                b.className = b.className
                                    .replace(/border-gold/g, 'border-white/20')
                                    .replace(new RegExp('bg-gold/[0-9]+', 'g'), '')
                                    .replace(new RegExp(' +', 'g'), ' ')
                                    .trim();
                                if (b.className.indexOf('hover:border') === -1) {
                                    b.className += ' hover:border-white/40';
                                }
                            }
                        });
                        
                        // Update info text if found
                        if (infoText && buttonLabels[index]) {
                            infoText.textContent = buttonLabels[index];
                        }
                        
                        // Store active index
                        container.setAttribute('data-active-index', index);
                    });
                });
                
                tabGroupsInitialized++;
            });
            
            if (tabGroupsInitialized > 0) {
                console.log('WPConvert Tab Selector: Initialized ' + tabGroupsInitialized + ' tab group(s)');
            }
        }
        
        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
        
    })();
    </script>
    <?php
}
add_action('wp_footer', 'wpconvert_tab_selector_enqueue', 996);

/**
 * EC-BLOG-228: Author byline / role / bio resolution.
 *
 * Imported posts carry the source site's author placeholder in post meta
 * (_wpconvert_author_name / _role / _bio). Those values are shown only while
 * the post is still owned by the user who imported it. As soon as the site
 * owner reassigns the post to a real WordPress author, the byline and bio
 * follow that WP author instead — so authorship stays editable the WP way.
 * The import author id is stamped on new posts only and NEVER backfilled, so a
 * post that predates this logic (no stamp) resolves to its real WP author.
 */
if ( ! function_exists( 'wpconvert_show_author' ) ) {
    /**
     * EC-BLOG-AUTHOR-TOGGLE-001: whether post author bylines are shown. Default ON so
     * every existing converted site is unchanged; the owner can hide all bylines under
     * Appearance → Customize → Blog. Every byline in the theme (single.php, home.php,
     * archive, category + front-page loops) is gated on this.
     */
    function wpconvert_show_author() {
        return (bool) get_theme_mod( 'wpconvert_show_author', true );
    }
}
if ( ! function_exists( 'wpconvert_post_is_source_author' ) ) {
    function wpconvert_post_is_source_author( $post_id = null ) {
        $post_id = $post_id ? $post_id : get_the_ID();
        $import_uid = get_post_meta( $post_id, '_wpconvert_import_author_id', true );
        if ( '' === $import_uid || null === $import_uid ) {
            return false;
        }
        return (int) $import_uid === (int) get_post_field( 'post_author', $post_id );
    }
}
if ( ! function_exists( 'wpconvert_author_name' ) ) {
    function wpconvert_author_name( $post_id = null ) {
        $post_id = $post_id ? $post_id : get_the_ID();
        $meta = get_post_meta( $post_id, '_wpconvert_author_name', true );
        if ( $meta && wpconvert_post_is_source_author( $post_id ) ) {
            return $meta;
        }
        $name = get_the_author_meta( 'display_name', (int) get_post_field( 'post_author', $post_id ) );
        return $name ? $name : $meta;
    }
}
if ( ! function_exists( 'wpconvert_author_bio' ) ) {
    function wpconvert_author_bio( $post_id = null ) {
        $post_id = $post_id ? $post_id : get_the_ID();
        if ( wpconvert_post_is_source_author( $post_id ) ) {
            return get_post_meta( $post_id, '_wpconvert_author_bio', true );
        }
        return get_the_author_meta( 'description', (int) get_post_field( 'post_author', $post_id ) );
    }
}
if ( ! function_exists( 'wpconvert_author_role' ) ) {
    function wpconvert_author_role( $post_id = null ) {
        $post_id = $post_id ? $post_id : get_the_ID();
        if ( wpconvert_post_is_source_author( $post_id ) ) {
            return get_post_meta( $post_id, '_wpconvert_author_role', true );
        }
        return '';
    }
}




?>